--
-- Name: formas_pagamento; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.formas_pagamento (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome text NOT NULL,
    ativa boolean DEFAULT true NOT NULL,
    visivel_cardapio boolean DEFAULT true NOT NULL,
    taxa_percentual numeric(5,2) DEFAULT 0 NOT NULL,
    taxa_fixa numeric(10,2) DEFAULT 0 NOT NULL,
    prazo_dias integer DEFAULT 0 NOT NULL,
    permite_troco boolean DEFAULT false NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    acrescimo_percentual numeric DEFAULT 0 NOT NULL,
    acrescimo_fixo numeric DEFAULT 0 NOT NULL,
    preco_proprio boolean DEFAULT false NOT NULL,
    aceita_online boolean DEFAULT false NOT NULL,
    tipo_online text,
    CONSTRAINT formas_pagamento_acrescimo_fixo_check CHECK (((acrescimo_fixo >= (0)::numeric) AND (acrescimo_fixo <= (1000)::numeric))),
    CONSTRAINT formas_pagamento_acrescimo_percentual_check CHECK (((acrescimo_percentual >= (0)::numeric) AND (acrescimo_percentual <= (100)::numeric))),
    CONSTRAINT formas_pagamento_online_exige_tipo CHECK (((NOT aceita_online) OR (tipo_online IS NOT NULL))),
    CONSTRAINT formas_pagamento_tipo_online_check CHECK (((tipo_online IS NULL) OR (tipo_online = ANY (ARRAY['pix'::text, 'credito'::text, 'debito'::text]))))
);


--
-- Name: _acrescimo_forma(public.formas_pagamento, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._acrescimo_forma(f public.formas_pagamento, base numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ select case when f.id is null then 0 else round(coalesce(base,0) * f.acrescimo_percentual / 100 + f.acrescimo_fixo, 2) end $$;


--
-- Name: _acrescimo_pagamento(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._acrescimo_pagamento(p_forma text, p_valor numeric) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select coalesce((select _acrescimo_forma(f, p_valor) from formas_pagamento f where lower(f.nome) = lower(btrim(coalesce(p_forma,''))) limit 1), 0) $$;


