--
-- Name: _ajustar_estoque(jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ajustar_estoque(p_itens jsonb, p_dir integer, p_venda uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; e estoque%rowtype; v_delta numeric; v_novo numeric;
        v_ref text := case when p_venda is not null then 'Venda #' || left(p_venda::text, 8) else case when p_dir > 0 then 'Venda' else 'Estorno de venda' end end;
        v_uid uuid := (select u.id from usuarios u where u.id = auth.uid());  -- cliente com conta não é da equipe: a movimentação fica sem usuário
begin
  for r in select * from _consumo(p_itens) order by ingrediente_id loop
    select * into e from estoque where id = r.ingrediente_id for update;
    if not found then continue; end if;
    v_delta := p_dir * r.qtd;
    v_novo := round(e.quantidade - v_delta, 3);
    update estoque set quantidade = v_novo where id = e.id;
    if p_dir > 0 and v_novo < 0 then perform _auditar('Estoque negativo', e.ingrediente || ': ' || v_novo || ' (' || v_ref || ')'); end if;
    if v_delta <> 0 then
      insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
      values (e.id, (case when p_dir > 0 then 'Venda' else 'Saída' end)::tipo_mov_estoque, -v_delta, e.quantidade, v_novo, v_ref, v_uid);
    end if;
  end loop;
end $$;


--
-- Name: _anonimizar_cliente(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._anonimizar_cliente(p_cli uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dig text;
begin
  if p_cli is null then return; end if;
  select _so_digitos(telefone) into v_dig from clientes where id = p_cli;
  insert into anonimizar_arquivo_fila (telefone, cliente_id) values (coalesce(v_dig, ''), p_cli);
  update vendas set cliente_nome = 'Cliente anonimizado', telefone_cliente = '', endereco = '', complemento = '', referencia = '', observacoes_entrega = '', cpf_nota = null
   where cliente_id = p_cli or (coalesce(v_dig, '') <> '' and _so_digitos(telefone_cliente) = v_dig);
  update vendas_resumo_arquivo set cliente_nome = 'Cliente anonimizado', telefone = '', endereco = '', complemento = ''
   where cliente_id = p_cli or (coalesce(v_dig, '') <> '' and telefone = v_dig);
  update feedbacks set telefone_cliente = '' where cliente_id = p_cli or (coalesce(v_dig, '') <> '' and _so_digitos(telefone_cliente) = v_dig);
  update clientes set nome = 'Cliente anonimizado', telefone = null, endereco = '', data_nascimento = null, observacoes = '', como_conheceu = '' where id = p_cli;
end $$;


--
-- Name: _aparelho_auditoria(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._aparelho_auditoria() RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare h jsonb;
begin
  begin h := nullif(current_setting('request.headers', true), '')::jsonb; exception when others then h := null; end;
  return nullif(left(regexp_replace(coalesce(h->>'user-agent', ''), '[\u0000-\u001f]', ' ', 'g'), 120), '');
end $$;


