--
-- Name: _caixa_msg_vencido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._caixa_msg_vencido() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ab timestamptz;
begin
  select abertura into v_ab from caixa_sessoes where status = 'Aberto'::status_caixa order by abertura desc limit 1;
  if auth_nivel()::text in ('Admin', 'Operador', 'Desenvolvedor') then
    return 'O caixa está vencido (aberto em ' || to_char(v_ab at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI')
      || '). Feche-o em "Fechar caixa vencido" e abra um novo. Em emergência, o Administrador pode liberar por algumas horas.';
  end if;
  return 'O caixa está vencido — chame o responsável.';
end $$;


--
-- Name: _caixa_vence_em(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._caixa_vence_em(p_abertura timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c caixa_config%rowtype; v_base timestamp; v_corte timestamp; v_vence timestamptz;
begin
  select * into c from caixa_config limit 1;
  v_base := (p_abertura at time zone 'America/Sao_Paulo') + make_interval(hours => c.vida_minima_horas);
  v_corte := date_trunc('day', v_base) + c.corte_hora;
  if v_corte < v_base then v_corte := v_corte + interval '1 day'; end if;
  v_vence := v_corte at time zone 'America/Sao_Paulo';
  return least(v_vence, p_abertura + make_interval(hours => c.teto_horas));
end $$;


--
-- Name: _caixa_vencido(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._caixa_vencido(p_caixa uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(s.status = 'Aberto'::status_caixa
         and now() >= _caixa_vence_em(s.abertura)
         and not exists (select 1 from caixa_liberacoes l where l.caixa_id = s.id and l.ate > now()), false)
  from caixa_sessoes s where s.id = p_caixa
$$;


--
-- Name: _calc_fechamento_entrega(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._calc_fechamento_entrega(p_login text, p_data date, OUT qtd integer, OUT total_taxas numeric, OUT ajuda numeric, OUT total numeric, OUT ids uuid[]) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare uid uuid; ja boolean; aj numeric;
begin
  select id into uid from usuarios where lower(login) = lower(p_login) and nivel::text = 'Entregador';
  select count(*)::int, coalesce(round(sum(taxa_entrega), 2), 0), coalesce(array_agg(id), '{}'::uuid[]) into qtd, total_taxas, ids
    from vendas where status = 'Confirmada' and tipo = 'Entrega' and status_pedido::text = 'Entregue' and entregador_id = uid
     and fechamento_entrega_id is null and (concluida_em at time zone 'America/Sao_Paulo')::date = p_data;
  select exists (select 1 from fechamentos_entrega where entregador_id = uid and data_ref = p_data) into ja;
  select coalesce(_num(valor #>> '{}'), 0) into aj from sistema where chave = 'AjudaDiariaEntregador';
  ajuda := case when qtd > 0 and not ja then coalesce(aj, 0) else 0 end;
  total := round(total_taxas + ajuda, 2);
end $$;


--
-- Name: _campanha_candidatos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._campanha_candidatos() RETURNS TABLE(user_id uuid, segmento text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.user_id, _segmento_cliente(x.n, x.total, x.ultimo, 45)
    from contas_cliente c
   cross join lateral (
     select count(*)::int n, coalesce(sum(b.valor_total), 0) total, max(b.data_hora) ultimo
       from (select v.valor_total, v.data_hora from vendas v
              where v.status = 'Confirmada'
                and ((c.cliente_id is not null and v.cliente_id = c.cliente_id)
                     or (length(_so_digitos(c.telefone)) >= 8 and _so_digitos(v.telefone_cliente) = _so_digitos(c.telefone)))
             union all
             select s.valor_total, s.data_hora from vendas_resumo_arquivo s
              where s.status = 'Confirmada'
                and ((c.cliente_id is not null and s.cliente_id = c.cliente_id)
                     or (length(_so_digitos(c.telefone)) >= 8 and s.telefone = _so_digitos(c.telefone)))) b) x
   where c.promo_ok and c.aceite_versao > 0 and x.n > 0
$$;


--
-- Name: _cardapio_bloqueio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cardapio_bloqueio() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m jsonb; per jsonb; e jsonb; hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  -- fechamento manual (chave ligada) e períodos programados (férias, manutenção); devolve a mensagem ao cliente ou null se está liberado
  select valor into m from sistema where chave = 'CardapioFechadoManual';
  if m is not null and jsonb_typeof(m) = 'object' and coalesce(m->>'ativo', 'false') = 'true' then
    return coalesce(nullif(btrim(m->>'mensagem'), ''), 'Estamos fechados no momento. Voltamos em breve!');
  end if;
  select valor into per from sistema where chave = 'CardapioPeriodosFechado';
  if per is not null and jsonb_typeof(per) = 'array' then
    for e in select value from jsonb_array_elements(per) loop
      begin
        if hoje between (e->>'inicio')::date and (e->>'fim')::date then
          return coalesce(nullif(btrim(e->>'mensagem'), ''), 'Estamos fechados neste período. Voltamos em breve!');
        end if;
      exception when others then null;
      end;
    end loop;
  end if;
  return null;
end $$;


--
-- Name: _carimbar_fidelidade(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._carimbar_fidelidade(p_tel text, p_nome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cli uuid := _upsert_cliente(p_tel, p_nome); f fidelidade%rowtype;
begin
  if v_cli is null then return; end if;
  select * into f from fidelidade where cliente_id = v_cli for update;
  if found then
    if f.carimbos < 10 then
      update fidelidade set carimbos = f.carimbos + 1, atualizada_em = now() where cliente_id = v_cli;
      perform _auditar('Marca adicionada (fidelidade)', (f.carimbos + 1) || '/10', p_tel);
    end if;
  else
    insert into fidelidade (cliente_id, carimbos, atualizada_em) values (v_cli, 1, now());
    perform _auditar('Cliente novo no fidelidade', coalesce(p_nome, ''), p_tel);
  end if;
end $$;


