-- Name: _chat_limpar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._chat_limpar(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$ select btrim(regexp_replace(coalesce(t, ''), '[\x01-\x08\x0B\x0C\x0E-\x1F]', '', 'g')) $$;


--
-- Name: _chat_normalizar_intencao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._chat_normalizar_intencao() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.estado <> 'recepcao' and new.venda_id is null then
    if new.intencao is null then new.intencao := 'antes_de_pedir';
    elsif new.intencao = 'pedido_feito' then new.pedido_nao_localizado := true; end if;
  end if;
  return new;
end $$;


--
-- Name: _chat_validar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._chat_validar(p_id uuid, p_token text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$ select exists (select 1 from chat_tokens t where t.conversa_id = p_id and t.token_hash = _chat_hash(p_token)) $$;


--
-- Name: _cnpj_valido(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cnpj_valido(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare d int[]; s int; i int; pesos1 int[] := array[5,4,3,2,9,8,7,6,5,4,3,2]; pesos2 int[] := array[6,5,4,3,2,9,8,7,6,5,4,3,2];
begin
  if p is null or p !~ '^[0-9]{14}$' or p ~ '^(.)\1{13}$' then return false; end if;
  for i in 1..14 loop d[i] := substr(p, i, 1)::int; end loop;
  s := 0; for i in 1..12 loop s := s + d[i] * pesos1[i]; end loop; s := s % 11; s := case when s < 2 then 0 else 11 - s end;
  if s <> d[13] then return false; end if;
  s := 0; for i in 1..13 loop s := s + d[i] * pesos2[i]; end loop; s := s % 11; s := case when s < 2 then 0 else 11 - s end;
  return s = d[14];
end $_$;


--
-- Name: _combo_gravar_itens(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._combo_gravar_itens(p_combo uuid, p_itens jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from combo_itens where combo_id = p_combo;
  insert into combo_itens (combo_id, produto_id, quantidade)
  select p_combo, _uuid(e->>'produtoId'), _num(e->>'quantidade')::int
  from jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) e
  where _uuid(e->>'produtoId') is not null and _num(e->>'quantidade') > 0;
end $$;


--
-- Name: _combo_gravar_precos(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._combo_gravar_precos(p_combo uuid, p_precos jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from combo_precos where combo_id = p_combo;
  insert into combo_precos (combo_id, forma_pagamento_id, preco, custo)
  select p_combo, _uuid(e->>'formaPagamentoId'), _num(e->>'preco'), _num(e->>'custo')
  from jsonb_array_elements(coalesce(p_precos, '[]'::jsonb)) e where _uuid(e->>'formaPagamentoId') is not null
  on conflict (combo_id, forma_pagamento_id) do update set preco = excluded.preco, custo = excluded.custo;
end $$;


--
-- Name: _comp_valida(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._comp_valida(v text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select coalesce(v ~ '^\d{4}-(0[1-9]|1[0-2])$', false)
$_$;


