$$;


--
-- Name: _compra_receber(uuid, text, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compra_receber(p_id uuid, p_pagamento text, p_venc date, p_saiu boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare c compras%rowtype; i record; e estoque%rowtype; v_q numeric; v_custo numeric; v_forn text; v_desp uuid; v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  select * into c from compras where id = p_id for update;
  if not found then raise exception '%', 'Compra não encontrada.'; end if;
  if c.status <> 'Pedido' then raise exception '%', 'Esta compra já foi ' || lower(c.status) || '.'; end if;
  if p_pagamento = 'A pagar' and p_venc is null then raise exception '%', 'Informe o vencimento da conta a pagar.'; end if;
  select nome into v_forn from fornecedores where id = c.fornecedor_id;
  for i in select * from compra_itens where compra_id = c.id order by id loop
    if i.ingrediente_id is null then continue; end if;
    select * into e from estoque where id = i.ingrediente_id for update;
    if not found then continue; end if;
    v_q := _converter_unidade(i.quantidade, i.unidade, e.unidade::text);
    if v_q is null or v_q <= 0 then raise exception '%', 'A unidade "' || i.unidade || '" de ' || e.ingrediente || ' não combina com a do estoque (' || e.unidade || ').'; end if;
    v_custo := round((greatest(e.quantidade, 0) * e.custo_unitario + i.valor_total) / (greatest(e.quantidade, 0) + v_q), 6);
    update estoque set quantidade = e.quantidade + v_q, custo_unitario = v_custo where id = e.id;
    insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
    values (e.id, 'Entrada', v_q, e.quantidade, e.quantidade + v_q, 'Compra de ' || v_forn || ' (R$ ' || _dinheiro(i.valor_total) || ')', auth.uid());
  end loop;
  if c.total > 0 then
    insert into despesas (data_hora, descricao, valor, observacao, status, categoria, vencimento, situacao, competencia, saiu_do_caixa)
    values (case when p_pagamento = 'A pagar' then _meio_dia(p_venc) else now() end, 'Compra: ' || v_forn, c.total, 'Compra ' || to_char(c.data, 'DD/MM/YYYY') || case when c.observacao <> '' then ' - ' || c.observacao else '' end,
            (case when p_pagamento = 'A pagar' then 'A pagar' else 'Paga' end)::status_despesa, _categoria_despesa('Insumos'), case when p_pagamento = 'A pagar' then p_venc end, case when p_pagamento = 'A pagar' then 'A pagar' else 'Paga' end,
            case when p_pagamento = 'A pagar' then to_char(p_venc, 'YYYY-MM') end, case when p_pagamento = 'Pago' then coalesce(p_saiu, false) else true end)
    returning id into v_desp;
  end if;
  update compras set status = 'Recebida', recebida_em = now(), pagamento = p_pagamento, vencimento = case when p_pagamento = 'A pagar' then p_venc end, despesa_id = v_desp where id = c.id;
  return null;
end $_$;


--
-- Name: _conceder_cupom_auto(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conceder_cupom_auto(p_tipo text, p_user uuid, p_ref text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c cupons%rowtype; n int;
begin
  select * into c from cupons where automatico = p_tipo and ativa;
  if not found then return false; end if;
  insert into cupons_concedidos (cupom_id, user_id, origem, ref, valido_ate) values (c.id, p_user, p_tipo, coalesce(p_ref, ''), _hoje_br() + c.validade_dias)
  on conflict do nothing;
  get diagnostics n = row_count;
  return n > 0;
end $$;


--
-- Name: _conflito(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conflito(p_msg text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object('ok', false, 'conflito', true, 'message', p_msg) $$;


--
-- Name: _consumo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._consumo(p_itens jsonb) RETURNS TABLE(ingrediente_id uuid, qtd numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with it as (
    select _uuid(e->>'produtoId') as produto_id, _uuid(e->>'comboId') as combo_id,
           _num(e->>'quantidade') as q, e->'adicionaisIds' as ads
    from jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) e
  ), consumo as (
    select pi.ingrediente_id, pi.quantidade_por_unidade * it.q as qtd
      from it join produto_ingredientes pi on pi.produto_id = it.produto_id
    union all
    select pi.ingrediente_id, pi.quantidade_por_unidade * ci.quantidade * it.q
      from it join combo_itens ci on ci.combo_id = it.combo_id
              join produto_ingredientes pi on pi.produto_id = ci.produto_id
    union all
    select a.ingrediente_id, coalesce(nullif(a.quantidade_descontar, 0), 1) * it.q
      from it
      cross join lateral jsonb_array_elements_text(case when jsonb_typeof(it.ads) = 'array' then it.ads else '[]'::jsonb end) x
      join adicionais a on a.id = _uuid(x)
      where a.ingrediente_id is not null
  )
  select c.ingrediente_id, sum(c.qtd) from consumo c where c.ingrediente_id is not null group by c.ingrediente_id having sum(c.qtd) <> 0
$$;


