-- Name: _conta_atual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_atual() RETURNS public.contas_cliente
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select * from contas_cliente where user_id = auth.uid() $$;


--
-- Name: _conta_cupom_usado(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_cupom_usado(p_user uuid, p_cupom uuid, p_venda uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_user is null then return; end if;
  update cupons_concedidos set usado_em = now(), venda_id = p_venda
   where id = (select id from cupons_concedidos where cupom_id = p_cupom and user_id = p_user and usado_em is null and (valido_ate is null or valido_ate >= _hoje_br())
                order by valido_ate nulls last, criado_em limit 1);
end $$;


--
-- Name: _conta_exigir(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_exigir() RETURNS public.contas_cliente
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente;
begin
  if auth.uid() is null or auth_nivel() is not null then return null; end if;
  select * into c from contas_cliente where user_id = auth.uid() and aceite_versao > 0;
  if c.user_id is null then return null; end if;
  return c;
end $$;


--
-- Name: _conta_premiar_indicacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conta_premiar_indicacao(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente; ind contas_cliente; v_mes int;
begin
  select * into c from contas_cliente where user_id = p_user;
  if c.user_id is null or c.indicado_por is null or c.indicacao_premiada then return; end if;
  select * into ind from contas_cliente where user_id = c.indicado_por;
  update contas_cliente set indicacao_premiada = true where user_id = p_user;
  if ind.user_id is null or ind.aceite_versao = 0 then return; end if;
  if ind.telefone <> '' and ind.telefone = c.telefone then return; end if;
  select greatest(
           (select count(*) from contas_beneficios where user_id = ind.user_id and tipo = 'Indicação' and criado_em > now() - interval '30 days'),
           (select count(*) from cupons_concedidos where user_id = ind.user_id and origem = 'indicacao_indicador' and criado_em > now() - interval '30 days')) into v_mes;
  if v_mes >= 10 then return; end if;
  perform _conceder_cupom_auto('indicacao_indicado', p_user, p_user::text);
  perform _conceder_cupom_auto('indicacao_indicador', ind.user_id, p_user::text);
  if exists (select 1 from produtos where ativo and premio_indicacao) then
    insert into contas_beneficios (user_id, tipo, ref) values (ind.user_id, 'Indicação', p_user::text) on conflict do nothing;
  end if;
end $$;


--
-- Name: _converter_unidade(numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._converter_unidade(p_qtd numeric, p_de text, p_para text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when lower(p_de) = lower(p_para) then p_qtd
    when lower(p_de) = 'kg' and lower(p_para) = 'g' then p_qtd * 1000
    when lower(p_de) = 'g' and lower(p_para) = 'kg' then p_qtd / 1000
    when lower(p_de) = 'l' and lower(p_para) = 'ml' then p_qtd * 1000
    when lower(p_de) = 'ml' and lower(p_para) = 'l' then p_qtd / 1000
    else null end
$$;


--
-- Name: _cpf_valido(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cpf_valido(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare s int; i int; d1 int; d2 int;
begin
  if p is null or p !~ '^[0-9]{11}$' or p ~ '^(.)\1{10}$' then return false; end if;
  s := 0; for i in 1..9 loop s := s + substr(p, i, 1)::int * (11 - i); end loop; d1 := (s * 10) % 11; if d1 = 10 then d1 := 0; end if;
  s := 0; for i in 1..10 loop s := s + substr(p, i, 1)::int * (12 - i); end loop; d2 := (s * 10) % 11; if d2 = 10 then d2 := 0; end if;
  return d1 = substr(p, 10, 1)::int and d2 = substr(p, 11, 1)::int;
end $_$;


--
-- Name: _criar_login_auth(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._criar_login_auth(p_id uuid, p_email text, p_senha text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token)
  values ('00000000-0000-0000-0000-000000000000', p_id, 'authenticated', 'authenticated', p_email,
    crypt(p_senha, gen_salt('bf')), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(), '', '', '', '', '', '', '', '');
  insert into auth.identities (id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at)
  values (gen_random_uuid(), p_id, jsonb_build_object('sub', p_id::text, 'email', p_email, 'email_verified', true, 'phone_verified', false),
          'email', p_id::text, now(), now(), now());
end $$;


--
-- Name: _criar_pedido_publico(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._criar_pedido_publico(p jsonb, p_mesa_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select public._criar_pedido_publico(p, p_mesa_id, false) $$;


--
-- Name: _criar_pedido_publico(jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._criar_pedido_publico(p jsonb, p_mesa_id uuid, p_reserva boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_eh_mesa boolean := p_mesa_id is not null; v_mesa mesas%rowtype;
  v_nome text := _texto_publico(p->>'clienteNome', 80);
  v_tel text := case when p_mesa_id is not null then '' else _texto_publico(p->>'clienteTelefone', 20) end;
  v_dig text := case when p_mesa_id is not null then '' else _so_digitos(p->>'clienteTelefone') end;
  v_obs_troco text := _texto_publico(p->>'observacaoTroco', 200);
  v_de jsonb := case when jsonb_typeof(p->'dadosEntrega') = 'object' then p->'dadosEntrega' else '{}'::jsonb end;
  v_end text := _texto_publico(v_de->>'endereco', 200); v_comp text := _texto_publico(v_de->>'complemento', 100); v_ref text := _texto_publico(v_de->>'referencia', 150);
  v_obs_ent text := _texto_publico(coalesce(nullif(p->>'observacoes', ''), v_de->>'observacoes'), 300);
  v_itens jsonb := p->'itens'; v_tipo_in text := p->>'tipoEntrega'; v_ip text := _ip_cliente();
  v_req text := nullif(left(btrim(coalesce(p->>'requisicaoId', '')), 80), '');
  v_forma formas_pagamento%rowtype; v_caixa uuid; v_tipo venda_tipo; v_ja record; v_prod produtos%rowtype; v_comb combos%rowtype;
  it record; r record; v_prod_id uuid; v_comb_id uuid; v_qtd numeric; v_preco numeric; v_custo_u numeric; v_nome_item text; v_extra numeric; v_n_ad int; v_n_ok int;
  v_ads text; v_obs_item text; v_ads_ids jsonb; v_itens_ok jsonb := '[]'::jsonb; v_orig numeric := 0; v_custo numeric := 0;
  v_cod text := ''; v_cup jsonb; v_desc numeric := 0; v_frete boolean := false; v_taxa numeric := 0; v_pad numeric; v_total numeric;
  v_venda uuid := gen_random_uuid(); v_numero int; v_cli uuid; v_chave text; v_obs_final text; v_bloqueia boolean; v_forma_nome text; v_acr numeric := 0; v_bloq text; v_user uuid := (select cc.user_id from contas_cliente cc where cc.user_id = auth.uid() and cc.aceite_versao > 0);
  v_ben jsonb := case when jsonb_typeof(p->'beneficios') = 'array' then p->'beneficios' else '[]'::jsonb end;
  b record; v_bens jsonb := '[]'::jsonb; v_bc contas_cliente; v_fid fidelidade%rowtype; v_bid uuid; v_pb produtos%rowtype; v_btipo text;
  v_res uuid; v_min int; v_cfg integracoes_config%rowtype; v_ja_res record;
begin
  -- Mercado Pago (p_reserva = true): valida tudo igual ao pedido normal, mas em vez de criar a venda guarda uma RESERVA até o pagamento ser aprovado
  if p_reserva then
    if p_mesa_id is not null then return _falha('Mesas e balcão não pagam pelo site.'); end if;
    if v_user is null then return _falha('Entre com a sua conta para pagar pelo site.'); end if;
    if v_req is null then return _falha('Não foi possível identificar esta tentativa. Atualize a página e tente de novo.'); end if;
    if coalesce((public.api_mp_config_publica('{}'::jsonb)->>'ligado')::boolean, false) is not true then
      return _falha('O pagamento pelo site não está disponível agora. Escolha pagar na entrega.');
    end if;
    perform pg_advisory_xact_lock(hashtext('reserva:' || v_req));
    select id, estado, valor_total, expira_em into v_ja_res from pedidos_reserva where requisicao_id = v_req;
    if found then
      return jsonb_build_object('ok', true, 'duplicado', true, 'reservaId', v_ja_res.id, 'estado', v_ja_res.estado,
        'valorTotal', v_ja_res.valor_total, 'expiraEm', v_ja_res.expira_em, 'message', 'Pedido já recebido — envio repetido ignorado.');
    end if;
  end if;

  -- repetição do mesmo envio (duplo toque, nova tentativa): devolve o pedido já criado, sem criar outro
  if v_req is not null and not p_reserva then
    perform pg_advisory_xact_lock(hashtext('venda:' || v_req));
    select id, numero_pedido, valor_total into v_ja from vendas where requisicao_id = v_req;
    if found then
      return jsonb_build_object('ok', true, 'duplicado', true, 'id', v_ja.id, 'numero', v_ja.numero_pedido, 'valorTotal', v_ja.valor_total, 'message', 'Pedido já recebido — envio repetido ignorado.');
    end if;
  end if;

  if jsonb_typeof(v_itens) <> 'array' then return _falha('Carrinho vazio.'); end if;
  if jsonb_array_length(v_itens) = 0 and (p_mesa_id is not null or jsonb_array_length(v_ben) = 0) then return _falha('Carrinho vazio.'); end if;
  if jsonb_array_length(v_itens) > 40 then return _falha('Carrinho grande demais.'); end if;
  if v_eh_mesa then
    if v_nome = '' then return _falha('Informe o seu nome.'); end if;
    v_chave := 'pedmesa_' || p_mesa_id::text;
  else
    if v_nome = '' or v_dig = '' then return _falha('Informe nome e telefone.'); end if;
    if length(v_dig) < 10 or length(v_dig) > 13 then return _falha('Informe um telefone válido com DDD.'); end if;
    v_chave := 'pedcard_' || v_dig;
  end if;
  if _excedeu('pedcard_global', 150) then return _falha('Estamos com muitos pedidos no momento. Tente novamente em alguns minutos ou ligue para o restaurante.'); end if;
  if _excedeu('pedcard_ip_' || v_ip, 40) then return _falha('Muitos pedidos em sequência deste local. Aguarde alguns minutos.'); end if;
  if _excedeu(v_chave, case when v_eh_mesa then 8 else 5 end) then
    return _falha(case when v_eh_mesa then 'Muitos pedidos em sequência nesta mesa. Chame o garçom.' else 'Muitos pedidos em sequência. Aguarde alguns minutos.' end);
  end if;

  -- cardápio fechado à mão ou em período programado (pedido de mesa, feito dentro do restaurante, não é bloqueado)
  if not v_eh_mesa then
    v_bloq := _cardapio_bloqueio();
    if v_bloq is not null then return _falha(v_bloq); end if;
  end if;
  select id into v_caixa from caixa_sessoes where status = 'Aberto' limit 1;
  if v_caixa is null then return _falha('Estamos fechados no momento. Tente novamente mais tarde.'); end if;

  if v_eh_mesa then
    select * into v_mesa from mesas where id = p_mesa_id for update;
    if not found then return _falha('Mesa não encontrada.'); end if;
    if v_mesa.status::text not in ('Livre', 'Ocupada') then
      return _falha(case when v_mesa.status::text = 'Aguardando fechamento' then 'A conta desta mesa já foi pedida. Chame o garçom para novos pedidos.' else 'Esta mesa não está disponível para pedidos pelo celular. Chame o garçom.' end);
    end if;
    v_tipo := 'Mesa';
    -- mesa: o cliente não escolhe a forma; vale a primeira forma do cardápio só para o preço (o recebimento é feito no fechamento da conta)
    select * into v_forma from formas_pagamento where ativa and visivel_cardapio order by ordem limit 1;
    v_forma_nome := 'A Receber (Mesa)';
  else
    v_tipo := (case when v_tipo_in = 'Entrega' then 'Entrega' else 'Retirada' end)::venda_tipo;
    if v_tipo = 'Entrega' and v_end = '' then return _falha('Informe o endereço de entrega.'); end if;
    if v_tipo = 'Entrega' then
      declare v_num text := _texto_publico(v_de->>'numero', 20); v_cid text := _texto_publico(v_de->>'cidade', 80);
              v_cid_loc text := _texto_publico(v_de->>'cidadeLocalizacao', 80); v_lista jsonb; v_nomes text;
      begin
        if v_de ? 'numero' and v_num = '' then return _falha('Informe o número da casa (ou "s/n").'); end if;
        if v_de ? 'cidade' and v_cid = '' then return _falha('Informe a cidade da entrega.'); end if;
        if v_num <> '' then v_end := left(v_end || ', nº ' || v_num, 200); end if;
        if v_cid <> '' then v_end := left(v_end || ' — ' || v_cid, 200); end if;
      end;
    end if;
    select * into v_forma from formas_pagamento where id = _uuid(p->>'formaPagamentoId') and ativa and visivel_cardapio;
    v_forma_nome := v_forma.nome;
  end if;
  if v_forma.id is null then return _falha('Forma de pagamento inválida.'); end if;
  if p_reserva and not (v_forma.aceita_online and v_forma.tipo_online is not null) then return _falha('Esta forma de pagamento não é aceita pelo site.'); end if;

  -- itens: tudo vem do cadastro (produto/combo ativo, preço da forma escolhida, adicionais ativos e vinculados)
  for it in select value as e from jsonb_array_elements(v_itens) loop
    v_qtd := _num(it.e->>'quantidade');
    if v_qtd <= 0 then continue; end if;
    if v_qtd > 50 or v_qtd <> floor(v_qtd) then return _falha('Quantidade inválida no carrinho.'); end if;
    v_prod_id := _uuid(it.e->>'produtoId'); v_comb_id := _uuid(it.e->>'comboId');
    if (v_prod_id is null) = (v_comb_id is null) then return _falha('Item inválido no carrinho.'); end if;
    if jsonb_typeof(it.e->'adicionaisIds') = 'array' and jsonb_array_length(it.e->'adicionaisIds') > 20 then return _falha('Adicionais demais em um item.'); end if;
    if v_prod_id is not null then
      select * into v_prod from produtos where id = v_prod_id and ativo;
      if not found then return _falha('Um dos produtos não está mais disponível.'); end if;
      v_nome_item := v_prod.nome;
      select preco, custo into v_preco, v_custo_u from produto_precos where produto_id = v_prod_id and forma_pagamento_id = v_forma.id limit 1;
      if not found then return _falha('"' || v_nome_item || '" não tem preço configurado para essa forma de pagamento.'); end if;
    else
      select * into v_comb from combos where id = v_comb_id and ativo;
      if not found then return _falha('Um dos combos não está mais disponível.'); end if;
      if exists (select 1 from combo_itens ci join produtos pr on pr.id = ci.produto_id where ci.combo_id = v_comb_id and not pr.ativo) then
        return _falha('O combo "' || v_comb.nome || '" está temporariamente indisponível.');
      end if;
      v_nome_item := v_comb.nome;
      select preco, custo into v_preco, v_custo_u from combo_precos where combo_id = v_comb_id and forma_pagamento_id = v_forma.id limit 1;
      if not found then return _falha('"' || v_nome_item || '" não tem preço configurado para essa forma de pagamento.'); end if;
    end if;
    select count(*), coalesce(sum(a.preco), 0),
           count(a.id) filter (where a.ativo and ((v_prod_id is not null and exists (select 1 from produto_adicionais pa where pa.produto_id = v_prod_id and pa.adicional_id = a.id)) or (v_comb_id is not null and exists (select 1 from combo_itens ci join produto_adicionais pa on pa.produto_id = ci.produto_id where ci.combo_id = v_comb_id and pa.adicional_id = a.id)))),
           coalesce(string_agg(' + ' || a.nome, '' order by s.ord) filter (where a.id is not null), ''),
           coalesce(jsonb_agg(a.id order by s.ord) filter (where a.id is not null), '[]'::jsonb)
      into v_n_ad, v_extra, v_n_ok, v_ads, v_ads_ids
      from jsonb_array_elements_text(case when jsonb_typeof(it.e->'adicionaisIds') = 'array' then it.e->'adicionaisIds' else '[]'::jsonb end) with ordinality as s(x, ord)
      left join adicionais a on a.id = _uuid(s.x);
    if v_n_ad <> v_n_ok then return _falha('Um adicional escolhido para "' || v_nome_item || '" não está disponível.'); end if;
    v_obs_item := _texto_publico(it.e->>'observacao', 100);
    v_itens_ok := v_itens_ok || jsonb_build_array(jsonb_build_object('produtoId', v_prod_id, 'comboId', v_comb_id,
      'descricao', v_nome_item || v_ads || case when v_obs_item <> '' then ' — Obs: ' || v_obs_item else '' end,
      'quantidade', v_qtd, 'valorUnitario', v_preco + v_extra, 'custoUnitario', v_custo_u, 'adicionaisIds', v_ads_ids));
    v_orig := v_orig + round(v_qtd * (v_preco + v_extra), 2); v_custo := v_custo + v_qtd * v_custo_u;
  end loop;
  if jsonb_array_length(v_itens_ok) = 0 and jsonb_array_length(v_ben) = 0 then return _falha('Carrinho vazio.'); end if;
  -- brindes da conta (cartão fidelidade e indicação): entram como item de R$ 0, com custo e baixa no estoque
  if jsonb_array_length(v_ben) > 0 then
    if v_eh_mesa or v_user is null then return _falha('Entre com a sua conta para resgatar o brinde.'); end if;
    if jsonb_array_length(v_ben) > 5 then return _falha('Brindes demais no mesmo pedido.'); end if;
    select * into v_bc from contas_cliente where user_id = v_user for update;
    for b in select value as e from jsonb_array_elements(v_ben) loop
      v_btipo := b.e->>'tipo';
      select * into v_pb from produtos where id = _uuid(b.e->>'produtoId') and ativo;
      if not found then return _falha('O brinde escolhido não está mais disponível.'); end if;
      select custo into v_custo_u from produto_precos where produto_id = v_pb.id and forma_pagamento_id = v_forma.id limit 1;
      if not found then return _falha('"' || v_pb.nome || '" não está disponível para essa forma de pagamento.'); end if;
      v_bid := null;
      if v_btipo = 'Fidelidade' then
        if not v_pb.premio_fidelidade then return _falha('"' || v_pb.nome || '" não é um prêmio do cartão fidelidade.'); end if;
        if v_bc.cliente_id is null then return _falha('Seu cartão fidelidade ainda não está ligado à sua conta. Ele liga depois do seu primeiro pedido concluído.'); end if;
        if exists (select 1 from jsonb_array_elements(v_bens) x where x->>'tipo' = 'Fidelidade') then return _falha('Só dá para resgatar 1 prêmio do cartão fidelidade por pedido.'); end if;
        select * into v_fid from fidelidade where cliente_id = v_bc.cliente_id for update;
        if v_fid.id is null or v_fid.carimbos < 10 then return _falha('Seu cartão fidelidade ainda não completou as 10 marcas.'); end if;
      elsif v_btipo = 'Indicação' then
        if not v_pb.premio_indicacao then return _falha('"' || v_pb.nome || '" não é um prêmio de indicação.'); end if;
        select id into v_bid from contas_beneficios where id = _uuid(b.e->>'id') and user_id = v_user and tipo = 'Indicação' and status = 'Disponível' for update;
        if v_bid is null or exists (select 1 from jsonb_array_elements(v_bens) x where x->>'id' = v_bid::text) then return _falha('Este brinde de indicação não está mais disponível.'); end if;
      else
        return _falha('Brinde inválido.');
      end if;
      v_bens := v_bens || jsonb_build_array(jsonb_build_object('tipo', v_btipo, 'id', v_bid, 'produtoId', v_pb.id));
      v_itens_ok := v_itens_ok || jsonb_build_array(jsonb_build_object('produtoId', v_pb.id, 'comboId', null,
        'descricao', '🎁 Brinde ' || case when v_btipo = 'Fidelidade' then 'fidelidade' else 'indicação' end || ' — ' || v_pb.nome,
        'quantidade', 1, 'valorUnitario', 0, 'custoUnitario', v_custo_u, 'adicionaisIds', '[]'::jsonb));
      v_custo := v_custo + v_custo_u;
    end loop;
  end if;
  v_orig := round(v_orig, 2); v_custo := round(v_custo, 2);

  select coalesce((select (valor #>> '{}') = 'true' from sistema where chave = 'BLOQUEAR_ESTOQUE_NEGATIVO'), false) into v_bloqueia;
  if v_bloqueia then
    for r in select c.ingrediente_id, c.qtd, e.quantidade from _consumo(v_itens_ok) c join estoque e on e.id = c.ingrediente_id loop
      if r.quantidade + 0.000000001 < r.qtd then return _falha('Um dos itens do pedido acabou. Escolha outro item ou fale com o restaurante.'); end if;
    end loop;
  end if;

  -- cupom (só no cardápio comum; travado por código para dois pedidos simultâneos não estourarem o limite)
  if not v_eh_mesa then
    v_cod := upper(regexp_replace(btrim(coalesce(p->>'codigoCupom', '')), '\s+', '', 'g'));
    if v_cod <> '' then
      if v_orig <= 0 then return _falha('O cupom vale para pedidos com pelo menos um item pago.'); end if;
      perform pg_advisory_xact_lock(hashtext('cupom:' || v_cod));
      v_cup := _cupom_calcular(v_cod, v_tel, v_orig, v_tipo::text, v_user);
      if coalesce(v_cup->>'ok', '') <> 'true' then return v_cup; end if;
      v_desc := (v_cup->>'desconto')::numeric; v_frete := (v_cup->>'freteGratis')::boolean;
    end if;
  end if;

  if v_tipo = 'Entrega' and not v_frete then
    select coalesce(_num(valor #>> '{}'), 0) into v_pad from sistema where chave = 'TaxaEntregaPadrao';
    v_taxa := coalesce(v_pad, 0);
  end if;
  v_total := case when v_orig <= 0 and jsonb_array_length(v_bens) > 0 then round(v_taxa, 2) else greatest(0.01, round(v_orig - v_desc + v_taxa, 2)) end;
  -- acréscimo da forma de pagamento escolhida (mesa: o acréscimo entra no fechamento da conta)
  if not v_eh_mesa and v_orig > 0 then v_acr := _acrescimo_forma(v_forma, greatest(0.01, v_total - v_taxa)); v_total := round(v_total + v_acr, 2); end if;
  v_obs_final := coalesce(concat_ws(' — ', nullif(v_obs_ent, ''), nullif(v_obs_troco, '')), '');

  -- Mercado Pago: não cria a venda agora. Guarda a reserva (e já segura estoque, cupom e brinde) até o pagamento ser aprovado.
  if p_reserva then
    if v_total <= 0 then return _falha('Este pedido não tem valor a pagar pelo site.'); end if;
    select * into v_cfg from integracoes_config where provedor = 'mercadopago';
    v_min := case when coalesce(v_cfg.config->>'pixValidadeMin', '') ~ '^[0-9]{1,3}$' then least(120, greatest(5, (v_cfg.config->>'pixValidadeMin')::int)) else 15 end;
    insert into pedidos_reserva (requisicao_id, user_id, cliente_nome, telefone, tipo_entrega, forma_pagamento_id, dados_entrega, observacoes,
                                 itens, beneficios, cupom, valor_original, valor_desconto, taxa_entrega, acrescimo_forma, valor_total, custo_total, expira_em)
    values (v_req, v_user, v_nome, v_tel, v_tipo::text, v_forma.id,
            jsonb_build_object('endereco', case when v_tipo = 'Entrega' then v_end else '' end, 'complemento', case when v_tipo = 'Entrega' then v_comp else '' end,
                               'referencia', case when v_tipo = 'Entrega' then v_ref else '' end),
            v_obs_final, v_itens_ok, v_bens, case when v_cod <> '' then v_cup else null end, v_orig, v_desc, v_taxa, v_acr, v_total, v_custo,
            now() + make_interval(mins => v_min))
    returning id into v_res;
    perform _mp_prender(v_res, false);
    perform _registrar_falha(v_chave, 600); perform _registrar_falha('pedcard_global', 300); perform _registrar_falha('pedcard_ip_' || v_ip, 600);
    perform _auditar_publico('Pedido reservado para pagamento pelo site',
      'Total R$ ' || _dinheiro(v_total) || case when jsonb_array_length(v_bens) > 0 then ' | Brindes ' || jsonb_array_length(v_bens) else '' end || case when v_cod <> '' then ' | Cupom ' || (v_cup->>'codigo') else '' end, v_tel);
    return jsonb_build_object('ok', true, 'reservaId', v_res, 'metodo', v_forma.tipo_online, 'valorTotal', v_total, 'valorOriginal', v_orig,
      'acrescimo', v_acr, 'valorDesconto', v_desc, 'taxaEntrega', v_taxa, 'minutos', v_min, 'expiraEm', now() + make_interval(mins => v_min));
  end if;

  insert into vendas (id, cliente_nome, telefone_cliente, forma_pagamento, valor_total, custo_total, status, tipo, status_pedido,
                      endereco, complemento, referencia, observacoes_entrega, status_pagamento, valor_original, valor_desconto,
                      desconto_detalhe, origem, mesa_id, taxa_entrega, caixa_id, requisicao_id, acrescimo_forma)
  values (v_venda, v_nome, v_tel, v_forma_nome, v_total, v_custo, 'Confirmada', v_tipo, 'Recebido',
          case when v_tipo = 'Entrega' then v_end else '' end, case when v_tipo = 'Entrega' then v_comp else '' end, case when v_tipo = 'Entrega' then v_ref else '' end,
          v_obs_final, (case when v_total <= 0 then 'Pago' else 'A Receber' end)::status_pagamento, v_orig, v_desc, case when v_cod <> '' then 'Cupom ' || (v_cup->>'codigo') else '' end, 'Cardápio',
          case when v_eh_mesa then p_mesa_id else null end, v_taxa, v_caixa, v_req, v_acr)
  returning numero_pedido into v_numero;

  insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
  select v_venda, _uuid(e->>'produtoId'), _uuid(e->>'comboId'), e->>'descricao', _num(e->>'quantidade', 1)::int, _num(e->>'valorUnitario'), _num(e->>'custoUnitario'),
         round(_num(e->>'quantidade', 1) * _num(e->>'valorUnitario'), 2),
         coalesce((select array_agg(_uuid(x)) filter (where _uuid(x) is not null) from jsonb_array_elements_text(e->'adicionaisIds') x), '{}')
  from jsonb_array_elements(v_itens_ok) e;

  insert into pagamentos_venda (venda_id, forma_pagamento, valor, taxa_aplicada, acrescimo)
  values (v_venda, v_forma_nome, v_total, case when v_eh_mesa or v_total <= 0 then 0 else round(v_total * v_forma.taxa_percentual / 100 + v_forma.taxa_fixa, 2) end, v_acr);
  if v_total <= 0 then update vendas set recebido_em = now() where id = v_venda; end if;

  if v_eh_mesa and v_mesa.status::text = 'Livre' then update mesas set status = 'Ocupada' where id = p_mesa_id; end if;
  perform _ajustar_estoque(v_itens_ok, 1, v_venda);
  if v_tel <> '' then v_cli := _upsert_cliente(v_tel, v_nome); end if;
  if v_user is not null and not v_eh_mesa then insert into contas_pedidos (venda_id, user_id) values (v_venda, v_user) on conflict do nothing; end if;
  if jsonb_array_length(v_bens) > 0 then
    for b in select value as e from jsonb_array_elements(v_bens) loop
      if b.e->>'tipo' = 'Fidelidade' then
        update fidelidade set carimbos = 0, premios_resgatados = premios_resgatados + 1, atualizada_em = now() where cliente_id = v_bc.cliente_id;
        insert into contas_beneficios (user_id, tipo, status, produto_id, venda_id, usado_em) values (v_user, 'Fidelidade', 'Usado', _uuid(b.e->>'produtoId'), v_venda, now());
      else
        update contas_beneficios set status = 'Usado', produto_id = _uuid(b.e->>'produtoId'), venda_id = v_venda, usado_em = now() where id = _uuid(b.e->>'id');
      end if;
    end loop;
  end if;
  if v_cod <> '' then
    insert into cupons_usos (cupom_id, codigo, venda_id, cliente_id, telefone, desconto, frete_gratis, requisicao_id, user_id)
    values ((v_cup->>'cupomId')::uuid, v_cup->>'codigo', v_venda, v_cli, v_tel, v_desc, v_frete, v_req, v_user);
    perform _conta_cupom_usado(v_user, (v_cup->>'cupomId')::uuid, v_venda);
  end if;
  perform _registrar_falha(v_chave, 600); perform _registrar_falha('pedcard_global', 300); perform _registrar_falha('pedcard_ip_' || v_ip, 600);
  perform _auditar_publico(case when v_eh_mesa then 'Pedido recebido pelo cliente na mesa ' || v_mesa.numero else 'Pedido recebido pelo Cardápio' end,
    'Total R$ ' || _dinheiro(v_total) || case when jsonb_array_length(v_bens) > 0 then ' | Brindes ' || jsonb_array_length(v_bens) else '' end || case when v_cod <> '' then ' | Cupom ' || (v_cup->>'codigo') else '' end, case when v_eh_mesa then v_nome else v_tel end);

  return jsonb_build_object('ok', true, 'message', 'Pedido enviado! Nº ' || v_numero || '. Total: R$ ' || _dinheiro(v_total) || '.',
    'id', v_venda, 'numero', v_numero, 'valorTotal', v_total, 'valorOriginal', v_orig, 'acrescimo', v_acr, 'valorDesconto', v_desc,
    'cupom', case when v_cod <> '' then v_cup->>'codigo' else '' end, 'freteGratis', v_frete);
end $_$;


--
-- Name: _cupom_calcular(text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cupom_calcular(p_codigo text, p_tel text, p_subtotal numeric, p_tipo text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select public._cupom_calcular(p_codigo, p_tel, p_subtotal, p_tipo, null::uuid) $$;


--
-- Name: _cupom_calcular(text, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cupom_calcular(p_codigo text, p_tel text, p_subtotal numeric, p_tipo text, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare c cupons%rowtype; v_cod text := upper(regexp_replace(btrim(coalesce(p_codigo, '')), '\s+', '', 'g'));
  v_tel text := _so_digitos(p_tel); v_bruto numeric := round(coalesce(p_subtotal, 0), 2); v_desc numeric := 0;
  v_agora timestamp := now() at time zone 'America/Sao_Paulo'; v_hh int; v_hi int; v_hf int; v_usos int; v_usos_cli int; v_fx record;
  v_conta contas_cliente; v_cc cupons_concedidos;
begin
  if v_cod = '' then return _falha('Informe um cupom.'); end if;
  select * into c from cupons where codigo = v_cod and ativa;
  if not found then return _falha('Cupom inválido ou inativo.'); end if;
  if p_user is not null then select * into v_conta from contas_cliente where user_id = p_user and aceite_versao > 0; end if;
  if (c.somente_conta or c.automatico is not null or c.cliente_id is not null) and v_conta.user_id is null then
    return _falha('Este cupom é para quem tem conta. Entre com a sua conta Google para usar.');
  end if;
  if c.cliente_id is not null and v_conta.cliente_id is distinct from c.cliente_id then
    return _falha('Este cupom não está disponível para a sua conta.');
  end if;
  if (c.data_inicio is not null and v_agora::date < c.data_inicio) or (c.data_fim is not null and v_agora::date > c.data_fim) then
    return _falha('Este cupom está fora do período de validade.');
  end if;
  if c.hora_inicio is not null and c.hora_fim is not null then
    v_hh := extract(hour from v_agora)::int * 60 + extract(minute from v_agora)::int;
    v_hi := extract(hour from c.hora_inicio)::int * 60 + extract(minute from c.hora_inicio)::int;
    v_hf := extract(hour from c.hora_fim)::int * 60 + extract(minute from c.hora_fim)::int;
    if v_hi <= v_hf then
      if v_hh < v_hi or v_hh > v_hf then return _falha('Este cupom está fora do período de validade.'); end if;
    else
      if v_hh < v_hi and v_hh > v_hf then return _falha('Este cupom está fora do período de validade.'); end if;
    end if;
  end if;
  if c.automatico is not null then
    select * into v_cc from cupons_concedidos
     where cupom_id = c.id and user_id = p_user and usado_em is null and (valido_ate is null or valido_ate >= v_agora::date)
     order by valido_ate nulls last, criado_em limit 1;
    if not found then return _falha('Você não tem este cupom disponível (ou ele já venceu).'); end if;
  end if;
  select count(*), count(*) filter (where (v_tel <> '' and _so_digitos(cu.telefone) = v_tel) or (p_user is not null and cu.user_id = p_user))
    into v_usos, v_usos_cli from cupons_usos cu where cu.cupom_id = c.id and not cu.anulado and not exists (select 1 from vendas vv where vv.id = cu.venda_id and vv.status = 'Cancelada');
  if c.limite_total > 0 and v_usos >= c.limite_total then return _falha('O limite de utilizações deste cupom foi atingido.'); end if;
  if c.automatico in ('boas_vindas', 'indicacao_indicado') then
    if v_usos_cli > 0 then return _falha('Este cupom já foi usado (uma vez por cliente).'); end if;
  elsif c.automatico is null and c.limite_por_cliente > 0 and v_usos_cli >= c.limite_por_cliente then
    return _falha('Você já atingiu o limite de uso deste cupom.');
  end if;
  if v_bruto < c.valor_minimo then return _falha('Este cupom exige pedido mínimo de R$ ' || replace(_dinheiro(c.valor_minimo), '.', ',') || '.'); end if;
  if c.tipo = 'percentual' then
    if c.valor <= 0 or c.valor > 100 then return _falha('Cupom configurado com percentual inválido.'); end if;
    v_desc := round(v_bruto * c.valor / 100, 2);
  elsif c.tipo = 'fixo' then
    if c.valor <= 0 then return _falha('Cupom configurado com valor inválido.'); end if;
    v_desc := least(v_bruto, round(c.valor, 2));
  elsif c.tipo = 'progressivo' then
    select (x->>'minimo')::numeric mn, (x->>'desconto')::numeric ds into v_fx from jsonb_array_elements(c.faixas) x where (x->>'minimo')::numeric <= v_bruto order by (x->>'minimo')::numeric desc limit 1;
    if v_fx.mn is null then
      select min((x->>'minimo')::numeric) into v_fx.mn from jsonb_array_elements(c.faixas) x;
      return _falha('Este cupom vale a partir de R$ ' || replace(_dinheiro(coalesce(v_fx.mn, 0)), '.', ',') || ' em pedidos.');
    end if;
    v_desc := least(v_bruto, round(v_fx.ds, 2));
  elsif c.tipo = 'frete' then
    v_desc := 0;
  else
    return _falha('Tipo de cupom não suportado.');
  end if;
  v_desc := round(least(v_desc, greatest(0, v_bruto - 0.01)), 2);
  return jsonb_build_object('ok', true, 'cupomId', c.id, 'codigo', c.codigo, 'nome', c.nome, 'tipo', c.tipo, 'desconto', v_desc,
    'freteGratis', (c.frete_gratis or c.tipo = 'frete'), 'acumula', c.acumula,
    'limiteRestante', case when c.limite_total > 0 then greatest(0, c.limite_total - v_usos - 1) else null end);
end $_$;


--
-- Name: cupons; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cupons (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo text NOT NULL,
    nome text,
    tipo text DEFAULT 'percentual'::text NOT NULL,
    valor numeric(10,2) DEFAULT 0 NOT NULL,
    frete_gratis boolean DEFAULT false NOT NULL,
    data_inicio date,
    data_fim date,
    hora_inicio time without time zone,
    hora_fim time without time zone,
    limite_total integer DEFAULT 0 NOT NULL,
    limite_por_cliente integer DEFAULT 1 NOT NULL,
    valor_minimo numeric(10,2) DEFAULT 0 NOT NULL,
    ativa boolean DEFAULT true NOT NULL,
    acumula boolean DEFAULT false NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    criado_por uuid,
    faixas jsonb DEFAULT '[]'::jsonb NOT NULL,
    somente_conta boolean DEFAULT false NOT NULL,
    cliente_id uuid,
    mensagem text DEFAULT ''::text NOT NULL,
    visivel_conta boolean DEFAULT false NOT NULL,
    automatico text,
    validade_dias integer DEFAULT 30 NOT NULL,
    CONSTRAINT cupons_automatico_chk CHECK (((automatico IS NULL) OR (automatico = ANY (ARRAY['boas_vindas'::text, 'aniversario'::text, 'indicacao_indicador'::text, 'indicacao_indicado'::text, 'em_risco'::text, 'vip'::text])))),
    CONSTRAINT cupons_validade_dias_chk CHECK (((validade_dias >= 1) AND (validade_dias <= 365)))
);


--
-- Name: _cupom_validar(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cupom_validar(p jsonb, p_id uuid, OUT erro text, OUT c public.cupons) RETURNS record
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare v_fx jsonb := '[]'::jsonb; f record; v_ant numeric := 0; v_n int := 0; v_cod text := upper(regexp_replace(btrim(coalesce(p->>'codigo', '')), '\s+', '', 'g'));
        v_tipo text := coalesce(nullif(btrim(p->>'tipo'), ''), 'percentual'); v_val numeric := _num(p->>'valor');
        v_auto text := nullif(btrim(coalesce(p->>'automatico', '')), ''); v_cli uuid := _uuid(nullif(btrim(coalesce(p->>'clienteId', '')), ''));
begin
  if v_cod !~ '^[A-Z0-9_-]{3,40}$' then erro := 'Código inválido. Use letras, números, _ ou -.'; return; end if;
  if btrim(coalesce(p->>'nome', '')) = '' then erro := 'Informe o nome da promoção.'; return; end if;
  if v_tipo <> all (array['percentual','fixo','frete','progressivo']) then erro := 'Tipo de cupom inválido.'; return; end if;
  if v_tipo = 'progressivo' then
    if jsonb_typeof(p->'faixas') <> 'array' or jsonb_array_length(p->'faixas') = 0 then erro := 'Informe ao menos uma faixa de desconto.'; return; end if;
    if jsonb_array_length(p->'faixas') > 10 then erro := 'No máximo 10 faixas.'; return; end if;
    for f in select _num(x->>'minimo') mn, _num(x->>'desconto') ds from jsonb_array_elements(p->'faixas') x order by 1 loop
      v_n := v_n + 1;
      if f.mn <= 0 or f.ds <= 0 then erro := 'Cada faixa precisa de pedido mínimo e desconto maiores que zero.'; return; end if;
      if f.ds >= f.mn then erro := 'O desconto de uma faixa tem que ser menor que o pedido mínimo dela.'; return; end if;
      if f.mn = v_ant then erro := 'Há duas faixas com o mesmo pedido mínimo.'; return; end if;
      v_ant := f.mn;
      v_fx := v_fx || jsonb_build_array(jsonb_build_object('minimo', round(f.mn, 2), 'desconto', round(f.ds, 2)));
    end loop;
    v_val := 0;
  elsif v_tipo <> 'frete' and v_val <= 0 then erro := 'Valor do benefício inválido.'; return; end if;
  if v_tipo = 'percentual' and v_val > 100 then erro := 'Percentual não pode ultrapassar 100%.'; return; end if;
  if exists (select 1 from cupons where codigo = v_cod and id is distinct from p_id) then erro := 'Já existe um cupom com esse código.'; return; end if;
  if v_auto is not null and v_auto <> all (array['boas_vindas','aniversario','indicacao_indicador','indicacao_indicado']) then erro := 'Tipo de cupom automático inválido.'; return; end if;
  if v_auto is not null and exists (select 1 from cupons where automatico = v_auto and id is distinct from p_id) then erro := 'Já existe um cupom automático desse tipo. Edite o que já existe.'; return; end if;
  if nullif(btrim(coalesce(p->>'clienteId', '')), '') is not null and v_cli is null then erro := 'Cliente inválido.'; return; end if;
  if v_cli is not null and not exists (select 1 from clientes where id = v_cli) then erro := 'Cliente não encontrado.'; return; end if;
  c.codigo := v_cod; c.nome := left(btrim(p->>'nome'), 80); c.tipo := v_tipo; c.valor := case when v_tipo = 'frete' then greatest(0, v_val) else round(v_val, 2) end; c.faixas := v_fx;
  c.frete_gratis := coalesce(p->>'freteGratis', '') in ('true', 't', 'Sim');
  c.data_inicio := _data_iso(btrim(coalesce(p->>'dataInicio', ''))); c.data_fim := _data_iso(btrim(coalesce(p->>'dataFim', '')));
  c.hora_inicio := _hora_valida(p->>'horaInicio'); c.hora_fim := _hora_valida(p->>'horaFim');
  c.limite_total := greatest(0, floor(_num(p->>'limiteTotal'))::int); c.limite_por_cliente := greatest(0, floor(_num(p->>'limitePorCliente'))::int);
  c.valor_minimo := greatest(0, round(_num(p->>'valorMinimo'), 2));
  c.ativa := coalesce(p->>'ativa', '') not in ('false', 'f', 'Não'); c.acumula := coalesce(p->>'acumula', '') in ('true', 't', 'Sim');
  c.automatico := v_auto; c.cliente_id := v_cli;
  c.somente_conta := (v_auto is not null) or (v_cli is not null) or coalesce(p->>'somenteConta', '') in ('true', 't', 'Sim');
  c.visivel_conta := (v_auto is null) and coalesce(p->>'visivelConta', '') in ('true', 't', 'Sim');
  c.mensagem := left(btrim(coalesce(p->>'mensagem', '')), 200);
  c.validade_dias := least(365, greatest(1, floor(_num(p->>'validadeDias', 30))::int));
end $_$;


--
-- Name: _custo_combo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._custo_combo(p_combo uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select round(sum(ci.quantidade * coalesce((select max(pp.custo) from produto_precos pp where pp.produto_id = ci.produto_id), 0)), 2)
  from combo_itens ci where ci.combo_id = p_combo
$$;


--
-- Name: _custo_receita(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._custo_receita(p_prod uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select round(sum(pi.quantidade_por_unidade * coalesce(e.custo_unitario, 0)), 2)
  from produto_ingredientes pi join estoque e on e.id = pi.ingrediente_id
  where pi.produto_id = p_prod
$$;


--
-- Name: _data_iso(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._data_iso(v text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
begin
  if v is null or v !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  return v::date;
exception when others then return null;
end $_$;


--
-- Name: _dinheiro(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._dinheiro(v numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select to_char(coalesce(v, 0), 'FM999999990.00')
$$;


--
-- Name: _dist_km(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._dist_km(a_lat double precision, a_lng double precision, b_lat double precision, b_lng double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select 6371 * 2 * atan2(sqrt(x), sqrt(1 - x)) from (
    select power(sin(radians(b_lat - a_lat) / 2), 2) + cos(radians(a_lat)) * cos(radians(b_lat)) * power(sin(radians(b_lng - a_lng) / 2), 2) as x) t
$$;


--
-- Name: _eh_dev(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._eh_dev() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from usuarios where id = auth.uid() and ativo and nivel::text = 'Desenvolvedor')
$$;


--
-- Name: _email_login(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._email_login(p_login text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select translate(lower(btrim(p_login)), 'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy') || '@usuarios.demo.app'
$$;


--
-- Name: _entrega_limpar_loc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._entrega_limpar_loc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status_pedido::text = 'Saiu para entrega' and new.status_pedido::text is distinct from 'Saiu para entrega' then
    delete from entregador_posicoes where venda_id = new.id;
  end if;
  if new.status_pedido::text in ('Entregue', 'Retirada', 'Servida') or new.status::text = 'Cancelada' then
    delete from entregador_posicoes where venda_id = new.id;
    delete from entrega_destinos where venda_id = new.id;
  end if;
  return new;
end $$;


--
-- Name: _erro_recorrente(text, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._erro_recorrente(p_desc text, p_valor numeric, p_dia numeric, p_period text, p_inicio text, p_termino text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when btrim(coalesce(p_desc, '')) = '' then 'Informe a descrição.'
    when coalesce(p_valor, 0) <= 0 then 'Informe um valor maior que zero.'
    when p_valor > 9999999 then 'Valor alto demais.'
    when p_dia is null or p_dia < 1 or p_dia > 31 or p_dia <> floor(p_dia) then 'O dia do vencimento deve ser de 1 a 31.'
    when _meses_periodicidade(p_period) is null then 'Periodicidade inválida.'
    when not _comp_valida(p_inicio) then 'Informe o mês de início.'
    when coalesce(p_termino, '') <> '' and (not _comp_valida(p_termino) or p_termino < p_inicio) then 'O término deve ser um mês igual ou depois do início.'
    else '' end
$$;


--
-- Name: _erro_senha_fraca(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._erro_senha_fraca(p_senha text, p_login text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
  select case
    when length(coalesce(p_senha, '')) < 8 then 'A senha precisa ter ao menos 8 caracteres.'
    when p_login is not null and lower(p_senha) = lower(p_login) then 'A senha não pode ser igual ao login.'
    when p_senha ~ '^(.)\1+$' or lower(p_senha) in ('12345678','123456789','1234567890','87654321','senha123','password','qwertyui','11111111')
      then 'Essa senha é fácil demais de adivinhar. Escolha outra.'
    else '' end
$_$;


--
-- Name: _estoque_proprio(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._estoque_proprio(p_atual uuid, p_nome text, p_ep jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_qtd numeric; v_un text;
begin
  if p_ep is null or jsonb_typeof(p_ep) <> 'object' or coalesce((p_ep->>'ativo')::boolean, false) is not true then
    return p_atual;   -- sem estoque próprio ativo: mantém o que já existia
  end if;
  v_un := coalesce(nullif(p_ep->>'unidade', ''), 'un');
  if v_un not in ('un','g','kg','ml','l') then v_un := 'un'; end if;
  if p_atual is not null and exists (select 1 from estoque where id = p_atual) then
    update estoque set ingrediente = p_nome, quantidade_minima = _num(p_ep->>'minimo'), unidade = v_un::unidade_estoque,
           custo_unitario = _num(p_ep->>'custo') where id = p_atual;   -- mantém a quantidade atual
    return p_atual;
  end if;
  select id into v_id from estoque where ingrediente = p_nome limit 1;   -- já existe um com esse nome: reaproveita
  if v_id is not null then return v_id; end if;
  v_id := gen_random_uuid(); v_qtd := _num(p_ep->>'quantidade');
  insert into estoque (id, ingrediente, quantidade, quantidade_minima, unidade, custo_unitario, status)
  values (v_id, p_nome, v_qtd, _num(p_ep->>'minimo'), v_un::unidade_estoque, _num(p_ep->>'custo'), 'Ativo');
  if v_qtd > 0 then
    insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
    values (v_id, 'Entrada', v_qtd, 0, v_qtd, 'Estoque inicial do cadastro', auth.uid());
  end if;
  return v_id;
end $$;


--
-- Name: _evento_json(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._evento_json(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('id', e.id, 'nome', e.nome, 'tipo', coalesce(e.tipo, ''), 'data', coalesce(e.data::text, ''),
    'horaInicio', coalesce(to_char(e.hora_inicio, 'HH24:MI'), ''), 'horaFim', coalesce(to_char(e.hora_fim, 'HH24:MI'), ''),
    'local', coalesce(e.local, ''), 'contratante', coalesce(e.contratante, ''), 'telefone', coalesce(e.telefone, ''), 'status', coalesce(e.status, 'Orçamento'),
    'valorContratado', e.valor_contratado, 'valorRecebido', e.valor_recebido, 'valorAReceber', e.valor_a_receber, 'custoTotal', e.custo_total,
    'resultado', e.resultado, 'observacoes', coalesce(e.observacoes, ''), 'criadoEm', e.criado_em, 'atualizadoEm', e.atualizado_em)
  from eventos e where e.id = p_id
$$;


--
-- Name: _excedeu(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._excedeu(p_chave text, p_max integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select falhas >= p_max and bloqueado_ate > now() from tentativas where chave = p_chave), false)
$$;


--
-- Name: _exige_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._exige_admin(p_senha text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare v_eu usuarios%rowtype; v_chave text; v_adm record; v_ok boolean;
begin
  select * into v_eu from usuarios where id = auth.uid() and ativo;
  if not found then return null; end if;
  v_chave := 'falhas_admin_' || lower(v_eu.login);
  if v_eu.nivel::text in ('Admin','Desenvolvedor') then
    if coalesce(p_senha, '') <> '' then
      if _excedeu(v_chave, 5) then return null; end if;
      select (au.encrypted_password = crypt(p_senha, au.encrypted_password)) into v_ok from auth.users au where au.id = v_eu.id;
      if not coalesce(v_ok, false) then
        perform _registrar_falha(v_chave);
        perform _auditar('Falha na senha de administrador', 'Tentativa por ' || v_eu.login);
        return null;
      end if;
      perform _limpar_falhas(v_chave);
    end if;
    perform set_config('app.autorizador', v_eu.login, true);
    return v_eu.login;
  end if;
  if coalesce(p_senha, '') = '' then return null; end if;
  if _excedeu(v_chave, 5) then return null; end if;
  select us.login into v_adm from usuarios us join auth.users au on au.id = us.id
    where us.nivel in ('Admin','Desenvolvedor') and us.ativo and au.encrypted_password = crypt(p_senha, au.encrypted_password) limit 1;
  if found then
    perform _limpar_falhas(v_chave);
    perform set_config('app.autorizador', v_adm.login, true);
    return v_adm.login;
  end if;
  perform _registrar_falha(v_chave);
  perform _auditar('Falha na senha de administrador', 'Tentativa por ' || v_eu.login);
  return null;
end $$;


--
-- Name: _falha(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._falha(p_msg text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object('ok', false, 'message', p_msg)
$$;


--
-- Name: _fiscal_empresa_ok(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._fiscal_empresa_ok() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
begin
  return coalesce((select _cnpj_valido(cnpj) and coalesce(razao_social, '') <> '' and coalesce(inscricao_estadual, '') <> '' and coalesce(logradouro, '') <> ''
                          and coalesce(numero, '') <> '' and coalesce(bairro, '') <> '' and coalesce(municipio, '') <> '' and codigo_municipio ~ '^[0-9]{7}$'
                          and uf ~ '^[A-Z]{2}$' and cep ~ '^[0-9]{8}$' and coalesce(csc_id, '') <> ''
                   from fiscal_empresa where id), false)
     and exists (select 1 from integracoes_segredos where chave = 'nfce_csc');
end $_$;


--
-- Name: _fiscal_perfis_ok(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._fiscal_perfis_ok() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return exists (select 1 from fiscal_perfis where ativo) and public._fiscal_sem_perfil_qtd() = 0;
end $$;


--
-- Name: _fiscal_sem_perfil_qtd(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._fiscal_sem_perfil_qtd() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return (select count(*) from produtos where ativo and public._perfil_fiscal_efetivo(id, null) is null)::int
       + (select count(*) from combos where ativo and public._perfil_fiscal_efetivo(null, id) is null)::int;
end $$;


--
-- Name: _gerar_despesas_recorrentes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gerar_despesas_recorrentes(p_comp text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v_ini date; v_dias int; v_dia int; v_venc date; v_meses int; v_n int := 0; v_lin int;
begin
  if not _comp_valida(p_comp) then return 0; end if;
  v_ini := (p_comp || '-01')::date;
  v_dias := extract(day from (v_ini + interval '1 month' - interval '1 day'))::int;
  for r in select * from despesas_recorrentes
            where ativa and inicio is not null and date_trunc('month', inicio)::date <= v_ini
              and (termino is null or v_ini <= date_trunc('month', termino)::date) loop
    v_meses := (extract(year from v_ini)::int * 12 + extract(month from v_ini)::int) - (extract(year from r.inicio)::int * 12 + extract(month from r.inicio)::int);
    continue when v_meses < 0 or v_meses % coalesce(_meses_periodicidade(r.periodicidade), 1) <> 0;
    v_dia := least(coalesce(r.dia_vencimento, 1), v_dias);
    v_venc := v_ini + (v_dia - 1);
    insert into despesas (data_hora, descricao, valor, observacao, status, categoria, vencimento, situacao, recorrente_id, competencia, saiu_do_caixa)
    values (_meio_dia(v_venc), r.descricao, r.valor, coalesce(r.observacao, ''), 'A pagar', coalesce(r.categoria, 'Outros'), v_venc, 'A pagar', r.id, p_comp, false)
    on conflict (recorrente_id, competencia) where recorrente_id is not null do nothing;
    get diagnostics v_lin = row_count;
    v_n := v_n + v_lin;
  end loop;
  if v_n > 0 then perform _auditar('Despesas mensais geradas', p_comp || ': ' || v_n || ' conta(s)'); end if;
  return v_n;
end $$;


--
-- Name: _hoje_br(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._hoje_br() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$ select (now() at time zone 'America/Sao_Paulo')::date $$;


--
-- Name: _hora_valida(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._hora_valida(v text) RETURNS time without time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
begin
  if v is null or btrim(v) !~ '^\d{1,2}:\d{2}(:\d{2})?$' then return null; end if;
  return btrim(v)::time;
exception when others then return null;
end $_$;


--
-- Name: _ia_mascara(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ia_mascara(j jsonb, p_adm boolean) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_object_agg(e.k,
           case when jsonb_typeof(e.v) = 'string' and e.k ~* '(texto|coment|observ|resumo|descri|mensagem|motivo|detalhe|solucao|pilha)'
                then to_jsonb(public._ia_scrub(e.v #>> '{}')) else e.v end), '{}'::jsonb)
  from jsonb_each(j) e(k, v)
  where not public._ia_oculta(e.k, p_adm)
$$;


--
-- Name: _ia_oculta(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ia_oculta(p_coluna text, p_adm boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select p_coluna ~* '(senha|hash|token|chave|secret|refresh|password|apikey|api_key)'
      or p_coluna ~* '(telefone|celular|whatsapp|^fone|endereco|complemento|^referencia$|^lat$|^lng$|latitude|longitude|e_?mail|cpf|cnpj|nascimento|^login$)'
      or (not p_adm and p_coluna ~* '(custo|taxa|valor_total|^total|_total|lucro|resultado|saldo|valor_contrat|valor_receb|valor_a_receber)')
$_$;


--
-- Name: _ia_provedor_descansando(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ia_provedor_descansando(p_prov text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with l as (select status, row_number() over (order by criado_em desc) rn from ai_log where provedor = p_prov and criado_em > now() - interval '5 minutes'),
       u as (select coalesce(min(rn), 1000) as rn_ok from l where status = 'ok')
  select (select count(*) from l, u where l.status = 'erro' and l.rn < u.rn_ok) >= 3
$$;


--
-- Name: _ia_scrub(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ia_scrub(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(regexp_replace(regexp_replace(coalesce(t,''),
    '(\+?55[\s.-]?)?\(?\d{2}\)?[\s.-]?9?\d{4}[\s.-]?\d{4}', '[telefone oculto]', 'g'),
    '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '[e-mail oculto]', 'g'),
    '\d{3}\.\d{3}\.\d{3}-\d{2}', '[cpf oculto]', 'g')
$$;


--
-- Name: _ia_tabelas(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ia_tabelas(p_adm boolean) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_adm then array[
    'adicionais','ajustes_pos_venda','auditoria','brindes','caixa_sessoes','categorias','chat_conversas','clientes',
    'combo_itens','combo_precos','combos','cupons','cupons_usos','despesas','despesas_recorrentes','entregas_fechadas',
    'estoque','eventos','eventos_custos','eventos_recebimentos','faq_publico','fechamentos_entrega','feedbacks','fidelidade',
    'formas_pagamento','indicacoes','integridade_checks','itens_venda','mesas','movimentacoes_estoque','ocorrencias',
    'pagamentos_venda','produto_adicionais','produto_ingredientes','produto_precos','produtos','promocoes','sangrias','vendas',
    -- ampliação (Admin e Desenvolvedor): entregas, atendimento, saúde do sistema. Continuam FORA: usuarios, senhas, chaves,
    -- tokens, códigos de mesa, segredos da IA e configuração da contingência.
    'pedido_destinos','entrega_destinos','entregador_posicoes','chat_mensagens','erros_cliente',
    'ai_log','ai_uso','usuarios','arquivo_historico','backups','sync_estado']
  else array[
    'adicionais','categorias','combo_itens','combo_precos','combos','cupons','estoque','faq_publico','formas_pagamento',
    'mesas','movimentacoes_estoque','produto_adicionais','produto_ingredientes','produto_precos','produtos','promocoes'] end
$$;


