--
-- Name: _ifood_aplicar_comissao(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_aplicar_comissao(p_venda uuid, p_comissao numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_tot numeric; v_soma numeric; v_maior uuid;
begin
  if p_venda is null or p_comissao is null or p_comissao < 0 then return; end if;
  select coalesce(sum(valor), 0) into v_tot from pagamentos_venda where venda_id = p_venda;
  if v_tot <= 0 then return; end if;
  update pagamentos_venda set taxa_aplicada = round(p_comissao * valor / v_tot, 2) where venda_id = p_venda;
  select coalesce(sum(taxa_aplicada), 0) into v_soma from pagamentos_venda where venda_id = p_venda;
  if round(p_comissao - v_soma, 2) <> 0 then
    select id into v_maior from pagamentos_venda where venda_id = p_venda order by valor desc limit 1;
    update pagamentos_venda set taxa_aplicada = taxa_aplicada + round(p_comissao - v_soma, 2) where id = v_maior;
  end if;
end $$;


--
-- Name: _ifood_enfileirar(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

