$$;


--
-- Name: _ifood_forma(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_forma() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select id from formas_pagamento where lower(nome) = 'ifood' order by preco_proprio desc limit 1
$$;


--
-- Name: _ifood_gravar_itens(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_gravar_itens(p_venda uuid, p_order jsonb, p_regravar boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare it jsonb; op jsonb; v_item ifood_itens%rowtype; v_op ifood_itens%rowtype; v_chave text; v_qtd int; v_tot numeric; v_ads uuid[]; v_desc text; v_custo numeric; v_sem int := 0; v_obs text; v_oq int;
        v_u numeric; v_pid uuid; v_cid uuid;
begin
  if p_regravar then
    perform _ajustar_estoque(_itens_da_venda(p_venda), -1, p_venda);
    delete from itens_venda where venda_id = p_venda;
  end if;
  for it in select value from jsonb_array_elements(coalesce(p_order->'items', '[]'::jsonb)) loop
    v_chave := coalesce(nullif(it->>'externalCode', ''), nullif(it->>'id', ''), 'sem-codigo-' || public._ifood_norm(it->>'name'));
    v_qtd := greatest(1, round(public._ifood_n(it->'quantity'))::int);
    v_tot := public._ifood_n(it->'totalPrice');
    if v_tot <= 0 then v_tot := public._ifood_n(it->'price'); end if;
    if v_tot <= 0 then v_tot := (public._ifood_n(it->'unitPrice') + public._ifood_n(it->'optionsPrice')) * v_qtd; end if;
    v_item := public._ifood_item_visto(v_chave, it->>'name', 'produto');
    v_ads := '{}'; v_desc := coalesce(it->>'name', 'Item iFood'); v_obs := nullif(btrim(coalesce(it->>'observations', '')), '');
    for op in select value from jsonb_array_elements(coalesce(it->'options', '[]'::jsonb)) loop
      v_op := public._ifood_item_visto(coalesce(nullif(op->>'externalCode', ''), nullif(op->>'id', ''), 'sem-codigo-' || public._ifood_norm(op->>'name')), op->>'name', 'opcao');
      v_oq := greatest(1, round(public._ifood_n(op->'quantity'))::int);
      v_desc := v_desc || ' + ' || coalesce(op->>'name', 'opção') || case when v_oq > 1 then ' x' || v_oq else '' end;
      if v_op.adicional_id is not null then
        for i in 1..(v_oq * v_qtd) loop v_ads := v_ads || v_op.adicional_id; end loop;
      end if;
    end loop;
    if v_obs is not null then v_desc := v_desc || ' (obs: ' || v_obs || ')'; end if;
    v_custo := 0;
    if v_item.produto_id is not null then select coalesce(min(custo), 0) into v_custo from produto_precos where produto_id = v_item.produto_id;
    elsif v_item.combo_id is not null then select coalesce(min(custo), 0) into v_custo from combo_precos where combo_id = v_item.combo_id;
    end if;
    if v_item.produto_id is null and v_item.combo_id is null and not v_item.ignorar then v_sem := v_sem + 1; v_desc := v_desc || ' [SEM LIGAÇÃO]'; end if;
    v_pid := case when v_item.ignorar then null else v_item.produto_id end; v_cid := case when v_item.ignorar then null else v_item.combo_id end;
    v_u := round(v_tot / v_qtd, 2);
    if v_qtd > 1 and round(v_u * v_qtd, 2) <> round(v_tot, 2) then
      insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
      values (p_venda, v_pid, v_cid, left(v_desc, 300), v_qtd - 1, v_u, round(v_custo, 2), round(v_u * (v_qtd - 1), 2), v_ads);
      insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
      values (p_venda, v_pid, v_cid, left(v_desc, 300), 1, round(v_tot, 2) - round(v_u * (v_qtd - 1), 2), round(v_custo, 2), round(v_tot, 2) - round(v_u * (v_qtd - 1), 2), '{}');
    else
      insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
      values (p_venda, v_pid, v_cid, left(v_desc, 300), v_qtd, v_u, round(v_custo, 2), round(v_tot, 2), v_ads);
    end if;
  end loop;
  perform _ajustar_estoque(_itens_da_venda(p_venda), 1, p_venda);
  return v_sem;
end $$;


--
-- Name: _ifood_gravar_pagamentos(uuid, jsonb, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_gravar_pagamentos(p_venda uuid, p_order jsonb, p_total numeric, p_entrega_ifood boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_pend numeric := public._ifood_n(p_order->'payments'->'pending'); v_dinheiro numeric; v_app numeric; v_pct numeric := 0; v_fixa numeric := 0;
        v_tx_app numeric; v_tx_din numeric;
begin
  select coalesce(taxa_percentual, 0), coalesce(taxa_fixa, 0) into v_pct, v_fixa from formas_pagamento where id = public._ifood_forma();
  v_pct := coalesce(v_pct, 0); v_fixa := coalesce(v_fixa, 0);
  v_dinheiro := case when p_entrega_ifood then 0 else round(least(greatest(v_pend, 0), p_total), 2) end;
  v_app := round(p_total - v_dinheiro, 2);
  v_tx_app := round(v_app * v_pct / 100 + v_fixa, 2);
  v_tx_din := round(v_dinheiro * v_pct / 100 + case when v_app > 0.009 then 0 else v_fixa end, 2);
  update pagamentos_venda set valor = 0, taxa_aplicada = 0 where venda_id = p_venda and forma_pagamento in ('iFood (pago no app)', 'iFood (pagar na entrega)');
  if v_app > 0.009 then
    update pagamentos_venda set valor = v_app, taxa_aplicada = v_tx_app where venda_id = p_venda and forma_pagamento = 'iFood (pago no app)';
    if not found then insert into pagamentos_venda (venda_id, forma_pagamento, valor, taxa_aplicada, acrescimo) values (p_venda, 'iFood (pago no app)', v_app, v_tx_app, 0); end if;
  end if;
  if v_dinheiro > 0.009 then
    update pagamentos_venda set valor = v_dinheiro, taxa_aplicada = v_tx_din where venda_id = p_venda and forma_pagamento = 'iFood (pagar na entrega)';
    if not found then insert into pagamentos_venda (venda_id, forma_pagamento, valor, taxa_aplicada, acrescimo) values (p_venda, 'iFood (pagar na entrega)', v_dinheiro, v_tx_din, 0); end if;
  end if;
  return case when v_dinheiro > 0.009 and v_app > 0.009 then 'iFood (pago no app) + iFood (pagar na entrega)' when v_dinheiro > 0.009 then 'iFood (pagar na entrega)' else 'iFood (pago no app)' end;
end $$;


--
-- Name: ifood_itens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ifood_itens (
    chave text NOT NULL,
    nome text NOT NULL,
    tipo text DEFAULT 'produto'::text NOT NULL,
    produto_id uuid,
    combo_id uuid,
    adicional_id uuid,
    ignorar boolean DEFAULT false NOT NULL,
    visto_em timestamp with time zone DEFAULT now() NOT NULL,
    ligado_em timestamp with time zone,
    ifood_item_id text,
    preco_ifood numeric,
    preco_visto_em timestamp with time zone,
    categoria text,
    pausado_por_nos boolean DEFAULT false NOT NULL,
    CONSTRAINT ifood_itens_tipo_check CHECK ((tipo = ANY (ARRAY['produto'::text, 'opcao'::text])))
);


--
-- Name: _ifood_item_visto(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_item_visto(p_chave text, p_nome text, p_tipo text) RETURNS public.ifood_itens
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare r ifood_itens%rowtype; v_u uuid;
begin
  insert into ifood_itens (chave, nome, tipo) values (p_chave, left(coalesce(nullif(p_nome, ''), p_chave), 200), p_tipo)
    on conflict (chave) do update set nome = excluded.nome, visto_em = now() returning * into r;
  if r.produto_id is null and r.combo_id is null and r.adicional_id is null and not r.ignorar then
    v_u := case when p_chave ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then p_chave::uuid end;
    if v_u is not null then
      if exists (select 1 from produtos where id = v_u) then update ifood_itens set produto_id = v_u, ligado_em = now() where chave = p_chave returning * into r;
      elsif exists (select 1 from combos where id = v_u) then update ifood_itens set combo_id = v_u, ligado_em = now() where chave = p_chave returning * into r;
      elsif p_tipo = 'opcao' and exists (select 1 from adicionais where id = v_u) then update ifood_itens set adicional_id = v_u, ligado_em = now() where chave = p_chave returning * into r;
      end if;
    end if;
  end if;
  return r;
end $_$;


--
-- Name: _ifood_n(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_n(j jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
begin
  if j is null then return 0; end if;
  return case jsonb_typeof(j)
    when 'number' then (j #>> '{}')::numeric
    when 'string' then coalesce(nullif(regexp_replace(j #>> '{}', '[^0-9.\-]', '', 'g'), '')::numeric, 0)
    when 'object' then public._ifood_n(coalesce(j->'value', j->'amount'))
    else 0 end;
exception when others then return 0;
end $$;


--
-- Name: _ifood_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_norm(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(lower(translate(coalesce(t, ''), 'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇç', 'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCc')), '[^a-z0-9]', '', 'g')
$$;


--
-- Name: _ifood_preco_sistema(public.ifood_itens); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_preco_sistema(p_item public.ifood_itens) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select pp.preco from produto_precos pp where pp.produto_id = p_item.produto_id and pp.forma_pagamento_id = public._ifood_forma()),
    (select min(pp.preco) from produto_precos pp where pp.produto_id = p_item.produto_id),
    (select cp.preco from combo_precos cp where cp.combo_id = p_item.combo_id and cp.forma_pagamento_id = public._ifood_forma()),
    (select min(cp.preco) from combo_precos cp where cp.combo_id = p_item.combo_id))
$$;


--
-- Name: _ifood_sugestao(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_sugestao(p_nome text, p_tipo text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n int; v_id uuid; v_nome text; v_k text := public._ifood_norm(p_nome);
begin
  if length(v_k) < 3 then return null; end if;
  if p_tipo = 'opcao' then
    select count(*), min(id::text)::uuid, min(nome) into v_n, v_id, v_nome from adicionais where ativo and public._ifood_norm(nome) = v_k;
    if v_n = 1 then return jsonb_build_object('tipo', 'adicional', 'id', v_id, 'nome', v_nome); end if;
  end if;
  select count(*), min(id::text)::uuid, min(nome) into v_n, v_id, v_nome from produtos where ativo and public._ifood_norm(nome) = v_k;
  if v_n = 1 then return jsonb_build_object('tipo', 'produto', 'id', v_id, 'nome', v_nome); end if;
  select count(*), min(id::text)::uuid, min(nome) into v_n, v_id, v_nome from combos where ativo and public._ifood_norm(nome) = v_k;
  if v_n = 1 then return jsonb_build_object('tipo', 'combo', 'id', v_id, 'nome', v_nome); end if;
  return null;
end $$;


--
-- Name: _ifood_trg_caixa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_trg_caixa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public._integracao_ligada('ifood') then return null; end if;
  if not coalesce((select (config->>'abrirFecharComCaixa')::boolean from integracoes_config where provedor = 'ifood'), false) then return null; end if;
  if tg_op = 'INSERT' and new.status::text = 'Aberto' then
    update ifood_loja set fechada_por_nos = false, pausada_ate = null where id;
    perform public._ifood_enfileirar('LOJA', 'loja_abrir', '{}'::jsonb);
  elsif tg_op = 'UPDATE' and old.status::text = 'Aberto' and new.status::text <> 'Aberto' then
    update ifood_loja set fechada_por_nos = true where id;
    perform public._ifood_enfileirar('LOJA', 'loja_fechar', '{}'::jsonb);
  end if;
  return null;
end $$;


--
-- Name: _ifood_trg_estoque(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_trg_estoque() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  if not public._integracao_ligada('ifood') then return null; end if;
  if not coalesce((select (config->>'pausarSemEstoque')::boolean from integracoes_config where provedor = 'ifood'), false) then return null; end if;
  if new.quantidade <= 0 and coalesce(old.quantidade, 1) > 0 then
    for r in select distinct ii.chave, ii.ifood_item_id from ifood_itens ii join produto_ingredientes pi on pi.produto_id = ii.produto_id
             where pi.ingrediente_id = new.id and ii.ifood_item_id is not null and not ii.pausado_por_nos and not ii.ignorar loop
      update ifood_itens set pausado_por_nos = true where chave = r.chave;
      insert into ifood_acoes (pedido_ifood, acao, dados) values ('LOJA', 'catalogo_pausar', jsonb_build_object('chave', r.chave, 'itemId', r.ifood_item_id)) on conflict do nothing;
    end loop;
  elsif new.quantidade > 0 and coalesce(old.quantidade, 0) <= 0 then
    for r in select distinct ii.chave, ii.ifood_item_id from ifood_itens ii join produto_ingredientes pi on pi.produto_id = ii.produto_id
             where pi.ingrediente_id = new.id and ii.pausado_por_nos
               and not exists (select 1 from produto_ingredientes p2 join estoque e2 on e2.id = p2.ingrediente_id where p2.produto_id = ii.produto_id and e2.quantidade <= 0) loop
      update ifood_itens set pausado_por_nos = false where chave = r.chave;
      insert into ifood_acoes (pedido_ifood, acao, dados) values ('LOJA', 'catalogo_retomar', jsonb_build_object('chave', r.chave, 'itemId', r.ifood_item_id)) on conflict do nothing;
    end loop;
  end if;
  return null;
exception when others then return null;
end $$;


--
-- Name: _ifood_trg_novo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_trg_novo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_venc boolean;
begin
  begin v_venc := coalesce(_caixa_vencido(_caixa_aberto_id()), false); exception when others then v_venc := false; end;
  perform _push_enviar('pedido', '🛵 Novo pedido iFood #' || coalesce(new.numero_pedido::text, ''),
    coalesce(new.tipo::text, '') || ' · R$ ' || replace(to_char(coalesce(new.valor_total, 0), 'FM9999990.00'), '.', ',')
      || case when v_venc then ' · ⚠️ caixa vencido: aceite e feche o caixa' else '' end,
    'pedido-' || new.id::text);
  return null;
exception when others then return null;
end $_$;


--
-- Name: _ifood_trg_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_trg_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r ifood_pedidos%rowtype;
begin
  if new.canal is distinct from 'iFood' then return null; end if;
  if not public._integracao_ligada('ifood') then return null; end if;
  select * into r from ifood_pedidos where venda_id = new.id;
  if not found or r.simulado or r.estado in ('cancelado', 'concluido') then return null; end if;
  if new.status = 'Cancelada' and old.status is distinct from 'Cancelada' then
    perform public._ifood_enfileirar(r.pedido_ifood, 'cancelar', jsonb_build_object('motivo', new.motivo_cancelamento));
  elsif new.status_pedido is distinct from old.status_pedido and new.status = 'Confirmada' then
    if new.status_pedido::text = 'Em preparo' then
      if r.estado = 'novo' then perform public._ifood_enfileirar(r.pedido_ifood, 'confirmar'); end if;
      perform public._ifood_enfileirar(r.pedido_ifood, 'iniciar_preparo');
    elsif new.status_pedido::text = 'Pronta' then
      perform public._ifood_enfileirar(r.pedido_ifood, 'pronto');
    elsif new.status_pedido::text = 'Saiu para entrega' and upper(coalesce(r.bruto->'delivery'->>'deliveredBy', '')) <> 'IFOOD' then
      perform public._ifood_enfileirar(r.pedido_ifood, 'despachar');
    end if;
  end if;
  return null;
end $$;


--
-- Name: _ifood_valores(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ifood_valores(p_order jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_sub numeric; v_fee numeric; v_ben numeric; v_loja numeric := 0; v_tem boolean := false; b jsonb; s jsonb; v_ifood boolean; v_total numeric;
begin
  v_sub := public._ifood_n(p_order->'total'->'subTotal');
  if v_sub <= 0 then
    select coalesce(sum(public._ifood_n(x->'totalPrice')), 0) into v_sub from jsonb_array_elements(case when jsonb_typeof(p_order->'items') = 'array' then p_order->'items' else '[]'::jsonb end) x;
  end if;
  v_fee := public._ifood_n(p_order->'total'->'deliveryFee');
  v_ben := public._ifood_n(p_order->'total'->'benefits');
  for b in select value from jsonb_array_elements(case when jsonb_typeof(p_order->'benefits') = 'array' then p_order->'benefits' else '[]'::jsonb end) loop
    for s in select value from jsonb_array_elements(case when jsonb_typeof(b->'sponsorshipValues') = 'array' then b->'sponsorshipValues' else '[]'::jsonb end) loop
      v_tem := true;
      if upper(coalesce(s->>'name', s->>'sponsor', '')) in ('MERCHANT', 'LOJA', 'RESTAURANT', 'RESTAURANTE') then v_loja := v_loja + public._ifood_n(s->'value'); end if;
    end loop;
  end loop;
  if not v_tem then v_loja := v_ben; end if;
  v_ifood := upper(coalesce(p_order->'delivery'->>'deliveredBy', '')) = 'IFOOD';
  if v_ifood then v_fee := 0; end if;
  if v_sub <= 0 then v_sub := greatest(public._ifood_n(p_order->'total'->'orderAmount') - v_fee + v_loja, 0); end if;
  v_total := greatest(round(v_sub - v_loja + v_fee, 2), 0.01);
  return jsonb_build_object('original', round(v_sub, 2), 'descontoLoja', round(v_loja, 2), 'descontoIfood', round(greatest(v_ben - v_loja, 0), 2),
    'taxaEntrega', round(v_fee, 2), 'total', v_total, 'entregaIfood', v_ifood);
end $$;


--
-- Name: _imposto_pct(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._imposto_pct(p_data date DEFAULT ((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select _num(e.value #>> '{}', 0) from sistema s
       cross join lateral jsonb_each(case when jsonb_typeof(s.valor) = 'object' then s.valor else '{}'::jsonb end) e
      where s.chave = 'ImpostoAliquotasMes' and e.key <= to_char(coalesce(p_data, (now() at time zone 'America/Sao_Paulo')::date), 'YYYY-MM')
      order by e.key desc limit 1),
    (select aliquota_simples from fiscal_empresa where id), 0)
$$;


--
-- Name: _integ_checklist_def(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._integ_checklist_def(p_prov text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case p_prov
    when 'ifood' then '[
      {"id":"conta_dev","titulo":"O dono criou a conta de desenvolvedor no iFood (precisa do CNPJ)"},
      {"id":"acesso","titulo":"Acesso liberado aos módulos Pedidos, Catálogo, Loja, Financeiro e Avaliações"},
      {"id":"chaves","titulo":"Client ID, Client Secret e código da loja digitados aqui","auto":true},
      {"id":"teste_conexao","titulo":"Teste de conexão deu certo","auto":true},
      {"id":"homologacao","titulo":"Homologação do iFood aprovada"},
      {"id":"itens","titulo":"Itens do iFood ligados aos produtos (aba Itens do iFood)"},
      {"id":"equipe","titulo":"Equipe avisada de como o pedido do iFood aparece"}]'::jsonb
    when 'nfce' then '[
      {"id":"contador","titulo":"O contador definiu NCM, CFOP e situação tributária de cada perfil"},
      {"id":"certificado","titulo":"Certificado digital A1 do restaurante pronto"},
      {"id":"sefaz","titulo":"Credenciamento na Sefaz-SP feito e CSC (código de segurança) obtido"},
      {"id":"focus","titulo":"Conta na Focus NFe criada e empresa cadastrada lá (com o certificado)"},
      {"id":"token","titulo":"Token da Focus digitado aqui","auto":true},
      {"id":"empresa","titulo":"Dados fiscais da empresa preenchidos aqui","auto":true},
      {"id":"perfis","titulo":"Todos os produtos têm perfil fiscal","auto":true},
      {"id":"nota_teste","titulo":"Nota de teste (homologação) emitida e conferida pelo contador"}]'::jsonb
    when 'mercadopago' then '[
      {"id":"conta_vendedor","titulo":"Conta de vendedor criada no Mercado Pago (com a verificação de identidade)"},
      {"id":"chaves_teste","titulo":"Chaves de teste coladas","auto":true},
      {"id":"webhook","titulo":"Endereço do aviso (webhook) cadastrado no Mercado Pago","auto":true},
      {"id":"teste_guiado","titulo":"Teste guiado feito (Pix e cartão)","auto":true},
      {"id":"chaves_producao","titulo":"Chaves de produção coladas","auto":true}]'::jsonb
    else '[]'::jsonb end
$$;


