--
-- Name: _integ_pendencias(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._integ_pendencias(p_prov text, p_modo text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_out text[] := '{}'; v_item jsonb; v_ck jsonb; v_ok boolean;
begin
  select checklist into v_ck from integracoes_config where provedor = p_prov;
  for v_item in select * from jsonb_array_elements(_integ_checklist_def(p_prov)) loop
    if p_prov = 'mercadopago' and p_modo = 'homologacao' and (v_item->>'id') in ('teste_guiado', 'chaves_producao') then continue; end if;
    if coalesce((v_item->>'auto')::boolean, false) then
      v_ok := case v_item->>'id'
        when 'chaves' then (select count(*) from integracoes_segredos where chave in ('ifood_client_id', 'ifood_client_secret', 'ifood_merchant_id')) = 3
        when 'token' then exists (select 1 from integracoes_segredos where chave = 'nfce_token_' || p_modo)
        when 'empresa' then public._fiscal_empresa_ok()
        when 'perfis' then public._fiscal_perfis_ok()
        when 'chaves_teste' then (select count(*) from integracoes_segredos where chave in ('mp_public_key_teste', 'mp_access_token_teste')) = 2
        when 'webhook' then exists (select 1 from integracoes_segredos where chave = 'mp_webhook_secret')
        when 'teste_guiado' then exists (select 1 from formas_pagamento where aceita_online and tipo_online is not null)
                             and not exists (select 1 from formas_pagamento f where f.aceita_online and f.tipo_online is not null
                                   and not exists (select 1 from pagamentos_online g where g.mp_modo = 'homologacao' and g.metodo = f.tipo_online and g.status in ('aprovado', 'reembolso_parcial', 'reembolsado')))
        when 'chaves_producao' then (select count(*) from integracoes_segredos where chave in ('mp_public_key_producao', 'mp_access_token_producao')) = 2
        else coalesce((v_ck->>(v_item->>'id'))::boolean, false) end;
    else
      v_ok := coalesce((v_ck->>(v_item->>'id'))::boolean, false);
    end if;
    if not v_ok then v_out := v_out || (v_item->>'titulo'); end if;
  end loop;
  return v_out;
end $$;


