--
-- Name: _job_aniversarios(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._job_aniversarios() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; hoje date := _hoje_br(); v_ano text := extract(year from _hoje_br())::text; v_bissexto boolean; v_a int := extract(year from _hoje_br())::int;
begin
  v_bissexto := (v_a % 4 = 0 and (v_a % 100 <> 0 or v_a % 400 = 0));
  for r in select user_id from contas_cliente
            where aceite_versao > 0 and data_nascimento is not null and criado_em < now() - interval '30 days'
              and ((extract(month from data_nascimento) = extract(month from hoje) and extract(day from data_nascimento) = extract(day from hoje))
                   or (not v_bissexto and extract(month from hoje) = 2 and extract(day from hoje) = 28 and extract(month from data_nascimento) = 2 and extract(day from data_nascimento) = 29))
  loop
    if _conceder_cupom_auto('aniversario', r.user_id, v_ano) then n := n + 1; end if;
  end loop;
  return n;
end $$;


--
-- Name: _job_campanhas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._job_campanhas() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n_risco int := 0; n_vip int := 0; hoje date := _hoje_br();
  v_tri text := extract(year from _hoje_br())::int || '-Q' || extract(quarter from _hoje_br())::int;
begin
  for r in select * from _campanha_candidatos() where segmento in ('Em risco', 'VIP') loop
    if r.segmento = 'Em risco' then
      if not exists (select 1 from cupons_concedidos cc where cc.user_id = r.user_id and cc.origem = 'em_risco' and cc.criado_em > now() - interval '60 days')
         and _conceder_cupom_auto('em_risco', r.user_id, hoje::text) then
        n_risco := n_risco + 1;
        perform _push_campanha_conta(r.user_id, '💌 Sentimos sua falta!', 'Um cupom do Restaurante Demo está esperando por você em Minha conta › Cupons.', 'campanha-risco');
      end if;
    else
      if _conceder_cupom_auto('vip', r.user_id, v_tri) then
        n_vip := n_vip + 1;
        perform _push_campanha_conta(r.user_id, '⭐ Cupom VIP para você', 'Obrigado por ser cliente VIP! Seu cupom está em Minha conta › Cupons.', 'campanha-vip');
      end if;
    end if;
  end loop;
  return jsonb_build_object('emRisco', n_risco, 'vip', n_vip);
end $$;


--
-- Name: _job_contas_inativas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._job_contas_inativas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; v_anos int := coalesce((select _num(valor #>> '{}')::int from sistema where chave = 'LgpdAnosAnonimizar'), 3);
begin
  if v_anos < 1 then return 0; end if;
  for r in select cc.user_id, cc.cliente_id from contas_cliente cc
            left join clientes cl on cl.id = cc.cliente_id
           where cc.aceite_versao > 0
             and greatest(cc.criado_em, coalesce(cc.ultimo_acesso, cc.criado_em)) < now() - make_interval(years => v_anos)
             and not exists (select 1 from contas_pedidos cp join vendas v on v.id = cp.venda_id where cp.user_id = cc.user_id and v.data_hora >= now() - make_interval(years => v_anos))
             and (cl.id is null or not exists (select 1 from vendas v where _so_digitos(coalesce(cl.telefone, '')) <> '' and _so_digitos(v.telefone_cliente) = _so_digitos(cl.telefone) and v.data_hora >= now() - make_interval(years => v_anos)))
           limit 100
  loop
    if r.cliente_id is not null then perform _anonimizar_cliente(r.cliente_id); end if;
    update vendas set cliente_nome = 'Cliente anonimizado', telefone_cliente = '', endereco = '', complemento = '', referencia = '', observacoes_entrega = '', cpf_nota = null
     where id in (select venda_id from contas_pedidos where user_id = r.user_id);
    update cupons_usos set user_id = null where user_id = r.user_id;
    delete from contas_cliente where user_id = r.user_id;
    delete from auth.users where id = r.user_id;
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: _job_contas_sem_aceite(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._job_contas_sem_aceite() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0;
begin
  for r in select user_id from contas_cliente where aceite_versao = 0 and criado_em < now() - interval '7 days' limit 200 loop
    delete from contas_cliente where user_id = r.user_id;
    delete from auth.users where id = r.user_id;
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: _job_lgpd_anonimizar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._job_lgpd_anonimizar() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; v_anos int := coalesce((select _num(valor #>> '{}')::int from sistema where chave = 'LgpdAnosAnonimizar'), 3);
begin
  if v_anos < 1 then return 0; end if;
  for r in select c.id from clientes c
            where c.nome <> 'Cliente anonimizado'
              and greatest(c.criado_em, coalesce((select max(v.data_hora) from vendas v where v.cliente_id = c.id or (_so_digitos(c.telefone) <> '' and _so_digitos(v.telefone_cliente) = _so_digitos(c.telefone))), c.criado_em)) < now() - make_interval(years => v_anos)
              and not exists (select 1 from contas_cliente cc where cc.cliente_id = c.id)
            limit 200
  loop
    perform _anonimizar_cliente(r.id); n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: _job_mp_lgpd(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._job_mp_lgpd() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update pagamentos_online set pix_copia_cola = null, pix_qr_base64 = null, atualizado_em = now()
   where status <> 'aguardando' and (pix_copia_cola is not null or pix_qr_base64 is not null) and atualizado_em < now() - interval '2 days';
  return public._mp_anonimizar_reservas(null, 180);
end $$;


--
-- Name: _lancar_pagamento_entregador(uuid, uuid, date, numeric, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lancar_pagamento_entregador(p_fid uuid, p_entregador uuid, p_dia date, p_taxas numeric, p_pago numeric, p_forma text, p_caixa_aberto boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nome text; v_repasse numeric; v_ajuda numeric; v_sai boolean; v_rot text;
begin
  select coalesce(nullif(btrim(nome), ''), login) into v_nome from usuarios where id = p_entregador;
  v_sai := (p_forma = 'Dinheiro') and p_caixa_aberto;
  v_repasse := round(least(p_pago, p_taxas), 2);
  v_ajuda := round(p_pago - v_repasse, 2);
  v_rot := v_nome || ' (' || to_char(p_dia, 'DD/MM/YYYY') || ')';
  if v_repasse > 0 then
    insert into despesas (descricao, valor, status, situacao, categoria, saiu_do_caixa, observacao, requisicao_id)
    values ('Repasse de taxas de entrega — ' || v_rot, v_repasse, 'Paga', 'Paga', 'Entregadores', v_sai, 'Pago em ' || p_forma, 'ent-' || p_fid::text || '-taxas');
  end if;
  if v_ajuda > 0 then
    insert into despesas (descricao, valor, status, situacao, categoria, saiu_do_caixa, observacao, requisicao_id)
    values ('Ajuda de custo diária — ' || v_rot, v_ajuda, 'Paga', 'Paga', 'Entregadores', v_sai, 'Pago em ' || p_forma, 'ent-' || p_fid::text || '-ajuda');
  end if;
end $$;


