--
-- Name: _lista_curta(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lista_curta(p_itens text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select array_to_string(p_itens[1:6], ', ') || case when coalesce(array_length(p_itens, 1), 0) > 6 then ' e mais ' || (array_length(p_itens, 1) - 6) else '' end
$$;


--
-- Name: _lista_qr_mesas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lista_qr_mesas() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'numero', m.numero, 'codigo', c.codigo)
         order by case when m.numero ~ '^\d{1,9}$' then m.numero::int end, m.numero), '[]'::jsonb)
  from mesas m join mesas_codigos c on c.mesa_id = m.id
$_$;


--
-- Name: _login_de(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._login_de(p_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select login from usuarios where id = p_id
$$;


--
-- Name: _meio_dia(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._meio_dia(d date) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select (d::timestamp + interval '12 hours') at time zone 'America/Sao_Paulo'
$$;


--
-- Name: _mesa_numero_de(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mesa_numero_de(p_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select numero::text from public.mesas where id = p_id
$$;


--
-- Name: _mesa_qr(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mesa_qr(p_numero text, p_codigo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ip text := _ip_cliente(); v_cod text := btrim(coalesce(p_codigo, '')); v_id uuid;
begin
  if _excedeu('mesaqr_ip_' || v_ip, 15) or _excedeu('mesaqr_fail', 200) then
    return jsonb_build_object('ok', false, 'message', 'Muitas tentativas. Aguarde alguns minutos ou chame o garçom.');
  end if;
  select me.id into v_id from mesas me join mesas_codigos mc on mc.mesa_id = me.id
   where me.numero = btrim(coalesce(p_numero, '')) and v_cod <> '' and mc.codigo = v_cod;
  if v_id is null then
    perform _registrar_falha('mesaqr_ip_' || v_ip, 600); perform _registrar_falha('mesaqr_fail', 600);
    return jsonb_build_object('ok', false, 'invalido', true, 'message', 'QR Code inválido ou desativado. Chame o garçom.');
  end if;
  return jsonb_build_object('ok', true, 'mesaId', v_id);
end $$;


--
-- Name: _meses_periodicidade(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._meses_periodicidade(p text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case p when 'Mensal' then 1 when 'Bimestral' then 2 when 'Trimestral' then 3 when 'Semestral' then 6 when 'Anual' then 12 end
$$;


--
-- Name: _mp_anonimizar_reservas(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_anonimizar_reservas(p_user uuid DEFAULT NULL::uuid, p_dias integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n integer := 0;
begin
  if p_user is null and p_dias is null then return 0; end if;
  with alvo as (
    select r.id from pedidos_reserva r
     where (r.cliente_nome <> 'Cliente anonimizado' or r.telefone <> '' or r.dados_entrega is not null or r.observacoes <> '')
       and ((p_user is not null and r.user_id = p_user)
         or (p_dias is not null and r.estado <> 'ativa' and r.criado_em < now() - make_interval(days => p_dias)))
       and not exists (select 1 from pagamentos_online g where g.reserva_id = r.id and g.status = 'aprovado' and g.decisao_pendente and g.decisao is null)
  ), a as (
    update pedidos_reserva r set cliente_nome = 'Cliente anonimizado', telefone = '', dados_entrega = null, observacoes = '', atualizado_em = now()
      from alvo where r.id = alvo.id returning r.id
  ), b as (
    update pagamentos_online g set pix_copia_cola = null, pix_qr_base64 = null, cartao_final = null, atualizado_em = now()
     where g.reserva_id in (select id from a) returning g.id
  )
  select count(*) into n from a;
  return n;
end $$;


--
-- Name: _mp_confirmar_pagamento(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_confirmar_pagamento(p_pag uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare g pagamentos_online%rowtype; r pedidos_reserva%rowtype; v_motivo text; v_v jsonb;
begin
  select * into g from pagamentos_online where id = p_pag;
  if not found then return _falha('Pagamento não encontrado.'); end if;
  select * into r from pedidos_reserva where id = g.reserva_id for update;
  select * into g from pagamentos_online where id = p_pag for update;
  if g.status in ('reembolso_parcial', 'reembolsado') or g.venda_id is not null or g.decisao_pendente or g.decisao is not null then
    return jsonb_build_object('ok', true, 'duplicado', true);
  end if;
  update pagamentos_online set status = 'aprovado', aprovado_em = coalesce(aprovado_em, now()), erro = '', atualizado_em = now() where id = g.id;

  if r.estado = 'confirmada' then v_motivo := 'Já existe um pedido pago nesta reserva (pagamento em duplicidade)';
  elsif r.estado = 'expirada' then v_motivo := case when g.metodo = 'pix' then 'Pix pago depois de vencer' else 'Pagamento aprovado depois de a reserva vencer' end;
  elsif r.estado = 'cancelada' then v_motivo := 'Pagamento aprovado depois de a reserva ser cancelada';
  elsif not exists (select 1 from caixa_sessoes where status = 'Aberto') then v_motivo := 'Caixa fechado quando o pagamento foi aprovado';
  elsif _cardapio_bloqueio() is not null then v_motivo := 'Cardápio fechado quando o pagamento foi aprovado';
  end if;
  if v_motivo is not null then
    perform _mp_marcar_decidir(g.id, v_motivo);
    return jsonb_build_object('ok', true, 'decidir', true, 'motivo', v_motivo);
  end if;

  v_v := _mp_criar_venda(r.id, g.id);
  return jsonb_build_object('ok', true, 'vendaId', v_v->>'vendaId', 'numero', (v_v->>'numero')::int);
end $$;


--
-- Name: _mp_criar_venda(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_criar_venda(p_reserva uuid, p_pag uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare r pedidos_reserva%rowtype; f formas_pagamento%rowtype; v_caixa uuid; v_venda uuid := gen_random_uuid(); v_numero int; v_cli uuid;
        v_cod text; rec record; v_tipo venda_tipo; v_de jsonb; v_nome text; v_cc uuid;
begin
  select * into r from pedidos_reserva where id = p_reserva for update;
  if not found then raise exception 'Reserva não encontrada.'; end if;
  select * into f from formas_pagamento where id = r.forma_pagamento_id;
  v_nome := coalesce(f.nome, 'Pagamento online');
  select id into v_caixa from caixa_sessoes where status = 'Aberto' limit 1;
  if v_caixa is null then raise exception 'Caixa fechado.'; end if;
  v_tipo := (case when r.tipo_entrega = 'Entrega' then 'Entrega' else 'Retirada' end)::venda_tipo;
  v_de := coalesce(r.dados_entrega, '{}'::jsonb);
  v_cod := coalesce(r.cupom->>'codigo', '');

  insert into vendas (id, cliente_nome, telefone_cliente, forma_pagamento, valor_total, custo_total, status, tipo, status_pedido,
                      endereco, complemento, referencia, observacoes_entrega, status_pagamento, recebido_em, valor_original, valor_desconto,
                      desconto_detalhe, origem, mesa_id, taxa_entrega, caixa_id, requisicao_id, acrescimo_forma)
  values (v_venda, r.cliente_nome, r.telefone, v_nome, r.valor_total, r.custo_total, 'Confirmada', v_tipo, 'Recebido',
          case when v_tipo = 'Entrega' then coalesce(v_de->>'endereco', '') else '' end, case when v_tipo = 'Entrega' then coalesce(v_de->>'complemento', '') else '' end,
          case when v_tipo = 'Entrega' then coalesce(v_de->>'referencia', '') else '' end, r.observacoes, 'Pago', now(), r.valor_original, r.valor_desconto,
          case when v_cod <> '' then 'Cupom ' || v_cod else '' end, 'Cardápio', null, r.taxa_entrega, v_caixa, r.requisicao_id, r.acrescimo_forma)
  returning numero_pedido into v_numero;

  insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
  select v_venda, _uuid(e->>'produtoId'), _uuid(e->>'comboId'), e->>'descricao', _num(e->>'quantidade', 1)::int, _num(e->>'valorUnitario'), _num(e->>'custoUnitario'),
         round(_num(e->>'quantidade', 1) * _num(e->>'valorUnitario'), 2),
         coalesce((select array_agg(_uuid(x)) filter (where _uuid(x) is not null) from jsonb_array_elements_text(e->'adicionaisIds') x), '{}')
  from jsonb_array_elements(r.itens) e;

  insert into pagamentos_venda (venda_id, forma_pagamento, valor, taxa_aplicada, acrescimo)
  values (v_venda, v_nome, r.valor_total, round(r.valor_total * coalesce(f.taxa_percentual, 0) / 100 + coalesce(f.taxa_fixa, 0), 2), r.acrescimo_forma);

  if r.telefone <> '' then
    v_cli := _upsert_cliente(r.telefone, r.cliente_nome);
    perform _carimbar_fidelidade(r.telefone, r.cliente_nome);   -- como no recebimento manual: pedido pago = marca no cartão fidelidade
  end if;
  insert into contas_pedidos (venda_id, user_id) values (v_venda, r.user_id) on conflict do nothing;

  if r.cupom_uso_id is not null then update cupons_usos set venda_id = v_venda, cliente_id = v_cli where id = r.cupom_uso_id; end if;
  v_cc := _uuid(r.cupom->>'concedidoId');
  if v_cc is not null then update cupons_concedidos set venda_id = v_venda where id = v_cc; end if;
  for rec in select value as e from jsonb_array_elements(r.beneficios) loop
    if _uuid(rec.e->>'id') is not null then update contas_beneficios set venda_id = v_venda where id = _uuid(rec.e->>'id'); end if;
  end loop;

  update pedidos_reserva set estado = 'confirmada', venda_id = v_venda, atualizado_em = now() where id = r.id;
  update pagamentos_online set venda_id = v_venda, atualizado_em = now() where id = p_pag;
  perform _auditar_publico('Pedido pago pelo site (Mercado Pago)', 'Nº ' || v_numero || ' | Total R$ ' || _dinheiro(r.valor_total), r.telefone);
  return jsonb_build_object('vendaId', v_venda, 'numero', v_numero);
end $_$;


--
-- Name: _mp_marcar_decidir(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_marcar_decidir(p_pag uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update pagamentos_online set decisao_pendente = true, decisao = null, decisao_motivo = left(coalesce(p_motivo, ''), 200), atualizado_em = now() where id = p_pag;
  perform _auditar('Pagamento a decidir', 'Pagamento ' || p_pag || ' | ' || coalesce(p_motivo, ''), '');
end $$;


--
-- Name: _mp_prender(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_prender(p_reserva uuid, p_forcar boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare r pedidos_reserva%rowtype; rec record; v_cup jsonb; v_uso uuid; v_cc uuid; v_novo jsonb := '[]'::jsonb;
        v_cli uuid; v_fid fidelidade%rowtype; v_bid uuid; v_tipo text; v_prod uuid;
begin
  select * into r from pedidos_reserva where id = p_reserva for update;
  if not found then raise exception 'Reserva não encontrada.'; end if;

  if not r.estoque_reservado then perform _ajustar_estoque(r.itens, 1, null); end if;

  v_cup := r.cupom; v_uso := r.cupom_uso_id;
  if v_cup is not null and v_uso is null then
    insert into cupons_usos (cupom_id, codigo, venda_id, cliente_id, telefone, desconto, frete_gratis, requisicao_id, user_id)
    values ((v_cup->>'cupomId')::uuid, v_cup->>'codigo', null, null, r.telefone, coalesce((v_cup->>'desconto')::numeric, 0),
            coalesce((v_cup->>'freteGratis')::boolean, false), r.requisicao_id, r.user_id)
    returning id into v_uso;
    -- cupom automático da conta (boas-vindas, aniversário, indicação): segura o cupom recebido enquanto a reserva existir
    select id into v_cc from cupons_concedidos
     where cupom_id = (v_cup->>'cupomId')::uuid and user_id = r.user_id and usado_em is null and (valido_ate is null or valido_ate >= _hoje_br())
     order by valido_ate nulls last, criado_em limit 1 for update;
    if v_cc is not null then update cupons_concedidos set usado_em = now(), venda_id = null where id = v_cc; end if;
    v_cup := v_cup || jsonb_build_object('concedidoId', v_cc);
  end if;

  for rec in select value as e from jsonb_array_elements(r.beneficios) loop
    v_tipo := rec.e->>'tipo'; v_prod := _uuid(rec.e->>'produtoId'); v_bid := _uuid(rec.e->>'id');
    if v_tipo = 'Fidelidade' then
      select cc.cliente_id into v_cli from contas_cliente cc where cc.user_id = r.user_id;
      select * into v_fid from fidelidade where cliente_id = v_cli for update;
      if v_fid.id is not null and v_fid.carimbos >= 10 then
        update fidelidade set carimbos = 0, premios_resgatados = premios_resgatados + 1, atualizada_em = now() where cliente_id = v_cli;
        insert into contas_beneficios (user_id, tipo, status, produto_id, venda_id, usado_em) values (r.user_id, 'Fidelidade', 'Usado', v_prod, null, now())
          returning id into v_bid;
      elsif not p_forcar then
        raise exception 'O cartão fidelidade não está completo.';
      else
        v_bid := null;   -- seguiu à força: o item sai a R$ 0, mas o cartão não é mexido
      end if;
    elsif v_tipo = 'Indicação' then
      update contas_beneficios set status = 'Usado', produto_id = v_prod, usado_em = now()
       where id = v_bid and user_id = r.user_id and status = 'Disponível';
      if not found then
        if not p_forcar then raise exception 'O brinde de indicação não está mais disponível.'; end if;
        v_bid := null;
      end if;
    end if;
    v_novo := v_novo || jsonb_build_array(jsonb_build_object('tipo', v_tipo, 'id', v_bid, 'produtoId', v_prod));
  end loop;

  update pedidos_reserva set estoque_reservado = true, cupom = v_cup, cupom_uso_id = v_uso, beneficios = v_novo,
         brindes_reservados = jsonb_array_length(v_novo) > 0, atualizado_em = now()
   where id = r.id;
end $_$;


--
-- Name: _mp_publico(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_publico(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare c integracoes_config%rowtype; v_prod boolean; v_pk text; v_formas jsonb; v_min int; v_email text; v_visivel boolean;
begin
  select * into c from integracoes_config where provedor = 'mercadopago';
  if c.provedor is null or not c.ligado then return jsonb_build_object('ok', true, 'ligado', false); end if;
  v_prod := (c.modo = 'producao');
  if not v_prod then
    v_visivel := coalesce((c.config->>'testeNoCardapio')::boolean, false);
    if not v_visivel and p_user is not null and jsonb_typeof(c.config->'emailsTeste') = 'array' then
      select lower(email) into v_email from auth.users where id = p_user;
      v_visivel := v_email is not null and exists (select 1 from jsonb_array_elements_text(c.config->'emailsTeste') x where lower(btrim(x)) = v_email);
    end if;
    if not coalesce(v_visivel, false) then return jsonb_build_object('ok', true, 'ligado', false); end if;
  end if;
  select valor into v_pk from integracoes_segredos where chave = case when v_prod then 'mp_public_key_producao' else 'mp_public_key_teste' end;
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'tipo', f.tipo_online) order by f.ordem), '[]'::jsonb) into v_formas
    from formas_pagamento f where f.ativa and f.visivel_cardapio and f.aceita_online and f.tipo_online is not null;
  if v_pk is null or jsonb_array_length(v_formas) = 0 then return jsonb_build_object('ok', true, 'ligado', false); end if;
  v_min := case when coalesce(c.config->>'pixValidadeMin', '') ~ '^[0-9]{1,3}$' then least(120, greatest(5, (c.config->>'pixValidadeMin')::int)) else 15 end;
  return jsonb_build_object('ok', true, 'ligado', true, 'modo', case when v_prod then 'producao' else 'teste' end,
    'publicKey', v_pk, 'formas', v_formas, 'pixValidadeMin', v_min);
end $_$;


--
-- Name: _mp_soltar(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mp_soltar(p_reserva uuid, p_estado text, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r pedidos_reserva%rowtype; rec record; v_cc uuid; v_cli uuid;
begin
  if p_estado not in ('expirada', 'cancelada') then raise exception 'Estado final inválido.'; end if;
  select * into r from pedidos_reserva where id = p_reserva for update;
  if not found or r.estado not in ('ativa', 'expirada', 'cancelada') then return; end if;   -- reserva já confirmada nunca é solta

  if r.estoque_reservado then perform _ajustar_estoque(r.itens, -1, null); end if;
  if r.cupom_uso_id is not null then update cupons_usos set anulado = true where id = r.cupom_uso_id and venda_id is null; end if;
  v_cc := _uuid(r.cupom->>'concedidoId');
  if v_cc is not null then update cupons_concedidos set usado_em = null, venda_id = null where id = v_cc and venda_id is null; end if;

  for rec in select value as e from jsonb_array_elements(r.beneficios) loop
    if _uuid(rec.e->>'id') is null then continue; end if;
    if rec.e->>'tipo' = 'Indicação' then
      update contas_beneficios set status = 'Disponível', venda_id = null, usado_em = null, produto_id = null
       where id = _uuid(rec.e->>'id') and venda_id is null and status = 'Usado';
    elsif rec.e->>'tipo' = 'Fidelidade' then
      update contas_beneficios set status = 'Anulado' where id = _uuid(rec.e->>'id') and venda_id is null and status = 'Usado';
      if found then
        select cc.cliente_id into v_cli from contas_cliente cc where cc.user_id = r.user_id;
        update fidelidade set carimbos = 10, premios_resgatados = greatest(0, premios_resgatados - 1), atualizada_em = now() where cliente_id = v_cli;
      end if;
    end if;
  end loop;

  update pedidos_reserva set estado = p_estado, motivo_fim = left(coalesce(p_motivo, ''), 200), estoque_reservado = false, brindes_reservados = false,
         cupom_uso_id = null, cupom = case when cupom is null then null else cupom - 'concedidoId' end, atualizado_em = now()
   where id = r.id;
end $$;


--
-- Name: _negado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._negado() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select jsonb_build_object('ok', false, 'message', 'Seu perfil não tem permissão para esta ação.')
$$;


--
-- Name: _nfce_canal_da_venda(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_canal_da_venda(p_origem text, p_tipo text, p_canal text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when p_canal = 'iFood' then 'ifood' when p_origem = 'Cardápio' then 'cardapio' when p_origem = 'Garçom' or p_tipo = 'Mesa' then 'mesa' else 'balcao' end
$$;


--
-- Name: _nfce_forma_codigo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_forma_codigo(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when lower(coalesce(p, '')) ~ 'dinheiro' then '01'
    when lower(coalesce(p, '')) ~ 'cr[eé]dito' then '03'
    when lower(coalesce(p, '')) ~ 'd[eé]bito' then '04'
    when lower(coalesce(p, '')) ~ 'pix' then '17'
    when lower(coalesce(p, '')) ~ 'alelo|vale|ticket|sodexo|refei|alimenta' then '10'
    else '99' end
$$;


--
-- Name: _nfce_forma_desc(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_forma_desc(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when public._nfce_forma_codigo(p) <> '99' then null
    else left(case
      when lower(coalesce(p,'')) ~ 'ifood' and lower(p) ~ 'entrega' and lower(p) ~ 'app' then 'iFood - parte no app, parte na entrega'
      when lower(coalesce(p,'')) ~ 'ifood' and lower(p) ~ 'entrega' then 'iFood - pagar na entrega'
      when lower(coalesce(p,'')) ~ 'ifood' then 'iFood - pago no app'
      else coalesce(nullif(btrim(p), ''), 'Outros') end, 60) end
$$;


--
-- Name: _nfce_iniciar_cancelamento(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_iniciar_cancelamento(p_id bigint, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n nfce_notas%rowtype; v_j text;
begin
  select * into n from nfce_notas where id = p_id for update;
  if not found or n.estado <> 'autorizada' then return; end if;
  if n.ambiente = 'simulado' then
    update nfce_notas set estado = 'cancelada', cancelada_em = now(), cancelar_pedido = false, atualizado_em = now() where id = p_id; return;
  end if;
  if n.emitida_em is null or now() - n.emitida_em > interval '28 minutes' then
    update nfce_notas set cancelar_manual = true, cancelar_pedido = false, atualizado_em = now(),
      erro_pt = 'Venda cancelada depois de 30 minutos da emissão: o cancelamento da nota precisa ser orientado pelo contador.' where id = p_id;
    perform public._integ_log('nfce', 'aviso', 'Venda cancelada fora do prazo da nota (' || n.ref || '): cancelar com o contador');
    return;
  end if;
  v_j := btrim(coalesce(p_motivo, 'Venda cancelada'));
  if length(v_j) < 15 then v_j := v_j || ' (cancelada no sistema)'; end if;
  update nfce_notas set estado = 'cancelando', cancelamento_motivo = left(v_j, 255), tentativas = 0, cancelar_pedido = false, proxima_tentativa = now(), emitir_apos = now(), trava_ate = null, atualizado_em = now() where id = p_id;
end $$;


--
-- Name: _nfce_traduzir(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_traduzir(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p is null or btrim(p) = '' then 'A nota foi rejeitada, sem explicação detalhada. Veja o registro e fale com o contador.'
    when p ~* 'ncm' then 'NCM inválido ou não aceito. Confira o NCM do perfil fiscal do produto (o contador informa).'
    when p ~* 'csosn|situa[cç][aã]o tribut|\mcst\M' then 'Situação tributária (CSOSN/CST) incompatível com o regime da empresa. Confira o perfil fiscal.'
    when p ~* 'cfop' then 'CFOP incompatível com a operação. Confira o perfil fiscal com o contador.'
    when p ~* 'csc' then 'CSC ou número do CSC inválido. Confira o CSC (Sefaz) em Dados fiscais e em Chaves.'
    when p ~* 'certificado' then 'Problema com o certificado digital A1 (vencido ou não enviado à Focus). Fale com o contador ou com a Focus.'
    when p ~* 'inscri[cç][aã]o estadual' then 'Inscrição estadual do emitente não confere. Confira em Dados fiscais da empresa.'
    when p ~* 'cnpj' then 'CNPJ do emitente não confere com o cadastrado na Focus/Sefaz.'
    when p ~* 'duplicidade|duplicad|j[aá] existe|ja existe' then 'Já existe nota para esta venda. Use "Consultar na Focus" antes de reemitir.'
    when p ~* 'data.*(emiss|atras)|atrasad' then 'Horário da emissão fora do permitido (máximo 5 minutos de diferença). Confira o relógio e reemita.'
    when p ~* 'pagamento|total' then 'Soma dos pagamentos diferente do total da nota. Confira descontos, taxa de entrega e acréscimos da venda com o contador.'
    when p ~* 'token|permiss|n[aã]o autorizado|unauthorized|forbidden|acesso negado' then 'A Focus recusou o token. Confira o token (teste × produção) em Chaves.'
    when p ~* 'sefaz|indispon|offline|timeout|conting' then 'A Sefaz está fora do ar ou lenta. O sistema tenta de novo sozinho.'
    else 'Rejeitada: ' || left(p, 220) end
$$;


--
-- Name: _nfce_trg_cancelada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_trg_cancelada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n nfce_notas%rowtype;
begin
  if not public._integracao_ligada('nfce') then return null; end if;
  begin
    if new.status::text <> 'Cancelada' or old.status::text = 'Cancelada' then return null; end if;
    select * into n from nfce_notas where venda_id = new.id for update;
    if not found then return null; end if;
    if n.estado in ('pendente', 'pendencia', 'rejeitada', 'erro', 'dispensada') then
      update nfce_notas set estado = 'dispensada', erro_pt = 'Venda cancelada antes da emissão: não há nota.', atualizado_em = now() where id = n.id;
    elsif n.estado in ('duvida', 'contingencia', 'emitindo') then
      update nfce_notas set cancelar_pedido = true, atualizado_em = now() where id = n.id;
    elsif n.estado = 'autorizada' then
      perform public._nfce_iniciar_cancelamento(n.id, 'Venda cancelada: ' || coalesce(nullif(btrim(new.motivo_cancelamento), ''), 'erro de operação'));
    end if;
  exception when others then
    perform public._integ_log('nfce', 'erro', 'Não consegui tratar a nota da venda cancelada ' || coalesce(new.numero_pedido::text, '?') || ': ' || sqlerrm);
  end;
  return null;
end $$;


--
-- Name: _nfce_trg_venda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._nfce_trg_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c integracoes_config%rowtype; v_canal text; v_ok boolean;
begin
  if not public._integracao_ligada('nfce') then return null; end if;
  begin
    if new.status::text <> 'Confirmada' then return null; end if;
    select * into c from integracoes_config where provedor = 'nfce';
    if c.ligado_em is not null and new.data_hora < c.ligado_em then return null; end if;
    v_canal := public._nfce_canal_da_venda(new.origem::text, new.tipo::text, new.canal);
    if not (c.config->'canais' ? v_canal) then return null; end if;
    v_ok := case when coalesce(c.config->>'emitirQuando', 'pagamento') = 'entrega'
                 then new.status_pedido::text in ('Entregue', 'Retirada', 'Servida')
                 else new.status_pagamento::text = 'Pago' end;
    if not v_ok then return null; end if;
    insert into nfce_notas (venda_id, ref, ambiente, valor, cpf, emitir_apos, proxima_tentativa)
      values (new.id, new.id::text, c.modo, new.valor_total, new.cpf_nota, now() + interval '45 seconds', now() + interval '45 seconds')
      on conflict (venda_id) do nothing;
  exception when others then
    perform public._integ_log('nfce', 'erro', 'Não consegui preparar a nota da venda ' || coalesce(new.numero_pedido::text, '?') || ': ' || sqlerrm);
  end;
  return null;
end $$;


--
-- Name: _norm_cidade(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._norm_cidade(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select btrim(regexp_replace(regexp_replace(lower(translate(coalesce(t,''),
    'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇáàâãäéèêëíìîïóòôõöúùûüç', 'AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc')),
    '\s*([-/,]\s*[a-z]{2})\s*$', ''), '\s+', ' ', 'g'))
$_$;


--
-- Name: _novo_codigo_indicacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._novo_codigo_indicacao() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v text; i int; alf text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
begin
  loop
    v := '';
    for i in 1..6 loop v := v || substr(alf, 1 + floor(random() * length(alf))::int, 1); end loop;
    exit when not exists (select 1 from contas_cliente where codigo_indicacao = v);
  end loop;
  return v;
end $$;


--
-- Name: _num(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._num(v text, padrao numeric DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  return coalesce(nullif(btrim(v), '')::numeric, padrao);
exception when others then
  return padrao;
end $$;


--
-- Name: vendas_numero_pedido_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.vendas_numero_pedido_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: vendas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    numero_pedido integer DEFAULT nextval('public.vendas_numero_pedido_seq'::regclass) NOT NULL,
    data_hora timestamp with time zone DEFAULT now() NOT NULL,
    cliente_id uuid,
    cliente_nome text,
    telefone_cliente text,
    forma_pagamento text,
    valor_total numeric(10,2) DEFAULT 0 NOT NULL,
    custo_total numeric(10,2) DEFAULT 0 NOT NULL,
    status public.venda_status DEFAULT 'Confirmada'::public.venda_status NOT NULL,
    motivo_cancelamento text,
    tipo public.venda_tipo DEFAULT 'Retirada'::public.venda_tipo NOT NULL,
    status_pedido public.status_pedido,
    endereco text,
    complemento text,
    referencia text,
    observacoes_entrega text,
    pronta_em timestamp with time zone,
    concluida_em timestamp with time zone,
    status_pagamento public.status_pagamento DEFAULT 'Pago'::public.status_pagamento NOT NULL,
    recebido_em timestamp with time zone,
    valor_original numeric(10,2),
    valor_desconto numeric(10,2) DEFAULT 0 NOT NULL,
    desconto_detalhe text,
    entregador_id uuid,
    saiu_em timestamp with time zone,
    origem public.origem_venda DEFAULT 'Balcão'::public.origem_venda NOT NULL,
    mesa_id uuid,
    taxa_entrega numeric(10,2) DEFAULT 0 NOT NULL,
    fechamento_entrega_id uuid,
    registrado_por uuid,
    inicio_preparo_em timestamp with time zone,
    caixa_id uuid,
    requisicao_id text,
    status_antes_suspensao text,
    acrescimo_forma numeric DEFAULT 0 NOT NULL,
    canal text,
    cpf_nota text,
    preferencias_cliente text,
    CONSTRAINT vendas_cpf_nota_check CHECK (((cpf_nota IS NULL) OR (cpf_nota ~ '^[0-9]{11}$'::text)))
);


--
-- Name: _pedido_trava(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pedido_trava(p jsonb, OUT v public.vendas, OUT erro jsonb) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  select * into v from vendas where id = _uuid(p->>'vendaId') for update;
  if not found then erro := _falha('Pedido não encontrado.');
  elsif v.status <> 'Confirmada' then erro := _falha('Este pedido foi cancelado.');
  elsif v.fechamento_entrega_id is not null then erro := _falha('Esta entrega já está em um fechamento — não pode mais ser alterada.');
  end if;
end $$;


--
-- Name: _perfil_fiscal_efetivo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._perfil_fiscal_efetivo(p_produto uuid, p_combo uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    case when p_produto is not null then (select coalesce(p.perfil_fiscal_id, c.perfil_fiscal_id) from produtos p left join categorias c on c.id = p.categoria_id where p.id = p_produto)
         else (select coalesce(b.perfil_fiscal_id, c.perfil_fiscal_id) from combos b left join categorias c on c.id = b.categoria_id where b.id = p_combo) end,
    (select perfil_padrao_id from fiscal_empresa where id))
$$;


--
-- Name: _pk_cols(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pk_cols(p_tabela text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select array_agg(a.attname::text order by k.ord)
  from pg_index i
  cross join lateral unnest(i.indkey::int2[]) with ordinality as k(attnum, ord)
  join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
  where i.indrelid = format('public.%I', p_tabela)::regclass and i.indisprimary
$$;


--
-- Name: _precos_ou_base(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._precos_ou_base(p jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- preço único: com precoBase, todas as formas recebem o mesmo preço (o que muda por forma é o acréscimo da forma de pagamento)
  select case when not (p ? 'precoBase') and jsonb_typeof(p->'precos') = 'array' and jsonb_array_length(p->'precos') > 0 then p->'precos'
    else coalesce((select jsonb_agg(jsonb_build_object('formaPagamentoId', f.id, 'preco', _num(p->>'precoBase'), 'custo', _num(p->>'custoBase'))) from formas_pagamento f), '[]'::jsonb) end
$$;


--
-- Name: _produto_gravar_adicionais(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._produto_gravar_adicionais(p_prod uuid, p_ads jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from produto_adicionais where produto_id = p_prod;
  insert into produto_adicionais (produto_id, adicional_id)
  select distinct p_prod, _uuid(x) from jsonb_array_elements_text(coalesce(p_ads, '[]'::jsonb)) x where _uuid(x) is not null
  on conflict (produto_id, adicional_id) do nothing;
end $$;


--
-- Name: _produto_gravar_precos(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._produto_gravar_precos(p_prod uuid, p_precos jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from produto_precos where produto_id = p_prod;
  insert into produto_precos (produto_id, forma_pagamento_id, preco, custo)
  select p_prod, _uuid(e->>'formaPagamentoId'), _num(e->>'preco'), _num(e->>'custo')
  from jsonb_array_elements(coalesce(p_precos, '[]'::jsonb)) e
  where _uuid(e->>'formaPagamentoId') is not null
  on conflict (produto_id, forma_pagamento_id) do update set preco = excluded.preco, custo = excluded.custo;
end $$;


--
-- Name: _produto_gravar_receita(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._produto_gravar_receita(p_prod uuid, p_ingr jsonb, p_proprio uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from produto_ingredientes where produto_id = p_prod;
  insert into produto_ingredientes (produto_id, ingrediente_id, quantidade_por_unidade)
  select p_prod, _uuid(e->>'ingredienteId'), _num(e->>'quantidadePorUnidade')
  from jsonb_array_elements(coalesce(p_ingr, '[]'::jsonb)) e where _uuid(e->>'ingredienteId') is not null;
  if p_proprio is not null then
    insert into produto_ingredientes (produto_id, ingrediente_id, quantidade_por_unidade) values (p_prod, p_proprio, 1);
  end if;
end $$;


--
-- Name: _proteger_desenvolvedor_usuarios(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._proteger_desenvolvedor_usuarios() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_eu uuid := auth.uid();
  v_eh_dev boolean := false;
begin
  if tg_op = 'UPDATE' then
    if old.nivel::text <> 'Desenvolvedor' and new.nivel::text <> 'Desenvolvedor' then
      return new;
    end if;
  elsif tg_op = 'DELETE' then
    if old.nivel::text <> 'Desenvolvedor' then
      return old;
    end if;
  end if;

  select exists (
    select 1
    from public.usuarios u
    where u.id = v_eu
      and u.ativo
      and u.nivel::text = 'Desenvolvedor'
  ) into v_eh_dev;

  if not v_eh_dev then
    raise exception 'Acesso de Desenvolvedor é protegido: somente um Desenvolvedor pode alterar, promover ou excluir esse usuário.'
      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' then
    return new;
  end if;
  return old;
end;
$$;


--
-- Name: _push_campanha_conta(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_campanha_conta(p_user uuid, p_titulo text, p_texto text, p_tag text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_venda uuid;
begin
  select v.id into v_venda
    from contas_cliente c
    join vendas v on ((c.cliente_id is not null and v.cliente_id = c.cliente_id)
                      or (length(_so_digitos(c.telefone)) >= 8 and _so_digitos(v.telefone_cliente) = _so_digitos(c.telefone)))
    join push_cliente_pedidos l on l.venda_id = v.id
   where c.user_id = p_user
   order by v.data_hora desc limit 1;
  if v_venda is not null then
    perform _push_cliente_enviar(v_venda, p_titulo, p_texto, './', p_tag || '-' || p_user::text);
  end if;
exception when others then null;
end $$;


--
-- Name: _push_chat_cliente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_chat_cliente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.autor = 'cliente' and exists (select 1 from chat_conversas c where c.id = new.conversa_id and c.estado in ('recepcao','em_atendimento'))
     and not exists (select 1 from chat_mensagens m where m.conversa_id = new.conversa_id and m.autor = 'cliente' and m.id <> new.id and m.criado_em > now() - interval '2 minutes') then
    perform _push_enviar('chat', '💬 Cliente no atendimento', 'Há uma mensagem aguardando resposta.', 'chat-' || new.conversa_id::text);
  end if;
  return null;
end $$;


--
-- Name: _push_cliente_enviar(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_cliente_enviar(p_venda uuid, p_titulo text, p_texto text, p_url text, p_tag text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not exists (select 1 from push_cliente_pedidos where venda_id = p_venda) then return; end if;
  perform chamar_edge('push-enviar', jsonb_build_object('publico', true, 'vendaId', p_venda, 'tipo', 'cliente', 'titulo', p_titulo, 'texto', p_texto, 'url', p_url, 'tag', p_tag));
exception when others then null;
end $$;


--
-- Name: _push_clientes_feedback(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_clientes_feedback() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  for r in select distinct v.id, v.numero_pedido from push_cliente_pedidos l join vendas v on v.id = l.venda_id
           where l.feedback_pedido_em is null and v.status = 'Confirmada' and v.status_pedido in ('Entregue', 'Retirada')
             and coalesce(v.concluida_em, v.data_hora) between now() - interval '3 hours' and now() - interval '30 minutes'
             and not exists (select 1 from feedbacks f where f.venda_id = v.id)
  loop
    update push_cliente_pedidos set feedback_pedido_em = now() where venda_id = r.id;
    perform _push_cliente_enviar(r.id, '⭐ Como foi seu pedido?', 'Toque para dar uma nota. Leva 10 segundos.', './?feedback=' || right(r.id::text, 8), 'feedback-cli-' || r.id::text);
  end loop;
end $$;


--
-- Name: _push_enviar(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_enviar(p_tipo text, p_titulo text, p_texto text, p_tag text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not exists (select 1 from push_inscricoes limit 1) then return; end if;
  perform chamar_edge('push-enviar', jsonb_build_object('tipo', p_tipo, 'titulo', p_titulo, 'texto', p_texto, 'tag', p_tag));
exception when others then null;
end $$;


--
-- Name: _push_novo_pedido(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_novo_pedido() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_venc boolean := coalesce(_caixa_vencido(_caixa_aberto_id()), false);
begin
  if new.origem::text = 'Cardápio' then
    perform _push_enviar('pedido', '🍔 Novo pedido #' || coalesce(new.numero_pedido::text, ''),
      coalesce(new.tipo::text, '') || ' · R$ ' || replace(to_char(coalesce(new.valor_total, 0), 'FM9999990.00'), '.', ',')
        || case when v_venc then ' · ⚠️ caixa vencido: aceite e feche o caixa' else '' end,
      'pedido-' || new.id::text);
  end if;
  return null;
end $_$;


--
-- Name: _push_status_cliente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._push_status_cliente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n text := coalesce('nº ' || new.numero_pedido::text, ''); v_t text; v_x text; v_url text := './?pedido=' || right(new.id::text, 8);
begin
  if new.origem <> 'Cardápio' or new.mesa_id is not null then return null; end if;
  if new.status = 'Cancelada' and old.status is distinct from 'Cancelada' then
    v_t := '❌ Pedido ' || v_n || ' cancelado'; v_x := 'Toque para ver os detalhes.';
  elsif new.status = 'Confirmada' and new.status_pedido is distinct from old.status_pedido then
    case new.status_pedido::text
      when 'Em preparo' then if old.status_pedido::text = 'Suspenso' then return null; end if;
                             v_t := '👨‍🍳 Pedido ' || v_n || ' confirmado'; v_x := 'Já estamos preparando o seu pedido.';
      when 'Pronta' then if new.tipo::text <> 'Retirada' then return null; end if;
                         v_t := '✅ Pedido ' || v_n || ' pronto'; v_x := 'Já pode retirar no balcão.';
      when 'Saiu para entrega' then v_t := '🛵 Pedido ' || v_n || ' saiu para entrega'; v_x := 'Está a caminho!';
      when 'Entregue' then v_t := '😋 Pedido ' || v_n || ' entregue'; v_x := 'Bom apetite!';
      when 'Retirada' then v_t := '😋 Pedido ' || v_n || ' retirado'; v_x := 'Bom apetite!';
      else return null;
    end case;
  else return null;
  end if;
  perform _push_cliente_enviar(new.id, v_t, v_x, v_url, 'pedido-cli-' || new.id::text);
  return null;
end $$;


--
-- Name: _recalc_combos(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recalc_combos(p_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update combo_precos cp set custo = _custo_combo(cp.combo_id)
  where cp.combo_id = any(p_ids)
    and _custo_combo(cp.combo_id) is not null
    and cp.custo is distinct from _custo_combo(cp.combo_id);
end $$;


--
-- Name: _recalc_produtos(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recalc_produtos(p_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update produto_precos pp set custo = _custo_receita(pp.produto_id)
  where pp.produto_id = any(p_ids)
    and _custo_receita(pp.produto_id) is not null
    and pp.custo is distinct from _custo_receita(pp.produto_id);
end $$;


--
-- Name: _recalcular_evento(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recalcular_evento(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_contr numeric; v_custos numeric; v_rec numeric;
begin
  select valor_contratado into v_contr from eventos where id = p_id;
  if not found then return; end if;
  select coalesce(sum(valor), 0) into v_custos from eventos_custos where evento_id = p_id;
  select coalesce(sum(valor), 0) into v_rec from eventos_recebimentos where evento_id = p_id;
  update eventos set valor_recebido = v_rec, valor_a_receber = greatest(0, v_contr - v_rec), custo_total = v_custos,
         resultado = round(v_contr - v_custos, 2) where id = p_id;
end $$;


--
-- Name: _reembolso_ao_cancelar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._reembolso_ao_cancelar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status::text = 'Cancelada' and old.status::text <> 'Cancelada' and new.status_pagamento::text = 'Pago'
     and new.canal is distinct from 'iFood' then
    insert into public.reembolsos (venda_id, valor, forma_pagamento, motivo, cancelado_por)
    values (new.id, new.valor_total, coalesce(new.forma_pagamento,''), coalesce(new.motivo_cancelamento,''), auth.uid())
    on conflict (venda_id) do nothing;
  end if;
  return new;
end $$;


--
-- Name: _registrar_falha(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._registrar_falha(p_chave text, p_seg integer DEFAULT 600) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t tentativas%rowtype;
begin
  select * into t from tentativas where chave = p_chave for update;
  if not found then
    insert into tentativas (chave, falhas, bloqueado_ate) values (p_chave, 1, now() + make_interval(secs => p_seg));
    return 1;
  end if;
  if t.bloqueado_ate is null or t.bloqueado_ate <= now() then
    update tentativas set falhas = 1, bloqueado_ate = now() + make_interval(secs => p_seg) where chave = p_chave;
    return 1;
  end if;
  update tentativas set falhas = falhas + 1 where chave = p_chave;
  return t.falhas + 1;
end $$;


--
-- Name: _saldo_gaveta_aberta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._saldo_gaveta_aberta() RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s caixa_sessoes%rowtype; v_din numeric; v_desp numeric; v_sang numeric; v_nomes text[];
begin
  select * into s from caixa_sessoes where status = 'Aberto' limit 1;
  if not found then return null; end if;
  select coalesce(array_agg(nome), '{}') into v_nomes from formas_pagamento where permite_troco;
  if coalesce(array_length(v_nomes, 1), 0) = 0 then v_nomes := array['Dinheiro']; end if;
  select coalesce(sum(pv.valor), 0) into v_din from pagamentos_venda pv join vendas v on v.id = pv.venda_id
   where v.status = 'Confirmada' and v.status_pagamento <> 'A Receber' and coalesce(v.recebido_em, v.data_hora) >= s.abertura and pv.forma_pagamento = any(v_nomes);
  select coalesce(sum(valor), 0) into v_desp from despesas where status = 'Paga' and saiu_do_caixa and data_hora >= s.abertura;
  select coalesce(sum(valor), 0) into v_sang from sangrias where data_hora >= s.abertura;
  return round(s.fundo_caixa + v_din - v_desp - v_sang, 2);
end $$;


--
-- Name: _saude_ifood_extra(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._saude_ifood_extra() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l ifood_loja%rowtype; v_neg int; v_urg int; v_txt text := '';
begin
  select * into l from ifood_loja where id;
  select count(*), count(*) filter (where expira_em < now() + interval '3 minutes') into v_neg, v_urg from ifood_negociacoes where estado = 'aberta' and expira_em > now();
  if l.verificado_em is not null then v_txt := v_txt || ' · loja: ' || case when l.disponivel then 'ABERTA no iFood' else 'FECHADA/indisponível no iFood' end || case when l.pausada_ate is not null then ' (pausada até ' || to_char(l.pausada_ate at time zone 'America/Sao_Paulo', 'HH24:MI') || ')' else '' end; end if;
  if v_neg > 0 then v_txt := v_txt || ' · ' || v_neg || ' negociação(ões) de cancelamento esperando resposta' || case when v_urg > 0 then ' (URGENTE)' else '' end; end if;
  return v_txt;
end $$;


--
-- Name: _saude_integracoes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._saude_integracoes() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record; v_desc int; e ifood_estado%rowtype; v_min numeric; v_sem int; v_novos int; v_acoes int; v_nivel text; v_txt text; v_urg int;
        v_dec int; v_dec_velho int; v_venc int; v_err int;
begin
  if exists (select 1 from ai_segredos where provedor = 'nvidia') or exists (select 1 from ai_segredos where provedor = 'cloudflare') then
    select count(*) into v_desc from unnest(array['nvidia', 'cloudflare']) x(p) where _ia_provedor_descansando(x.p);
    v := v || jsonb_build_object('id', 'ia_extras', 'titulo', 'IAs de reserva (NVIDIA / Cloudflare)', 'nivel', case when v_desc > 0 then 'atencao' else 'ok' end,
      'texto', (select string_agg(x.rot || ': ' || case when not exists (select 1 from ai_segredos where provedor = x.p) then 'sem chave' when _ia_provedor_descansando(x.p) then 'descansando (erros recentes)' else 'pronta' end, ' · ')
                from (values ('nvidia', 'NVIDIA'), ('cloudflare', 'Cloudflare')) x(p, rot)));
  end if;
  if _integracao_ligada('ifood') then
    select * into e from ifood_estado where id;
    v_min := case when e.ultima_consulta_ok is null then null else extract(epoch from (now() - e.ultima_consulta_ok)) / 60 end;
    select coalesce(sum(itens_sem_ligacao), 0) into v_sem from ifood_pedidos where estado <> 'cancelado' and criado_em > now() - interval '7 days';
    select count(*) into v_novos from ifood_pedidos where estado = 'novo' and not simulado and criado_em < now() - interval '4 minutes';
    select count(*) into v_acoes from ifood_acoes where estado in ('erro', 'duvida') and criado_em > now() - interval '1 day';
    select count(*) into v_urg from ifood_negociacoes where estado = 'aberta' and expira_em > now() and expira_em < now() + interval '3 minutes';
    v_nivel := case when v_min is null or v_min > 2 or e.token_ok is false or v_novos > 0 or v_urg > 0 then 'problema' when v_acoes > 0 or v_sem > 0 or e.ultimo_erro is not null or exists (select 1 from ifood_negociacoes where estado = 'aberta' and expira_em > now()) then 'atencao' else 'ok' end;
    v_txt := case when v_min is null then 'Ligado, mas ainda sem nenhuma consulta bem-sucedida ao iFood.' else 'Última consulta ao iFood há ' || round(v_min, 1) || ' min' end
      || case when e.ultimo_pedido_em is not null then ' · último pedido às ' || to_char(e.ultimo_pedido_em at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI') else ' · nenhum pedido ainda' end
      || case when e.token_ok is false then ' · ACESSO RECUSADO (confira as chaves)' else '' end
      || case when v_novos > 0 then ' · ' || v_novos || ' pedido(s) esperando confirmação há mais de 4 min' else '' end
      || case when v_acoes > 0 then ' · ' || v_acoes || ' ação(ões) não confirmada(s) no iFood' else '' end
      || case when v_sem > 0 then ' · ' || v_sem || ' item(ns) sem ligação' else '' end || public._saude_ifood_extra();
    v := v || jsonb_build_object('id', 'ifood', 'titulo', 'iFood', 'nivel', v_nivel, 'texto', v_txt);
  end if;
  v := v || public._saude_nfce();
  if _integracao_ligada('mercadopago') then
    select count(*) into v_dec from pagamentos_online where decisao_pendente and decisao is null;
    select count(*) into v_dec_velho from pagamentos_online where decisao_pendente and decisao is null and atualizado_em < now() - interval '10 minutes';
    select count(*) into v_venc from pedidos_reserva pr where pr.estado = 'ativa' and pr.expira_em < now() - interval '3 minutes'
      and not exists (select 1 from pagamentos_online g where g.reserva_id = pr.id and (g.status = 'aprovado' or (g.decisao_pendente and g.decisao is null)));
    select count(*) into v_err from pagamentos_online where status = 'erro' and criado_em > now() - interval '1 hour';
    v_nivel := case when v_venc > 0 or v_dec_velho > 0 then 'problema' when v_dec > 0 or v_err > 0 then 'atencao' else 'ok' end;
    v_txt := 'Ligado (' || case when (select modo from integracoes_config where provedor = 'mercadopago') = 'producao' then 'produção' else 'teste' end || ')'
      || case when v_dec > 0 then ' · ' || v_dec || ' pagamento(s) esperando decisão (seguir ou reembolsar)' else '' end
      || case when v_venc > 0 then ' · ' || v_venc || ' reserva(s) vencida(s) não liberada(s) (confira o agendamento mp-expirar-reservas)' else '' end
      || case when v_err > 0 then ' · ' || v_err || ' erro(s) ao criar pagamento na última hora' else '' end;
    v := v || jsonb_build_object('id', 'mercadopago', 'titulo', 'Mercado Pago', 'nivel', v_nivel, 'texto', v_txt);
  end if;
  return v;
end $$;


--
-- Name: _saude_nfce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._saude_nfce() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v_rej int; v_pend int; v_atras int; v_cont int; v_man int; v_mes int; v_nivel text; v_txt text;
begin
  select * into r from integracoes_config where ligado and provedor = 'nfce';
  if not found then return '[]'::jsonb; end if;
  select count(*) filter (where estado in ('rejeitada', 'erro')), count(*) filter (where estado = 'pendencia'), count(*) filter (where estado in ('pendente', 'duvida', 'cancelando') and emitir_apos < now() - interval '10 minutes'),
         count(*) filter (where estado = 'contingencia'), count(*) filter (where cancelar_manual)
    into v_rej, v_pend, v_atras, v_cont, v_man from nfce_notas where criado_em > now() - interval '7 days' or cancelar_manual;
  select count(*) into v_mes from nfce_notas where estado in ('autorizada', 'cancelada') and ambiente = 'producao' and emitida_em >= date_trunc('month', now() at time zone 'America/Sao_Paulo') at time zone 'America/Sao_Paulo';
  v_nivel := case when v_atras > 0 or v_rej > 0 then 'problema' when v_pend > 0 or v_cont > 0 or v_man > 0 or v_mes >= 400 or public._fiscal_sem_perfil_qtd() > 0 then 'atencao' else 'ok' end;
  v_txt := 'Nota fiscal ligada (' || case when r.modo = 'producao' then 'produção' else 'teste' end || ')'
    || case when v_rej > 0 then ' · ' || v_rej || ' nota(s) rejeitada(s)/com erro' else '' end
    || case when v_atras > 0 then ' · ' || v_atras || ' nota(s) esperando há mais de 10 min' else '' end
    || case when v_pend > 0 then ' · ' || v_pend || ' parada(s) por pendência (ex.: item sem perfil)' else '' end
    || case when v_cont > 0 then ' · ' || v_cont || ' em contingência' else '' end
    || case when v_man > 0 then ' · ' || v_man || ' cancelamento(s) para o contador orientar' else '' end
    || case when v_mes >= 400 then ' · ' || v_mes || ' de 500 notas do plano usadas neste mês' else '' end
    || case when public._fiscal_sem_perfil_qtd() > 0 then ' · ' || public._fiscal_sem_perfil_qtd() || ' item(ns) sem perfil fiscal' else '' end;
  return jsonb_build_array(jsonb_build_object('id', 'nfce', 'titulo', 'Nota fiscal (NFC-e)', 'nivel', v_nivel, 'texto', v_txt));
end $$;


--
-- Name: _saude_uso_plano(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._saude_uso_plano() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
declare
  v_banco numeric; v_arq numeric; v_mau int; v_edge_dia int; v_ia_dia int; v_proj numeric;
  itens jsonb := '[]'::jsonb;
begin
  select pg_database_size(current_database()) / 1048576.0 into v_banco;
  begin select coalesce(sum((metadata->>'size')::bigint), 0) / 1048576.0 into v_arq from storage.objects; exception when others then v_arq := null; end;
  begin select count(*) into v_mau from auth.users where last_sign_in_at > now() - interval '30 days'; exception when others then v_mau := null; end;
  select count(*) into v_edge_dia from cron.job_run_details d join cron.job j on j.jobid = d.jobid
   where d.start_time > now() - interval '24 hours' and j.command ilike '%chamar_edge%'
     and (j.jobname not in ('ifood-sync-minuto') or public._integracao_ligada('ifood'))
     and (j.jobname not in ('nfce-emitir-minuto') or public._integracao_ligada('nfce'));
  select count(*) into v_ia_dia from ai_log where criado_em > now() - interval '24 hours';
  v_proj := (coalesce(v_edge_dia, 0) + coalesce(v_ia_dia, 0)) * 30;
  itens := itens || jsonb_build_object('id', 'uso_banco', 'titulo', 'Plano grátis: tamanho do banco',
    'nivel', case when v_banco >= 450 then 'problema' when v_banco >= 350 then 'atencao' else 'ok' end,
    'texto', replace(round(v_banco, 1)::text, '.', ',') || ' MB de 500 MB (' || replace(round(v_banco / 5, 1)::text, '.', ',') || '%).');
  if v_arq is not null then
    itens := itens || jsonb_build_object('id', 'uso_arquivos', 'titulo', 'Plano grátis: arquivos guardados',
      'nivel', case when v_arq >= 900 then 'problema' when v_arq >= 700 then 'atencao' else 'ok' end,
      'texto', replace(round(v_arq, 1)::text, '.', ',') || ' MB de 1 GB (' || replace(round(v_arq / 10.24, 1)::text, '.', ',') || '%).');
  end if;
  if v_mau is not null then
    itens := itens || jsonb_build_object('id', 'uso_usuarios', 'titulo', 'Plano grátis: usuários ativos no mês',
      'nivel', case when v_mau >= 45000 then 'problema' when v_mau >= 35000 then 'atencao' else 'ok' end,
      'texto', v_mau || ' de 50.000.');
  end if;
  itens := itens || jsonb_build_object('id', 'uso_funcoes', 'titulo', 'Plano grátis: chamadas às funções (estimativa)',
    'nivel', case when v_proj >= 450000 then 'problema' when v_proj >= 350000 then 'atencao' else 'ok' end,
    'texto', 'Cerca de ' || replace(to_char(round(v_proj), 'FM999G999G999'), ',', '.') || ' por mês, de 500.000 (' || replace(round(v_proj / 5000, 1)::text, '.', ',') || '%). Número aproximado, calculado pelas últimas 24 h; o oficial está no painel do Supabase (Settings → Usage).');
  return itens;
end $$;


--
-- Name: _segmento_cliente(integer, numeric, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._segmento_cliente(p_pedidos integer, p_total numeric, p_ultimo timestamp with time zone, p_dias_risco integer DEFAULT 45) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case
    when coalesce(p_pedidos,0) = 0 then 'Sem pedido'
    when p_ultimo < now() - (greatest(coalesce(p_dias_risco,45),1) || ' days')::interval then 'Em risco'
    when p_pedidos >= 10 or coalesce(p_total,0) >= 800 then 'VIP'
    when p_pedidos >= 4 then 'Fiel'
    else 'Novo' end
$$;


--
-- Name: _senha_confere(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._senha_confere(p_user uuid, p_senha text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
  select coalesce((select u.encrypted_password = crypt(p_senha, u.encrypted_password) from auth.users u where u.id = p_user), false)
$$;


--
-- Name: _so_digitos(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._so_digitos(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select regexp_replace(coalesce(t, ''), '\D', '', 'g')
$$;


--
-- Name: _texto_publico(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._texto_publico(t text, mx integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select btrim(left(btrim(replace(replace(regexp_replace(regexp_replace(coalesce(t, ''), '[' || chr(1) || '-' || chr(31) || chr(127) || ']+', ' ', 'g'), '[<>`]', '', 'g'), '"', '”'), '''', '’')), greatest(mx, 0)))
$$;


--
-- Name: _travar_unico_desenvolvedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._travar_unico_desenvolvedor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.nivel::text = 'Desenvolvedor' then
      raise exception 'O acesso de Desenvolvedor não pode ser excluído.' using errcode = '42501';
    end if;
    return old;
  end if;
  if new.nivel::text = 'Desenvolvedor' and (tg_op = 'INSERT' or old.nivel::text <> 'Desenvolvedor') then
    raise exception 'O acesso de Desenvolvedor já existe. Não é possível criar outro.' using errcode = '42501';
  end if;
  return new;
end $$;


