--
-- Name: _trg_combo_precos_custo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trg_combo_precos_custo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
