--
-- Name: _trg_conta_cancelada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trg_conta_cancelada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare u uuid; bf record;
begin
  begin
    -- devolve o cupom recebido que foi usado neste pedido
    update cupons_concedidos set usado_em = null, venda_id = null where venda_id = new.id;
    update cupons_usos set user_id = null, telefone = '' where venda_id = new.id and cupom_id in (select id from cupons where automatico is not null);
    -- brindes usados neste pedido voltam: o de indicação fica disponível de novo e o cartão fidelidade reabre
    update contas_beneficios set status = 'Disponível', venda_id = null, usado_em = null, produto_id = null where venda_id = new.id and tipo = 'Indicação' and status = 'Usado';
    for bf in select b.id, cc.cliente_id from contas_beneficios b join contas_cliente cc on cc.user_id = b.user_id where b.venda_id = new.id and b.tipo = 'Fidelidade' and b.status = 'Usado' loop
      update fidelidade set carimbos = 10, premios_resgatados = greatest(0, premios_resgatados - 1), atualizada_em = now() where cliente_id = bf.cliente_id;
      update contas_beneficios set status = 'Anulado' where id = bf.id;
    end loop;
    -- indique e ganhe: se o pedido cancelado era o único concluído do indicado, o prêmio ainda não usado perde o efeito
    select user_id into u from contas_pedidos where venda_id = new.id;
    if u is not null and not exists (select 1 from contas_pedidos cp join vendas v on v.id = cp.venda_id
                                      where cp.user_id = u and v.id <> new.id and v.status = 'Confirmada' and v.status_pedido in ('Entregue', 'Retirada', 'Servida')) then
      update contas_beneficios set status = 'Anulado' where tipo = 'Indicação' and ref = u::text and status = 'Disponível';
      update cupons_concedidos set usado_em = now() where ref = u::text and origem in ('indicacao_indicador', 'indicacao_indicado') and usado_em is null and venda_id is null;
    end if;
  exception when others then null;
  end;
  return null;
end $$;


--
-- Name: _trg_conta_vincular(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trg_conta_vincular() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare u uuid; c contas_cliente; v_cli uuid; v_dig text;
begin
  begin
    select user_id into u from contas_pedidos where venda_id = new.id;
    if u is null then return null; end if;
    select * into c from contas_cliente where user_id = u for update;
    if c.user_id is null or c.cliente_id is not null then return null; end if;
    v_dig := _so_digitos(new.telefone_cliente);
    if length(v_dig) < 10 then return null; end if;
    v_cli := _upsert_cliente(new.telefone_cliente, new.cliente_nome);
    if v_cli is null then return null; end if;
    if exists (select 1 from contas_cliente where cliente_id = v_cli and user_id <> u) then return null; end if;
    update contas_cliente set cliente_id = v_cli, telefone = v_dig, nome = case when nome = '' then left(btrim(coalesce(new.cliente_nome, '')), 80) else nome end where user_id = u;
    perform _conta_premiar_indicacao(u);
  exception when others then
    null;
  end;
  return null;
end $$;


--
-- Name: _trg_estoque_custo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trg_estoque_custo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform _recalc_produtos(array(select distinct produto_id from produto_ingredientes where ingrediente_id = new.id));
  return null;
end $$;


--
-- Name: _trg_estoque_unidade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trg_estoque_unidade() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare f numeric;
begin
  f := _converter_unidade(1, old.unidade::text, new.unidade::text);
  if f is null or f = 1 then return null; end if;
  update produto_ingredientes set quantidade_por_unidade = quantidade_por_unidade * f where ingrediente_id = new.id;
  update adicionais set quantidade_descontar = case when coalesce(quantidade_descontar, 0) = 0 then f else quantidade_descontar * f end
   where ingrediente_id = new.id;
  return null;
end $$;


--
-- Name: _trg_precos_combos_ins(); Type: FUNCTION; Schema: public; Owner: -
