--
-- Name: api_conta_exportar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_conta_exportar() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente := _conta_exigir(); cl clientes%rowtype;
begin
  if c.user_id is null then return _falha('Entre com a sua conta para continuar.'); end if;
  if c.cliente_id is not null then select * into cl from clientes where id = c.cliente_id; end if;
  return jsonb_build_object('ok', true, 'geradoEm', now(),
    'conta', jsonb_build_object('email', c.email, 'nome', c.nome, 'telefone', c.telefone, 'nascimento', c.data_nascimento, 'criadaEm', c.criado_em, 'aceiteEm', c.aceite_em, 'aceiteVersao', c.aceite_versao, 'receberPromocoes', c.promo_ok, 'codigoIndicacao', c.codigo_indicacao),
    'cadastroNoRestaurante', case when cl.id is null then null else jsonb_build_object('nome', cl.nome, 'telefone', cl.telefone, 'primeiroContato', cl.primeiro_contato) end,
    'enderecos', coalesce((select jsonb_agg(jsonb_build_object('apelido', apelido, 'endereco', endereco, 'numero', numero, 'cidade', cidade, 'complemento', complemento, 'referencia', referencia)) from contas_enderecos where user_id = c.user_id), '[]'::jsonb),
    'pedidos', coalesce((select jsonb_agg(p.j order by p.d) from (
        select v.data_hora d, jsonb_build_object('numero', v.numero_pedido, 'data', v.data_hora, 'status', v.status_pedido::text, 'cancelado', v.status = 'Cancelada', 'total', v.valor_total, 'forma', v.forma_pagamento, 'endereco', case when v.id in (select venda_id from contas_pedidos where user_id = c.user_id) then v.endereco end,
          'itens', (select coalesce(jsonb_agg(jsonb_build_object('descricao', i.descricao, 'quantidade', i.quantidade, 'valor', i.valor_total_item)), '[]'::jsonb) from itens_venda i where i.venda_id = v.id)) j
          from vendas v where v.id in (select venda_id from contas_pedidos where user_id = c.user_id) or (c.cliente_id is not null and (v.cliente_id = c.cliente_id or (c.telefone <> '' and _so_digitos(v.telefone_cliente) = c.telefone)))
        union all
        select s.data_hora, jsonb_build_object('numero', s.numero_pedido, 'data', s.data_hora, 'status', s.status_pedido, 'cancelado', s.status = 'Cancelada', 'total', s.valor_total, 'forma', s.forma_pagamento, 'endereco', case when s.user_id = c.user_id then s.endereco end,
          'itens', (select coalesce(jsonb_agg(jsonb_build_object('descricao', e->>'descricao', 'quantidade', (e->>'quantidade')::numeric)), '[]'::jsonb) from jsonb_array_elements(s.itens) e), 'arquivado', true)
          from vendas_resumo_arquivo s where s.user_id = c.user_id or (c.cliente_id is not null and (s.cliente_id = c.cliente_id or (c.telefone <> '' and s.telefone = c.telefone)))
      ) p), '[]'::jsonb),
    'cupons', coalesce((select jsonb_agg(jsonb_build_object('codigo', k.codigo, 'recebidoEm', g.criado_em, 'validoAte', g.valido_ate, 'usadoEm', g.usado_em)) from cupons_concedidos g join cupons k on k.id = g.cupom_id where g.user_id = c.user_id), '[]'::jsonb),
    'feedbacks', coalesce((select jsonb_agg(jsonb_build_object('data', f.data, 'nota', f.nota, 'comentario', f.comentario, 'resposta', f.resposta, 'respondidoEm', f.respondido_em) order by f.data) from feedbacks f where f.user_id = c.user_id), '[]'::jsonb),
    'fidelidade', (select jsonb_build_object('carimbos', f.carimbos, 'premiosResgatados', f.premios_resgatados) from fidelidade f where f.cliente_id = c.cliente_id));
end $$;


