  if c.cliente_id is not null then select * into f from fidelidade where cliente_id = c.cliente_id; end if;
  return jsonb_build_object('ok', true, 'vinculada', c.cliente_id is not null, 'carimbos', coalesce(f.carimbos, 0), 'premios', coalesce(f.premios_resgatados, 0));
end $$;


--
-- Name: api_conta_iniciar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_conta_iniciar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare uid uuid := auth.uid(); c contas_cliente; u record; v_ind uuid; v_cod text := upper(left(btrim(coalesce(p->>'indicacao', '')), 12)); v_nome text;
begin
  if uid is null then return _falha('Entre com a sua conta para continuar.'); end if;
  if auth_nivel() is not null then return _falha('Esta é uma conta da equipe. Para pedir como cliente, use outro e-mail.'); end if;
  if _excedeu('conta_ini_' || uid::text, 30) then return _falha('Muitas tentativas. Aguarde alguns minutos.'); end if;
  perform _registrar_falha('conta_ini_' || uid::text, 600);
  select * into c from contas_cliente where user_id = uid;
  if c.user_id is null then
    select id, email, raw_user_meta_data into u from auth.users where id = uid;
    if u.id is null then return _falha('Conta não encontrada.'); end if;
    v_nome := _texto_publico(coalesce(nullif(u.raw_user_meta_data->>'full_name', ''), u.raw_user_meta_data->>'name', ''), 80);
    if v_cod ~ '^[A-Z0-9]{4,12}$' then select user_id into v_ind from contas_cliente where codigo_indicacao = v_cod and aceite_versao > 0 and user_id <> uid; end if;
    insert into contas_cliente (user_id, email, nome, codigo_indicacao, indicado_por)
    values (uid, left(coalesce(u.email, ''), 200), v_nome, _novo_codigo_indicacao(), v_ind)
    on conflict (user_id) do nothing;
    select * into c from contas_cliente where user_id = uid;
  end if;
  update contas_cliente set ultimo_acesso = now() where user_id = uid;
  return jsonb_build_object('ok', true, 'precisaAceite', c.aceite_versao < _aviso_versao(), 'versaoAviso', _aviso_versao(),
    'conta', jsonb_build_object('email', c.email, 'nome', c.nome, 'telefone', c.telefone, 'nascimento', c.data_nascimento,
       'nascimentoEditavel', (c.nasc_alterado_em is null or c.nasc_alterado_em < now() - interval '180 days'),
       'codigoIndicacao', c.codigo_indicacao, 'promoOk', c.promo_ok, 'aceiteVersao', c.aceite_versao, 'vinculada', c.cliente_id is not null));
end $_$;


--
-- Name: api_conta_pedidos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_conta_pedidos() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente := _conta_exigir(); r jsonb;
begin
  if c.user_id is null then return _falha('Entre com a sua conta para continuar.'); end if;
  select coalesce(jsonb_agg(u.x order by (u.x->>'data') desc), '[]'::jsonb) into r from (
    select * from (
      select v.data_hora as d, jsonb_build_object('id', v.id, 'numero', v.numero_pedido, 'data', v.data_hora, 'status', case when v.status = 'Cancelada' then 'Cancelado' else v.status_pedido::text end,
          'tipo', v.tipo::text, 'total', v.valor_total, 'desconto', v.valor_desconto, 'forma', v.forma_pagamento,
          'itens', coalesce((select jsonb_agg(jsonb_build_object('produtoId', i.produto_id, 'comboId', i.combo_id, 'descricao', i.descricao, 'quantidade', i.quantidade, 'adicionaisIds', to_jsonb(i.adicionais_ids)))
                              from itens_venda i where i.venda_id = v.id), '[]'::jsonb),
          'feedback', (select jsonb_build_object('id', f.id, 'nota', f.nota, 'comentario', f.comentario, 'data', f.data, 'resposta', f.resposta, 'respondidoEm', f.respondido_em)
                         from feedbacks f where f.venda_id = v.id and f.user_id = c.user_id order by f.data desc limit 1)) as x
        from vendas v
       where v.origem::text = 'Cardápio' and v.mesa_id is null
         and (v.id in (select venda_id from contas_pedidos where user_id = c.user_id) or (c.cliente_id is not null and (v.cliente_id = c.cliente_id or (c.telefone <> '' and _so_digitos(v.telefone_cliente) = c.telefone))))
      union all
      select s.data_hora, jsonb_build_object('id', s.venda_id, 'numero', s.numero_pedido, 'data', s.data_hora, 'status', case when s.status = 'Cancelada' then 'Cancelado' else s.status_pedido end,
          'tipo', s.tipo, 'total', s.valor_total, 'desconto', s.valor_desconto, 'forma', s.forma_pagamento, 'itens', s.itens, 'arquivado', true,
          'feedback', (select jsonb_build_object('id', f.id, 'nota', f.nota, 'comentario', f.comentario, 'data', f.data, 'resposta', f.resposta, 'respondidoEm', f.respondido_em)
                         from feedbacks f where f.venda_id = s.venda_id and f.user_id = c.user_id order by f.data desc limit 1))
        from vendas_resumo_arquivo s
       where s.origem = 'Cardápio' and s.mesa_id is null
         and (s.user_id = c.user_id or (c.cliente_id is not null and (s.cliente_id = c.cliente_id or (c.telefone <> '' and s.telefone = c.telefone))))
    ) z order by d desc limit 30) u;
  return jsonb_build_object('ok', true, 'pedidos', r);
end $$;


--
-- Name: api_conta_preferencias(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_conta_preferencias(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente := _conta_exigir(); v_cli uuid; v_txt text;
begin
  if c.user_id is null then return _falha('Entre com a sua conta para continuar.'); end if;
  if length(_so_digitos(c.telefone)) < 8 then return _falha('Cadastre o seu telefone na conta para guardar preferências.'); end if;
  v_cli := coalesce(c.cliente_id, _upsert_cliente(c.telefone, c.nome));
  if p ? 'texto' then
    v_txt := _texto_publico(p->>'texto', 300);
    update clientes set preferencias = nullif(v_txt, '') where id = v_cli;
  end if;
  select preferencias into v_txt from clientes where id = v_cli;
  return jsonb_build_object('ok', true, 'preferencias', coalesce(v_txt, ''));
end $$;


--
-- Name: api_conta_salvar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_conta_salvar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente := _conta_exigir(); v_nasc date := _data_iso(btrim(coalesce(p->>'nascimento', ''))); v_nome text := _texto_publico(p->>'nome', 80);
begin
  if c.user_id is null then return _falha('Entre com a sua conta para continuar.'); end if;
  if v_nome = '' then return _falha('Informe o seu nome.'); end if;
  if v_nasc is not null and (v_nasc > _hoje_br() or v_nasc < date '1900-01-01') then return _falha('Data de nascimento inválida.'); end if;
  if v_nasc is distinct from c.data_nascimento and c.data_nascimento is not null and c.nasc_alterado_em > now() - interval '180 days' then
    return _falha('A data de nascimento só pode ser alterada uma vez a cada 6 meses.');
  end if;
  update contas_cliente set nome = v_nome, data_nascimento = v_nasc,
         nasc_alterado_em = case when v_nasc is distinct from data_nascimento then now() else nasc_alterado_em end,
         promo_ok = coalesce(case when p ? 'promo' then p->>'promo' in ('true', 't') end, promo_ok),
         promo_em = case when p ? 'promo' and (p->>'promo' in ('true', 't')) is distinct from promo_ok then now() else promo_em end
   where user_id = c.user_id;
  return jsonb_build_object('ok', true, 'message', 'Dados salvos.');
end $$;


--
-- Name: api_conta_salvar_endereco(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_conta_salvar_endereco(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c contas_cliente := _conta_exigir(); v_id uuid := _uuid(p->>'id'); v_end text := _texto_publico(p->>'endereco', 200);
begin
  if c.user_id is null then return _falha('Entre com a sua conta para continuar.'); end if;
  if v_end = '' then return _falha('Informe o endereço.'); end if;
  if v_id is null then
    if (select count(*) from contas_enderecos where user_id = c.user_id) >= 5 then return _falha('Você pode guardar até 5 endereços.'); end if;
    insert into contas_enderecos (user_id, apelido, endereco, numero, cidade, complemento, referencia)
    values (c.user_id, _texto_publico(p->>'apelido', 30), v_end, _texto_publico(p->>'numero', 20), _texto_publico(p->>'cidade', 80), _texto_publico(p->>'complemento', 100), _texto_publico(p->>'referencia', 150));
  else
    update contas_enderecos set apelido = _texto_publico(p->>'apelido', 30), endereco = v_end, numero = _texto_publico(p->>'numero', 20), cidade = _texto_publico(p->>'cidade', 80),
           complemento = _texto_publico(p->>'complemento', 100), referencia = _texto_publico(p->>'referencia', 150)
     where id = v_id and user_id = c.user_id;
  end if;
  return jsonb_build_object('ok', true, 'message', 'Endereço salvo.');
end $$;


