--
-- Name: api_editar_premio_produto(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_premio_produto(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid := nullif(btrim(coalesce(p->>'produtoId','')),'')::uuid;
begin
  if not public.tem_nivel('Admin') then return public._negado(); end if;
  if v_id is null then return public._falha('Produto inválido.'); end if;
  update public.produtos
     set premio_fidelidade = coalesce((p->>'premioFidelidade')::boolean, premio_fidelidade),
         premio_indicacao  = coalesce((p->>'premioIndicacao')::boolean,  premio_indicacao)
   where id = v_id;
  if not found then return public._falha('Produto não encontrado.'); end if;
  return jsonb_build_object('ok', true, 'message', 'Prêmio atualizado.');
end $$;


--
-- Name: api_editar_produto(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_produto(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare pr produtos%rowtype; v_id uuid := _uuid(p->>'id'); v_nome text := btrim(coalesce(p->>'nome', '')); v_proprio uuid; v_det text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into pr from produtos where id = v_id;
  if not found then return _falha('Produto não encontrado.'); end if;
  if _versao_conflita(p, 'produtos', v_id) then return _conflito('Este registro foi alterado por outra pessoa enquanto você editava. A tela foi atualizada — confira e edite de novo.'); end if;
  if v_nome = '' then return _falha('Informe o nome do produto.'); end if;
  if jsonb_typeof(p->'precos') = 'array' then
    select coalesce(string_agg(f.nome || ': R$ ' || to_char(a.preco, 'FM999990.00') || ' → R$ ' || to_char(_num(e->>'preco'), 'FM999990.00'), '; '), '') into v_det
    from jsonb_array_elements(p->'precos') e
    join produto_precos a on a.produto_id = v_id and a.forma_pagamento_id = _uuid(e->>'formaPagamentoId')
    join formas_pagamento f on f.id = a.forma_pagamento_id
    where a.preco <> _num(e->>'preco');
  end if;
  v_proprio := _estoque_proprio(pr.estoque_proprio_ingrediente_id, v_nome, p->'estoqueProprio');
  update produtos set nome = v_nome, descricao = coalesce(p->>'descricao', ''), categoria_id = _uuid(p->>'categoria'),
         ativo = (coalesce(p->>'ativo','') <> 'false'), estoque_proprio_ingrediente_id = v_proprio where id = v_id;
  if p ? 'destaque' then update produtos set destaque = coalesce((p->>'destaque')::boolean, false) where id = v_id; end if;
  if p ? 'premioFidelidade' then update produtos set premio_fidelidade = coalesce((p->>'premioFidelidade')::boolean, false) where id = v_id; end if;
  if p ? 'premioIndicacao' then update produtos set premio_indicacao = coalesce((p->>'premioIndicacao')::boolean, false) where id = v_id; end if;
  perform _produto_gravar_receita(v_id, p->'ingredientes', v_proprio);
  if jsonb_typeof(p->'precos') = 'array' then perform _produto_gravar_precos(v_id, p->'precos'); end if;
  if p ? 'adicionaisIds' then perform _produto_gravar_adicionais(v_id, p->'adicionaisIds'); end if;
  perform _auditar('Produto editado', v_nome || case when coalesce(v_det, '') <> '' then ' — Preços alterados: ' || v_det else '' end);
  return jsonb_build_object('ok', true, 'message', 'Produto atualizado.');
end $_$;


--
-- Name: api_editar_status_feedback(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_status_feedback(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_st text := coalesce(nullif(btrim(p->>'novoStatus'), ''), 'Novo');
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if v_st <> all (array['Novo','Visto','Respondido']) then return _falha('Status de feedback inválido.'); end if;
  update feedbacks set status = v_st where id = _uuid(p->>'id');
  if not found then return _falha('Feedback não encontrado.'); end if;
  perform _auditar('Feedback atualizado', 'Status: ' || v_st);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_editar_status_mesa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_status_mesa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m mesas%rowtype; v_id uuid := _uuid(p->>'id'); v_novo text := p->>'novoStatus'; v_eu uuid := auth.uid(); v_nivel nivel_acesso := auth_nivel();
begin
  if v_nivel is null or v_nivel not in ('Admin','Operador','Garçom') then return _negado(); end if;
  if v_novo is null or v_novo not in ('Livre','Ocupada','Aguardando fechamento','Fechada','Bloqueada/Manutenção') then return _falha('Status de mesa inválido.'); end if;
  select * into m from mesas where id = v_id;
  if not found then return _falha('Mesa não encontrada.'); end if;
  if v_nivel = 'Garçom' then
    if not ((m.status = 'Livre' and v_novo = 'Ocupada') or (m.status = 'Ocupada' and v_novo = 'Aguardando fechamento')) then
      return _falha('O garçom só pode abrir uma mesa livre ou pedir o fechamento de uma mesa ocupada.');
    end if;
    if m.status = 'Ocupada' and m.garcom_responsavel_id is not null and m.garcom_responsavel_id <> v_eu then
      return _falha('Esta mesa está sob responsabilidade de outro garçom.');
    end if;
    update mesas set status = v_novo::status_mesa where id = m.id;
    if v_novo = 'Ocupada' then update mesas set garcom_responsavel_id = v_eu where id = m.id; end if;
    if p ? 'observacao' then update mesas set observacao = p->>'observacao' where id = m.id; end if;
    if v_novo = 'Aguardando fechamento' then perform _auditar('Fechamento de mesa solicitado', 'Mesa ' || m.numero); end if;
  else
    update mesas set status = v_novo::status_mesa where id = m.id;
    if p ? 'observacao' then update mesas set observacao = p->>'observacao' where id = m.id; end if;
    if v_novo = 'Livre' then update mesas set garcom_responsavel_id = null where id = m.id; end if;
  end if;
  perform _auditar('Status de mesa alterado', 'Mesa ' || m.numero || ': ' || m.status || ' → ' || v_novo);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_editar_usuario(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_usuario(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  u usuarios%rowtype;
  v_alvo text := coalesce(p->>'loginAlvo', '');
  v_aut text; v_erro text;
  v_sera_admin boolean; v_sera_ativo boolean; v_contato boolean := false; v_nome text; v_tel text;
  v_nivel_real nivel_acesso; v_sessao uuid;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select nivel into v_nivel_real from usuarios where id = auth.uid() and ativo;
  if v_nivel_real is null then return _negado(); end if;
  if p ? 'novoNivel' and coalesce(p->>'novoNivel', '') not in ('Admin','Operador','Garçom','Cozinha','Entregador','Desenvolvedor') then return _falha('Nível de acesso inválido.'); end if;
  if p ? 'novoNivel' and p->>'novoNivel' = 'Desenvolvedor' and coalesce((select nivel::text from usuarios where lower(login) = lower(coalesce(p->>'loginAlvo','')) ), '') <> 'Desenvolvedor' then
    return _falha('Não é possível conceder o nível Desenvolvedor.');
  end if;
  if p ? 'novoNivel' and p->>'novoNivel' = 'Desenvolvedor' and v_nivel_real <> 'Desenvolvedor' then
    return _falha('Somente um Desenvolvedor pode conceder o nível Desenvolvedor.');
  end if;
  if (p ? 'novaSenha' or p ? 'novoNivel' or p ? 'novoAtivo') and coalesce(p->>'senhaAdminConfirmacao', '') = '' then return _falha('Informe a sua senha de administrador para confirmar.'); end if;
  v_aut := _exige_admin(p->>'senhaAdminConfirmacao');
  if v_aut is null then return _falha('Senha de administrador incorreta.'); end if;
  select * into u from usuarios where lower(login) = lower(v_alvo);
  if not found then return _falha('Usuário não encontrado.'); end if;
  if u.nivel = 'Desenvolvedor' and v_nivel_real <> 'Desenvolvedor' then
    return _falha('A conta de Desenvolvedor é protegida e só pode ser alterada por um Desenvolvedor.');
  end if;
  if p ? 'nome' and length(coalesce(p->>'nome', '')) > 60 then return _falha('O nome pode ter no máximo 60 caracteres.'); end if;
  if p ? 'telefone' and length(coalesce(p->>'telefone', '')) > 25 then return _falha('O telefone pode ter no máximo 25 caracteres.'); end if;
  v_sera_admin := case when p ? 'novoNivel' then p->>'novoNivel' = 'Admin' else u.nivel = 'Admin' end;
  v_sera_ativo := case when p ? 'novoAtivo' then coalesce((p->>'novoAtivo')::boolean, false) else u.ativo end;
  if u.id = auth.uid() and p ? 'novoAtivo' and not v_sera_ativo then return _falha('Você não pode desativar o seu próprio acesso.'); end if;
  if u.id = auth.uid() and p ? 'novoNivel' and p->>'novoNivel' <> u.nivel::text then return _falha('Você não pode alterar o seu próprio perfil.'); end if;
  if u.nivel = 'Admin' and (not v_sera_admin or not v_sera_ativo) then
    if not exists (select 1 from usuarios where nivel = 'Admin' and ativo and id <> u.id) then return _falha('Não é possível remover o último administrador ativo.'); end if;
  end if;
  -- ao editar a si mesmo, a sessão atual continua valendo (as outras caem)
  v_sessao := case when u.id = auth.uid() then nullif(auth.jwt() ->> 'session_id', '')::uuid else null end;
  if coalesce(p->>'novaSenha', '') <> '' then
    v_erro := _erro_senha_fraca(p->>'novaSenha', u.login);
    if v_erro <> '' then return _falha(v_erro); end if;
    update auth.users set encrypted_password = crypt(p->>'novaSenha', gen_salt('bf')), updated_at = now() where id = u.id;
    delete from auth.sessions where user_id = u.id and id is distinct from v_sessao;
  end if;
  if p ? 'novoNivel' then update usuarios set nivel = (p->>'novoNivel')::nivel_acesso where id = u.id; end if;
  if p ? 'novoAtivo' then
    update usuarios set ativo = v_sera_ativo where id = u.id;
    if not v_sera_ativo then delete from auth.sessions where user_id = u.id and id is distinct from v_sessao; end if;
  end if;
  if p ? 'nome' then v_nome := btrim(coalesce(p->>'nome', '')); if v_nome <> coalesce(u.nome, '') then update usuarios set nome = v_nome where id = u.id; v_contato := true; end if; end if;
  if p ? 'telefone' then v_tel := btrim(coalesce(p->>'telefone', '')); if v_tel <> coalesce(u.telefone, '') then update usuarios set telefone = v_tel where id = u.id; v_contato := true; end if; end if;
  perform _auditar('Usuário editado', u.login || case when coalesce(p->>'novaSenha', '') <> '' then ' (senha alterada)' else '' end
    || case when v_contato then ' (nome/telefone alterado)' else '' end
    || case when p ? 'novoNivel' then ' nível=' || (p->>'novoNivel') else '' end
    || case when p ? 'novoAtivo' then ' ativo=' || case when v_sera_ativo then 'Sim' else 'Não' end else '' end);
  return jsonb_build_object('ok', true, 'message', 'Usuário atualizado.');
end
$$;


--
-- Name: api_editar_venda(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_venda(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v vendas%rowtype; v_aut text; v_motivo text := btrim(coalesce(p->>'motivo', '')); v_itens jsonb := p->'itens'; v_login text;
  it record; v_qtd numeric; v_v numeric; v_c numeric; v_nome text; v_extra numeric; v_n_ad int; v_n_ok int; v_exige boolean; v_prod uuid; v_comb uuid;
  v_ads jsonb; v_soma numeric := 0; v_custo numeric := 0; v_total numeric; v_novos jsonb := '[]'::jsonb; v_npag int; v_antes numeric; v_st text; v_antes_aceite boolean; v_aviso text := ''; v_acr numeric := 0; v_forma_ed formas_pagamento%rowtype;
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  v_aut := _exige_admin(p->>'senhaAdminConfirmacao');
  if v_aut is null then return _falha('Senha de administrador incorreta.'); end if;
  if v_motivo = '' then return _falha('Informe o motivo da edição.'); end if;
  if jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then return _falha('A venda precisa ter ao menos um item.'); end if;
  if jsonb_array_length(v_itens) > 60 then return _falha('Itens demais na venda.'); end if;
  select * into v from vendas where id = _uuid(p->>'id') for update;
  if not found then return _falha('Venda não encontrada.'); end if;
  if _versao_conflita(p, 'vendas', v.id) then return _conflito('Este registro foi alterado por outra pessoa enquanto você editava. A tela foi atualizada — confira e edite de novo.'); end if;
  if v.status <> 'Confirmada' then return _falha('Só é possível editar vendas confirmadas.'); end if;
  if v.fechamento_entrega_id is not null then return _falha('Esta entrega já está em um fechamento — não pode mais ser alterada.'); end if;
  v_st := v.status_pedido::text;
  if v_st is not null and v_st not in ('Em preparo', 'Recebido') then return _falha('Este pedido já está "' || v_st || '" — não é mais possível editar os itens.'); end if;
  v_antes_aceite := v_st = 'Recebido';
  select count(*) into v_npag from pagamentos_venda where venda_id = v.id;
  if v_npag > 1 then return _falha('Venda com pagamento dividido não pode ser editada. Cancele e lance novamente.'); end if;
  v_exige := not (auth_nivel() = 'Admin' and v.origem::text <> 'Cardápio');

  for it in select value as e from jsonb_array_elements(v_itens) loop
    v_nome := coalesce(nullif(it.e->>'descricao', ''), 'item');
    v_qtd := _num(it.e->>'quantidade'); v_v := _num(it.e->>'valorUnitario', -1); v_c := _num(it.e->>'custoUnitario');
    v_prod := _uuid(it.e->>'produtoId'); v_comb := _uuid(it.e->>'comboId');
    if not (v_qtd > 0) or v_qtd > 200 or v_qtd <> floor(v_qtd) then return _falha('Quantidade inválida em "' || v_nome || '".'); end if;
    if v_v < 0 then return _falha('Preço inválido em "' || v_nome || '".'); end if;
    if v_c < 0 then return _falha('Custo inválido em "' || v_nome || '".'); end if;
    -- adicionais: os enviados; se não vierem, mantém os do item antigo de mesma descrição (como na planilha)
    v_ads := case when jsonb_typeof(it.e->'adicionaisIds') = 'array' then it.e->'adicionaisIds'
                  else coalesce((select to_jsonb(iv.adicionais_ids) from itens_venda iv where iv.venda_id = v.id and iv.descricao = it.e->>'descricao' limit 1), '[]'::jsonb) end;
    if v_exige and not exists (select 1 from itens_venda iv where iv.venda_id = v.id and iv.descricao = it.e->>'descricao' and abs(iv.valor_unitario - v_v) <= 0.001 and abs(iv.custo_unitario - v_c) <= 0.011
                                 and coalesce(iv.produto_id, iv.combo_id) is not distinct from coalesce(v_prod, v_comb)) then
      -- item novo ou com preço mudado: precisa conferir com o cadastro
      if (v_prod is null and v_comb is null) or (v_prod is not null and v_comb is not null) then return _falha('"' || v_nome || '" não é um item cadastrado de forma válida.'); end if;
      select count(*), coalesce(sum(a.preco) filter (where a.ativo), 0), count(a.id) filter (where a.ativo and ((v_prod is not null and exists (select 1 from produto_adicionais pa where pa.produto_id = v_prod and pa.adicional_id = a.id)) or (v_comb is not null and exists (select 1 from combo_itens ci join produto_adicionais pa on pa.produto_id = ci.produto_id where ci.combo_id = v_comb and pa.adicional_id = a.id)))) into v_n_ad, v_extra, v_n_ok
        from jsonb_array_elements_text(v_ads) x left join adicionais a on a.id = _uuid(x);
      if v_n_ad <> v_n_ok then return _falha('O adicional selecionado para "' || v_nome || '" não está disponível.'); end if;
      if v_prod is not null then
        if not exists (select 1 from produto_precos pp where pp.produto_id = v_prod and abs(pp.preco + v_extra - v_v) <= 0.011) then
          perform _auditar('Preço divergente bloqueado', v_nome || ' enviado a R$ ' || _dinheiro(v_v) || ' (edição de venda)');
          return _falha('O preço de "' || v_nome || '" não confere com o cadastro.');
        end if;
        if not exists (select 1 from produto_precos pp where pp.produto_id = v_prod and abs(pp.preco + v_extra - v_v) <= 0.011 and abs(pp.custo - v_c) <= 0.011) then
          perform _auditar('Custo divergente bloqueado', v_nome || ' enviado com custo R$ ' || _dinheiro(v_c) || ' (edição de venda)');
          return _falha('O custo de "' || v_nome || '" não confere com o cadastro.');
        end if;
      else
        if not exists (select 1 from combo_precos cp where cp.combo_id = v_comb and abs(cp.preco + v_extra - v_v) <= 0.011) then
          perform _auditar('Preço divergente bloqueado', v_nome || ' enviado a R$ ' || _dinheiro(v_v) || ' (edição de venda)');
          return _falha('O preço de "' || v_nome || '" não confere com o cadastro.');
        end if;
        if not exists (select 1 from combo_precos cp where cp.combo_id = v_comb and abs(cp.preco + v_extra - v_v) <= 0.011 and abs(cp.custo - v_c) <= 0.011) then
          perform _auditar('Custo divergente bloqueado', v_nome || ' enviado com custo R$ ' || _dinheiro(v_c) || ' (edição de venda)');
          return _falha('O custo de "' || v_nome || '" não confere com o cadastro.');
        end if;
      end if;
    end if;
    v_novos := v_novos || jsonb_build_array(jsonb_build_object('produtoId', v_prod, 'comboId', v_comb, 'descricao', v_nome, 'quantidade', v_qtd,
                                                                 'valorUnitario', v_v, 'custoUnitario', v_c, 'adicionaisIds', v_ads));
    v_soma := v_soma + round(v_qtd * v_v, 2); v_custo := v_custo + v_qtd * v_c;
  end loop;
  v_soma := round(v_soma, 2); v_custo := round(v_custo, 2);
  if v.valor_desconto >= v_soma then return _falha('Com o desconto já aplicado, o novo total ficaria zero ou negativo.'); end if;
  v_total := round(v_soma - v.valor_desconto + v.taxa_entrega, 2);
  -- o acréscimo da forma de pagamento acompanha o novo valor dos itens
  if v_npag = 1 then
    select * into v_forma_ed from formas_pagamento where lower(nome) = (select lower(forma_pagamento) from pagamentos_venda where venda_id = v.id limit 1) limit 1;
    if found then v_acr := _acrescimo_forma(v_forma_ed, greatest(0.01, v_total - v.taxa_entrega)); end if;
  end if;
  v_total := round(v_total + v_acr, 2);
  v_antes := v.valor_total;

  perform _ajustar_estoque(_itens_da_venda(v.id), -1, v.id);
  delete from itens_venda where venda_id = v.id;
  insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
  select v.id, _uuid(e->>'produtoId'), _uuid(e->>'comboId'), e->>'descricao', _num(e->>'quantidade', 1)::int, _num(e->>'valorUnitario'), _num(e->>'custoUnitario'),
         round(_num(e->>'quantidade', 1) * _num(e->>'valorUnitario'), 2),
         coalesce((select array_agg(_uuid(x)) filter (where _uuid(x) is not null) from jsonb_array_elements_text(e->'adicionaisIds') x), '{}')
  from jsonb_array_elements(v_novos) e;
  update vendas set valor_total = v_total, custo_total = v_custo, valor_original = v_soma, acrescimo_forma = v_acr where id = v.id;
  if v_npag = 1 then
    update pagamentos_venda pv set valor = v_total, acrescimo = v_acr,
      taxa_aplicada = coalesce((select round(v_total * f.taxa_percentual / 100 + f.taxa_fixa, 2) from formas_pagamento f where lower(f.nome) = lower(pv.forma_pagamento) limit 1), 0)
    where pv.venda_id = v.id;
  end if;
  perform _ajustar_estoque(v_novos, 1, v.id);
  select login into v_login from usuarios where id = auth.uid();
  perform _auditar('Venda editada', case when v_antes_aceite then '[edição antes do aceite] ' else '' end || 'Autorizado por ' || coalesce(nullif(current_setting('app.autorizador', true), ''), v_login)
    || ' | Motivo: ' || v_motivo || ' | Total: R$ ' || _dinheiro(v_antes) || ' → R$ ' || _dinheiro(v_total), v.telefone_cliente);
  if v_antes_aceite and v.origem::text = 'Cardápio' and v.status_pagamento::text = 'Pago' and abs(v_total - v_antes) >= 0.01 then
    v_aviso := ' ATENÇÃO: o valor mudou (R$ ' || _dinheiro(v_antes) || ' → R$ ' || _dinheiro(v_total) || ') e este pedido já consta como pago — acerte a diferença com o cliente.';
  end if;
  return jsonb_build_object('ok', true, 'message', 'Venda atualizada. Novo total: R$ ' || _dinheiro(v_total) || '.' || v_aviso, 'aviso', v_aviso <> '');
end $_$;


--
-- Name: api_editar_visibilidade_cardapio_combo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_visibilidade_cardapio_combo(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not exists (select 1 from combos where id = v_id) then return _falha('Combo não encontrado.'); end if;
  if p ? 'ativo' then update combos set ativo = (coalesce(p->>'ativo','') <> 'false') where id = v_id; end if;
  if p ? 'destaque' then update combos set destaque = coalesce((p->>'destaque')::boolean, false) where id = v_id; end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_editar_visibilidade_cardapio_produto(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_editar_visibilidade_cardapio_produto(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not exists (select 1 from produtos where id = v_id) then return _falha('Produto não encontrado.'); end if;
  if p ? 'ativo' then update produtos set ativo = (coalesce(p->>'ativo','') <> 'false') where id = v_id; end if;
  if p ? 'destaque' then update produtos set destaque = coalesce((p->>'destaque')::boolean, false) where id = v_id; end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_encerrar_sessao_remota(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_encerrar_sessao_remota(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $_$
declare v_alvo text := coalesce(p->>'sessaoId', ''); s record; v_atual uuid := nullif(auth.jwt() ->> 'session_id', '')::uuid;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_alvo !~ '^[0-9a-f]{12}$' then return _falha('Sessão inválida.'); end if;
  select se.id, us.login, se.user_agent into s from auth.sessions se join usuarios us on us.id = se.user_id
    where left(replace(se.id::text, '-', ''), 12) = v_alvo limit 1;
  if not found then return _falha('Sessão não encontrada (talvez já tenha expirado).'); end if;
  if s.id = v_atual then return _falha('Esta é a sua sessão atual. Use "Sair" para encerrá-la.'); end if;
  delete from auth.sessions where id = s.id;
  perform _auditar('Acesso encerrado remotamente (usuário)', 'Sessão de ' || s.login || ' | ' || coalesce(s.user_agent, ''));
  return jsonb_build_object('ok', true, 'message', 'Sessão de ' || s.login || ' encerrada.');
end $_$;


--
-- Name: api_espaco_percentual_servico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_espaco_percentual_servico() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select round(pg_database_size(current_database())/1024.0/1024.0/_limite_banco_mb()*100, 1) $$;


--
-- Name: api_espaco_uso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_espaco_uso() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_db bigint;
BEGIN
  IF NOT tem_nivel('Admin') THEN RETURN _negado(); END IF;
  SELECT pg_database_size(current_database()) INTO v_db;
  RETURN jsonb_build_object('ok',true,'db_bytes',v_db,'db_mb',round(v_db/1024.0/1024.0,2),
    'limite_mb',_limite_banco_mb(),'percentual',round(v_db/1024.0/1024.0/_limite_banco_mb()*100,1),
    'vendas_total',(SELECT count(*) FROM vendas),
    'vendas_arquivadas',(SELECT count(*) FROM arquivo_historico WHERE tabela='vendas'),
    'backups_total',(SELECT count(*) FROM backups),
    'backups_bytes',(SELECT coalesce(sum(tamanho_bytes),0) FROM backups));
END $$;


--
-- Name: api_excluir_adicional(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_adicional(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  delete from adicionais where id = v_id;   -- os vínculos com produtos saem junto
  perform _auditar('Adicional excluído', v_id::text);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_categoria(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_categoria(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id'); v_prod int; v_comb int;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select count(*) into v_prod from produtos where categoria_id = v_id;
  select count(*) into v_comb from combos where categoria_id = v_id;
  if v_prod + v_comb > 0 then
    return _falha((v_prod + v_comb) || ' item(ns) usam essa categoria (' || v_prod || ' produto(s), ' || v_comb || ' combo(s)). Mova-os para outra categoria antes de excluir.');
  end if;
  delete from categorias where id = v_id;
  perform _auditar('Categoria excluída', v_id::text);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_cliente(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_cliente(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id'); v_aut text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  v_aut := _exige_admin(p->>'senhaAdminConfirmacao');
  if v_aut is null then return _falha('Senha de administrador incorreta.'); end if;
  delete from clientes where id = v_id;   -- vendas antigas ficam com o nome e telefone gravados
  perform _auditar('Cliente excluído', v_id::text);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_combo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_combo(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  delete from combos where id = v_id;   -- preços e itens saem junto
  perform _auditar('Combo excluído', v_id::text);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_conta(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_conta(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare c contas_acessos%rowtype;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  delete from contas_acessos where id = _uuid(p->>'id') returning * into c;
  if not found then return _falha('Conta não encontrada.'); end if;
  if c.senha_id is not null then delete from vault.secrets where id = c.senha_id; end if;
  perform _auditar('Conta excluída', c.servico);
  return jsonb_build_object('ok', true, 'message', 'Conta excluída.') || api_listar_contas('{}');
end $$;


--
-- Name: api_excluir_ingrediente(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_ingrediente(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if exists (select 1 from produto_ingredientes where ingrediente_id = v_id) then
    return _falha('Este ingrediente faz parte da receita de algum produto. Tire-o das receitas antes de excluir (ou deixe-o inativo).');
  end if;
  if exists (select 1 from movimentacoes_estoque where ingrediente_id = v_id) then
    return _falha('Este ingrediente tem histórico de movimentações e não pode ser excluído. Deixe-o inativo.');
  end if;
  delete from estoque where id = v_id;
  perform _auditar('Ingrediente excluído', v_id::text);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_mesa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_mesa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m mesas%rowtype; v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into m from mesas where id = v_id;
  if found and m.status = 'Ocupada' then return _falha('Não é possível excluir uma mesa ocupada.'); end if;
  delete from mesas where id = v_id;
  perform _auditar('Mesa excluída', coalesce('Mesa ' || m.numero, v_id::text));
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_produto(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_produto(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if exists (select 1 from combo_itens where produto_id = v_id) then
    return _falha('Este produto faz parte de um ou mais combos. Tire-o dos combos antes de excluir (ou deixe-o inativo).');
  end if;
  delete from produtos where id = v_id;   -- preços, receita e adicionais saem junto
  perform _auditar('Produto excluído', v_id::text);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_excluir_usuario(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_excluir_usuario(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare u usuarios%rowtype; v_aut text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if coalesce(p->>'senhaAdminConfirmacao', '') = '' then return _falha('Informe a sua senha de administrador para confirmar.'); end if;
  v_aut := _exige_admin(p->>'senhaAdminConfirmacao');
  if v_aut is null then return _falha('Senha de administrador incorreta.'); end if;
  select * into u from usuarios where lower(login) = lower(coalesce(p->>'loginAlvo', ''));
  if not found then return _falha('Usuário não encontrado.'); end if;
  if u.nivel = 'Desenvolvedor' then
    return _falha('O acesso de Desenvolvedor não pode ser excluído. Nada foi alterado.');
  end if;
  if u.nivel = 'Admin' and not exists (select 1 from usuarios where nivel = 'Admin' and ativo and id <> u.id) then
    return _falha('Não é possível excluir o último administrador.');
  end if;
  perform _auditar('Usuário excluído', u.login);
  delete from auth.users where id = u.id;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_fechar_caixa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fechar_caixa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  s caixa_sessoes%rowtype; v_login text; v_chave text; v_seg int; v_contado numeric; v_fim timestamptz := now();
  v_mesas text[]; v_pend text[]; v_nrec text[]; v_msgs text[] := '{}';
  v_total numeric; v_pendente numeric; v_qv int; v_desp numeric; v_qd int; v_sang numeric; v_qs int;
  v_forma jsonb; v_dinheiro numeric; v_saldo numeric; v_dif numeric; v_nomes_dinheiro text[];
  v_feitos jsonb := '[]'::jsonb; v_falhas jsonb := '[]'::jsonb; ed record; c record; fid uuid; v_req_auto text;
  v_acertos numeric := 0; v_atrasado boolean := false; v_motivo text;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  select login into v_login from usuarios where id = auth.uid();
  v_chave := 'falhas_senha_propria_' || lower(coalesce(v_login, ''));
  if _excedeu(v_chave, 5) then
    select greatest(1, extract(epoch from (bloqueado_ate - now()))::int) into v_seg from tentativas where chave = v_chave;
    return jsonb_build_object('ok', false, 'bloqueioSegundos', v_seg, 'message', 'Muitas tentativas erradas. Aguarde ' || ceil(v_seg / 60.0)::int || ' min e tente de novo.');
  end if;
  if coalesce(p->>'senhaConfirmacao', '') = '' or not _senha_confere(auth.uid(), p->>'senhaConfirmacao') then
    perform _registrar_falha(v_chave);
    return _falha('Senha incorreta. O caixa não foi fechado.');
  end if;
  perform _limpar_falhas(v_chave);
  if nullif(btrim(coalesce(p->>'valorContado', '')), '') is null or _num(p->>'valorContado', -1) < 0 then
    return _falha('Informe quanto dinheiro há na gaveta (pode ser zero).');
  end if;
  v_contado := round(_num(p->>'valorContado'), 2);
  select * into s from caixa_sessoes where id = _uuid(p->>'id') for update;
  if not found then return _falha('Sessão de caixa não encontrada.'); end if;
  if s.status = 'Fechado' then return _falha('Este caixa já foi fechado.'); end if;
  v_atrasado := (now() >= _caixa_vence_em(s.abertura));
  v_motivo := case when v_atrasado then 'Fechamento atrasado: o caixa passou do vencimento' || coalesce(' — ' || nullif(left(btrim(coalesce(p->>'motivo', '')), 200), ''), '') else null end;

  -- trava: mesas abertas, pedidos pendentes ou não recebidos
  select coalesce(array_agg('Mesa ' || numero order by numero), '{}') into v_mesas from mesas where status in ('Ocupada','Aguardando fechamento');
  select coalesce(array_agg('#' || numero_pedido || case when btrim(coalesce(cliente_nome, '')) <> '' then ' ' || split_part(btrim(cliente_nome), ' ', 1) else '' end || ' (' || status_pedido || ')' order by numero_pedido), '{}')
    into v_pend from vendas where status = 'Confirmada' and status_pedido is not null and status_pedido not in ('Entregue','Retirada','Servida');
  select coalesce(array_agg('#' || numero_pedido || case when btrim(coalesce(cliente_nome, '')) <> '' then ' ' || split_part(btrim(cliente_nome), ' ', 1) else '' end order by numero_pedido), '{}')
    into v_nrec from vendas where status = 'Confirmada' and status_pagamento = 'A Receber';
  if coalesce(array_length(v_mesas, 1), 0) + coalesce(array_length(v_pend, 1), 0) + coalesce(array_length(v_nrec, 1), 0) > 0 then
    if array_length(v_mesas, 1) > 0 then v_msgs := v_msgs || ('Mesas abertas: ' || _lista_curta(v_mesas)); end if;
    if array_length(v_pend, 1) > 0 then v_msgs := v_msgs || ('Pedidos pendentes: ' || _lista_curta(v_pend)); end if;
    if array_length(v_nrec, 1) > 0 then v_msgs := v_msgs || ('Pedidos não recebidos: ' || _lista_curta(v_nrec)); end if;
    return jsonb_build_object('ok', false, 'pendencias', true, 'mesas', to_jsonb(v_mesas), 'pedidos', to_jsonb(v_pend), 'naoRecebidos', to_jsonb(v_nrec),
      'message', 'O caixa não pode ser fechado enquanto houver pendências. ' || array_to_string(v_msgs, ' | ') || '. Resolva (finalize, receba ou cancele) e tente de novo.');
  end if;

  select coalesce(sum(valor_total), 0), coalesce(sum(valor_total) filter (where status_pagamento = 'A Receber'), 0), count(*)
    into v_total, v_pendente, v_qv from vendas where status = 'Confirmada' and data_hora >= s.abertura and data_hora <= v_fim;
  select coalesce(sum(valor), 0), count(*) into v_desp, v_qd from despesas
    where status = 'Paga' and saiu_do_caixa and data_hora >= s.abertura and data_hora <= v_fim;
  select coalesce(sum(valor), 0), count(*) into v_sang, v_qs from sangrias where data_hora >= s.abertura and data_hora <= v_fim;
  -- o dinheiro conta na sessão em que ENTROU (data do recebimento), não em que o pedido foi criado
  select coalesce(jsonb_object_agg(forma, tot), '{}'::jsonb) into v_forma from (
    select pv.forma_pagamento as forma, sum(pv.valor) as tot
    from pagamentos_venda pv join vendas v on v.id = pv.venda_id
    where v.status = 'Confirmada' and v.status_pagamento <> 'A Receber'
      and coalesce(v.recebido_em, v.data_hora) >= s.abertura and coalesce(v.recebido_em, v.data_hora) <= v_fim
    group by pv.forma_pagamento) t;
  select coalesce(array_agg(nome), '{}') into v_nomes_dinheiro from formas_pagamento where permite_troco;
  if coalesce(array_length(v_nomes_dinheiro, 1), 0) = 0 then v_nomes_dinheiro := array['Dinheiro']; end if;
  select coalesce(sum((value)::numeric), 0) into v_dinheiro from jsonb_each_text(v_forma) where key = any(v_nomes_dinheiro);
  v_saldo := s.fundo_caixa + v_dinheiro - v_desp - v_sang;
  v_dif := round(v_contado - v_saldo, 2);

  update caixa_sessoes set fechamento = v_fim, total_vendas = v_total, total_despesas = v_desp, saldo_final = v_saldo, status = 'Fechado',
         usuario_fechamento = auth.uid(), valor_contado = v_contado, diferenca = v_dif, fechamento_atrasado = v_atrasado, fechamento_motivo = v_motivo where id = s.id;
  perform _auditar('Caixa fechado', 'Esperado: R$ ' || _dinheiro(v_saldo) || ' | Contado: R$ ' || _dinheiro(v_contado) || ' | Diferença: R$ ' || _dinheiro(v_dif) || case when v_atrasado then ' | FECHAMENTO ATRASADO' else '' end);
  if abs(v_dif) >= 0.01 then
    perform _auditar('Diferença de caixa', case when v_dif > 0 then 'SOBRA' else 'FALTA' end || ' de R$ ' || _dinheiro(abs(v_dif)) || ' no fechamento');
  end if;

  -- fechamento automático das entregas concluídas na sessão (um fechamento por entregador e por dia)
  for ed in
    select distinct v.entregador_id, u.login, (v.concluida_em at time zone 'America/Sao_Paulo')::date as dia
      from vendas v join usuarios u on u.id = v.entregador_id
     where v.status = 'Confirmada' and v.tipo = 'Entrega' and v.status_pedido::text = 'Entregue'
       and v.entregador_id is not null and v.fechamento_entrega_id is null
       and v.concluida_em >= s.abertura and v.concluida_em <= v_fim
     order by 3, 2
  loop
    begin
      fid := null;
      perform pg_advisory_xact_lock(hashtext(ed.entregador_id::text || ed.dia::text));
      select * into c from _calc_fechamento_entrega(ed.login, ed.dia);
      if c.qtd > 0 then
        v_req_auto := 'auto-' || s.id::text || '-' || lower(ed.login) || '-' || ed.dia::text;
        insert into fechamentos_entrega (data_ref, entregador_id, qtd_entregas, total_taxas, ajuda_diaria, total_devido, valor_pago, diferenca, fechado_por, observacao, requisicao_id)
        values (ed.dia, ed.entregador_id, c.qtd, c.total_taxas, c.ajuda, c.total, c.total, 0, auth.uid(), 'Fechamento automático ao fechar o caixa', v_req_auto)
        on conflict (requisicao_id) do nothing returning id into fid;
        if fid is not null then
          v_acertos := v_acertos + c.total;
          insert into entregas_fechadas (fechamento_id, venda_id, data_ref, entregador_id, taxa)
          select fid, id, ed.dia, ed.entregador_id, taxa_entrega from vendas where id = any(c.ids);
          update vendas set fechamento_entrega_id = fid where id = any(c.ids);
          perform _auditar('Fechamento de entregas (automático)', ed.login || ' | ' || ed.dia || ' | ' || c.qtd || ' entregas | devido e pago R$ ' || _dinheiro(c.total));
          v_feitos := v_feitos || to_jsonb(ed.login || ' (' || to_char(ed.dia, 'DD/MM/YYYY') || '): R$ ' || _dinheiro(c.total));
        end if;
      end if;
    exception when others then
      v_falhas := v_falhas || to_jsonb(ed.login || ' (' || to_char(ed.dia, 'DD/MM/YYYY') || '): ' || sqlerrm);
    end;
  end loop;
  if jsonb_array_length(v_falhas) > 0 then
    perform _auditar('Falha no fechamento automático de entregas', v_falhas::text);
  end if;

  return jsonb_build_object('ok', true, 'entregasAuto', jsonb_build_object('feitos', v_feitos, 'falhas', v_falhas),
    'relatorio', jsonb_build_object(
      'abertura', to_char(s.abertura at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
      'fechamento', to_char(v_fim at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
      'fundoCaixa', s.fundo_caixa, 'totalVendas', v_total, 'totalVendasDinheiro', v_dinheiro, 'porForma', v_forma,
      'totalPendente', v_pendente, 'totalDespesas', v_desp, 'totalSangrias', v_sang, 'saldoFinal', v_saldo,
      'acertoEntregadores', v_acertos, 'saldoAposAcertos', v_saldo - v_acertos,
      'valorContado', v_contado, 'diferenca', v_dif, 'fechamentoAtrasado', v_atrasado, 'quantidadeVendas', v_qv, 'quantidadeDespesas', v_qd, 'quantidadeSangrias', v_qs,
      'reconciliadasNaSessao', jsonb_build_object('quantidade', 0, 'valor', 0), 'pendentesContingencia', 0));
end $_$;


--
-- Name: api_fechar_conta_mesa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fechar_conta_mesa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare m mesas; eu uuid := auth.uid(); nv text; ids uuid[]; total numeric; soma numeric; pg record; resumo text; v record; parte numeric; forma formas_pagamento; share numeric; acr_v numeric; acr_p numeric; acr_all numeric := 0;
begin
  if not tem_nivel('Admin','Operador','Garçom') then return _negado(); end if;
  select * into m from mesas where id = _uuid(p->>'mesaId') for update;
  if not found then return _falha('Mesa não encontrada.'); end if;
  select nivel::text into nv from usuarios where id = eu;
  if nv = 'Garçom' and m.garcom_responsavel_id is not null and m.garcom_responsavel_id <> eu then return _falha('Esta mesa está sob responsabilidade de outro garçom.'); end if;
  if exists (select 1 from jsonb_array_elements(coalesce(p->'pagamentos','[]'::jsonb)) e where btrim(coalesce(e->>'forma','')) = 'A Receber (Mesa)') then return _falha('Forma de pagamento inválida para esta operação.'); end if;
  select array_agg(id), coalesce(round(sum(valor_total), 2), 0) into ids, total from vendas where mesa_id = m.id and status = 'Confirmada' and status_pagamento = 'A Receber';
  if ids is null then
    update mesas set status = 'Livre', garcom_responsavel_id = null, chamado_tipo = null, chamado_em = null where id = m.id;
    perform _auditar('Status de mesa alterado', 'Mesa ' || m.numero || ' → Livre');
    return jsonb_build_object('ok', true, 'message', 'Essa mesa não tinha conta pendente. Liberada.');
  end if;
  if not exists (select 1 from caixa_sessoes where status = 'Aberto') then return _falha('Abra o caixa antes de fechar a conta da mesa — o valor recebido precisa entrar no fechamento do caixa.'); end if;
  if _caixa_vencido(_caixa_aberto_id()) then return _falha(_caixa_msg_vencido()); end if;
  if jsonb_typeof(p->'pagamentos') <> 'array' or jsonb_array_length(p->'pagamentos') = 0 then return _falha('Informe ao menos uma forma de pagamento.'); end if;
  for pg in select value as e from jsonb_array_elements(p->'pagamentos') loop
    if btrim(coalesce(pg.e->>'forma','')) = '' then return _falha('Forma de pagamento não informada.'); end if;
    if not (_num(pg.e->>'valor', 0) > 0) then return _falha('Cada pagamento deve ter um valor maior que zero.'); end if;
    select * into forma from formas_pagamento where lower(nome) = lower(btrim(pg.e->>'forma')) limit 1;
    if not found then return _falha('Forma de pagamento não cadastrada: ' || btrim(pg.e->>'forma')); end if;
    if not forma.ativa then return _falha('A forma de pagamento está inativa: ' || btrim(pg.e->>'forma')); end if;
  end loop;
  select round(coalesce(sum(_num(e->>'valor')), 0), 2) into soma from jsonb_array_elements(p->'pagamentos') e;
  if abs(soma - total) > 0.02 then return _falha('A soma dos pagamentos (R$ ' || _dinheiro(soma) || ') não bate com a conta da mesa (R$ ' || _dinheiro(total) || ').'); end if;
  select string_agg(btrim(e->>'forma'), ' + ') into resumo from jsonb_array_elements(p->'pagamentos') e;
  for v in select id, valor_total, telefone_cliente, cliente_nome from vendas where id = any(ids) loop
    share := case when total > 0 then v.valor_total / total else 1.0 / array_length(ids, 1) end;
    acr_v := 0;
    delete from pagamentos_venda where venda_id = v.id and forma_pagamento = 'A Receber (Mesa)';
    for pg in select value as e from jsonb_array_elements(p->'pagamentos') loop
      -- os valores enviados são a parte da conta paga em cada forma (sem acréscimo); o acréscimo da forma é somado aqui
      parte := round(_num(pg.e->>'valor') * share, 2);
      acr_p := round(_acrescimo_pagamento(pg.e->>'forma', _num(pg.e->>'valor')) * share, 2);
      acr_v := acr_v + acr_p;
      insert into pagamentos_venda (venda_id, forma_pagamento, valor, taxa_aplicada, acrescimo) values (v.id, btrim(pg.e->>'forma'), parte + acr_p, coalesce((select round((parte + acr_p) * f.taxa_percentual / 100 + f.taxa_fixa, 2) from formas_pagamento f where lower(f.nome) = lower(btrim(pg.e->>'forma'))), 0), acr_p);
    end loop;
    update vendas set forma_pagamento = resumo, status_pagamento = 'Pago', recebido_em = now(), valor_total = v.valor_total + acr_v, acrescimo_forma = acr_v where id = v.id;
    acr_all := acr_all + acr_v;
  end loop;
  perform _carimbar_fidelidade(t.tel, t.nome) from (select distinct on (regexp_replace(telefone_cliente, '\D', '', 'g')) telefone_cliente as tel, cliente_nome as nome from vendas where id = any(ids) and nullif(telefone_cliente,'') is not null) t;
  update mesas set status = 'Livre', garcom_responsavel_id = null, chamado_tipo = null, chamado_em = null where id = m.id;
  perform _auditar('Conta de mesa fechada', 'Mesa ' || m.numero || ': R$ ' || _dinheiro(total + acr_all) || case when acr_all > 0 then ' (acréscimo R$ ' || _dinheiro(acr_all) || ')' else '' end || ' | ' || resumo || ' | recebido por ' || coalesce(_login_de(eu), '?') || ' (' || nv || ')');
  return jsonb_build_object('ok', true, 'message', 'Conta da mesa ' || m.numero || ' fechada — R$ ' || _dinheiro(total + acr_all) || '.');
end $_$;


--
-- Name: api_fechar_periodo_entregador(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fechar_periodo_entregador(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare u usuarios; c record; pago numeric; dif numeric; fid uuid; d date; v_saldo numeric;
        req text := btrim(coalesce(p->>'requisicaoId','')); obs text := btrim(coalesce(p->>'observacao',''));
        forma text := btrim(coalesce(p->>'forma',''));
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if btrim(coalesce(p->>'entregador','')) = '' or coalesce(p->>'dataRef','') !~ '^\d{4}-\d{2}-\d{2}$' then return _falha('Informe o entregador e a data.'); end if;
  if req = '' then return _falha('Requisição sem identificador.'); end if;
  if exists (select 1 from fechamentos_entrega where requisicao_id = req) then
    return jsonb_build_object('ok', true, 'duplicado', true, 'message', 'Este fechamento já havia sido registrado.'); end if;
  pago := _num(p->>'valorPago', -1);
  if pago < 0 then return _falha('Informe o valor pago ao entregador.'); end if;
  if forma not in ('Dinheiro','Pix') then return _falha('Escolha a forma de pagamento do entregador: Dinheiro ou Pix.'); end if;
  select * into u from usuarios where lower(login) = lower(p->>'entregador') and nivel::text = 'Entregador';
  if not found then return _falha('Entregador não encontrado.'); end if;
  d := (p->>'dataRef')::date;
  perform pg_advisory_xact_lock(hashtext(u.id::text || d::text));
  select * into c from _calc_fechamento_entrega(u.login, d);
  if c.qtd = 0 then return _falha('Não há entregas concluídas em aberto para esse entregador nessa data.'); end if;
  pago := round(pago, 2); dif := round(pago - c.total, 2);
  if dif <> 0 and obs = '' then return _falha('O valor pago é diferente do devido (R$ ' || _dinheiro(c.total) || '). Informe o motivo da diferença.'); end if;
  if forma = 'Dinheiro' and pago > 0 then
    v_saldo := _saldo_gaveta_aberta();
    if v_saldo is not null and pago > v_saldo then
      return _falha('O dinheiro na gaveta (R$ ' || _dinheiro(v_saldo) || ') não cobre o pagamento de R$ ' || _dinheiro(pago) || '. Escolha Pix ou ajuste o valor. Nada foi registrado.');
    end if;
  end if;
  insert into fechamentos_entrega (data_ref, entregador_id, qtd_entregas, total_taxas, ajuda_diaria, total_devido, valor_pago, diferenca, fechado_por, observacao, requisicao_id, forma_pagamento)
  values (d, u.id, c.qtd, c.total_taxas, c.ajuda, c.total, pago, dif, auth.uid(), nullif(obs,''), req, forma) returning id into fid;
  insert into entregas_fechadas (fechamento_id, venda_id, data_ref, entregador_id, taxa)
  select fid, id, d, u.id, taxa_entrega from vendas where id = any(c.ids);
  update vendas set fechamento_entrega_id = fid where id = any(c.ids);
  perform _lancar_pagamento_entregador(fid, u.id, d, c.total_taxas, pago, forma, exists (select 1 from caixa_sessoes where status = 'Aberto'));
  perform _auditar('Fechamento de entregas', u.login || ' | ' || d || ' | ' || c.qtd || ' entregas | devido R$ ' || _dinheiro(c.total) || ' | pago R$ ' || _dinheiro(pago) || ' em ' || forma || ' | dif R$ ' || _dinheiro(dif) || case when obs <> '' then ' | ' || obs else '' end);
  return jsonb_build_object('ok', true, 'message', 'Fechamento registrado: devido R$ ' || _dinheiro(c.total) || ', pago R$ ' || _dinheiro(pago) || ' em ' || forma || '.');
end $_$;


--
-- Name: api_fiscal_atribuir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_atribuir(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_alvo text := p->>'alvo'; v_id uuid := nullif(p->>'id', '')::uuid; v_perf uuid := nullif(p->>'perfilId', '')::uuid; v_n int := 0; v_ids uuid[];
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_perf is not null and not exists (select 1 from fiscal_perfis where id = v_perf and ativo) then return _falha('Perfil não encontrado ou desativado.'); end if;
  if v_alvo = 'padrao' then update fiscal_empresa set perfil_padrao_id = v_perf, atualizado_em = now() where id;
  elsif v_alvo = 'categoria' then update categorias set perfil_fiscal_id = v_perf where id = v_id; get diagnostics v_n = row_count;
  elsif v_alvo = 'produto' then update produtos set perfil_fiscal_id = v_perf where id = v_id; get diagnostics v_n = row_count;
  elsif v_alvo = 'combo' then update combos set perfil_fiscal_id = v_perf where id = v_id; get diagnostics v_n = row_count;
  elsif v_alvo = 'lote' then
    update produtos set perfil_fiscal_id = v_perf where id in (select (x->>'id')::uuid from jsonb_array_elements(coalesce(p->'ids', '[]')) x where x->>'tipo' = 'produto');
    get diagnostics v_n = row_count;
    update combos set perfil_fiscal_id = v_perf where id in (select (x->>'id')::uuid from jsonb_array_elements(coalesce(p->'ids', '[]')) x where x->>'tipo' = 'combo');
  else return _falha('Destino inválido.'); end if;
  if v_alvo <> 'padrao' and v_alvo <> 'lote' and v_n = 0 then return _falha('Item não encontrado.'); end if;
  perform _auditar('Fiscal: perfil atribuído', v_alvo || coalesce(' · ' || v_id::text, ''));
  return api_fiscal_perfis('{}') || jsonb_build_object('message', 'Perfil atribuído.');
end $$;


--
-- Name: api_fiscal_empresa_ler(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_empresa_ler(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e fiscal_empresa%rowtype;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into e from fiscal_empresa where id;
  return jsonb_build_object('ok', true, 'empresa', to_jsonb(e) - 'id', 'temCsc', exists (select 1 from integracoes_segredos where chave = 'nfce_csc'),
    'completa', _fiscal_empresa_ok(), 'semPerfil', _fiscal_sem_perfil_qtd());
end $$;


--
-- Name: api_fiscal_empresa_salvar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_empresa_salvar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_cnpj text := regexp_replace(coalesce(p->>'cnpj', ''), '\D', '', 'g'); v_cep text := regexp_replace(coalesce(p->>'cep', ''), '\D', '', 'g');
  v_uf text := upper(btrim(coalesce(p->>'uf', ''))); v_ibge text := regexp_replace(coalesce(p->>'codigoMunicipio', ''), '\D', '', 'g');
  v_aliq numeric := coalesce(nullif(replace(coalesce(p->>'aliquotaSimples', '0'), ',', '.'), '')::numeric, 0); v_reg text := coalesce(nullif(p->>'regime', ''), 'simples');
  v_serie int := coalesce(nullif(p->>'serie', '')::int, 1);
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_cnpj <> '' and not _cnpj_valido(v_cnpj) then return _falha('CNPJ inválido. Confira os 14 números.'); end if;
  if v_cep <> '' and v_cep !~ '^[0-9]{8}$' then return _falha('CEP inválido (8 números).'); end if;
  if v_uf <> '' and v_uf !~ '^[A-Z]{2}$' then return _falha('Estado inválido (2 letras, ex.: SP).'); end if;
  if v_ibge <> '' and v_ibge !~ '^[0-9]{7}$' then return _falha('Código do município inválido (7 números, o contador informa).'); end if;
  if v_aliq < 0 or v_aliq > 40 then return _falha('Alíquota fora do esperado (0 a 40%).'); end if;
  if v_reg not in ('mei', 'simples', 'normal') then return _falha('Regime inválido.'); end if;
  if v_serie < 1 or v_serie > 999 then return _falha('Série inválida (1 a 999).'); end if;
  update fiscal_empresa set
    razao_social = left(btrim(coalesce(p->>'razaoSocial', '')), 120), nome_fantasia = left(btrim(coalesce(p->>'nomeFantasia', '')), 120),
    cnpj = nullif(v_cnpj, ''), inscricao_estadual = left(regexp_replace(coalesce(p->>'inscricaoEstadual', ''), '[^0-9A-Za-z]', '', 'g'), 20),
    regime = v_reg, cep = nullif(v_cep, ''), logradouro = left(btrim(coalesce(p->>'logradouro', '')), 120), numero = left(btrim(coalesce(p->>'numero', '')), 20),
    complemento = left(btrim(coalesce(p->>'complemento', '')), 60), bairro = left(btrim(coalesce(p->>'bairro', '')), 60), municipio = left(btrim(coalesce(p->>'municipio', '')), 60),
    codigo_municipio = nullif(v_ibge, ''), uf = nullif(v_uf, ''), telefone = left(regexp_replace(coalesce(p->>'telefone', ''), '\D', '', 'g'), 14),
    csc_id = left(regexp_replace(coalesce(p->>'cscId', ''), '\D', '', 'g'), 10), serie = v_serie, aliquota_simples = v_aliq, atualizado_em = now()
  where id;
  perform _auditar('Fiscal: dados da empresa salvos', coalesce(nullif(v_cnpj, ''), 'sem CNPJ'));
  return api_fiscal_empresa_ler('{}') || jsonb_build_object('message', 'Dados fiscais salvos.');
end $_$;


--
-- Name: api_fiscal_exportar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_exportar(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'linhas', coalesce((
    select jsonb_agg(x order by x->>'tipo', x->>'nome') from (
      select jsonb_build_object('tipo', 'produto', 'id', pr.id, 'nome', pr.nome, 'categoria', c.nome, 'perfil', f.nome, 'ncm', f.ncm, 'cest', f.cest, 'cfop', f.cfop, 'csosn', f.csosn, 'cstIcms', f.cst_icms, 'origem', f.origem, 'unidade', f.unidade) x
        from produtos pr left join categorias c on c.id = pr.categoria_id left join fiscal_perfis f on f.id = _perfil_fiscal_efetivo(pr.id, null) where pr.ativo
      union all
      select jsonb_build_object('tipo', 'combo', 'id', b.id, 'nome', b.nome, 'categoria', c.nome, 'perfil', f.nome, 'ncm', f.ncm, 'cest', f.cest, 'cfop', f.cfop, 'csosn', f.csosn, 'cstIcms', f.cst_icms, 'origem', f.origem, 'unidade', f.unidade)
        from combos b left join categorias c on c.id = b.categoria_id left join fiscal_perfis f on f.id = _perfil_fiscal_efetivo(null, b.id) where b.ativo) t), '[]'::jsonb));
end $$;


--
-- Name: api_fiscal_importar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_importar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare x jsonb; v_ok int := 0; v_ign int := 0; v_msgs text[] := '{}'; v_nome text; v_perf uuid; v_id uuid; v_reg text; v_ncm text; v_csosn text; v_cst text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if jsonb_array_length(coalesce(p->'linhas', '[]')) > 3000 then return _falha('Planilha grande demais (máx. 3000 linhas).'); end if;
  select regime into v_reg from fiscal_empresa where id;
  for x in select * from jsonb_array_elements(coalesce(p->'linhas', '[]')) loop
    v_nome := btrim(coalesce(x->>'perfil', ''));
    v_ncm := regexp_replace(coalesce(x->>'ncm', ''), '\D', '', 'g');
    v_csosn := nullif(regexp_replace(coalesce(x->>'csosn', ''), '\D', '', 'g'), '');
    v_cst := nullif(regexp_replace(coalesce(x->>'cstIcms', ''), '\D', '', 'g'), '');
    if v_nome = '' or v_ncm !~ '^[0-9]{8}$' or (v_reg <> 'normal' and v_csosn is null) or (v_reg = 'normal' and v_cst is null) then
      v_ign := v_ign + 1; if array_length(v_msgs, 1) is null or array_length(v_msgs, 1) < 8 then v_msgs := v_msgs || ('Ignorada: ' || left(coalesce(x->>'nome', '?'), 40)); end if; continue;
    end if;
    insert into fiscal_perfis (nome, ncm, cest, cfop, csosn, cst_icms, origem, unidade)
      values (v_nome, v_ncm, nullif(regexp_replace(coalesce(x->>'cest', ''), '\D', '', 'g'), ''), coalesce(nullif(regexp_replace(coalesce(x->>'cfop', ''), '\D', '', 'g'), ''), '5102'), v_csosn, v_cst,
              coalesce(nullif(x->>'origem', ''), '0'), upper(left(coalesce(nullif(btrim(x->>'unidade'), ''), 'UN'), 6)))
      on conflict (nome) do update set ncm = excluded.ncm, cest = excluded.cest, cfop = excluded.cfop, csosn = excluded.csosn, cst_icms = excluded.cst_icms, origem = excluded.origem, unidade = excluded.unidade
      returning id into v_perf;
    begin v_id := nullif(x->>'id', '')::uuid; exception when others then v_id := null; end;
    if v_id is not null then
      if x->>'tipo' = 'combo' then update combos set perfil_fiscal_id = v_perf where id = v_id;
      elsif x->>'tipo' = 'produto' then update produtos set perfil_fiscal_id = v_perf where id = v_id; end if;
    end if;
    v_ok := v_ok + 1;
  end loop;
  perform _auditar('Fiscal: planilha do contador importada', v_ok || ' linhas, ' || v_ign || ' ignoradas');
  return api_fiscal_perfis('{}') || jsonb_build_object('message', v_ok || ' linha(s) aplicada(s)' || case when v_ign > 0 then ', ' || v_ign || ' ignorada(s) (faltava perfil, NCM ou CSOSN)' else '' end || '.', 'ignoradas', to_jsonb(v_msgs));
end $_$;


--
-- Name: api_fiscal_perfil_excluir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_perfil_excluir(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := (p->>'id')::uuid; v_nome text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select nome into v_nome from fiscal_perfis where id = v_id;
  if v_nome is null then return _falha('Perfil não encontrado.'); end if;
  if exists (select 1 from produtos where perfil_fiscal_id = v_id) or exists (select 1 from combos where perfil_fiscal_id = v_id) or exists (select 1 from categorias where perfil_fiscal_id = v_id)
     or exists (select 1 from fiscal_empresa where perfil_padrao_id = v_id) then
    return _falha('Este perfil está em uso. Troque o perfil dos itens antes de excluir (ou desative o perfil).');
  end if;
  delete from fiscal_perfis where id = v_id;
  perform _auditar('Fiscal: perfil excluído', v_nome);
  return api_fiscal_perfis('{}') || jsonb_build_object('message', 'Perfil excluído.');
end $$;


--
-- Name: api_fiscal_perfil_salvar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_perfil_salvar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_id uuid := nullif(p->>'id', '')::uuid; v_nome text := btrim(coalesce(p->>'nome', '')); v_ncm text := regexp_replace(coalesce(p->>'ncm', ''), '\D', '', 'g');
  v_cest text := nullif(regexp_replace(coalesce(p->>'cest', ''), '\D', '', 'g'), ''); v_cfop text := coalesce(nullif(regexp_replace(coalesce(p->>'cfop', ''), '\D', '', 'g'), ''), '5102');
  v_csosn text := nullif(regexp_replace(coalesce(p->>'csosn', ''), '\D', '', 'g'), ''); v_cst text := nullif(regexp_replace(coalesce(p->>'cstIcms', ''), '\D', '', 'g'), '');
  v_origem text := coalesce(nullif(p->>'origem', ''), '0'); v_un text := upper(left(coalesce(nullif(btrim(p->>'unidade'), ''), 'UN'), 6));
  v_reg text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_nome = '' then return _falha('Dê um nome ao perfil (ex.: Lanches, Bebidas).'); end if;
  if v_ncm !~ '^[0-9]{8}$' then return _falha('NCM precisa ter 8 números (o contador informa).'); end if;
  if v_cest is not null and v_cest !~ '^[0-9]{7}$' then return _falha('CEST precisa ter 7 números (ou deixe em branco).'); end if;
  if v_cfop !~ '^[0-9]{4}$' then return _falha('CFOP precisa ter 4 números.'); end if;
  if v_origem !~ '^[0-8]$' then return _falha('Origem inválida (0 a 8).'); end if;
  select regime into v_reg from fiscal_empresa where id;
  if v_reg in ('mei', 'simples') and v_csosn is null then return _falha('Para Simples/MEI informe o CSOSN (o contador informa, ex.: 102).'); end if;
  if v_reg = 'normal' and v_cst is null then return _falha('Para o regime normal informe o CST do ICMS.'); end if;
  if v_id is null then
    insert into fiscal_perfis (nome, ncm, cest, cfop, csosn, cst_icms, origem, unidade, ativo) values (v_nome, v_ncm, v_cest, v_cfop, v_csosn, v_cst, v_origem, v_un, coalesce((p->>'ativo')::boolean, true));
  else
    update fiscal_perfis set nome = v_nome, ncm = v_ncm, cest = v_cest, cfop = v_cfop, csosn = v_csosn, cst_icms = v_cst, origem = v_origem, unidade = v_un, ativo = coalesce((p->>'ativo')::boolean, ativo) where id = v_id;
    if not found then return _falha('Perfil não encontrado.'); end if;
  end if;
  perform _auditar('Fiscal: perfil salvo', v_nome);
  return api_fiscal_perfis('{}') || jsonb_build_object('message', 'Perfil salvo.');
exception when unique_violation then return _falha('Já existe um perfil com esse nome.');
end $_$;


--
-- Name: api_fiscal_perfis(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_perfis(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'padraoId', (select perfil_padrao_id from fiscal_empresa where id),
    'perfis', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'nome', f.nome, 'ncm', f.ncm, 'cest', f.cest, 'cfop', f.cfop, 'csosn', f.csosn, 'cstIcms', f.cst_icms,
        'origem', f.origem, 'unidade', f.unidade, 'pisCst', f.pis_cst, 'cofinsCst', f.cofins_cst, 'ativo', f.ativo,
        'usos', (select count(*) from produtos x where x.perfil_fiscal_id = f.id) + (select count(*) from combos x where x.perfil_fiscal_id = f.id) + (select count(*) from categorias x where x.perfil_fiscal_id = f.id))
        order by f.nome) from fiscal_perfis f), '[]'::jsonb),
    'categorias', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'nome', c.nome, 'perfilId', c.perfil_fiscal_id) order by c.ordem, c.nome) from categorias c where c.ativa), '[]'::jsonb),
    'semPerfil', _fiscal_sem_perfil_qtd());
end $$;


--
-- Name: api_fiscal_sem_perfil(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_fiscal_sem_perfil(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'itens', coalesce((
    select jsonb_agg(x order by x->>'nome') from (
      select jsonb_build_object('tipo', 'produto', 'id', id, 'nome', nome, 'categoria', (select nome from categorias c where c.id = produtos.categoria_id)) x from produtos where ativo and _perfil_fiscal_efetivo(id, null) is null
      union all
      select jsonb_build_object('tipo', 'combo', 'id', id, 'nome', nome, 'categoria', (select nome from categorias c where c.id = combos.categoria_id)) from combos where ativo and _perfil_fiscal_efetivo(null, id) is null) t), '[]'::jsonb));
end $$;


--
-- Name: api_garantir_despesas_do_mes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_garantir_despesas_do_mes(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_comp text := _competencia_atual(); v_n int := 0;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if coalesce((select valor #>> '{}' from sistema where chave = 'ULTIMA_GERACAO_DESPESAS'), '') <> v_comp then
    v_n := _gerar_despesas_recorrentes(v_comp);
    perform _cfg_gravar('ULTIMA_GERACAO_DESPESAS', to_jsonb(v_comp));
  end if;
  return jsonb_build_object('ok', true, 'geradas', v_n);
end $$;


--
-- Name: api_gerar_despesas_mes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_gerar_despesas_mes(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n int; v_comp text := _competencia_atual();
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  v_n := _gerar_despesas_recorrentes(v_comp);
  perform _cfg_gravar('ULTIMA_GERACAO_DESPESAS', to_jsonb(v_comp));
  return jsonb_build_object('ok', true, 'message', case when v_n > 0 then v_n || ' conta(s) gerada(s) para este mês.' else 'Nenhuma conta nova: este mês já está gerado.' end);
end $$;


--
-- Name: api_gerar_novo_codigo_mesa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_gerar_novo_codigo_mesa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m mesas;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into m from mesas where id = _uuid(p->>'mesaId');
  if not found then return _falha('Mesa não encontrada.'); end if;
  insert into mesas_codigos (mesa_id, codigo) values (m.id, substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))
    on conflict (mesa_id) do update set codigo = excluded.codigo, gerado_em = now();
  perform _auditar('Código QR da mesa renovado', 'Mesa ' || m.numero || ' — o QR antigo deixou de funcionar');
  return jsonb_build_object('ok', true, 'message', 'Novo código gerado. Imprima o QR da mesa ' || m.numero || ' de novo.', 'mesas', _lista_qr_mesas());
end $$;


--
-- Name: api_get_mesa_publica(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_get_mesa_publica(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_q jsonb := _mesa_qr(p->>'mesa', p->>'codigo'); m mesas; v_ped jsonb; v_total numeric;
begin
  if v_q->>'ok' <> 'true' then return v_q; end if;
  select * into m from mesas where id = (v_q->>'mesaId')::uuid;
  select coalesce(round(sum(valor_total), 2), 0) into v_total from vendas where mesa_id = m.id and status = 'Confirmada' and status_pagamento = 'A Receber';
  select coalesce(jsonb_agg(t.j order by t.dh), '[]'::jsonb) into v_ped from (
    select v.data_hora as dh, jsonb_build_object('id', v.id, 'numero', v.numero_pedido,
      'hora', to_char(v.data_hora at time zone 'America/Sao_Paulo', 'HH24:MI'), 'valor', v.valor_total, 'cancelado', v.status = 'Cancelada',
      'status', case when v.status = 'Cancelada' then 'Cancelado' else case v.status_pedido::text when 'Recebido' then 'Aguardando confirmação' when 'Em preparo' then 'Em preparo'
                      when 'Pronta' then 'Pronto' when 'Servida' then 'Servido' when 'Suspenso' then 'Em preparo' else coalesce(v.status_pedido::text, '') end end,
      'podeCancelar', (v.status = 'Confirmada' and v.origem = 'Cardápio' and v.status_pedido = 'Recebido'),
      'itens', (select coalesce(jsonb_agg(jsonb_build_object('quantidade', i.quantidade, 'descricao', i.descricao) order by i.ctid), '[]'::jsonb) from itens_venda i where i.venda_id = v.id)) as j
    from vendas v
    where v.mesa_id = m.id and ((v.status = 'Confirmada' and v.status_pagamento = 'A Receber') or (v.status = 'Cancelada' and v.origem = 'Cardápio' and v.data_hora >= now() - interval '3 hours'))
    order by v.data_hora desc limit 12) t;
  return jsonb_build_object('ok', true, 'mesa', jsonb_build_object('numero', m.numero, 'status', m.status::text, 'chamando', m.chamado_em is not null),
    'pedidos', v_ped, 'total', v_total, 'caixaAberto', exists (select 1 from caixa_sessoes where status = 'Aberto'));
end $$;


--
-- Name: api_get_qr_mesas(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_get_qr_mesas(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  insert into mesas_codigos (mesa_id, codigo) select m.id, substr(replace(gen_random_uuid()::text, '-', ''), 1, 12) from mesas m
    where not exists (select 1 from mesas_codigos c where c.mesa_id = m.id);
  return jsonb_build_object('ok', true, 'mesas', _lista_qr_mesas());
end $$;


--
-- Name: api_get_status_pedido_publico(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_get_status_pedido_publico(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_alvo text := lower(btrim(coalesce(p->>'codigo', ''))); v vendas%rowtype; v_ip text := _ip_cliente(); v_itens jsonb; v_resta int; v_cancelavel boolean;
begin
  if v_alvo !~ '^[0-9a-f-]{8,36}$' then return _falha('Código do pedido inválido.'); end if;
  if _excedeu('statuspub_ip_' || v_ip, 40) or _excedeu('statuspub_falhas', 200) then
    return jsonb_build_object('ok', false, 'message', 'Muitas consultas seguidas. Aguarde alguns minutos.', 'limite', true);
  end if;
  select * into v from vendas where right(id::text, 8) = right(v_alvo, 8) and right(id::text, length(v_alvo)) = v_alvo order by data_hora desc limit 1;
  if not found then
    perform _registrar_falha('statuspub_ip_' || v_ip, 600); perform _registrar_falha('statuspub_falhas', 600);
    return _falha('Pedido não encontrado. Confira o código.');
  end if;
  select coalesce(jsonb_agg(i.quantidade || 'x ' || coalesce(i.descricao, '') order by i.ctid), '[]'::jsonb) into v_itens from itens_venda i where i.venda_id = v.id;
  v_cancelavel := v.origem = 'Cardápio' and v.mesa_id is null and v.status = 'Confirmada' and v.status_pedido = 'Recebido' and v.status_pagamento = 'A Receber';
  v_resta := greatest(0, ceil(180 - extract(epoch from (now() - v.data_hora)))::int);
  return jsonb_build_object('ok', true, 'status', v.status::text, 'statusPedido', v.status_pedido::text, 'tipoEntrega', v.tipo::text,
    'motivoCancelamento', coalesce(v.motivo_cancelamento, ''), 'clienteNome', split_part(btrim(coalesce(v.cliente_nome, '')), ' ', 1),
    'itens', v_itens, 'valorTotal', v.valor_total, 'data', to_char(v.data_hora at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
    'statusPagamento', v.status_pagamento::text, 'numero', v.numero_pedido,
    'podeCancelar', (v_cancelavel and v_resta > 0), 'segundosParaCancelar', case when v_cancelavel then v_resta else 0 end);
end $_$;


--
-- Name: api_historico_cliente_arquivo(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_historico_cliente_arquivo(p_telefone text DEFAULT ''::text, p_cliente_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_tel text := _so_digitos(coalesce(p_telefone,''));
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if length(v_tel) < 8 and p_cliente_id is null then return jsonb_build_object('ok', true, 'pedidos', '[]'::jsonb); end if;
  return jsonb_build_object('ok', true, 'pedidos', coalesce((
    select jsonb_agg(to_jsonb(s) order by s.data_hora desc)
      from (select * from vendas_resumo_arquivo r
             where (length(v_tel) >= 8 and r.telefone = v_tel) or (p_cliente_id is not null and r.cliente_id = p_cliente_id)
             order by r.data_hora desc limit 2000) s), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_avaliacao_responder(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_avaliacao_responder(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_texto text := btrim(coalesce(p->>'texto', ''));
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if length(v_texto) < 3 or length(v_texto) > 600 then return _falha('Escreva a resposta (3 a 600 letras).'); end if;
  if not exists (select 1 from ifood_avaliacoes where id = p->>'id') then return _falha('Avaliação não encontrada.'); end if;
  update ifood_avaliacoes set resposta = v_texto, respondida_em = now() where id = p->>'id';
  insert into ifood_acoes (pedido_ifood, acao, dados) values ('LOJA', 'avaliacao_responder', jsonb_build_object('avaliacao', p->>'id', 'texto', v_texto)) on conflict do nothing;
  perform _auditar('Resposta a avaliação do iFood', left(v_texto, 100));
  return jsonb_build_object('ok', true, 'message', 'Resposta enviada ao iFood.') || api_ifood_avaliacoes('{}');
end $$;


--
-- Name: api_ifood_avaliacoes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_avaliacoes(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'media30d', (select round(avg(nota), 2) from ifood_avaliacoes where coalesce(criada_em, visto_em) > now() - interval '30 days'),
    'itens', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'nota', a.nota, 'comentario', a.comentario, 'em', a.criada_em, 'resposta', a.resposta, 'pedido', i.numero_ifood) order by coalesce(a.criada_em, a.visto_em) desc)
      from (select * from ifood_avaliacoes order by coalesce(criada_em, visto_em) desc limit 20) a left join ifood_pedidos i on i.pedido_ifood = a.pedido_ifood), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_financeiro(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_financeiro(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'aReceber', (select jsonb_build_object('pedidos', count(distinct v.id), 'valor', coalesce(sum(pv.valor - coalesce(pv.taxa_aplicada, 0)), 0), 'bruto', coalesce(sum(pv.valor), 0))
       from ifood_pedidos i join vendas v on v.id = i.venda_id join pagamentos_venda pv on pv.venda_id = v.id and pv.forma_pagamento = 'iFood (pago no app)'
       where not i.simulado and v.status = 'Confirmada' and i.repassado_em is null and i.estado <> 'cancelado'),
    'recebido30d', (select jsonb_build_object('repasses', count(*), 'valor', coalesce(sum(valor), 0)) from ifood_repasses where coalesce(pago_em, (criado_em at time zone 'America/Sao_Paulo')::date) >= (now() at time zone 'America/Sao_Paulo')::date - 30),
    'comissao30d', (select coalesce(sum(comissao), 0) from ifood_pedidos where repassado_em > now() - interval '30 days'),
    'repasses', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'pagoEm', r.pago_em, 'valor', r.valor, 'pedidos', r.pedidos) order by r.pago_em desc nulls last) from (select * from ifood_repasses order by coalesce(pago_em, (criado_em at time zone 'America/Sao_Paulo')::date) desc limit 15) r), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_itens(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_itens(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'itens', coalesce((select jsonb_agg(jsonb_build_object('chave', i.chave, 'nome', i.nome, 'tipo', i.tipo, 'ignorar', i.ignorar,
        'ligado', case when i.produto_id is not null then 'produto' when i.combo_id is not null then 'combo' when i.adicional_id is not null then 'adicional' end,
        'ligadoId', coalesce(i.produto_id, i.combo_id, i.adicional_id),
        'ligadoNome', coalesce((select nome from produtos where id = i.produto_id), (select nome from combos where id = i.combo_id), (select nome from adicionais where id = i.adicional_id)),
        'sugestao', case when i.produto_id is null and i.combo_id is null and i.adicional_id is null and not i.ignorar then public._ifood_sugestao(i.nome, i.tipo) end)
        order by (i.produto_id is null and i.combo_id is null and i.adicional_id is null and not i.ignorar) desc, i.nome) from ifood_itens i), '[]'::jsonb),
    'produtos', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'nome', nome) order by nome) from produtos where ativo), '[]'::jsonb),
    'combos', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'nome', nome) order by nome) from combos where ativo), '[]'::jsonb),
    'adicionais', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'nome', nome) order by nome) from adicionais where ativo), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_ligar_item(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_ligar_item(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_chave text := p->>'chave'; v_tipo text := p->>'tipo'; v_id uuid := nullif(p->>'id', '')::uuid; v_ignorar boolean := coalesce((p->>'ignorar')::boolean, false);
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not exists (select 1 from ifood_itens where chave = v_chave) then return _falha('Item não encontrado.'); end if;
  if v_ignorar then
    update ifood_itens set ignorar = true, produto_id = null, combo_id = null, adicional_id = null, ligado_em = now() where chave = v_chave;
  elsif v_tipo = 'produto' and exists (select 1 from produtos where id = v_id) then
    update ifood_itens set ignorar = false, produto_id = v_id, combo_id = null, adicional_id = null, ligado_em = now() where chave = v_chave;
  elsif v_tipo = 'combo' and exists (select 1 from combos where id = v_id) then
    update ifood_itens set ignorar = false, produto_id = null, combo_id = v_id, adicional_id = null, ligado_em = now() where chave = v_chave;
  elsif v_tipo = 'adicional' and exists (select 1 from adicionais where id = v_id) then
    update ifood_itens set ignorar = false, produto_id = null, combo_id = null, adicional_id = v_id, ligado_em = now() where chave = v_chave;
  elsif v_tipo = 'desligar' then
    update ifood_itens set ignorar = false, produto_id = null, combo_id = null, adicional_id = null, ligado_em = null where chave = v_chave;
  else return _falha('Escolha um item válido do sistema.'); end if;
  perform _auditar('Item do iFood ligado', v_chave || ' → ' || coalesce(v_tipo, '') || case when v_ignorar then ' (ignorar)' else '' end);
  return api_ifood_itens('{}');
end $$;


--
-- Name: api_ifood_loja(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_loja(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'loja', (select to_jsonb(l) - 'bruto' from ifood_loja l where id), 'ligado', _integracao_ligada('ifood'));
end $$;


--
-- Name: api_ifood_loja_acao(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_loja_acao(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_acao text := p->>'acao'; v_min int := coalesce(nullif(p->>'minutos', '')::int, 30);
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  if not _integracao_ligada('ifood') then return _falha('O iFood está desligado.'); end if;
  if v_acao = 'pausar' then
    if v_min < 5 or v_min > 480 then return _falha('Escolha entre 5 minutos e 8 horas.'); end if;
    update ifood_loja set pausada_ate = now() + make_interval(mins => v_min), fechada_por_nos = false where id;
    perform _ifood_enfileirar('LOJA', 'loja_pausar', jsonb_build_object('minutos', v_min));
  elsif v_acao = 'retomar' then
    update ifood_loja set pausada_ate = null, fechada_por_nos = false where id;
    perform _ifood_enfileirar('LOJA', 'loja_retomar', '{}'::jsonb);
  elsif v_acao = 'fechar' then
    update ifood_loja set fechada_por_nos = true where id;
    perform _ifood_enfileirar('LOJA', 'loja_fechar', '{}'::jsonb);
  elsif v_acao = 'abrir' then
    update ifood_loja set fechada_por_nos = false, pausada_ate = null where id;
    perform _ifood_enfileirar('LOJA', 'loja_abrir', '{}'::jsonb);
  else return _falha('Ação inválida.'); end if;
  perform _auditar('Loja no iFood', v_acao || case when v_acao = 'pausar' then ' ' || v_min || ' min' else '' end);
  return jsonb_build_object('ok', true, 'message', 'Pedido enviado ao iFood (confira o estado em instantes).') || api_ifood_loja('{}');
end $$;


--
-- Name: api_ifood_negociacao_responder(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_negociacao_responder(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n ifood_negociacoes%rowtype; v_acao text := p->>'acao'; v_login text;
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  select * into n from ifood_negociacoes where id = p->>'id' for update;
  if not found then return _falha('Negociação não encontrada.'); end if;
  if n.estado <> 'aberta' then return _falha('Esta negociação já foi respondida ou encerrada.'); end if;
  if n.expira_em < now() then return _falha('O prazo para responder acabou; o iFood decide.'); end if;
  if v_acao not in ('aceitar', 'recusar', 'alternativa') then return _falha('Resposta inválida.'); end if;
  select login into v_login from usuarios where id = auth.uid();
  update ifood_negociacoes set estado = case v_acao when 'aceitar' then 'aceita' when 'recusar' then 'recusada' else 'alternativa' end, respondido_em = now(), resposta_por = v_login where id = n.id;
  perform public._ifood_enfileirar(n.pedido_ifood, 'negociacao_' || v_acao, jsonb_build_object('disputa', n.id, 'alternativaId', p->>'alternativaId', 'motivo', left(coalesce(p->>'motivo', ''), 200)));
  perform _auditar('Negociação do iFood respondida', 'Pedido ' || n.pedido_ifood || ' · ' || v_acao || ' por ' || coalesce(v_login, ''));
  return jsonb_build_object('ok', true, 'message', 'Resposta enviada ao iFood.') || api_ifood_negociacoes('{}');
end $$;


--
-- Name: api_ifood_negociacoes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_negociacoes(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'itens', coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'pedido', i.numero_ifood, 'tipo', n.tipo, 'motivo', n.motivo, 'expiraEm', n.expira_em,
      'segundos', greatest(0, round(extract(epoch from (n.expira_em - now())))), 'estado', n.estado, 'alternativas', n.alternativas, 'em', n.criado_em) order by n.criado_em desc)
    from (select * from ifood_negociacoes order by criado_em desc limit 15) n left join ifood_pedidos i on i.pedido_ifood = n.pedido_ifood), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_pedidos(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_pedidos(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'estado', (select jsonb_build_object('ultimaConsulta', ultima_consulta, 'ultimaConsultaOk', ultima_consulta_ok, 'ultimoPedido', ultimo_pedido_em, 'tokenOk', token_ok, 'ultimoErro', ultimo_erro) from ifood_estado where id),
    'pedidos', coalesce((select jsonb_agg(jsonb_build_object('pedido', i.pedido_ifood, 'numero', i.numero_ifood, 'estado', i.estado, 'semLigacao', i.itens_sem_ligacao, 'simulado', i.simulado,
        'venda', v.numero_pedido, 'total', v.valor_total, 'em', i.criado_em, 'cancelado', v.status = 'Cancelada',
        'acaoErro', (select a.acao || ': ' || coalesce(a.erro, '') from ifood_acoes a where a.pedido_ifood = i.pedido_ifood and a.estado in ('erro', 'duvida') order by a.id desc limit 1)) order by i.criado_em desc)
      from (select * from ifood_pedidos order by criado_em desc limit 30) i left join vendas v on v.id = i.venda_id), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_precos(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_precos(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_lim numeric := coalesce((select (config->>'limitePrecoPct')::numeric from integracoes_config where provedor = 'ifood'), 30);
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'limitePct', v_lim, 'enviarLigado', coalesce((select (config->>'enviarPrecos')::boolean from integracoes_config where provedor = 'ifood'), false),
    'itens', coalesce((select jsonb_agg(x order by (x->>'nome')) from (
      select jsonb_build_object('chave', i.chave, 'nome', coalesce((select nome from produtos where id = i.produto_id), (select nome from combos where id = i.combo_id)), 'nomeIfood', i.nome,
        'precoSistema', public._ifood_preco_sistema(i), 'precoIfood', i.preco_ifood, 'visto', i.preco_visto_em,
        'diff', round(coalesce(i.preco_ifood, 0) - coalesce(public._ifood_preco_sistema(i), 0), 2),
        'pct', case when coalesce(public._ifood_preco_sistema(i), 0) > 0 and i.preco_ifood is not null then round(abs(i.preco_ifood - public._ifood_preco_sistema(i)) / public._ifood_preco_sistema(i) * 100, 1) end,
        'podeEnviar', i.ifood_item_id is not null) x
      from ifood_itens i where (i.produto_id is not null or i.combo_id is not null) and not i.ignorar) t), '[]'::jsonb),
    'historico', coalesce((select jsonb_agg(jsonb_build_object('id', h.id, 'quando', h.quando, 'nome', h.nome, 'antes', h.preco_antes, 'depois', h.preco_depois, 'origem', h.origem, 'estado', h.estado, 'erro', h.erro) order by h.id desc)
      from (select * from ifood_precos_hist order by id desc limit 30) h), '[]'::jsonb));
end $$;


--
-- Name: api_ifood_precos_aplicar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_precos_aplicar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r ifood_itens%rowtype; v_forma uuid := public._ifood_forma(); v_chave text; v_n int := 0; v_antes numeric; v_login text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_forma is null then return _falha('Cadastre a forma de pagamento "iFood" (com preço próprio) em Pagamentos antes de importar preços.'); end if;
  select login into v_login from usuarios where id = auth.uid();
  for v_chave in select jsonb_array_elements_text(coalesce(p->'chaves', '[]'::jsonb)) loop
    select * into r from ifood_itens where chave = v_chave and preco_ifood is not null and preco_ifood > 0;
    if not found then continue; end if;
    v_antes := public._ifood_preco_sistema(r);
    if r.produto_id is not null then
      update produto_precos set preco = r.preco_ifood where produto_id = r.produto_id and forma_pagamento_id = v_forma;
      if not found then insert into produto_precos (produto_id, forma_pagamento_id, preco, custo) values (r.produto_id, v_forma, r.preco_ifood, coalesce((select min(custo) from produto_precos where produto_id = r.produto_id), 0)); end if;
    elsif r.combo_id is not null then
      update combo_precos set preco = r.preco_ifood where combo_id = r.combo_id and forma_pagamento_id = v_forma;
      if not found then insert into combo_precos (combo_id, forma_pagamento_id, preco, custo) values (r.combo_id, v_forma, r.preco_ifood, coalesce((select min(custo) from combo_precos where combo_id = r.combo_id), 0)); end if;
    else continue; end if;
    insert into ifood_precos_hist (chave, nome, preco_antes, preco_depois, origem, usuario, estado) values (r.chave, r.nome, v_antes, r.preco_ifood, 'importar', v_login, 'ok');
    v_n := v_n + 1;
  end loop;
  perform _auditar('Preços importados do iFood', v_n || ' item(ns)');
  return jsonb_build_object('ok', true, 'message', v_n || ' preço(s) do iFood gravado(s) no sistema.') || api_ifood_precos('{}');
end $$;


--
-- Name: api_ifood_precos_desfazer(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_precos_desfazer(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare h ifood_precos_hist%rowtype; i ifood_itens%rowtype; v_id bigint;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into h from ifood_precos_hist where id = (p->>'id')::bigint for update;
  if not found or h.origem <> 'enviar' or h.estado <> 'ok' then return _falha('Só dá para desfazer um envio já concluído.'); end if;
  if h.preco_antes is null then return _falha('Não há preço anterior guardado.'); end if;
  select * into i from ifood_itens where chave = h.chave;
  update ifood_precos_hist set estado = 'desfeito' where id = h.id;
  insert into ifood_precos_hist (chave, nome, preco_antes, preco_depois, origem, usuario) values (h.chave, h.nome, h.preco_depois, h.preco_antes, 'desfazer', coalesce((select login from usuarios where id = auth.uid()), '')) returning id into v_id;
  insert into ifood_acoes (pedido_ifood, acao, dados) values ('LOJA', 'catalogo_preco', jsonb_build_object('chave', h.chave, 'itemId', i.ifood_item_id, 'preco', h.preco_antes, 'hist', v_id)) on conflict do nothing;
  perform _auditar('Envio de preço desfeito', h.nome);
  return jsonb_build_object('ok', true, 'message', 'Preço anterior reenviado ao iFood.') || api_ifood_precos('{}');
end $$;


--
-- Name: api_ifood_precos_enviar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_precos_enviar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r ifood_itens%rowtype; v_chave text; v_novo numeric; v_lim numeric := coalesce((select (config->>'limitePrecoPct')::numeric from integracoes_config where provedor = 'ifood'), 30);
        v_n int := 0; v_bloq text[] := '{}'; v_id bigint; v_login text; v_pct numeric;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not _integracao_ligada('ifood') then return _falha('O iFood está desligado.'); end if;
  if not coalesce((select (config->>'enviarPrecos')::boolean from integracoes_config where provedor = 'ifood'), false) then return _falha('Ligue antes o ajuste "Enviar nossos preços ao iFood".'); end if;
  if coalesce(p->>'confirmar', '') <> 'true' then return _falha('Confirme o envio.'); end if;
  select login into v_login from usuarios where id = auth.uid();
  for v_chave in select jsonb_array_elements_text(coalesce(p->'chaves', '[]'::jsonb)) loop
    select * into r from ifood_itens where chave = v_chave;
    if not found or r.ifood_item_id is null then v_bloq := v_bloq || (coalesce(r.nome, v_chave) || ' (importe o cardápio do iFood antes)'); continue; end if;
    v_novo := public._ifood_preco_sistema(r);
    if v_novo is null or v_novo <= 0 then continue; end if;
    if r.preco_ifood is not null and r.preco_ifood > 0 and abs(r.preco_ifood - v_novo) < 0.005 then continue; end if;
    v_pct := case when coalesce(r.preco_ifood, 0) > 0 then abs(v_novo - r.preco_ifood) / r.preco_ifood * 100 else 0 end;
    if v_pct > v_lim and coalesce(p->>'ignorarLimite', '') <> 'true' then v_bloq := v_bloq || (r.nome || ' (' || round(v_pct) || '% de variação, acima do limite de ' || v_lim || '%)'); continue; end if;
    insert into ifood_precos_hist (chave, nome, preco_antes, preco_depois, origem, usuario) values (r.chave, r.nome, r.preco_ifood, v_novo, 'enviar', v_login) returning id into v_id;
    insert into ifood_acoes (pedido_ifood, acao, dados) values ('LOJA', 'catalogo_preco', jsonb_build_object('chave', r.chave, 'itemId', r.ifood_item_id, 'preco', v_novo, 'hist', v_id)) on conflict do nothing;
    v_n := v_n + 1;
  end loop;
  perform _auditar('Preços enviados ao iFood', v_n || ' item(ns)' || case when array_length(v_bloq, 1) > 0 then ' · bloqueados: ' || array_length(v_bloq, 1) else '' end);
  return jsonb_build_object('ok', true, 'message', v_n || ' preço(s) enviado(s) ao iFood.' || case when array_length(v_bloq, 1) > 0 then ' Não enviados: ' || array_to_string(v_bloq, '; ') else '' end) || api_ifood_precos('{}');
end $$;


--
-- Name: api_ifood_precos_pedir_catalogo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_precos_pedir_catalogo(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not _integracao_ligada('ifood') then return _falha('O iFood está desligado.'); end if;
  perform _ifood_enfileirar('LOJA', 'catalogo_importar', '{}'::jsonb);
  return jsonb_build_object('ok', true, 'message', 'Pedido enviado: em cerca de 1 minuto o cardápio do iFood aparece aqui. Atualize a lista.');
end $$;


--
-- Name: api_ifood_relatorio(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_relatorio(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dias int := least(greatest(coalesce(nullif(p->>'dias', '')::int, 30), 1), 365);
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'dias', v_dias,
    'canais', coalesce((select jsonb_agg(jsonb_build_object('canal', c, 'pedidos', n, 'total', t, 'ticket', case when n > 0 then round(t / n, 2) else 0 end,
          'custo', k, 'taxas', tx, 'impostos', round(imp, 2), 'margem', round(t - k - tx - imp, 2),
          'margemPct', case when t > 0 then round((t - k - tx - imp) / t * 100, 1) else 0 end, 'cancelados', cx) order by t desc)
      from (select case when v.canal = 'iFood' then 'iFood' when v.origem::text = 'Cardápio' then 'Cardápio' when v.origem::text = 'Garçom' then 'Garçom' else 'Balcão' end c,
                   count(*) filter (where v.status = 'Confirmada') n, coalesce(sum(v.valor_total) filter (where v.status = 'Confirmada'), 0) t,
                   coalesce(sum(v.custo_total) filter (where v.status = 'Confirmada'), 0) k,
                   coalesce(sum((select coalesce(sum(pv.taxa_aplicada), 0) from pagamentos_venda pv where pv.venda_id = v.id)) filter (where v.status = 'Confirmada'), 0) tx,
                   coalesce(sum(v.valor_total * public._imposto_pct((v.data_hora at time zone 'America/Sao_Paulo')::date) / 100) filter (where v.status = 'Confirmada'), 0) imp,
                   count(*) filter (where v.status = 'Cancelada') cx
            from vendas v where v.data_hora > now() - make_interval(days => v_dias) group by 1) x), '[]'::jsonb),
    'ifood', jsonb_build_object(
      'confirmacaoMediaMin', (select round(avg(extract(epoch from (confirmado_em - criado_em)) / 60)::numeric, 1) from ifood_pedidos where confirmado_em is not null and not simulado and criado_em > now() - make_interval(days => v_dias)),
      'itensSemLigacao', (select coalesce(sum(itens_sem_ligacao), 0) from ifood_pedidos where criado_em > now() - make_interval(days => v_dias) and estado <> 'cancelado'),
      'comissaoReal', (select coalesce(sum(comissao), 0) from ifood_pedidos where comissao is not null and criado_em > now() - make_interval(days => v_dias)),
      'cancelamentos', coalesce((select jsonb_agg(jsonb_build_object('motivo', m, 'qtd', q) order by q desc) from (select coalesce(nullif(motivo_cancelamento, ''), 'sem motivo') m, count(*) q from vendas where canal = 'iFood' and status = 'Cancelada' and data_hora > now() - make_interval(days => v_dias) group by 1) y), '[]'::jsonb),
      'maisVendidos', coalesce((select jsonb_agg(jsonb_build_object('nome', n, 'qtd', q) order by q desc) from (select left(iv.descricao, 60) n, sum(iv.quantidade) q from itens_venda iv join vendas v on v.id = iv.venda_id where v.canal = 'iFood' and v.status = 'Confirmada' and v.data_hora > now() - make_interval(days => v_dias) group by 1 order by 2 desc limit 8) z), '[]'::jsonb)));
end $$;


--
-- Name: api_ifood_reprocessar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_reprocessar(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v_n int := 0; v_sem int;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  for r in select i.* from ifood_pedidos i join vendas v on v.id = i.venda_id where i.itens_sem_ligacao > 0 and v.status = 'Confirmada' and i.bruto ? 'items' and v.fechamento_entrega_id is null loop
    v_sem := public._ifood_gravar_itens(r.venda_id, r.bruto, true);
    update vendas set custo_total = coalesce((select sum(custo_unitario * quantidade) from itens_venda where venda_id = r.venda_id), 0) where id = r.venda_id;
    update ifood_pedidos set itens_sem_ligacao = v_sem, atualizado_em = now() where pedido_ifood = r.pedido_ifood;
    v_n := v_n + 1;
  end loop;
  perform _auditar('Pedidos do iFood reprocessados', v_n || ' pedido(s)');
  return jsonb_build_object('ok', true, 'message', v_n || ' pedido(s) refeito(s) com as ligações atuais.') || api_ifood_pedidos('{}');
end $$;


--
-- Name: api_ifood_simular(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ifood_simular(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_prod record; v_id text := 'SIM-' || substr(md5(random()::text), 1, 10); v_order jsonb; v_itens jsonb := '[]'::jsonb; v_sub numeric := 0; v_pre boolean := coalesce((p->>'pagoNoApp')::boolean, true); v_res jsonb; v_pr numeric;
begin
  if not public._eh_dev() then return _negado(); end if;
  for v_prod in select pr.id, pr.nome, coalesce((select min(preco) from produto_precos where produto_id = pr.id), 20) preco from produtos pr where pr.ativo order by random() limit 2 loop
    v_pr := v_prod.preco;
    v_itens := v_itens || jsonb_build_object('id', 'it-' || substr(md5(v_prod.id::text), 1, 8), 'name', v_prod.nome, 'externalCode', v_prod.id::text, 'quantity', 1, 'unitPrice', v_pr, 'optionsPrice', 0, 'totalPrice', v_pr, 'observations', 'sem cebola (teste)', 'options', '[]'::jsonb);
    v_sub := v_sub + v_pr;
  end loop;
  if jsonb_array_length(v_itens) = 0 then return _falha('Cadastre ao menos um produto ativo para simular.'); end if;
  v_itens := v_itens || jsonb_build_object('id', 'it-sim-novo', 'name', 'Item novo do iFood (teste sem ligação)', 'externalCode', 'SIM-SEM-LIGACAO', 'quantity', 1, 'unitPrice', 10, 'totalPrice', 10, 'options', '[]'::jsonb);
  v_sub := v_sub + 10;
  v_order := jsonb_build_object('id', v_id, 'displayId', right(v_id, 4), 'orderType', 'DELIVERY', 'orderTiming', 'IMMEDIATE', 'createdAt', now(),
    'customer', jsonb_build_object('name', 'Cliente Teste', 'phone', jsonb_build_object('number', '11999990000')),
    'delivery', jsonb_build_object('deliveredBy', 'MERCHANT', 'deliveryAddress', jsonb_build_object('formattedAddress', 'Rua de Teste, 100 - Centro', 'complement', 'ap 1', 'reference', 'perto da praça')),
    'items', v_itens,
    'total', jsonb_build_object('subTotal', v_sub, 'deliveryFee', 6, 'benefits', 0, 'orderAmount', v_sub + 6),
    'payments', case when v_pre then jsonb_build_object('prepaid', v_sub + 6, 'pending', 0, 'methods', jsonb_build_array(jsonb_build_object('type', 'PREPAID', 'method', 'CREDIT', 'value', v_sub + 6)))
                     else jsonb_build_object('prepaid', 0, 'pending', v_sub + 6, 'methods', jsonb_build_array(jsonb_build_object('type', 'PENDING', 'method', 'CASH', 'value', v_sub + 6, 'cash', jsonb_build_object('changeFor', 100)))) end);
  v_res := public.ifood_criar_pedido(v_order, true);
  update ifood_pedidos set estado = 'confirmado', confirmado_em = now() where pedido_ifood = v_id;
  return jsonb_build_object('ok', true, 'message', 'Pedido de TESTE criado (venda #' || (v_res->>'numero') || '). Cancele a venda depois do treino. Nada foi enviado ao iFood.') || api_ifood_pedidos('{}');
end $$;


--
-- Name: api_indicar_novo_cliente(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_indicar_novo_cliente(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ti text := btrim(coalesce(p->>'telIndicador', '')); v_ni text := btrim(coalesce(p->>'nomeIndicador', ''));
        v_nome text := btrim(coalesce(p->>'nome', '')); v_tel text := btrim(coalesce(p->>'telefone', ''));
        v_r jsonb; v_ja indicacoes%rowtype;
begin
  if not tem_nivel('Admin','Operador','Garçom') then return _negado(); end if;
  if v_nome = '' or v_tel = '' then return _falha('Nome e telefone são obrigatórios.'); end if;
  if v_ti = '' or v_ni = '' then return _falha('Preencha todos os campos.'); end if;
  if _so_digitos(v_ti) = _so_digitos(v_tel) then return _falha('Quem indicou e quem foi indicado não podem ser a mesma pessoa.'); end if;
  v_r := api_salvar_cliente((p - 'id') || jsonb_build_object('nome', v_nome, 'telefone', v_tel));
  if coalesce(v_r->>'ok', '') <> 'true' then return v_r; end if;
  select * into v_ja from indicacoes where _so_digitos(telefone_indicado) = _so_digitos(v_tel) limit 1;
  if v_ja.id is not null then
    return jsonb_build_object('ok', true, 'message', 'Cliente cadastrado, mas: ' || v_nome || ' já foi indicado antes (por ' || coalesce(v_ja.nome_indicador, '') || ').');
  end if;
  insert into indicacoes (indicador_id, indicado_id, nome_indicador, telefone_indicador, nome_indicado, telefone_indicado, status, observacoes)
  values (_upsert_cliente(v_ti, v_ni), _upsert_cliente(v_tel, v_nome), v_ni, v_ti, v_nome, v_tel, 'Pendente', '');
  perform _auditar('Indicação registrada', v_ni || ' indicou ' || v_nome, v_tel);
  return jsonb_build_object('ok', true, 'message', 'Cliente cadastrado e indicação registrada! ' || v_ni || ' ganhará 1 batata pequena na próxima compra.');
end $$;


--
-- Name: api_iniciar_preparo_pedido(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_iniciar_preparo_pedido(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t record; v vendas; v_eu uuid := auth.uid(); v_nivel text;
begin
  if not tem_nivel('Admin','Operador','Cozinha','Garçom') then return _negado(); end if;
  select * into t from _pedido_trava(p); v := t.v; if t.erro is not null then return t.erro; end if;
  if v.status_pedido::text not in ('Recebido','Em preparo') then return _conflito('Este pedido já está "' || coalesce(v.status_pedido::text,'') || '". A tela foi atualizada.'); end if;
  v_nivel := auth_nivel()::text;
  if v_nivel = 'Garçom' and not (v.registrado_por = v_eu or exists (select 1 from mesas m where m.id = v.mesa_id and m.garcom_responsavel_id = v_eu)) then
    return _falha('Este pedido não está no seu escopo operacional.');
  end if;
  if v.status_pedido::text = 'Recebido' then perform _auditar('Pedido aceito', '#' || v.numero_pedido || ' — aceito e em preparo', v.telefone_cliente); end if;
  update vendas set status_pedido = 'Em preparo', inicio_preparo_em = coalesce(inicio_preparo_em, now()) where id = v.id;
  perform _auditar('Preparo iniciado', '#' || v.numero_pedido);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_iniciar_venda(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_iniciar_venda(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_nivel nivel_acesso := auth_nivel(); v_eu uuid := auth.uid(); v_login text;
  v_itens jsonb := p->'itens'; v_pags jsonb := p->'pagamentos'; v_tipo_in text := p->>'tipoEntrega';
  v_mesa_id uuid := _uuid(p->>'mesaId'); v_mesa mesas%rowtype; v_mesa_status text; v_mesa_garcom uuid;
  v_origem text := coalesce(nullif(p->>'origem', ''), 'Balcão'); v_status_pag text := p->>'statusPagamento';
  v_nome text := btrim(coalesce(p->>'clienteNome', '')); v_tel text := btrim(coalesce(p->>'clienteTelefone', ''));
  v_de jsonb := case when jsonb_typeof(p->'dadosEntrega') = 'object' then p->'dadosEntrega' else '{}'::jsonb end;
  v_desc jsonb := case when jsonb_typeof(p->'desconto') = 'object' then p->'desconto' else null end;
  v_req text := nullif(left(coalesce(p->>'requisicaoId', ''), 80), ''); v_ja uuid;
  it record; pg record; v_exige boolean; v_qtd numeric; v_v numeric; v_c numeric; v_nome_item text; v_extra numeric; v_n_ad int; v_n_ok int;
  v_orig numeric := 0; v_custo numeric := 0; v_total_item numeric; v_desc_val numeric := 0; v_desc_det text := ''; v_sol numeric; v_aut text;
  v_tipo venda_tipo; v_taxa numeric := 0; v_total numeric; v_soma numeric := 0; v_erro text; v_venda uuid := gen_random_uuid();
  v_pad numeric; v_t numeric; v_forma_row formas_pagamento%rowtype; v_resumo text; v_origem_final origem_venda; v_status_pedido_ini status_pedido;
  v_status_pag_final status_pagamento; v_numero int; v_msg_extra text := ''; v_caixa uuid; v_bloqueia boolean; r record; v_acr numeric := 0;
begin
  if v_nivel is null or v_nivel not in ('Admin','Operador','Garçom') then return _negado(); end if;
  if jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then return _falha('Adicione ao menos um item à venda.'); end if;
  if jsonb_typeof(v_pags) <> 'array' or jsonb_array_length(v_pags) = 0 then return _falha('Informe ao menos uma forma de pagamento.'); end if;
  if v_tipo_in = 'Mesa' and v_mesa_id is null then return _falha('Informe a mesa.'); end if;
  if v_origem like 'Contingência%' then return _falha('Vendas da contingência entram pelo botão "Trazer vendas pendentes da contingência" (Administrador).'); end if;
  if coalesce(p->'promocaoValidada'->>'ok', '') = 'true' then return _falha('Cupom não é aceito no Caixa. Use o desconto por porcentagem.'); end if;
  select login into v_login from usuarios where id = v_eu;
  select id into v_caixa from caixa_sessoes where status = 'Aberto' limit 1;
  if v_caixa is null then return _falha(case when v_nivel = 'Garçom' then 'O caixa está fechado — peça ao caixa para abrir.' else 'Abra o caixa antes de registrar uma venda.' end); end if;
  if _caixa_vencido(v_caixa) then return _falha(_caixa_msg_vencido()); end if;

  -- garçom: só mesa/entrega/retirada, sem desconto, sem receber pagamento; vale no servidor, não só na tela
  if v_nivel = 'Garçom' then
    if v_tipo_in not in ('Mesa','Entrega','Retirada') then return _falha('O garçom só lança pedidos de mesa, entrega ou retirada.'); end if;
    if v_tipo_in <> 'Mesa' and v_tel = '' then return _falha('Informe o cliente (nome e telefone) para pedidos por telefone.'); end if;
    if v_tipo_in = 'Mesa' then
      select * into v_mesa from mesas where id = v_mesa_id for update;
      if not found then return _falha('Mesa não encontrada.'); end if;
      if v_mesa.status not in ('Livre','Ocupada') then return _falha('A mesa ' || v_mesa.numero || ' está "' || v_mesa.status || '" — não aceita novos itens.'); end if;
      if v_mesa.status = 'Ocupada' and v_mesa.garcom_responsavel_id is not null and v_mesa.garcom_responsavel_id <> v_eu then
        return _falha('Esta mesa está sob responsabilidade de outro garçom.');
      end if;
    end if;
    v_origem := 'Garçom'; v_desc := null; v_status_pag := 'A Receber';
    if v_tipo_in = 'Mesa' then
      v_pags := jsonb_build_array(jsonb_build_object('forma', 'A Receber (Mesa)', 'valor', _num(v_pags->0->>'valor')));
    else
      v_pags := jsonb_build_array(jsonb_build_object('forma', btrim(coalesce(v_pags->0->>'forma', '')), 'valor', _num(v_pags->0->>'valor')));
    end if;
  elsif v_tipo_in = 'Mesa' then
    select * into v_mesa from mesas where id = v_mesa_id for update;
    if not found then return _falha('Mesa não encontrada.'); end if;
  end if;

  if v_tipo_in = 'Mesa' then v_mesa_status := v_mesa.status::text; v_mesa_garcom := v_mesa.garcom_responsavel_id; end if;

  -- idempotência: a mesma requisição (duplo toque, nova tentativa) nunca gera duas vendas
  if v_req is not null then
    perform pg_advisory_xact_lock(hashtext('venda:' || v_req));
    select id into v_ja from vendas where requisicao_id = v_req;
    if found then return jsonb_build_object('ok', true, 'duplicado', true, 'id', v_ja, 'message', 'Venda já registrada — requisição repetida ignorada.'); end if;
  end if;

  -- itens: quantidade, preço, custo e (para quem não é Admin) preço conferido com o cadastro
  v_exige := not (v_nivel = 'Admin' and v_origem <> 'Cardápio');
  for it in select value as e from jsonb_array_elements(v_itens) loop
    v_nome_item := coalesce(nullif(it.e->>'descricao', ''), 'item');
    v_qtd := _num(it.e->>'quantidade'); v_v := _num(it.e->>'valorUnitario', -1); v_c := _num(it.e->>'custoUnitario');
    if not (v_qtd > 0) or v_qtd > 200 or v_qtd <> floor(v_qtd) then return _falha('Quantidade inválida em "' || v_nome_item || '".'); end if;
    if v_v < 0 then return _falha('Preço inválido em "' || v_nome_item || '".'); end if;
    if v_c < 0 then return _falha('Custo inválido em "' || v_nome_item || '".'); end if;
    if v_exige then
      if (_uuid(it.e->>'produtoId') is null and _uuid(it.e->>'comboId') is null) or (_uuid(it.e->>'produtoId') is not null and _uuid(it.e->>'comboId') is not null) then
        return _falha('"' || v_nome_item || '" não é um item cadastrado de forma válida.');
      end if;
      select count(*), coalesce(sum(a.preco) filter (where a.ativo), 0), count(a.id) filter (where a.ativo and ((_uuid(it.e->>'produtoId') is not null and exists (select 1 from produto_adicionais pa where pa.produto_id = _uuid(it.e->>'produtoId') and pa.adicional_id = a.id)) or (_uuid(it.e->>'comboId') is not null and exists (select 1 from combo_itens ci join produto_adicionais pa on pa.produto_id = ci.produto_id where ci.combo_id = _uuid(it.e->>'comboId') and pa.adicional_id = a.id))))
        into v_n_ad, v_extra, v_n_ok
        from jsonb_array_elements_text(case when jsonb_typeof(it.e->'adicionaisIds') = 'array' then it.e->'adicionaisIds' else '[]'::jsonb end) x
        left join adicionais a on a.id = _uuid(x);
      if v_n_ad <> v_n_ok then return _falha('O adicional selecionado para "' || v_nome_item || '" não está disponível.'); end if;
      if _uuid(it.e->>'produtoId') is not null then
        if not exists (select 1 from produto_precos pp where pp.produto_id = _uuid(it.e->>'produtoId') and abs(pp.preco + v_extra - v_v) <= 0.011) then
          perform _auditar('Preço divergente bloqueado', v_nome_item || ' enviado a R$ ' || _dinheiro(v_v));
          return _falha('O preço de "' || v_nome_item || '" não confere com o cadastro.');
        end if;
        if not exists (select 1 from produto_precos pp where pp.produto_id = _uuid(it.e->>'produtoId') and abs(pp.preco + v_extra - v_v) <= 0.011 and abs(pp.custo - v_c) <= 0.011) then
          perform _auditar('Custo divergente bloqueado', v_nome_item || ' enviado com custo R$ ' || _dinheiro(v_c));
          return _falha('O custo de "' || v_nome_item || '" não confere com o cadastro.');
        end if;
      else
        if not exists (select 1 from combo_precos cp where cp.combo_id = _uuid(it.e->>'comboId') and abs(cp.preco + v_extra - v_v) <= 0.011) then
          perform _auditar('Preço divergente bloqueado', v_nome_item || ' enviado a R$ ' || _dinheiro(v_v));
          return _falha('O preço de "' || v_nome_item || '" não confere com o cadastro.');
        end if;
        if not exists (select 1 from combo_precos cp where cp.combo_id = _uuid(it.e->>'comboId') and abs(cp.preco + v_extra - v_v) <= 0.011 and abs(cp.custo - v_c) <= 0.011) then
          perform _auditar('Custo divergente bloqueado', v_nome_item || ' enviado com custo R$ ' || _dinheiro(v_c));
          return _falha('O custo de "' || v_nome_item || '" não confere com o cadastro.');
        end if;
      end if;
    end if;
    v_total_item := round(v_qtd * v_v, 2);
    v_orig := v_orig + v_total_item; v_custo := v_custo + v_qtd * v_c;
  end loop;
  v_orig := round(v_orig, 2); v_custo := round(v_custo, 2);

  -- estoque (só se a regra "bloquear venda sem estoque" estiver ligada)
  select coalesce((select (valor #>> '{}') = 'true' from sistema where chave = 'BLOQUEAR_ESTOQUE_NEGATIVO'), false) into v_bloqueia;
  if v_bloqueia then
    for r in select c.ingrediente_id, c.qtd, e.ingrediente, e.quantidade from _consumo(v_itens) c join estoque e on e.id = c.ingrediente_id loop
      if r.quantidade + 0.000000001 < r.qtd then
        if v_origem = 'Cardápio' then return _falha('Um dos itens do pedido acabou. Escolha outro item ou fale com o restaurante.'); end if;
        return _falha('Estoque insuficiente de "' || r.ingrediente || '" (tem ' || r.quantidade || ', a venda precisa de ' || round(r.qtd, 3) || ').');
      end if;
    end loop;
  end if;

  -- desconto manual (precisa da senha de Admin quando quem lança não é Admin)
  if v_desc is not null and v_desc->>'valor' is not null then
    v_sol := _num(v_desc->>'valor', -1);
    if v_sol <= 0 then return _falha('Valor de desconto inválido.'); end if;
    v_aut := _exige_admin(p->>'senhaAdminConfirmacao');
    if v_aut is null then return _falha('Senha de administrador incorreta — desconto não aplicado.'); end if;
    if v_desc->>'tipo' = 'percentual' then
      if v_sol > 100 then return _falha('O desconto percentual não pode ser maior que 100%.'); end if;
      v_desc_val := round(v_orig * (v_sol / 100), 2);
      v_desc_det := v_sol || '% (R$ ' || _dinheiro(v_desc_val) || ')';
    elsif coalesce(v_desc->>'tipo', 'fixo') = 'fixo' then
      if v_sol > v_orig then return _falha('O desconto fixo não pode ser maior que o valor da venda.'); end if;
      v_desc_val := round(v_sol, 2);
      v_desc_det := 'R$ ' || _dinheiro(v_desc_val) || ' fixo';
    else
      return _falha('Tipo de desconto inválido.');
    end if;
    if v_desc_val <= 0 or v_desc_val >= v_orig then return _falha('O desconto não pode deixar a venda com valor zero ou negativo.'); end if;
  end if;

  -- tipo, taxa de entrega e total
  v_tipo := case v_tipo_in when 'Entrega' then 'Entrega' when 'Mesa' then 'Mesa' else 'Retirada' end::venda_tipo;
  if v_tipo = 'Entrega' and btrim(coalesce(v_de->>'endereco', '')) = '' then return _falha('Informe o endereço da entrega.'); end if;
  if v_tipo = 'Entrega' and coalesce(v_de->>'freteGratis', '') <> 'true' then
    select coalesce(_num(valor #>> '{}'), 0) into v_pad from sistema where chave = 'TaxaEntregaPadrao';
    v_taxa := coalesce(v_pad, 0);
    if v_nivel in ('Admin','Operador') and nullif(btrim(coalesce(v_de->>'taxa', '')), '') is not null then
      v_t := _num(v_de->>'taxa', -1);
      if v_t >= 0 and v_t <= 500 then v_taxa := round(v_t, 2); end if;
    end if;
  end if;
  v_total := round(v_orig - v_desc_val + v_taxa, 2);
  if v_total < 0.01 then return _falha('O total da venda precisa ser maior que zero.'); end if;
  if v_nivel = 'Garçom' and v_tipo_in <> 'Mesa' then
    v_pags := jsonb_build_array(jsonb_build_object('forma', v_pags->0->>'forma', 'valor', v_total));
  end if;

  -- pagamentos
  if exists (select 1 from jsonb_array_elements(v_pags) e where e->>'forma' = 'A Receber (Mesa)') then
    if jsonb_array_length(v_pags) <> 1 then return _falha('Forma de pagamento inválida para esta operação.'); end if;
    v_status_pag := 'A Receber';
  end if;
  for pg in select value as e from jsonb_array_elements(v_pags) loop
    if btrim(coalesce(pg.e->>'forma', '')) = '' then return _falha('Forma de pagamento não informada.'); end if;
    if not (_num(pg.e->>'valor', 0) > 0) then return _falha('Cada pagamento deve ter um valor maior que zero.'); end if;
    if btrim(pg.e->>'forma') = 'A Receber (Mesa)' then
      if v_nivel not in ('Admin','Operador','Garçom') or v_tipo_in <> 'Mesa' then return _falha('Forma de pagamento inválida para esta operação.'); end if;
      continue;
    end if;
    select * into v_forma_row from formas_pagamento where lower(nome) = lower(btrim(pg.e->>'forma')) limit 1;
    if not found then return _falha('Forma de pagamento não cadastrada: ' || btrim(pg.e->>'forma')); end if;
    if not v_forma_row.ativa then return _falha('A forma de pagamento está inativa: ' || btrim(pg.e->>'forma')); end if;
  end loop;
  select round(coalesce(sum(_num(e->>'valor')), 0), 2) into v_soma from jsonb_array_elements(v_pags) e;
  if abs(v_soma - v_total) > 0.02 then
    return _falha('A soma dos pagamentos (R$ ' || _dinheiro(v_soma) || ') não bate com o total da venda (R$ ' || _dinheiro(v_total) || ').');
  end if;

  -- acréscimo por forma de pagamento: os valores enviados são a parte do pedido paga em cada forma (sem acréscimo)
  for pg in select value as e from jsonb_array_elements(v_pags) loop
    if btrim(pg.e->>'forma') = 'A Receber (Mesa)' then continue; end if;
    v_acr := v_acr + _acrescimo_pagamento(pg.e->>'forma', round(_num(pg.e->>'valor') * (case when v_total > 0 then (v_total - v_taxa) / v_total else 1 end), 2));
  end loop;
  v_total := round(v_total + v_acr, 2);

  -- grava tudo
  v_status_pag_final := case when v_status_pag = 'A Receber' then 'A Receber' else 'Pago' end::status_pagamento;
  v_origem_final := (case when v_origem in ('Cardápio','Garçom') then v_origem else 'Balcão' end)::origem_venda;
  v_status_pedido_ini := (case when v_origem_final = 'Cardápio' then 'Recebido' else 'Em preparo' end)::status_pedido;
  select string_agg(btrim(e->>'forma'), ' + ') into v_resumo from jsonb_array_elements(v_pags) e;

  insert into vendas (id, cliente_nome, telefone_cliente, forma_pagamento, valor_total, custo_total, status, tipo, status_pedido,
                      endereco, complemento, referencia, observacoes_entrega, status_pagamento, recebido_em, valor_original, valor_desconto,
                      desconto_detalhe, origem, mesa_id, taxa_entrega, registrado_por, caixa_id, requisicao_id, acrescimo_forma)
  values (v_venda, v_nome, v_tel, v_resumo, v_total, v_custo, 'Confirmada', v_tipo, v_status_pedido_ini,
          case when v_tipo = 'Entrega' then coalesce(v_de->>'endereco', '') else '' end,
          case when v_tipo = 'Entrega' then coalesce(v_de->>'complemento', '') else '' end,
          case when v_tipo = 'Entrega' then coalesce(v_de->>'referencia', '') else '' end,
          coalesce(v_de->>'observacoes', ''), v_status_pag_final, case when v_status_pag_final = 'Pago' then now() else null end,
          v_orig, v_desc_val, v_desc_det, v_origem_final, case when v_tipo = 'Mesa' then v_mesa_id else null end, v_taxa, v_eu, v_caixa, v_req, v_acr)
  returning numero_pedido into v_numero;

  insert into itens_venda (venda_id, produto_id, combo_id, descricao, quantidade, valor_unitario, custo_unitario, valor_total_item, adicionais_ids)
  select v_venda, _uuid(e->>'produtoId'), _uuid(e->>'comboId'), e->>'descricao', _num(e->>'quantidade', 1)::int,
         _num(e->>'valorUnitario'), _num(e->>'custoUnitario'), round(_num(e->>'quantidade', 1) * _num(e->>'valorUnitario'), 2),
         coalesce((select array_agg(_uuid(x)) filter (where _uuid(x) is not null)
                   from jsonb_array_elements_text(case when jsonb_typeof(e->'adicionaisIds') = 'array' then e->'adicionaisIds' else '[]'::jsonb end) x), '{}')
  from jsonb_array_elements(v_itens) e;

  insert into pagamentos_venda (venda_id, forma_pagamento, valor, taxa_aplicada, acrescimo)
  select v_venda, btrim(e->>'forma'), _num(e->>'valor') + _acrescimo_pagamento(e->>'forma', _num(e->>'valor')),
         coalesce((select round((_num(e->>'valor') + _acrescimo_pagamento(e->>'forma', _num(e->>'valor'))) * f.taxa_percentual / 100 + f.taxa_fixa, 2) from formas_pagamento f where f.nome = btrim(e->>'forma')), 0),
         _acrescimo_pagamento(e->>'forma', _num(e->>'valor'))
  from jsonb_array_elements(v_pags) e;

  if v_tipo = 'Mesa' and v_mesa_status = 'Livre' then
    update mesas set status = 'Ocupada', garcom_responsavel_id = case when v_nivel = 'Garçom' then v_eu else garcom_responsavel_id end where id = v_mesa_id;
  elsif v_tipo = 'Mesa' and v_nivel = 'Garçom' and v_mesa_garcom is null then
    update mesas set garcom_responsavel_id = v_eu where id = v_mesa_id;
  end if;

  perform _ajustar_estoque(v_itens, 1, v_venda);

  if v_desc_val > 0 then
    perform _auditar('Desconto aplicado na venda', 'Autorizado por ' || coalesce(nullif(current_setting('app.autorizador', true), ''), v_login) || ' | Valor original: R$ ' || _dinheiro(v_orig)
      || ' → Desconto: ' || v_desc_det || ' → Valor final: R$ ' || _dinheiro(v_total), v_tel);
  end if;
  if v_tel <> '' then
    perform _upsert_cliente(v_tel, v_nome);
    if v_origem_final = 'Balcão' and v_status_pag_final = 'Pago' then
      perform _carimbar_fidelidade(v_tel, v_nome);
      v_msg_extra := ' Marca de fidelidade adicionada para ' || v_nome || '.';
    end if;
  end if;
  perform _auditar('Venda registrada', 'Total R$ ' || _dinheiro(v_total) || ' via ' || v_resumo || ' (' || v_tipo || ', ' || v_status_pag_final || ')', v_tel);

  return jsonb_build_object('ok', true, 'message', 'Venda registrada: R$ ' || _dinheiro(v_total) || '.' || v_msg_extra,
                            'id', v_venda, 'numero', v_numero, 'valorTotal', v_total);
end $_$;


--
-- Name: api_integracoes_config(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_config(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_prov text := p->>'provedor'; v_cfg jsonb := coalesce(p->'config', '{}'::jsonb); v_atual jsonb; v_chave text; v_novo jsonb := '{}'::jsonb;
        v_re text := '^[^@\s]+@[^@\s]+\.[^@\s]+$';
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_prov not in ('ifood', 'nfce', 'mercadopago') then return _falha('Integração inválida.'); end if;
  select config into v_atual from integracoes_config where provedor = v_prov;
  for v_chave in select jsonb_object_keys(v_cfg) loop
    if v_prov = 'ifood' and v_chave in ('confirmacaoAutomatica', 'abrirFecharComCaixa', 'pausarSemEstoque', 'enviarPrecos') then v_novo := v_novo || jsonb_build_object(v_chave, coalesce((v_cfg->>v_chave)::boolean, false));
    elsif v_prov = 'ifood' and v_chave = 'baixaEstoque' and (v_cfg->>v_chave) in ('confirmacao', 'entrega') then v_novo := v_novo || jsonb_build_object(v_chave, v_cfg->>v_chave);
    elsif v_prov = 'ifood' and v_chave = 'retencaoClientesDias' and (v_cfg->>v_chave)::int between 7 and 365 then v_novo := v_novo || jsonb_build_object(v_chave, (v_cfg->>v_chave)::int);
    elsif v_prov = 'ifood' and v_chave = 'limitePrecoPct' and (v_cfg->>v_chave)::numeric between 0 and 100 then v_novo := v_novo || jsonb_build_object(v_chave, (v_cfg->>v_chave)::numeric);
    elsif v_prov = 'nfce' and v_chave = 'emitirQuando' and (v_cfg->>v_chave) in ('pagamento', 'entrega') then v_novo := v_novo || jsonb_build_object(v_chave, v_cfg->>v_chave);
    elsif v_prov = 'nfce' and v_chave = 'canais' and jsonb_typeof(v_cfg->v_chave) = 'array' then v_novo := v_novo || jsonb_build_object(v_chave, (select coalesce(jsonb_agg(c), '[]'::jsonb) from jsonb_array_elements_text(v_cfg->v_chave) c where c in ('balcao', 'cardapio', 'ifood', 'mesa')));
    elsif v_prov = 'mercadopago' and v_chave = 'pixValidadeMin' then
      if coalesce(v_cfg->>v_chave, '') !~ '^[0-9]{1,3}$' or (v_cfg->>v_chave)::int not between 5 and 120 then return _falha('A validade do Pix deve ficar entre 5 e 120 minutos.'); end if;
      v_novo := v_novo || jsonb_build_object(v_chave, (v_cfg->>v_chave)::int);
    elsif v_prov = 'mercadopago' and v_chave = 'testeNoCardapio' then v_novo := v_novo || jsonb_build_object(v_chave, coalesce((v_cfg->>v_chave)::boolean, false));
    elsif v_prov = 'mercadopago' and v_chave = 'emailPagadorTeste' then
      if btrim(coalesce(v_cfg->>v_chave, '')) <> '' and (lower(btrim(v_cfg->>v_chave)) !~ v_re or length(v_cfg->>v_chave) > 120) then return _falha('E-mail do comprador de teste inválido.'); end if;
      v_novo := v_novo || jsonb_build_object(v_chave, lower(btrim(coalesce(v_cfg->>v_chave, ''))));
    elsif v_prov = 'mercadopago' and v_chave = 'emailsTeste' and jsonb_typeof(v_cfg->v_chave) = 'array' then
      if exists (select 1 from jsonb_array_elements_text(v_cfg->v_chave) x where btrim(x) <> '' and lower(btrim(x)) !~ v_re) then return _falha('Um dos e-mails de teste é inválido.'); end if;
      v_novo := v_novo || jsonb_build_object(v_chave, (select coalesce(jsonb_agg(q.e), '[]'::jsonb) from (select distinct lower(btrim(x)) as e from jsonb_array_elements_text(v_cfg->v_chave) x where btrim(x) <> '' limit 5) q));
    end if;
  end loop;
  update integracoes_config set config = v_atual || v_novo, atualizado_em = now() where provedor = v_prov;
  perform _auditar('Integração: ajustes salvos', v_prov);
  return api_integracoes_status('{}') || jsonb_build_object('message', 'Ajustes salvos.');
end $_$;


--
-- Name: api_integracoes_desligar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_desligar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if p->>'provedor' not in ('ifood', 'nfce', 'mercadopago') then return _falha('Integração inválida.'); end if;
  if coalesce(p->>'senhaAdmin', '') = '' or _exige_admin(p->>'senhaAdmin') is null then return _falha('Senha de administrador incorreta.'); end if;
  update integracoes_config set ligado = false, atualizado_em = now() where provedor = p->>'provedor';
  perform _auditar('Integração DESLIGADA', p->>'provedor');
  perform _integ_log(p->>'provedor', 'aviso', 'Integração desligada');
  return api_integracoes_status('{}') || jsonb_build_object('message', 'Desligado. O sistema voltou a funcionar como antes.');
end $$;


--
-- Name: api_integracoes_flags(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_flags(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_adm boolean := tem_nivel('Admin');
begin
  if auth_nivel() is null then return _negado(); end if;
  return jsonb_build_object('ok', true, 'ifood', _integracao_ligada('ifood'), 'nfce', _integracao_ligada('nfce'),
    'mercadopago', _integracao_ligada('mercadopago'),
    'nfceModo', (select modo from integracoes_config where provedor = 'nfce'),
    'impostoPct', case when v_adm then _imposto_pct((now() at time zone 'America/Sao_Paulo')::date) else 0 end,
    'impostoPadrao', case when v_adm then coalesce((select aliquota_simples from fiscal_empresa where id), 0) else 0 end,
    'impostoMeses', case when v_adm then coalesce((select valor from sistema where chave = 'ImpostoAliquotasMes' and jsonb_typeof(valor) = 'object'), '{}'::jsonb) else '{}'::jsonb end);
end $$;


--
-- Name: api_integracoes_ligar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_ligar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_prov text := p->>'provedor'; v_modo text := coalesce(p->>'modo', 'producao'); v_pend text[]; v_uid text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_prov not in ('ifood', 'nfce', 'mercadopago') then return _falha('Integração inválida.'); end if;
  if v_prov in ('nfce', 'mercadopago') and (nullif(p->>'modo', '') is null or v_modo not in ('homologacao', 'producao')) then return _falha('Escolha o ambiente: teste (homologação) ou produção.'); end if;
  if v_prov = 'ifood' then v_modo := 'producao'; end if;
  v_uid := _exige_admin(p->>'senhaAdmin');
  if coalesce(p->>'senhaAdmin', '') = '' or v_uid is null then return _falha('Senha de administrador incorreta.'); end if;
  v_pend := _integ_pendencias(v_prov, v_modo);
  if coalesce(array_length(v_pend, 1), 0) > 0 then return _falha('Ainda faltam passos: ' || array_to_string(v_pend, '; ')); end if;
  if v_prov = 'mercadopago' and not exists (select 1 from formas_pagamento where ativa and visivel_cardapio and aceita_online and tipo_online is not null) then
    return _falha('Escolha pelo menos uma forma de pagamento online (Pix ou cartão de crédito) antes de ligar.');
  end if;
  update integracoes_config set ligado = true, modo = v_modo, ligado_em = now(), ligado_por = v_uid, atualizado_em = now() where provedor = v_prov;
  perform _auditar('Integração LIGADA', v_prov || ' · ' || v_modo);
  perform _integ_log(v_prov, 'info', 'Integração ligada (' || v_modo || ')');
  return api_integracoes_status('{}') || jsonb_build_object('message', 'Ligado.');
end $$;


--
-- Name: api_integracoes_log(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_log(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'itens', coalesce((select jsonb_agg(jsonb_build_object('em', to_char(criado_em at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI:SS'), 'nivel', nivel, 'texto', mensagem) order by criado_em desc)
     from (select * from integracoes_log where provedor = p->>'provedor' order by criado_em desc limit 60) x), '[]'::jsonb));
end $$;


--
-- Name: api_integracoes_marcar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_marcar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_prov text := p->>'provedor'; v_item text := p->>'item'; v_feito boolean := coalesce((p->>'feito')::boolean, false);
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not exists (select 1 from jsonb_array_elements(_integ_checklist_def(v_prov)) x where x->>'id' = v_item and not coalesce((x->>'auto')::boolean, false)) then return _falha('Passo inválido.'); end if;
  update integracoes_config set checklist = jsonb_set(checklist, array[v_item], to_jsonb(v_feito), true), atualizado_em = now() where provedor = v_prov;
  perform _auditar('Integração: passo marcado', v_prov || ' · ' || v_item || ' · ' || v_feito::text);
  return api_integracoes_status('{}');
end $$;


--
-- Name: api_integracoes_salvar_segredo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_salvar_segredo(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_chave text := p->>'chave'; v_valor text := btrim(coalesce(p->>'valor', ''));
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_chave not in ('ifood_client_id', 'ifood_client_secret', 'ifood_merchant_id', 'nfce_token_homologacao', 'nfce_token_producao', 'nfce_csc',
                     'mp_public_key_teste', 'mp_public_key_producao', 'mp_access_token_teste', 'mp_access_token_producao', 'mp_webhook_secret') then return _falha('Campo desconhecido.'); end if;
  if coalesce(p->>'senhaAdmin', '') = '' then return _falha('Informe a sua senha de administrador.'); end if;
  if _exige_admin(p->>'senhaAdmin') is null then return _falha('Senha de administrador incorreta.'); end if;
  if length(v_valor) < 8 or length(v_valor) > 400 or v_valor ~ '\s' then return _falha('Valor inválido. Copie inteiro, sem espaços.'); end if;
  if v_chave like 'mp\_%' then
    if v_valor !~ '^[A-Za-z0-9_-]+$' then return _falha('Valor inválido. Use só letras, números, - e _ (copie inteiro, sem espaços).'); end if;
    if v_chave = 'mp_webhook_secret' and length(v_valor) < 16 then return _falha('A chave secreta do aviso (webhook) é maior que isso. Copie inteira.'); end if;
    if v_chave like 'mp\_access\_token%' and length(v_valor) < 30 then return _falha('O Access Token é maior que isso. Copie inteiro.'); end if;
  end if;
  insert into integracoes_segredos (chave, valor, atualizado_em) values (v_chave, v_valor, now())
    on conflict (chave) do update set valor = excluded.valor, atualizado_em = now();
  perform _auditar('Integração: chave salva', v_chave);
  return api_integracoes_status('{}') || jsonb_build_object('message', 'Salvo.');
end $_$;


--
-- Name: api_integracoes_status(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_status(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record; v_modo text; v_def jsonb; v_it jsonb; v_pend text[]; v_pt text[]; v_pp text[];
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  for r in select * from integracoes_config order by provedor loop
    v_def := _integ_checklist_def(r.provedor); v_pend := _integ_pendencias(r.provedor, r.modo);
    v := v || (jsonb_build_object('provedor', r.provedor, 'ligado', r.ligado, 'modo', r.modo, 'ligadoEm', r.ligado_em, 'config', r.config,
      'checklist', (select coalesce(jsonb_agg(jsonb_build_object('id', x->>'id', 'titulo', x->>'titulo', 'auto', coalesce((x->>'auto')::boolean, false),
          'feito', not ((x->>'titulo') = any (v_pend))) ), '[]'::jsonb) from jsonb_array_elements(v_def) x),
      'pendencias', to_jsonb(v_pend), 'podeLigar', coalesce(array_length(v_pend, 1), 0) = 0,
      'segredos', (select coalesce(jsonb_object_agg(s.chave, jsonb_build_object('tem', true, 'final', case when length(s.valor) > 8 then right(s.valor, 4) else '' end, 'em', s.atualizado_em)), '{}'::jsonb)
                    from integracoes_segredos s where (r.provedor = 'ifood' and s.chave like 'ifood\_%') or (r.provedor = 'nfce' and s.chave like 'nfce\_%') or (r.provedor = 'mercadopago' and s.chave like 'mp\_%')))
      || case when r.provedor = 'mercadopago' then (
           select jsonb_build_object('pendenciasTeste', to_jsonb(a.t), 'pendenciasProducao', to_jsonb(a.p),
             'podeLigarTeste', coalesce(array_length(a.t, 1), 0) = 0, 'podeLigarProducao', coalesce(array_length(a.p, 1), 0) = 0,
             'formas', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', f.nome, 'aceitaOnline', f.aceita_online, 'tipoOnline', f.tipo_online) order by f.ordem), '[]'::jsonb)
                          from formas_pagamento f where f.ativa and f.visivel_cardapio))
             from (select _integ_pendencias('mercadopago', 'homologacao') as t, _integ_pendencias('mercadopago', 'producao') as p) a)
         else '{}'::jsonb end);
  end loop;
  return jsonb_build_object('ok', true, 'integracoes', v);
end $$;


--
-- Name: api_integracoes_ver_segredo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_integracoes_ver_segredo(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if coalesce(p->>'senhaAdmin', '') = '' then return _falha('Informe a sua senha de administrador.'); end if;
  if _exige_admin(p->>'senhaAdmin') is null then return _falha('Senha de administrador incorreta.'); end if;
  select valor into v from integracoes_segredos where chave = p->>'chave';
  if v is null then return _falha('Nada guardado neste campo.'); end if;
  perform _auditar('Integração: chave visualizada', p->>'chave');
  return jsonb_build_object('ok', true, 'valor', v);
end $$;


--
-- Name: api_ler_tabelas(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_ler_tabelas(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_permitidas text[] := array['formas_pagamento','v_formas_operacional','categorias','produtos','produto_precos','produto_ingredientes','combos','combo_precos','combo_itens','adicionais','produto_adicionais','sistema','usuarios','promocoes','estoque','v_mesas','clientes','movimentacoes_estoque','sangrias','v_vendas','v_itens_venda','pagamentos_venda','v_fidelidade','v_sessao_aberta','caixa_sessoes','fechamentos_entrega','entregas_fechadas','despesas','despesas_recorrentes','ajustes_pos_venda','cupons','eventos','v_indicacoes','feedbacks','v_ocorrencias','v_cardapio_mais_pedidos'];
  v_nome text; v_ord text; v_arr jsonb; v_dados jsonb := '{}'::jsonb;
begin
  if auth_nivel() is null then return _negado(); end if;
  for v_nome in select jsonb_array_elements_text(coalesce(p->'tabelas', '[]'::jsonb)) loop
    if not (v_nome = any(v_permitidas)) then continue; end if;
    v_ord := case v_nome
      when 'v_vendas' then 't.data_hora, t.id'
      when 'v_fidelidade' then 't.cliente_id'
      when 'sistema' then 't.chave'
      when 'despesas' then 't.data_hora, t.id'
      when 'despesas_recorrentes' then 't.criada_em, t.id'
      when 'ajustes_pos_venda' then 't.data_hora, t.id'
      when 'cupons' then 't.criado_em, t.id'
      when 'eventos' then 't.data, t.id'
      when 'v_indicacoes' then 't.data, t.id'
      when 'feedbacks' then 't.data, t.id'
      when 'v_ocorrencias' then 't.numero, t.id'
      when 'v_cardapio_mais_pedidos' then 't.posicao'
      when 'v_formas_operacional' then 't.ordem'
      when 'caixa_sessoes' then 't.abertura desc, t.id'
      when 'fechamentos_entrega' then 't.fechado_em, t.id'
      else 't.id' end;
    execute format('select coalesce(jsonb_agg(to_jsonb(t) order by %s), ''[]''::jsonb) from public.%I t', v_ord, v_nome) into v_arr;
    v_dados := v_dados || jsonb_build_object(v_nome, v_arr);
  end loop;
  return jsonb_build_object('ok', true, 'dados', v_dados);
end $$;


--
-- Name: api_lgpd_config(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_lgpd_config(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_anos int; v_msg text := ''; v_cnpj text; v_razao text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if p ? 'anos' then
    v_anos := floor(_num(p->>'anos'))::int;
    if v_anos < 1 or v_anos > 10 then return _falha('Informe de 1 a 10 anos.'); end if;
    update sistema set valor = to_jsonb(v_anos) where chave = 'LgpdAnosAnonimizar';
    perform _auditar('Privacidade (LGPD): prazo alterado', 'anos', v_anos || ' anos para anonimizar clientes sem pedidos');
    v_msg := 'Prazo salvo.';
  end if;
  if p ? 'cnpj' or p ? 'razaoSocial' then
    v_cnpj := left(btrim(coalesce(p->>'cnpj', '')), 30); v_razao := left(btrim(coalesce(p->>'razaoSocial', '')), 120);
    if v_cnpj <> '' and v_cnpj !~ '^[0-9./ -]{14,20}$' then return _falha('CNPJ inválido. Use só números, pontos, barra e traço.'); end if;
    insert into sistema (chave, valor) values ('RestauranteCnpj', to_jsonb(v_cnpj)) on conflict (chave) do update set valor = excluded.valor;
    insert into sistema (chave, valor) values ('RestauranteRazaoSocial', to_jsonb(v_razao)) on conflict (chave) do update set valor = excluded.valor;
    perform _auditar('Privacidade (LGPD): dados do responsável alterados', 'cnpj', 'Razão social e CNPJ do Aviso de Privacidade');
    v_msg := 'Dados do responsável salvos.';
  end if;
  if coalesce(p->>'novaVersaoAviso', '') in ('true', 't') then
    update sistema set valor = to_jsonb(_aviso_versao() + 1) where chave = 'AvisoPrivacidadeVersao';
    perform _auditar('Privacidade (LGPD): Aviso atualizado', 'versão', 'Clientes com conta precisarão aceitar de novo');
    v_msg := 'Nova versão do Aviso publicada.';
  end if;
  return jsonb_build_object('ok', true, 'message', v_msg,
    'anos', coalesce((select _num(valor #>> '{}')::int from sistema where chave = 'LgpdAnosAnonimizar'), 3), 'versao', _aviso_versao(),
    'cnpj', coalesce((select valor #>> '{}' from sistema where chave = 'RestauranteCnpj'), ''), 'razaoSocial', coalesce((select valor #>> '{}' from sistema where chave = 'RestauranteRazaoSocial'), ''),
    'contas', (select count(*) from contas_cliente where aceite_versao > 0), 'contasPromo', (select count(*) from contas_cliente where promo_ok and aceite_versao > 0),
    'anonimizados', (select count(*) from clientes where nome = 'Cliente anonimizado'));
end $_$;


--
-- Name: api_listar_auditoria(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_listar_auditoria(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dias int := least(greatest(coalesce(nullif(p->>'dias', '')::int, 30), 1), 180); v_b text := lower(btrim(coalesce(p->>'busca', '')));
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'itens', coalesce((
    select jsonb_agg(jsonb_build_object('id', a.id, 'data', to_char(a.data_hora at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), 'usuario', a.usuario_login, 'perfil', a.perfil,
        'acao', a.acao, 'detalhes', coalesce(a.detalhes, ''), 'autorizador', a.autorizado_por, 'aparelho', a.aparelho, 'ip', a.ip) order by a.data_hora desc, a.id desc)
    from (select * from auditoria where data_hora > now() - make_interval(days => v_dias)
            and (v_b = '' or lower(coalesce(usuario_login, '') || ' ' || acao || ' ' || coalesce(detalhes, '') || ' ' || coalesce(ip, '')) like '%' || v_b || '%')
          order by data_hora desc, id desc limit 300) a), '[]'::jsonb));
end $$;


--
-- Name: api_listar_chaves_ia(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_listar_chaves_ia(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok',true,
    'extrasPublico',coalesce((select extras_publico from ai_config limit 1),false),
    'chaves',coalesce((select jsonb_agg(jsonb_build_object(
      'provedor',v.prov,
      'temChave',length(coalesce(s.chave,''))>0 and (v.prov<>'cloudflare' or length(coalesce(c.chave,''))>0),
      'final',case when length(coalesce(s.chave,''))>8 then right(s.chave,4) else '' end,
      'temConta',length(coalesce(c.chave,''))>0,
      'descansando',_ia_provedor_descansando(v.prov),
      'atualizadoEm',s.atualizado_em
    ) order by v.ordem)
    from (values ('groq',1),('groq_2',2),('nvidia',3),('cloudflare',4),('gemini',5),('gemini_2',6)) v(prov,ordem)
    left join ai_segredos s on s.provedor=v.prov
    left join ai_segredos c on c.provedor='cloudflare_conta' and v.prov='cloudflare'),'[]'::jsonb));
end $$;


