-- Name: api_listar_compras(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_listar_compras(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'fornecedores', coalesce((select jsonb_agg(to_jsonb(f) order by lower(f.nome)) from fornecedores f), '[]'::jsonb),
    'compras', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'fornecedorId', c.fornecedor_id, 'fornecedor', f.nome, 'data', c.data, 'status', c.status, 'pagamento', c.pagamento,
        'vencimento', c.vencimento, 'total', c.total, 'observacao', c.observacao, 'origem', c.origem, 'motivoCancelamento', c.motivo_cancelamento,
        'itens', coalesce((select jsonb_agg(jsonb_build_object('descricao', i.descricao, 'quantidade', i.quantidade, 'unidade', i.unidade, 'valorTotal', i.valor_total, 'ingredienteId', i.ingrediente_id) order by i.id) from compra_itens i where i.compra_id = c.id), '[]'::jsonb))
        order by c.data desc, c.criado_em desc) from (select * from compras order by data desc, criado_em desc limit 300) c join fornecedores f on f.id = c.fornecedor_id), '[]'::jsonb));
end $$;


