--
-- Name: api_listar_reembolsos(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_listar_reembolsos(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_st text := nullif(btrim(coalesce(p->>'status','')),'');
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'itens', coalesce((
    select jsonb_agg(jsonb_build_object('id', r.id, 'vendaId', r.venda_id, 'numero', v.numero_pedido, 'cliente', v.cliente_nome,
      'valor', r.valor, 'forma', r.forma_pagamento, 'motivo', r.motivo, 'status', r.status, 'criadoEm', r.criado_em,
      'devolvidoEm', r.devolvido_em, 'observacao', r.observacao, 'pagamentoOnlineId', po.id) order by r.criado_em desc)
    from reembolsos r join vendas v on v.id = r.venda_id left join pagamentos_online po on po.venda_id = r.venda_id
    where v_st is null or r.status = v_st), '[]'::jsonb));
end $$;


--
-- Name: api_listar_sessoes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_listar_sessoes(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare v_atual uuid := nullif(auth.jwt() ->> 'session_id', '')::uuid;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true, 'sessoes', coalesce((
    select jsonb_agg(x order by (x->>'vistoMs')::bigint desc) from (
      select jsonb_build_object(
        'sessaoId', left(replace(s.id::text, '-', ''), 12), 'login', u.login, 'nivel', u.nivel, 'deviceId', '',
        'ua', coalesce(s.user_agent, ''), 'ip', coalesce(host(s.ip), ''),
        'criadaEm', to_char(s.created_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
        'vistoEm', to_char(coalesce(s.refreshed_at, s.updated_at, s.created_at) at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
        'vistoMs', (extract(epoch from coalesce(s.refreshed_at, s.updated_at, s.created_at)) * 1000)::bigint,
        'atual', s.id = v_atual) as x
      from auth.sessions s join usuarios u on u.id = s.user_id
    ) t), '[]'::jsonb));
end $$;


--
-- Name: api_mp_cancelar_reserva(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_cancelar_reserva(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r pedidos_reserva%rowtype;
begin
  if auth.uid() is null then return _negado(); end if;
  select * into r from pedidos_reserva where id = _uuid(p->>'reservaId') and user_id = auth.uid() for update;
  if not found then return _falha('Pedido não encontrado.'); end if;
  if r.estado <> 'ativa' then return jsonb_build_object('ok', true, 'estado', r.estado); end if;
  if exists (select 1 from pagamentos_online g where g.reserva_id = r.id and (g.status = 'aprovado' or (g.decisao_pendente and g.decisao is null))) then
    return _falha('O pagamento deste pedido já foi aprovado. Fale com o restaurante.');
  end if;
  update pagamentos_online set status = 'cancelado', status_detalhe = 'cancelado pelo cliente', atualizado_em = now() where reserva_id = r.id and status = 'aguardando';
  perform _mp_soltar(r.id, 'cancelada', 'Cancelado pelo cliente');
  return jsonb_build_object('ok', true, 'estado', 'cancelada');
end $$;


