--
-- Name: api_mp_decidir_pagamento(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_decidir_pagamento(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare g pagamentos_online%rowtype; r pedidos_reserva%rowtype; v_dec text := lower(btrim(coalesce(p->>'decisao', ''))); v_v jsonb; v_id uuid := _uuid(p->>'pagamentoId');
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  if v_dec not in ('seguir', 'reembolsar') then return _falha('Escolha entre seguir com o pedido ou reembolsar.'); end if;
  select * into g from pagamentos_online where id = v_id;
  if not found then return _falha('Pagamento não encontrado.'); end if;
  select * into r from pedidos_reserva where id = g.reserva_id for update;
  select * into g from pagamentos_online where id = v_id for update;
  if not g.decisao_pendente or g.decisao is not null then return _falha('Este pagamento não está aguardando decisão.'); end if;
  if g.status <> 'aprovado' then return _falha('Só dá para decidir sobre um pagamento aprovado.'); end if;

  if v_dec = 'seguir' then
    if r.estado = 'confirmada' then return _falha('Já existe um pedido pago nesta reserva. Aqui só dá para reembolsar.'); end if;
    if not exists (select 1 from caixa_sessoes where status = 'Aberto') then return _falha('Abra o caixa para seguir com este pedido.'); end if;
    if r.estado <> 'ativa' then perform _mp_prender(r.id, true); end if;   -- reserva já foi solta: segura estoque, cupom e brinde de novo, sem barrar
    update pagamentos_online set decisao = 'seguir', decisao_pendente = false, decidido_por = auth.uid(), decidido_em = now(), atualizado_em = now() where id = g.id;
    v_v := _mp_criar_venda(r.id, g.id);
    perform _auditar('Pagamento online: seguir com o pedido', 'Pagamento ' || g.id || ' | Pedido Nº ' || (v_v->>'numero'), '');
    return jsonb_build_object('ok', true, 'decisao', 'seguir', 'vendaId', v_v->>'vendaId', 'numero', (v_v->>'numero')::int, 'message', 'Pedido liberado para a cozinha.');
  end if;

  if r.estado = 'ativa' then perform _mp_soltar(r.id, 'cancelada', 'Pagamento será reembolsado'); end if;
  update pagamentos_online set decisao = 'reembolsar', decisao_pendente = false, decidido_por = auth.uid(), decidido_em = now(), atualizado_em = now() where id = g.id;
  perform _auditar('Pagamento online: reembolsar', 'Pagamento ' || g.id || ' | R$ ' || _dinheiro(g.valor), '');
  return jsonb_build_object('ok', true, 'decisao', 'reembolsar', 'pagamentoId', g.id, 'valorAReembolsar', round(g.valor - g.valor_reembolsado, 2),
    'message', 'Decisão registrada. Falta devolver o dinheiro pelo Mercado Pago.');
end $_$;


--
-- Name: api_mp_forma_online(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_forma_online(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_id uuid := _uuid(p->>'formaId'); v_on boolean := coalesce((p->>'aceitaOnline')::boolean, false); v_tipo text := lower(btrim(coalesce(p->>'tipoOnline', '')));
        f formas_pagamento%rowtype; o formas_pagamento%rowtype; v_nome text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into f from formas_pagamento where id = v_id;
  if not found then return _falha('Forma de pagamento não encontrada.'); end if;
  if v_on then
    v_nome := translate(lower(f.nome), 'áàâãéêíóôõúç', 'aaaaeeiooouc');
    if v_tipo = '' then
      v_tipo := case when v_nome ~ '(^|[^a-z])pix([^a-z]|$)' then 'pix' when v_nome ~ 'credito' then 'credito' when v_nome ~ 'debito' then 'debito' else '' end;
    end if;
    if v_tipo not in ('pix', 'credito', 'debito') then return _falha('Só dá para aceitar online as formas Pix, Cartão de Crédito e Cartão de Débito.'); end if;
    if not f.ativa or not f.visivel_cardapio then return _falha('Esta forma está oculta no cardápio. Deixe-a ativa e visível antes.'); end if;
    if f.permite_troco then return _falha('Forma com troco (dinheiro) não pode ser paga pelo site.'); end if;
    select * into o from formas_pagamento where id <> f.id and aceita_online and tipo_online = v_tipo limit 1;
    if found then return _falha('A forma "' || o.nome || '" já está como ' || case v_tipo when 'pix' then 'Pix' when 'credito' then 'cartão de crédito' else 'cartão de débito' end || ' online. Desmarque-a antes.'); end if;
    update formas_pagamento set aceita_online = true, tipo_online = v_tipo where id = f.id;
  else
    update formas_pagamento set aceita_online = false, tipo_online = null where id = f.id;
  end if;
  perform _auditar('Mercado Pago: forma online', f.nome || ' · ' || case when v_on then v_tipo else 'desligada' end);
  return api_integracoes_status('{}') || jsonb_build_object('message', 'Salvo.');
end $_$;


--
-- Name: api_mp_pagamentos_recentes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_pagamentos_recentes(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'itens', (select coalesce(jsonb_agg(jsonb_build_object('em', to_char(x.criado_em at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI'), 'modo', x.mp_modo, 'metodo', x.metodo,
                'status', x.status, 'valor', x.valor, 'aDecidir', (x.decisao_pendente and x.decisao is null), 'detalhe', left(coalesce(nullif(x.erro, ''), x.status_detalhe, ''), 120)) order by x.criado_em desc), '[]'::jsonb)
              from (select * from pagamentos_online order by criado_em desc limit 15) x),
    'testePix', exists (select 1 from pagamentos_online where mp_modo = 'homologacao' and metodo = 'pix' and status in ('aprovado', 'reembolso_parcial', 'reembolsado')),
    'testeCredito', exists (select 1 from pagamentos_online where mp_modo = 'homologacao' and metodo = 'credito' and status in ('aprovado', 'reembolso_parcial', 'reembolsado')),
    'testeDebito', exists (select 1 from pagamentos_online where mp_modo = 'homologacao' and metodo = 'debito' and status in ('aprovado', 'reembolso_parcial', 'reembolsado')),
    'aDecidir', (select count(*) from pagamentos_online where decisao_pendente and decisao is null));
end $$;


--
-- Name: api_mp_pendencias_decisao(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_pendencias_decisao(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'itens', (select coalesce(jsonb_agg(jsonb_build_object(
      'pagamentoId', x.id, 'reservaId', x.reserva_id, 'metodo', x.metodo, 'modo', x.mp_modo,
      'valor', x.valor, 'criadoEm', to_char(x.criado_em at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
      'motivo', left(coalesce(nullif(x.decisao_motivo, ''), nullif(x.erro, ''), 'Pagamento aprovado sem pedido confirmado.'), 240),
      'clienteNome', coalesce(r.cliente_nome, ''), 'telefone', coalesce(r.telefone, '')
    ) order by x.criado_em), '[]'::jsonb)
    from pagamentos_online x join pedidos_reserva r on r.id = x.reserva_id
    where x.status = 'aprovado' and x.decisao_pendente and x.decisao is null));
end $$;


--
-- Name: api_mp_reservar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_reservar(p jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select public._criar_pedido_publico(p, null, true) $$;


--
-- Name: api_mp_resumo_operacional(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_resumo_operacional(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ini timestamptz := date_trunc('month', now()); v_fim timestamptz := date_trunc('month', now()) + interval '1 month';
        v_total numeric(12,2); v_taxas numeric(12,2); v_qtd integer;
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  select coalesce(sum(greatest(x.valor - x.valor_reembolsado, 0)),0), count(*)::int into v_total, v_qtd
    from pagamentos_online x where x.status in ('aprovado','reembolso_parcial','reembolsado') and x.aprovado_em >= v_ini and x.aprovado_em < v_fim;
  select coalesce(sum(pv.taxa_aplicada),0) into v_taxas
    from pagamentos_online x join pagamentos_venda pv on pv.venda_id = x.venda_id
    where x.status in ('aprovado','reembolso_parcial','reembolsado') and x.aprovado_em >= v_ini and x.aprovado_em < v_fim;
  return jsonb_build_object('ok', true, 'periodo', to_char(v_ini at time zone 'America/Sao_Paulo','MM/YYYY'),
    'quantidade', v_qtd, 'total', round(v_total,2), 'taxas', round(v_taxas,2),
    'itens', (select coalesce(jsonb_agg(jsonb_build_object('metodo', q.metodo, 'quantidade', q.quantidade, 'total', q.total, 'taxas', q.taxas) order by q.metodo), '[]'::jsonb)
      from (select x.metodo, count(*)::int as quantidade, round(coalesce(sum(greatest(x.valor - x.valor_reembolsado, 0)),0),2) as total,
                   round(coalesce(sum(pv.taxa_aplicada),0),2) as taxas
              from pagamentos_online x left join (select venda_id, sum(taxa_aplicada) as taxa_aplicada from pagamentos_venda group by venda_id) pv on pv.venda_id = x.venda_id
             where x.status in ('aprovado','reembolso_parcial','reembolsado') and x.aprovado_em >= v_ini and x.aprovado_em < v_fim
             group by x.metodo) q));
end $$;


--
-- Name: api_mp_status_pagamento(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_mp_status_pagamento(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r pedidos_reserva%rowtype; g pagamentos_online%rowtype; v_est text;
begin
  if auth.uid() is null then return _negado(); end if;
  select * into r from pedidos_reserva where id = _uuid(p->>'reservaId') and user_id = auth.uid();
  if not found then return _falha('Pedido não encontrado.'); end if;
  select * into g from pagamentos_online where reserva_id = r.id order by criado_em desc limit 1;
  v_est := case
    when r.estado = 'confirmada' then 'aprovado'
    when g.id is not null and (g.decisao = 'reembolsar' or g.status in ('reembolso_parcial', 'reembolsado')) then 'reembolso'
    when g.id is not null and g.status = 'aprovado' then 'conferindo'
    when r.estado = 'expirada' then 'expirado'
    when r.estado = 'cancelada' then 'cancelado'
    when g.id is not null and g.status = 'recusado' then 'recusado'
    when g.id is not null and g.status = 'erro' then 'erro'
    else 'aguardando' end;
  return jsonb_build_object('ok', true, 'estado', v_est, 'reservaId', r.id, 'metodo', g.metodo, 'valorTotal', r.valor_total, 'expiraEm', r.expira_em,
    'vendaId', r.venda_id, 'numero', (select v.numero_pedido from vendas v where v.id = r.venda_id), 'detalhe', coalesce(g.status_detalhe, ''),
    'pixCopiaCola', case when v_est = 'aguardando' then g.pix_copia_cola else null end, 'pixQrBase64', case when v_est = 'aguardando' then g.pix_qr_base64 else null end,
    'pixExpiraEm', case when v_est = 'aguardando' then g.pix_expira_em else null end);
end $$;


--
-- Name: api_nfce_conferencia(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_conferencia(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c integracoes_config%rowtype; v_dias int := least(coalesce(nullif(p->>'dias', '')::int, 30), 120); v_quando text; v_canais jsonb;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into c from integracoes_config where provedor = 'nfce';
  v_quando := coalesce(c.config->>'emitirQuando', 'pagamento'); v_canais := coalesce(c.config->'canais', '["balcao"]'::jsonb);
  return jsonb_build_object('ok', true, 'ligado', c.ligado, 'modo', c.modo, 'dias', v_dias,
    'semNota', coalesce((select jsonb_agg(jsonb_build_object('vendaId', v.id, 'pedido', v.numero_pedido, 'cliente', v.cliente_nome, 'quando', v.data_hora, 'valor', v.valor_total) order by v.data_hora desc)
       from (select * from vendas v where v.status::text = 'Confirmada' and v.data_hora > now() - make_interval(days => v_dias) and (c.ligado_em is null or v.data_hora >= c.ligado_em)
               and v_canais ? public._nfce_canal_da_venda(v.origem::text, v.tipo::text, v.canal)
               and case when v_quando = 'entrega' then v.status_pedido::text in ('Entregue', 'Retirada', 'Servida') else v.status_pagamento::text = 'Pago' end
               and v.valor_total > 0 and not exists (select 1 from nfce_notas n where n.venda_id = v.id) order by v.data_hora desc limit 100) v), '[]'::jsonb),
    'comProblema', (select count(*) from nfce_notas where estado in ('rejeitada', 'pendencia', 'erro') and criado_em > now() - make_interval(days => v_dias)),
    'cancelarManual', coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'pedido', v.numero_pedido, 'numero', n.numero, 'motivo', n.erro_pt)) from nfce_notas n left join vendas v on v.id = n.venda_id where n.cancelar_manual), '[]'::jsonb),
    'buracos', coalesce((select jsonb_agg(jsonb_build_object('serie', g.serie, 'ini', g.ini, 'fim', g.fim) order by g.serie, g.ini) from (
        select x.serie, x.numero + 1 ini, x.prox - 1 fim from (select serie, numero, lead(numero) over (partition by serie order by numero) prox
          from (select distinct serie, numero from nfce_notas where ambiente = c.modo and numero is not null and estado in ('autorizada', 'cancelada')) t) x
        where x.prox is not null and x.prox - x.numero > 1
          and not exists (select 1 from nfce_inutilizacoes i where i.serie = x.serie and i.ambiente = c.modo and i.estado in ('feita', 'pendente', 'duvida') and i.numero_ini <= x.numero + 1 and i.numero_fim >= x.prox - 1)) g), '[]'::jsonb),
    'inutilizacoes', coalesce((select jsonb_agg(jsonb_build_object('serie', i.serie, 'ini', i.numero_ini, 'fim', i.numero_fim, 'estado', i.estado, 'em', i.criado_em) order by i.id desc) from (select * from nfce_inutilizacoes order by id desc limit 10) i), '[]'::jsonb),
    'totais', jsonb_build_object(
      'vendas', (select coalesce(sum(v.valor_total), 0) from vendas v where v.status::text = 'Confirmada' and v.data_hora > now() - make_interval(days => v_dias) and (c.ligado_em is null or v.data_hora >= c.ligado_em) and v_canais ? public._nfce_canal_da_venda(v.origem::text, v.tipo::text, v.canal)),
      'notas', (select coalesce(sum(valor), 0) from nfce_notas where estado = 'autorizada' and ambiente <> 'simulado' and criado_em > now() - make_interval(days => v_dias))));
end $$;


--
-- Name: api_nfce_cpf(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_cpf(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cpf text := regexp_replace(coalesce(p->>'cpf', ''), '\D', '', 'g'); v_venda uuid := nullif(p->>'vendaId', '')::uuid; n nfce_notas%rowtype;
begin
  if auth_nivel() is null or not tem_nivel('Admin', 'Operador', 'Garçom') then return _negado(); end if;
  if not public._integracao_ligada('nfce') then return jsonb_build_object('ok', true, 'ignorado', true); end if;
  if v_cpf <> '' and not public._cpf_valido(v_cpf) then return _falha('CPF inválido. Confira os 11 números.'); end if;
  select * into n from nfce_notas where venda_id = v_venda for update;
  if found and n.estado not in ('pendente', 'pendencia', 'rejeitada', 'dispensada') then return _falha('A nota desta venda já foi emitida; não dá mais para incluir o CPF.'); end if;
  update vendas set cpf_nota = nullif(v_cpf, '') where id = v_venda;
  if not found then return _falha('Venda não encontrada.'); end if;
  update nfce_notas set cpf = nullif(v_cpf, ''), atualizado_em = now() where venda_id = v_venda;
  return jsonb_build_object('ok', true, 'message', case when v_cpf = '' then 'CPF removido.' else 'CPF incluído na nota.' end);
end $$;


--
-- Name: api_nfce_emitir_venda(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_emitir_venda(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v vendas%rowtype;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if not public._integracao_ligada('nfce') then return _falha('A nota fiscal está desligada.'); end if;
  select * into v from vendas where id = (p->>'vendaId')::uuid;
  if not found or v.status::text <> 'Confirmada' then return _falha('Venda não encontrada ou não confirmada.'); end if;
  insert into nfce_notas (venda_id, ref, ambiente, valor, cpf, emitir_apos, proxima_tentativa)
    values (v.id, v.id::text, (select modo from integracoes_config where provedor = 'nfce'), v.valor_total, v.cpf_nota, now(), now()) on conflict (venda_id) do nothing;
  if not found then return _falha('Esta venda já tem nota (veja a lista).'); end if;
  perform _auditar('Nota fiscal: emissão manual pedida', v.id::text);
  perform public.chamar_edge('nfce-emitir', '{}'::jsonb);
  return api_nfce_lista('{}') || jsonb_build_object('message', 'Nota criada; sendo emitida.');
end $$;


--
-- Name: api_nfce_inutilizar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_inutilizar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ini int := (p->>'ini')::int; v_fim int := (p->>'fim')::int; v_serie int := coalesce(nullif(p->>'serie', '')::int, 1); v_j text := btrim(coalesce(p->>'justificativa', '')); v_modo text; v_uid text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  v_uid := _exige_admin(p->>'senhaAdmin');
  if coalesce(p->>'senhaAdmin', '') = '' or v_uid is null then return _falha('Senha de administrador incorreta.'); end if;
  select modo into v_modo from integracoes_config where provedor = 'nfce';
  if v_ini is null or v_fim is null or v_fim < v_ini or v_fim - v_ini > 50 then return _falha('Faixa de números inválida.'); end if;
  if length(v_j) < 15 then v_j := 'Numeração pulada por falha de emissão'; end if;
  if exists (select 1 from nfce_notas where serie = v_serie and numero between v_ini and v_fim and ambiente = v_modo and estado in ('autorizada', 'cancelada')) then return _falha('Algum desses números já foi usado por uma nota.'); end if;
  insert into nfce_inutilizacoes (serie, numero_ini, numero_fim, justificativa, ambiente, por) values (v_serie, v_ini, v_fim, left(v_j, 255), v_modo, v_uid);
  perform _auditar('Nota fiscal: inutilização pedida', v_serie || ' · ' || v_ini || '-' || v_fim);
  perform public.chamar_edge('nfce-emitir', '{}'::jsonb);
  return api_nfce_conferencia('{}') || jsonb_build_object('message', 'Inutilização enviada. Atualize em instantes.');
end $$;


--
-- Name: api_nfce_lista(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_lista(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_est text := nullif(p->>'estado', ''); v_lim int := least(coalesce(nullif(p->>'limite', '')::int, 60), 200);
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  return jsonb_build_object('ok', true,
    'contagem', coalesce((select jsonb_object_agg(estado, q) from (select estado, count(*) q from nfce_notas where criado_em > now() - interval '30 days' group by 1) x), '{}'::jsonb),
    'mes', (select count(*) from nfce_notas where estado in ('autorizada', 'cancelada') and ambiente = 'producao' and emitida_em >= date_trunc('month', now() at time zone 'America/Sao_Paulo') at time zone 'America/Sao_Paulo'),
    'itens', coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'vendaId', n.venda_id, 'pedido', v.numero_pedido, 'cliente', v.cliente_nome, 'quando', v.data_hora, 'estado', n.estado, 'ambiente', n.ambiente,
        'numero', n.numero, 'serie', n.serie, 'valor', n.valor, 'erro', n.erro_pt, 'danfe', n.url_danfe, 'xml', n.url_xml, 'consulta', n.url_consulta, 'cpf', (n.cpf is not null), 'tentativas', n.tentativas,
        'emitidaEm', n.emitida_em, 'canceladaEm', n.cancelada_em, 'cancelarManual', n.cancelar_manual) order by n.id desc)
      from (select * from nfce_notas where (v_est is null or estado = v_est) order by id desc limit v_lim) n left join vendas v on v.id = n.venda_id), '[]'::jsonb));
end $$;


--
-- Name: api_nfce_pacote(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_pacote(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ano int := coalesce(nullif(p->>'ano', '')::int, extract(year from now() at time zone 'America/Sao_Paulo')::int); v_mes int := coalesce(nullif(p->>'mes', '')::int, extract(month from now() at time zone 'America/Sao_Paulo')::int);
  v_ini timestamptz; v_fim timestamptz; v_modo text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_mes not between 1 and 12 or v_ano not between 2024 and 2100 then return _falha('Mês inválido.'); end if;
  v_ini := make_timestamptz(v_ano, v_mes, 1, 0, 0, 0, 'America/Sao_Paulo'); v_fim := v_ini + interval '1 month';
  select modo into v_modo from integracoes_config where provedor = 'nfce';
  return jsonb_build_object('ok', true, 'ano', v_ano, 'mes', v_mes, 'ambiente', v_modo,
    'notas', coalesce((select jsonb_agg(jsonb_build_object('pedido', v.numero_pedido, 'emitidaEm', n.emitida_em, 'numero', n.numero, 'serie', n.serie, 'chave', n.chave, 'valor', n.valor, 'estado', n.estado,
        'canceladaEm', n.cancelada_em, 'comCpf', n.cpf is not null, 'xml', n.url_xml, 'danfe', n.url_danfe) order by n.numero)
      from nfce_notas n left join vendas v on v.id = n.venda_id where n.ambiente = v_modo and n.estado in ('autorizada', 'cancelada') and n.emitida_em >= v_ini and n.emitida_em < v_fim), '[]'::jsonb),
    'inutilizacoes', coalesce((select jsonb_agg(jsonb_build_object('serie', serie, 'ini', numero_ini, 'fim', numero_fim, 'estado', estado, 'em', criado_em)) from nfce_inutilizacoes where ambiente = v_modo and criado_em >= v_ini and criado_em < v_fim), '[]'::jsonb));
end $$;


--
-- Name: api_nfce_reemitir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_reemitir(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n nfce_notas%rowtype;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into n from nfce_notas where id = (p->>'id')::bigint for update;
  if not found then return _falha('Nota não encontrada.'); end if;
  if n.estado not in ('rejeitada', 'pendencia', 'erro', 'duvida', 'dispensada') then return _falha('Esta nota não precisa ser reemitida (' || n.estado || ').'); end if;
  update nfce_notas set estado = 'pendente', tentativas = 0, erro_pt = null, emitir_apos = now(), proxima_tentativa = now(), trava_ate = null, ambiente = coalesce((select modo from integracoes_config where provedor = 'nfce'), ambiente), atualizado_em = now() where id = n.id;
  perform _auditar('Nota fiscal: reemissão pedida', n.ref);
  perform public.chamar_edge('nfce-emitir', '{}'::jsonb);
  return api_nfce_lista('{}') || jsonb_build_object('message', 'Pedido de reemissão enviado. Atualize a lista em alguns segundos.');
end $$;


--
-- Name: api_nfce_simular(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_nfce_simular(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v vendas%rowtype; v_m jsonb; v_id bigint;
begin
  if not public._eh_dev() then return _negado(); end if;
  select * into v from vendas where status::text = 'Confirmada' and coalesce(canal, '') <> 'iFood' and not exists (select 1 from nfce_notas x where x.venda_id = vendas.id) order by data_hora desc limit 1;
  if not found then return _falha('Não há venda confirmada sem nota para usar no treino. Faça uma venda de teste antes.'); end if;
  insert into nfce_notas (venda_id, ref, ambiente, valor, cpf, emitir_apos, proxima_tentativa) values (v.id, v.id::text, 'simulado', v.valor_total, v.cpf_nota, now(), now()) returning id into v_id;
  v_m := public.nfce_montar(v_id);
  perform public.chamar_edge('nfce-emitir', '{}'::jsonb);
  return jsonb_build_object('ok', true, 'message', 'Nota de treino criada para o pedido ' || v.numero_pedido || '. ' || case when (v_m->>'ok')::boolean then 'Os dados fiscais estão completos.' else 'Atenção: ' || coalesce(v_m->>'motivo', '') end);
end $$;


--
-- Name: api_pagar_despesa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_pagar_despesa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare d despesas%rowtype; v_req text := nullif(p->>'requisicaoId', ''); v_r jsonb; v_caixa boolean := (coalesce(p->>'saiuDoCaixa', '') = 'true'); v_valor numeric;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_req is not null then perform pg_advisory_xact_lock(hashtext(v_req)); v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if; end if;
  select * into d from despesas where id = _uuid(p->>'id') for update;
  if not found then return _falha('Despesa não encontrada.'); end if;
  if d.status = 'Cancelada' then return _falha('Essa despesa está cancelada.'); end if;
  if d.status <> 'A pagar' then return _falha('Essa despesa já foi paga.'); end if;
  if v_caixa and not exists (select 1 from caixa_sessoes where status = 'Aberto') then
    return _falha('Abra o caixa para registrar um pagamento que sai do caixa.');
  end if;
  v_valor := d.valor;
  if nullif(btrim(coalesce(p->>'valorPago', '')), '') is not null then
    v_valor := round(_num(p->>'valorPago'), 2);
    if v_valor <= 0 then return _falha('Informe um valor pago maior que zero.'); end if;
    if v_valor > 9999999 then return _falha('Valor alto demais.'); end if;
  end if;
  update despesas set data_hora = now(), valor = v_valor, status = 'Paga', situacao = 'Paga', saiu_do_caixa = v_caixa where id = d.id;
  perform _auditar('Conta paga', d.descricao || ' | previsto R$ ' || _dinheiro(d.valor) || ' | pago R$ ' || _dinheiro(v_valor) || ' | ' || case when v_caixa then 'saiu do caixa' else 'fora do caixa' end);
  v_r := jsonb_build_object('ok', true, 'message', 'Pagamento registrado: R$ ' || _dinheiro(v_valor));
  if v_req is not null then perform _idem_gravar(v_req, 'pagarDespesa', v_r); end if;
  return v_r;
end $_$;


--
-- Name: api_pedir_conta_mesa(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_pedir_conta_mesa(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_q jsonb := _mesa_qr(p->>'mesa', p->>'codigo'); m mesas;
begin
  if v_q->>'ok' <> 'true' then return v_q; end if;
  select * into m from mesas where id = (v_q->>'mesaId')::uuid for update;
  if m.status::text = 'Aguardando fechamento' then return jsonb_build_object('ok', true, 'message', 'A conta já foi pedida. Já estamos a caminho!'); end if;
  if m.status::text <> 'Ocupada' then return _falha('Faça um pedido antes de pedir a conta.'); end if;
  if _excedeu('pedirconta_' || m.id::text, 3) then return _falha('Já recebemos seu pedido de conta. Aguarde um instante.'); end if;
  update mesas set status = 'Aguardando fechamento' where id = m.id;
  perform _registrar_falha('pedirconta_' || m.id::text, 600);
  perform _auditar_publico('Conta pedida pelo cliente na mesa', 'Mesa ' || m.numero, null);
  return jsonb_build_object('ok', true, 'message', 'Conta solicitada! Em instantes alguém vem até a sua mesa.');
end $$;


--
-- Name: api_preview_fechamento_entrega(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_preview_fechamento_entrega(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare c record;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if btrim(coalesce(p->>'entregador','')) = '' or coalesce(p->>'dataRef','') !~ '^\d{4}-\d{2}-\d{2}$' then return _falha('Informe o entregador e a data.'); end if;
  select * into c from _calc_fechamento_entrega(p->>'entregador', (p->>'dataRef')::date);
  return jsonb_build_object('ok', true, 'qtd', c.qtd, 'totalTaxas', c.total_taxas, 'ajudaDiaria', c.ajuda, 'totalDevido', c.total, 'vendaIds', to_jsonb(coalesce(c.ids, '{}'::uuid[])));
end $_$;


--
-- Name: api_push_cancelar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_push_cancelar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then return _negado(); end if;
  delete from push_inscricoes where usuario_id = auth.uid() and endpoint = btrim(coalesce(p->>'endpoint',''));
  return jsonb_build_object('ok', true, 'message', 'Avisos com o app fechado desativados neste aparelho.');
end $$;


--
-- Name: api_push_cliente_inscrever(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_push_cliente_inscrever(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_ep text := btrim(coalesce(p->>'endpoint','')); v_k text := btrim(coalesce(p->'keys'->>'p256dh','')); v_a text := btrim(coalesce(p->'keys'->>'auth',''));
  v_cod text := lower(btrim(coalesce(p->>'codigo',''))); v_ip text := _ip_cliente(); v_insc uuid; v_venda uuid;
begin
  if v_ep not like 'https://%' or char_length(v_ep) > 800 or v_k = '' or v_a = '' or char_length(v_k) > 200 or char_length(v_a) > 100 then return _falha('Inscrição inválida.'); end if;
  if _excedeu('pushcli_ip_' || v_ip, 30) or _excedeu('pushcli_global', 600) then return _falha('Muitas tentativas. Tente mais tarde.'); end if;
  perform _registrar_falha('pushcli_ip_' || v_ip, 600); perform _registrar_falha('pushcli_global', 600);
  insert into push_clientes (endpoint, p256dh, auth) values (v_ep, v_k, v_a)
  on conflict (endpoint) do update set p256dh = excluded.p256dh, auth = excluded.auth, falhas = 0, usado_em = now()
  returning id into v_insc;
  if v_cod ~ '^[0-9a-f]{8}$' then
    select id into v_venda from vendas where right(id::text, 8) = v_cod and origem = 'Cardápio' and mesa_id is null
      and data_hora > now() - interval '6 hours' order by data_hora desc limit 1;
    if v_venda is not null and (select count(*) from push_cliente_pedidos where venda_id = v_venda) < 5 then
      insert into push_cliente_pedidos (venda_id, inscricao_id) values (v_venda, v_insc) on conflict do nothing;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'ligado', v_venda is not null);
end $_$;


--
-- Name: api_push_inscrever(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_push_inscrever(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ep text := btrim(coalesce(p->>'endpoint','')); v_k text := btrim(coalesce(p->'keys'->>'p256dh','')); v_a text := btrim(coalesce(p->'keys'->>'auth',''));
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  if v_ep not like 'https://%' or char_length(v_ep) > 800 or v_k = '' or v_a = '' or char_length(v_k) > 200 or char_length(v_a) > 100 then return _falha('Inscrição inválida.'); end if;
  insert into push_inscricoes (usuario_id, endpoint, p256dh, auth) values (auth.uid(), v_ep, v_k, v_a)
  on conflict (endpoint) do update set usuario_id = excluded.usuario_id, p256dh = excluded.p256dh, auth = excluded.auth, falhas = 0;
  delete from push_inscricoes where usuario_id = auth.uid() and id not in (select id from push_inscricoes where usuario_id = auth.uid() order by criado_em desc limit 10);
  perform _auditar('Avisos com app fechado ativados', null);
  return jsonb_build_object('ok', true, 'message', 'Avisos com o app fechado ativados neste aparelho.');
end $$;


--
-- Name: api_receber_compra(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_receber_compra(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_id uuid := _uuid(p->>'id'); v_pg text := case when p->>'pagamento' = 'A pagar' then 'A pagar' else 'Pago' end; v_venc date := _data_iso(p->>'vencimento'); v_t numeric;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_id is null or not exists (select 1 from compras where id = v_id) then return _falha('Compra não encontrada.'); end if;
  perform _compra_receber(v_id, v_pg, v_venc, coalesce(p->>'saiuDoCaixa', '') in ('true', 't'));
  select total into v_t from compras where id = v_id;
  perform _auditar('Compra recebida', 'R$ ' || _dinheiro(v_t));
  return jsonb_build_object('ok', true, 'message', 'Compra recebida e estoque atualizado.');
exception when others then
  if sqlstate = 'P0001' then return _falha(sqlerrm); end if;
  raise;
end $_$;


--
-- Name: api_reconciliar_venda_contingencia(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_reconciliar_venda_contingencia(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id text := nullif(left(btrim(coalesce(p->>'idFila','')), 120), '');
  d jsonb := p->'dados'; v_ja contingencia_reconciliada%rowtype; v_r jsonb; v_req text; v_venda uuid; v_origem text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_id is null or jsonb_typeof(d) <> 'object' or jsonb_typeof(d->'itens') <> 'array' then return _falha('Item da fila da contingência inválido.'); end if;
  perform pg_advisory_xact_lock(hashtext('recon:' || v_id));
  select * into v_ja from contingencia_reconciliada where id_fila = v_id;
  if found then return jsonb_build_object('ok', true, 'jaFeita', true, 'id', v_ja.venda_id); end if;

  v_origem := coalesce(d->>'origem', '');
  if v_origem = 'Cardápio' then
    -- mesmo caminho do pedido do cardápio; o id da fila vira requisicaoId (reenvio devolve o pedido já criado)
    v_r := _criar_pedido_publico((d - 'desconto' - 'senhaAdminConfirmacao') || jsonb_build_object('requisicaoId', v_id), null);
  elsif v_origem = 'Caixa' then
    -- usa o id da tentativa original: se o servidor chegou a gravar a venda antes de cair, não duplica
    v_req := coalesce(nullif(d->>'requisicaoOriginal', ''), v_id);
    v_r := api_iniciar_venda((d - 'desconto' - 'senhaAdminConfirmacao' - 'timestampOriginal' - 'requisicaoOriginal' - 'emergenciaOperador')
      || jsonb_build_object('origem', 'Balcão', 'requisicaoId', v_req));
  else
    return _falha('Origem desconhecida na fila: ' || left(v_origem, 40));
  end if;

  if coalesce(v_r->>'ok', '') <> 'true' then
    return jsonb_build_object('ok', false, 'message', coalesce(v_r->>'message', 'Não foi possível lançar a venda.'));
  end if;
  v_venda := nullif(v_r->>'id', '')::uuid;
  insert into contingencia_reconciliada (id_fila, venda_id, origem, usuario_id) values (v_id, v_venda, v_origem, auth.uid()) on conflict do nothing;
  perform _auditar('Venda da contingência reconciliada',
    'Fila ' || v_id || ' · origem ' || v_origem || ' · venda ' || left(coalesce(v_venda::text, ''), 8)
      || case when coalesce(d->>'emergenciaOperador', '') <> '' then ' · feita em modo emergência por ' || left(d->>'emergenciaOperador', 40) else '' end, '');
  return jsonb_build_object('ok', true, 'id', v_venda, 'numero', v_r->'numero', 'duplicado', coalesce((v_r->>'duplicado')::boolean, false));
end $$;


--
-- Name: api_registrar_acesso(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_acesso(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then return jsonb_build_object('ok', false); end if;
  if exists (select 1 from auditoria where usuario_id = auth.uid() and acao = 'Login' and data_hora > now() - interval '1 minute') then return jsonb_build_object('ok', true); end if;
  perform _auditar('Login', null);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_registrar_ajuste_pos_venda(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_ajuste_pos_venda(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_aut text; v_aut_id uuid; v_req text := nullif(p->>'requisicaoId', ''); v_r jsonb;
        v_tipo text := btrim(coalesce(p->>'tipo', '')); v_motivo text := btrim(coalesce(p->>'motivo', '')); v_det text := left(btrim(coalesce(p->>'detalhe', '')), 200);
        v_valor numeric := round(_num(p->>'valor'), 2); ve vendas%rowtype; v_saida boolean; v_onde text; v_ja numeric; v_desp uuid; v_ref text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_req is not null then perform pg_advisory_xact_lock(hashtext(v_req)); v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if; end if;
  v_aut := _exige_admin(p->>'senhaAdminConfirmacao');
  if v_aut is null then return _falha('Senha de administrador incorreta.'); end if;
  if v_tipo <> all (array['Reembolso em dinheiro','Crédito para próxima compra','Cortesia (item grátis)','Desconto retroativo']) then return _falha('Escolha o tipo de ajuste.'); end if;
  if v_motivo <> all (array['Produto errado','Item faltando','Qualidade do produto','Atraso na entrega','Cobrança em duplicidade','Atendimento','Outro']) then return _falha('Escolha o motivo do ajuste.'); end if;
  if v_motivo = 'Outro' and v_det = '' then return _falha('Descreva o motivo (campo "Detalhe") quando escolher "Outro".'); end if;
  if not (v_valor > 0) then return _falha('Informe um valor maior que zero.'); end if;
  select * into ve from vendas where id = _uuid(p->>'vendaId') for update;
  if not found then return _falha('Venda não encontrada.'); end if;
  if ve.status <> 'Confirmada' then return _falha('Só dá para ajustar venda confirmada. Venda cancelada já foi tratada no cancelamento.'); end if;
  if ve.status_pedido is not null and ve.status_pedido::text not in ('Entregue','Retirada','Servida') then
    return _falha('O pedido ainda está "' || ve.status_pedido || '". Antes de terminar, use Editar ou Cancelar. Ajuste pós-venda é para pedido já entregue.');
  end if;
  v_saida := v_tipo in ('Reembolso em dinheiro', 'Desconto retroativo');
  if v_saida and ve.status_pagamento::text is distinct from 'Pago' then return _falha('Esta venda ainda não foi paga — não há o que devolver. Use Editar ou Cancelar.'); end if;
  if v_valor > ve.valor_total + 0.001 then return _falha('O ajuste (R$ ' || _dinheiro(v_valor) || ') não pode ser maior que o valor da venda (R$ ' || _dinheiro(ve.valor_total) || ').'); end if;
  if v_saida then
    select coalesce(sum(valor), 0) into v_ja from ajustes_pos_venda where venda_id = ve.id and status = 'Ativo' and tipo in ('Reembolso em dinheiro', 'Desconto retroativo');
    if v_ja + v_valor > ve.valor_total + 0.001 then
      return _falha('Já foram devolvidos R$ ' || _dinheiro(v_ja) || ' desta venda. Com este ajuste passaria do valor da venda (R$ ' || _dinheiro(ve.valor_total) || ').');
    end if;
  end if;
  v_onde := case when v_saida then (case when p->>'saida' = 'Do caixa' then 'Do caixa' else 'Fora do caixa' end) else 'Sem saída de dinheiro' end;
  if v_onde = 'Do caixa' and not exists (select 1 from caixa_sessoes where status = 'Aberto') then
    return _falha('Abra o caixa para registrar uma devolução que sai do caixa (ou escolha "Fora do caixa").');
  end if;
  v_ref := coalesce('nº ' || ve.numero_pedido, right(ve.id::text, 8));
  if v_saida then
    insert into despesas (descricao, valor, observacao, status, categoria, situacao, saiu_do_caixa)
    values ('Ajuste pós-venda: ' || v_tipo || ' — pedido ' || v_ref, v_valor,
            'Venda ' || right(ve.id::text, 8) || ' | ' || v_motivo || case when v_det <> '' then ' — ' || v_det else '' end,
            'Paga', 'Ajuste pós-venda', 'Paga', (v_onde = 'Do caixa'))
    returning id into v_desp;
  end if;
  select id into v_aut_id from usuarios where lower(login) = lower(v_aut);
  insert into ajustes_pos_venda (venda_id, pedido_numero, cliente, telefone, tipo, valor, motivo, detalhe, saida, despesa_id, status, autorizado_por, registrado_por)
  values (ve.id, ve.numero_pedido, ve.cliente_nome, ve.telefone_cliente, v_tipo, v_valor, v_motivo, v_det, v_saida, v_desp, 'Ativo', v_aut_id, auth.uid());
  perform _auditar('Ajuste pós-venda registrado', v_tipo || ' R$ ' || _dinheiro(v_valor) || ' | pedido ' || v_ref || ' | ' || v_motivo
                   || case when v_det <> '' then ' — ' || v_det else '' end || ' | ' || v_onde, ve.telefone_cliente);
  v_r := jsonb_build_object('ok', true, 'message', 'Ajuste registrado: ' || v_tipo || ' de R$ ' || _dinheiro(v_valor) || '.');
  if v_req is not null then perform _idem_gravar(v_req, 'registrarAjustePosVenda', v_r); end if;
  return v_r;
end $_$;


--
-- Name: api_registrar_brinde(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_brinde(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tipo text := btrim(coalesce(p->>'tipo', ''));
  v_req text := nullif(left(coalesce(p->>'requisicaoId', ''), 80), '');
  v_tel text := btrim(coalesce(p->>'telefone', ''));
  v_tel_ind text := _so_digitos(p->>'telIndicado');
  v_prod uuid := _uuid(p->>'produtoId');
  pr produtos%rowtype; f fidelidade%rowtype; i indicacoes%rowtype; e estoque%rowtype; c record;
  v_r jsonb; v_caixa uuid; v_cli uuid; v_nome text := ''; v_tel_ben text := '';
  v_custo numeric := 0; v_novo numeric; v_bloqueia boolean; v_id uuid := gen_random_uuid(); v_desp uuid;
  v_cons jsonb := '[]'::jsonb; v_itens jsonb;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if v_req is not null then
    perform pg_advisory_xact_lock(hashtext('brinde:' || v_req));
    v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if;
  end if;
  if v_tipo not in ('Fidelidade','Indicação') then return _falha('Tipo de benefício inválido.'); end if;
  if v_prod is null then return _falha('Escolha o prêmio que vai ser entregue.'); end if;
  select id into v_caixa from caixa_sessoes where status = 'Aberto'::status_caixa order by abertura desc limit 1;
  if v_caixa is null then return _falha('Abra o caixa antes de resgatar o prêmio — ele fica registrado no turno.'); end if;
  if _caixa_vencido(v_caixa) then return _falha(_caixa_msg_vencido()); end if;

  select * into pr from produtos where id = v_prod;
  if pr.id is null then return _falha('Produto não encontrado.'); end if;
  if not ((v_tipo = 'Fidelidade' and pr.premio_fidelidade) or (v_tipo = 'Indicação' and pr.premio_indicacao)) then
    return _falha('Este produto não está marcado como prêmio de ' || lower(v_tipo) || '. Marque em Editar produto › Opções avançadas.');
  end if;

  -- 1) só validações
  if v_tipo = 'Fidelidade' then
    if _so_digitos(v_tel) = '' then return _falha('Cliente não encontrado.'); end if;
    select id into v_cli from clientes where _so_digitos(telefone) = _so_digitos(v_tel) limit 1;
    if v_cli is not null then select * into f from fidelidade where cliente_id = v_cli for update; end if;
    if f.id is null then return _falha('Cliente não encontrado.'); end if;
    if f.carimbos < 10 then return _falha('Este cartão ainda não completou 10 marcas.'); end if;
    select nome, telefone into v_nome, v_tel_ben from clientes where id = v_cli;
  else
    if v_tel_ind = '' then return _falha('Indicação não encontrada.'); end if;
    select * into i from indicacoes where _so_digitos(telefone_indicado) = v_tel_ind and status = 'Pendente' order by data limit 1 for update;
    if i.id is null then return _falha('Esta indicação não está pendente (já foi resgatada ou não existe).'); end if;
    v_cli := i.indicador_id; v_nome := coalesce(i.nome_indicador, ''); v_tel_ben := coalesce(i.telefone_indicador, '');
  end if;

  v_itens := jsonb_build_array(jsonb_build_object('produtoId', pr.id, 'quantidade', 1));
  select coalesce((select (valor #>> '{}') = 'true' from sistema where chave = 'BLOQUEAR_ESTOQUE_NEGATIVO'), false) into v_bloqueia;
  for c in select * from _consumo(v_itens) order by ingrediente_id loop
    select * into e from estoque where id = c.ingrediente_id for update;
    if e.id is null then continue; end if;
    if v_bloqueia and e.quantidade + 0.000000001 < c.qtd then
      return _falha('Estoque insuficiente de "' || e.ingrediente || '" (tem ' || e.quantidade || ', o prêmio usa ' || c.qtd || ').');
    end if;
    v_custo := v_custo + round(coalesce(e.custo_unitario, 0) * c.qtd, 2);
  end loop;

  -- 2) grava
  if v_tipo = 'Fidelidade' then
    update fidelidade set carimbos = 0, premios_resgatados = f.premios_resgatados + 1, atualizada_em = now() where id = f.id;
  else
    update indicacoes set status = 'Resgatado' where id = i.id;
  end if;
  for c in select * from _consumo(v_itens) order by ingrediente_id loop
    select * into e from estoque where id = c.ingrediente_id for update;
    if e.id is null then continue; end if;
    v_novo := round(e.quantidade - c.qtd, 3);
    update estoque set quantidade = v_novo where id = e.id;
    insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
    values (e.id, 'Saída'::tipo_mov_estoque, -c.qtd, e.quantidade, v_novo, '🎁 Prêmio ' || lower(v_tipo) || ' — ' || pr.nome || ' (' || v_nome || ')', auth.uid());
    if v_novo < 0 then perform _auditar('Estoque negativo', e.ingrediente || ': ' || v_novo || ' (prêmio)'); end if;
    v_cons := v_cons || jsonb_build_array(jsonb_build_object('ingredienteId', c.ingrediente_id, 'qtd', c.qtd));
  end loop;
  v_custo := round(v_custo, 2);
  if v_custo > 0 then
    insert into despesas (data_hora, descricao, valor, observacao, status, categoria, situacao, saiu_do_caixa)
    values (now(), '🎁 Prêmio ' || lower(v_tipo) || ' — ' || pr.nome || ' (' || v_nome || ')', v_custo,
            'Custo do prêmio entregue ao cliente (não sai do caixa)', 'Paga'::status_despesa, 'Marketing', 'Paga', false)
    returning id into v_desp;
  end if;
  insert into brindes (id, tipo, cliente_id, cliente_nome, telefone, indicacao_id, produto_id, produto_nome, custo, consumo, caixa_id, despesa_id, registrado_por, requisicao_id)
  values (v_id, v_tipo, v_cli, v_nome, v_tel_ben, i.id, pr.id, pr.nome, v_custo, v_cons, v_caixa, v_desp, auth.uid(), v_req);
  perform _auditar('Prêmio entregue (' || v_tipo || ')', pr.nome || ' para ' || v_nome, v_tel_ben);

  v_r := jsonb_build_object('ok', true, 'id', v_id, 'message', '🎁 ' || pr.nome || ' entregue a ' || v_nome || '.' ||
          case when jsonb_array_length(v_cons) = 0 then ' (o produto não tem receita cadastrada: nada foi baixado do estoque)' else '' end);
  if v_req is not null then perform _idem_gravar(v_req, 'registrarBrinde', v_r); end if;
  return v_r;
end $$;


--
-- Name: api_registrar_compra(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_compra(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_req text := nullif(p->>'requisicaoId', ''); v_r jsonb; v_forn uuid; v_fnome text; x jsonb; v_n int := 0; v_tot numeric := 0; v_id uuid := gen_random_uuid();
        v_status text := case when p->>'status' = 'Pedido' then 'Pedido' else 'Recebida' end; v_pg text := case when p->>'pagamento' = 'A pagar' then 'A pagar' else 'Pago' end;
        v_venc date := _data_iso(p->>'vencimento'); v_data date := coalesce(_data_iso(p->>'data'), (now() at time zone 'America/Sao_Paulo')::date);
        v_org text := case when p->>'origem' = 'ia' then 'ia' else 'manual' end; v_ing uuid; v_ie estoque%rowtype; v_val numeric; v_qtd numeric; v_un text; v_desc text; v_erro text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_req is not null then perform pg_advisory_xact_lock(hashtext(v_req)); v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if; end if;
  if v_data > (now() at time zone 'America/Sao_Paulo')::date + 1 then return _falha('A data da compra não pode ser no futuro.'); end if;
  v_forn := _uuid(p->>'fornecedorId');
  if v_forn is null and btrim(coalesce(p->>'fornecedorNome', '')) <> '' then
    select id into v_forn from fornecedores where lower(btrim(nome)) = lower(btrim(p->>'fornecedorNome'));
    if v_forn is null then return _falha('Fornecedor "' || btrim(p->>'fornecedorNome') || '" não está cadastrado. Cadastre-o primeiro.'); end if;
  end if;
  select nome into v_fnome from fornecedores where id = v_forn and ativo;
  if v_fnome is null then return _falha('Escolha um fornecedor ativo.'); end if;
  if jsonb_typeof(p->'itens') <> 'array' or jsonb_array_length(p->'itens') = 0 then return _falha('Informe ao menos um item da compra.'); end if;
  if jsonb_array_length(p->'itens') > 30 then return _falha('No máximo 30 itens por compra.'); end if;
  if v_pg = 'A pagar' and v_status = 'Recebida' and v_venc is null then return _falha('Informe o vencimento da conta a pagar.'); end if;
  insert into compras (id, fornecedor_id, data, status, pagamento, vencimento, observacao, origem, requisicao_id, criado_por)
  values (v_id, v_forn, v_data, 'Pedido', v_pg, v_venc, left(btrim(coalesce(p->>'observacao', '')), 300), v_org, v_req, auth.uid());
  for x in select value from jsonb_array_elements(p->'itens') loop
    v_qtd := _num(x->>'quantidade'); v_val := round(_num(x->>'valorTotal'), 2); v_un := lower(btrim(coalesce(x->>'unidade', '')));
    v_ing := _uuid(x->>'ingredienteId'); v_desc := btrim(coalesce(x->>'descricao', x->>'ingrediente', ''));
    if v_ing is null and btrim(coalesce(x->>'ingrediente', '')) <> '' then
      select id into v_ing from estoque where lower(btrim(ingrediente)) = lower(btrim(x->>'ingrediente')) limit 1;
    end if;
    if v_ing is not null then
      select * into v_ie from estoque where id = v_ing;
      if not found then raise exception 'Ingrediente não encontrado no estoque.'; end if;
      if v_un = '' then v_un := v_ie.unidade::text; end if;
      if v_desc = '' then v_desc := v_ie.ingrediente; end if;
      if _converter_unidade(1, v_un, v_ie.unidade::text) is null then raise exception 'A unidade "%" não combina com a do estoque de % (%).', v_un, v_ie.ingrediente, v_ie.unidade; end if;
    elsif v_desc = '' then
      raise exception 'Cada item precisa de um nome ou de um ingrediente do estoque.';
    elsif btrim(coalesce(x->>'ingrediente', '')) <> '' and btrim(coalesce(x->>'descricao', '')) = '' then
      raise exception 'Ingrediente "%" não está no estoque. Cadastre-o em Estoque antes, ou informe só a descrição do item.', btrim(x->>'ingrediente');
    end if;
    if v_qtd <= 0 then raise exception 'Informe a quantidade de "%" maior que zero.', v_desc; end if;
    if v_val < 0 or v_val > 9999999 then raise exception 'Valor inválido em "%".', v_desc; end if;
    if v_un = '' then v_un := 'un'; end if;
    insert into compra_itens (compra_id, ingrediente_id, descricao, quantidade, unidade, valor_total) values (v_id, v_ing, left(v_desc, 80), v_qtd, left(v_un, 10), v_val);
    v_tot := v_tot + v_val; v_n := v_n + 1;
  end loop;
  update compras set total = round(v_tot, 2) where id = v_id;
  if v_status = 'Recebida' then perform _compra_receber(v_id, v_pg, v_venc, coalesce(p->>'saiuDoCaixa', '') in ('true', 't')); end if;
  perform _auditar('Compra registrada', v_fnome || ' | R$ ' || _dinheiro(v_tot) || ' | ' || v_n || ' item(ns) | ' || v_status || ' | ' || v_org);
  v_r := jsonb_build_object('ok', true, 'message', case when v_status = 'Recebida' then 'Compra registrada e estoque atualizado: R$ ' || _dinheiro(v_tot) else 'Pedido de compra registrado: R$ ' || _dinheiro(v_tot) end, 'id', v_id);
  if v_req is not null then perform _idem_gravar(v_req, 'registrarCompra', v_r); end if;
  return v_r;
exception when others then
  if sqlstate = 'P0001' then return _falha(sqlerrm); end if;
  raise;
end $_$;


--
-- Name: api_registrar_entrada_estoque(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_entrada_estoque(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e estoque%rowtype; v_qtd numeric := _num(p->>'quantidade'); v_req text := nullif(p->>'requisicaoId', ''); v_r jsonb; v_depois numeric;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_req is not null then perform pg_advisory_xact_lock(hashtext(v_req)); v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if; end if;
  if v_qtd <= 0 then return _falha('Informe uma quantidade de entrada maior que zero.'); end if;
  select * into e from estoque where id = _uuid(p->>'ingredienteId') for update;
  if not found then return _falha('Ingrediente não encontrado.'); end if;
  v_depois := e.quantidade + v_qtd;
  update estoque set quantidade = v_depois where id = e.id;
  insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
  values (e.id, 'Entrada', v_qtd, e.quantidade, v_depois, coalesce(nullif(p->>'motivo', ''), 'Reposição de estoque'), auth.uid());
  perform _auditar('Entrada de estoque', e.ingrediente || ': +' || v_qtd);
  v_r := jsonb_build_object('ok', true, 'message', 'Entrada registrada.');
  if v_req is not null then perform _idem_gravar(v_req, 'registrarEntradaEstoque', v_r); end if;
  return v_r;
end $$;


--
-- Name: api_registrar_falha_login(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_falha_login(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ip text := _ip_auditoria(); v_chave text := 'falhalogin_ip_' || coalesce(v_ip, 'sem-ip'); v_n int; v_login text;
begin
  v_login := left(regexp_replace(lower(btrim(coalesce(p->>'login', ''))), '[^a-z0-9._@ -]', '', 'g'), 40);
  v_n := _registrar_falha(v_chave, 3600);
  if v_n > 30 then return jsonb_build_object('ok', true); end if;
  if (select count(*) from auditoria where acao = 'Falha de login' and data_hora > now() - interval '1 hour') >= 300 then return jsonb_build_object('ok', true); end if;
  insert into auditoria (usuario_login, perfil, acao, detalhes, ip, aparelho) values (coalesce(nullif(v_login, ''), '—'), 'Desconhecido', 'Falha de login', 'Senha ou login incorretos', v_ip, _aparelho_auditoria());
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_registrar_inventario_estoque(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_inventario_estoque(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e estoque%rowtype; v_nova numeric := _num(p->>'novaQuantidade', -1); v_req text := nullif(p->>'requisicaoId', ''); v_r jsonb;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_req is not null then perform pg_advisory_xact_lock(hashtext(v_req)); v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if; end if;
  if v_nova < 0 then return _falha('Informe uma quantidade de inventário válida.'); end if;
  select * into e from estoque where id = _uuid(p->>'ingredienteId') for update;
  if not found then return _falha('Ingrediente não encontrado.'); end if;
  update estoque set quantidade = v_nova where id = e.id;
  insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
  values (e.id, 'Inventário', v_nova - e.quantidade, e.quantidade, v_nova, coalesce(nullif(p->>'motivo', ''), 'Contagem de inventário'), auth.uid());
  perform _auditar('Inventário de estoque', e.ingrediente || ': ' || e.quantidade || ' → ' || v_nova || ' (contagem física)');
  v_r := jsonb_build_object('ok', true, 'message', 'Inventário registrado.');
  if v_req is not null then perform _idem_gravar(v_req, 'registrarInventarioEstoque', v_r); end if;
  return v_r;
end $$;


--
-- Name: api_registrar_ocorrencia(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_ocorrencia(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_tipo text := btrim(coalesce(p->>'tipo', '')); v_desc text := btrim(coalesce(p->>'descricao', ''));
        v_vid uuid := _uuid(p->>'vendaId'); ve vendas%rowtype; v_niv text := auth_nivel()::text; v_nivel_real text; v_login text := _login_de(auth.uid());
        v_ok boolean := false; v_setor text; v_id uuid; v_num integer;
begin
  if not tem_nivel('Admin','Operador','Garçom','Cozinha','Entregador') then return _negado(); end if;
  if v_tipo <> all (array['Produção','Entrega','Atendimento','Pagamento','Estoque','Outro']) then return _falha('Escolha o tipo da ocorrência.'); end if;
  if char_length(v_desc) < 3 then return _falha('Descreva o que aconteceu.'); end if;
  if char_length(v_desc) > 600 then return _falha('Descrição muito longa (máximo 600 caracteres).'); end if;
  if nullif(btrim(coalesce(p->>'vendaId', '')), '') is not null then
    if v_vid is null then return _falha('Pedido não encontrado.'); end if;
    select * into ve from vendas where id = v_vid;
    if ve.id is null then return _falha('Pedido não encontrado.'); end if;
    v_ok := case v_niv
      when 'Admin' then true when 'Operador' then true
      when 'Entregador' then ve.tipo::text = 'Entrega' and ve.entregador_id = auth.uid()
      when 'Garçom' then ve.mesa_id is not null and ve.registrado_por = auth.uid()
                         and exists (select 1 from mesas m where m.id = ve.mesa_id and m.status::text in ('Ocupada','Aguardando fechamento'))
      when 'Cozinha' then ve.status::text = 'Confirmada' and coalesce(ve.status_pedido::text, '') in ('Recebido','Em preparo','Pronta','Servida','Retirada','Saiu para entrega','Entregue')
      else false end;
    if not v_ok then return _falha('Este pedido não está no seu escopo operacional.'); end if;
  end if;
  select nivel::text into v_nivel_real from usuarios where id = auth.uid();
  v_setor := case v_niv when 'Cozinha' then 'Cozinha' when 'Garçom' then 'Salão' when 'Entregador' then 'Entrega' when 'Operador' then 'Caixa' when 'Admin' then 'Administração' else 'Outro' end;
  insert into ocorrencias (tipo, setor, venda_id, cliente, telefone, registrado_por, descricao, status, historico)
  values (v_tipo, v_setor, ve.id, ve.cliente_nome, ve.telefone_cliente, auth.uid(), v_desc, 'Aberta',
          jsonb_build_array(_agora_br() || ' — ' || coalesce(v_login, '') || ' (' || coalesce(v_nivel_real, v_niv) || '): ocorrência registrada'))
  returning id, numero into v_id, v_num;
  perform _auditar('Ocorrência registrada', '#' || v_num || ' ' || v_tipo
                   || case when ve.id is not null then ' — pedido #' || coalesce(ve.numero_pedido::text, right(ve.id::text, 5)) else '' end
                   || ': ' || left(v_desc, 120));
  return jsonb_build_object('ok', true, 'message', 'Ocorrência #' || v_num || ' registrada.', 'id', v_id);
end $$;


--
-- Name: api_registrar_perda_estoque(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_perda_estoque(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e estoque%rowtype; v_qtd numeric := _num(p->>'quantidade'); v_req text := nullif(p->>'requisicaoId', ''); v_r jsonb; v_depois numeric; v_motivo text := btrim(coalesce(p->>'motivo', ''));
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_req is not null then perform pg_advisory_xact_lock(hashtext(v_req)); v_r := _idem_ler(v_req); if v_r is not null then return v_r; end if; end if;
  if v_qtd <= 0 then return _falha('Informe uma quantidade de perda maior que zero.'); end if;
  if v_motivo = '' then return _falha('Informe o motivo da perda.'); end if;
  select * into e from estoque where id = _uuid(p->>'ingredienteId') for update;
  if not found then return _falha('Ingrediente não encontrado.'); end if;
  if v_qtd > e.quantidade then return _falha('A perda (' || v_qtd || ') é maior que o estoque atual de ' || e.ingrediente || ' (' || e.quantidade || '). Nada foi registrado.'); end if;
  v_depois := greatest(0, e.quantidade - v_qtd);
  update estoque set quantidade = v_depois where id = e.id;
  insert into movimentacoes_estoque (ingrediente_id, tipo, quantidade, qtd_antes, qtd_depois, motivo_referencia, usuario_id)
  values (e.id, 'Perda', -v_qtd, e.quantidade, v_depois, v_motivo, auth.uid());
  perform _auditar('Perda de estoque', e.ingrediente || ': -' || v_qtd || ' (' || v_motivo || ')');
  v_r := jsonb_build_object('ok', true, 'message', 'Perda registrada.');
  if v_req is not null then perform _idem_gravar(v_req, 'registrarPerdaEstoque', v_r); end if;
  return v_r;
end $$;


--
-- Name: api_registrar_visita_cardapio(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_registrar_visita_cardapio(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_ap text := lower(btrim(coalesce(p->>'aparelho', ''))); v_dia date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  if v_ap !~ '^[a-z0-9]{16,40}$' then return jsonb_build_object('ok', false); end if;
  if (select count(*) from cardapio_visitas where dia = v_dia) >= 20000 then return jsonb_build_object('ok', true); end if;
  insert into cardapio_visitas (dia, aparelho) values (v_dia, v_ap) on conflict do nothing;
  return jsonb_build_object('ok', true);
end $_$;


