--
-- Name: api_responder_feedback(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_responder_feedback(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id'); v_txt text := left(btrim(coalesce(p->>'resposta', '')), 1000); v_nome text; v_user uuid;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if v_txt = '' then return _falha('Escreva a resposta.'); end if;
  select nome into v_nome from usuarios where id = auth.uid();
  update feedbacks set resposta = v_txt, respondido_em = now(), respondido_por = coalesce(v_nome, ''), status = 'Respondido'
   where id = v_id returning user_id into v_user;
  if not found then return _falha('Feedback não encontrado.'); end if;
  perform _auditar('Feedback respondido', 'Resposta enviada' || case when v_user is null then ' (cliente sem conta)' else '' end);
  return jsonb_build_object('ok', true, 'comConta', v_user is not null);
end $$;


--
-- Name: api_retomar_pedido(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_retomar_pedido(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t record; v vendas; antes text;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  select * into t from _pedido_trava(p); v := t.v; if t.erro is not null then return t.erro; end if;
  if v.status_pedido::text <> 'Suspenso' then return _conflito('Este pedido não está suspenso.'); end if;
  antes := coalesce(nullif(v.status_antes_suspensao,''), 'Em preparo');
  update vendas set status_pedido = (case when antes in ('Recebido','Pronta') then antes else 'Em preparo' end)::status_pedido, status_antes_suspensao = null where id = v.id;
  perform _auditar('Pedido retomado', '#' || v.numero_pedido || ' → ' || antes, v.telefone_cliente);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: api_salvar_aliquota_mes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_aliquota_mes(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_comp text := btrim(coalesce(p->>'competencia', '')); v_txt text := btrim(coalesce(p->>'aliquota', '')); v_val numeric; v_atual jsonb;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_comp !~ '^\d{4}-(0[1-9]|1[0-2])$' then return _falha('Mês inválido.'); end if;
  select case when jsonb_typeof(valor) = 'object' then valor end into v_atual from sistema where chave = 'ImpostoAliquotasMes';
  v_atual := coalesce(v_atual, '{}'::jsonb);
  if v_txt = '' then
    v_atual := v_atual - v_comp;
  else
    v_val := _num(replace(v_txt, ',', '.'), -1);
    if v_val < 0 or v_val > 33 then return _falha('Alíquota inválida: use um número de 0 a 33 (%).'); end if;
    v_atual := v_atual || jsonb_build_object(v_comp, round(v_val, 2));
  end if;
  perform _cfg_gravar('ImpostoAliquotasMes', v_atual);
  perform _auditar('Alíquota do imposto alterada', v_comp || ': ' || coalesce(nullif(v_txt, ''), 'sem alíquota própria (usa a anterior)'), null);
  return public.api_integracoes_flags('{}'::jsonb) || jsonb_build_object('message', case when v_txt = '' then 'Alíquota do mês removida.' else 'Alíquota salva.' end);
end $_$;


--
-- Name: api_salvar_cardapio_fechamento(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_cardapio_fechamento(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ativo boolean := coalesce(p->>'manualAtivo', 'false') = 'true'; v_msg text := left(btrim(coalesce(p->>'manualMensagem', '')), 150);
        v_per jsonb := '[]'::jsonb; e jsonb; v_ini date; v_fim date; v_m text; v_antes jsonb; v_n int := 0;
begin
  if not tem_nivel('Admin','Operador') then return _negado(); end if;
  if p ? 'periodos' and jsonb_typeof(p->'periodos') <> 'array' then return _falha('Lista de períodos inválida.'); end if;
  if p ? 'periodos' then
    for e in select value from jsonb_array_elements(p->'periodos') loop
      v_n := v_n + 1;
      if v_n > 30 then return _falha('No máximo 30 períodos.'); end if;
      begin v_ini := (e->>'inicio')::date; v_fim := (e->>'fim')::date;
      exception when others then return _falha('Data inválida em um dos períodos.'); end;
      if v_ini is null or v_fim is null then return _falha('Informe início e fim de cada período.'); end if;
      if v_fim < v_ini then return _falha('O fim do período não pode ser antes do início.'); end if;
      if v_fim - v_ini > 400 then return _falha('Um período não pode passar de 400 dias.'); end if;
      v_m := left(btrim(coalesce(e->>'mensagem', '')), 150);
      v_per := v_per || jsonb_build_array(jsonb_build_object('inicio', v_ini, 'fim', v_fim, 'mensagem', v_m));
    end loop;
    if tem_nivel('Operador') and not tem_nivel('Admin') then
      select valor into v_antes from sistema where chave = 'CardapioPeriodosFechado';
      if coalesce(v_antes, '[]'::jsonb) <> v_per then return _falha('Só o administrador altera os períodos programados.'); end if;
    end if;
    perform _cfg_gravar('CardapioPeriodosFechado', v_per);
  end if;
  perform _cfg_gravar('CardapioFechadoManual', jsonb_build_object('ativo', v_ativo, 'mensagem', v_msg));
  perform _auditar('Fechamento do cardápio atualizado', (case when v_ativo then 'Fechado manualmente' else 'Aberto (sem fechamento manual)' end) || ' | períodos: ' || jsonb_array_length(v_per));
  return jsonb_build_object('ok', true, 'message', case when v_ativo then 'Cardápio fechado. Os clientes veem a mensagem e não conseguem pedir.' else 'Salvo.' end);
end $$;


--
-- Name: api_salvar_chave_ia(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_chave_ia(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_prov text:=lower(coalesce(p->>'provedor','')); v_chave text:=btrim(coalesce(p->>'chave','')); v_conta text:=lower(btrim(coalesce(p->>'contaId','')));
begin
 if not tem_nivel('Admin') then return _negado(); end if;
 if v_prov not in ('gemini','groq','nvidia','cloudflare','gemini_2','groq_2') then return _falha('IA desconhecida.'); end if;
 if coalesce(p->>'senhaAdmin','')='' then return _falha('Informe a sua senha de administrador.'); end if;
 if _exige_admin(p->>'senhaAdmin') is null then return _falha('Senha de administrador incorreta.'); end if;
 if length(v_chave)<20 or length(v_chave)>300 or v_chave ~ '\s' then return _falha('Chave inválida. Copie a chave inteira, sem espaços.'); end if;
 if v_prov='cloudflare' then
  if v_conta='' and not exists(select 1 from ai_segredos where provedor='cloudflare_conta') then return _falha('Informe também o Account ID da Cloudflare.'); end if;
  if v_conta<>'' and v_conta !~ '^[0-9a-f]{32}$' then return _falha('Account ID inválido: são 32 letras e números.'); end if;
  if v_conta<>'' then insert into ai_segredos(provedor,chave,atualizado_em) values('cloudflare_conta',v_conta,now()) on conflict(provedor) do update set chave=excluded.chave,atualizado_em=now(); end if;
 end if;
 insert into ai_segredos(provedor,chave,atualizado_em) values(v_prov,v_chave,now()) on conflict(provedor) do update set chave=excluded.chave,atualizado_em=now();
 perform _auditar('Chave de IA trocada',v_prov);
 return jsonb_build_object('ok',true,'message','Chave salva.')||api_listar_chaves_ia('{}');
end $_$;


--
-- Name: api_salvar_cliente(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_cliente(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_nome text := btrim(coalesce(p->>'nome', '')); v_tel text := btrim(coalesce(p->>'telefone', ''));
        v_alvo text := nullif(btrim(coalesce(p->>'id', '')), ''); v_nasc date; v_id uuid; v_novo_id uuid := gen_random_uuid();
begin
  if not tem_nivel('Admin','Operador','Garçom') then return _negado(); end if;
  if v_nome = '' or v_tel = '' then return _falha('Nome e telefone são obrigatórios.'); end if;
  if length(v_nome) > 120 then return _falha('Nome muito longo.'); end if;
  if length(v_tel) > 25 then return _falha('Telefone muito longo.'); end if;
  perform pg_advisory_xact_lock(hashtextextended('cliente:' || _so_digitos(v_tel), 0)); -- dois cadastros do mesmo telefone ao mesmo tempo passam um de cada vez
  begin v_nasc := nullif(btrim(coalesce(p->>'dataNascimento', '')), '')::date; exception when others then v_nasc := null; end;
  -- o cliente que estamos editando (por id; por compatibilidade, também pelo telefone original)
  if v_alvo is not null then
    select id into v_id from clientes where id::text = v_alvo or _so_digitos(telefone) = _so_digitos(v_alvo) limit 1;
  end if;
  if exists (select 1 from clientes where _so_digitos(telefone) = _so_digitos(v_tel) and id is distinct from v_id) then
    return _falha('Já existe outro cliente cadastrado com esse telefone.');
  end if;
  if v_alvo is not null then
    if v_id is null then return _falha('Cliente não encontrado para edição.'); end if;
  if _versao_conflita(p, 'clientes', v_id) then return _conflito('Este registro foi alterado por outra pessoa enquanto você editava. A tela foi atualizada — confira e edite de novo.'); end if;
    update clientes set nome = v_nome, telefone = v_tel, data_nascimento = v_nasc, endereco = coalesce(p->>'endereco', ''), como_conheceu = coalesce(p->>'comoConheceu', '') where id = v_id;
    if p ? 'observacao' then update clientes set observacoes = coalesce(p->>'observacao', '') where id = v_id; end if;
    perform _auditar('Cliente atualizado', v_nome, v_tel);
    return jsonb_build_object('ok', true, 'message', 'Cadastro atualizado.');
  end if;
  insert into clientes (id, nome, telefone, data_nascimento, endereco, como_conheceu, primeiro_contato, observacoes)
  values (v_novo_id, v_nome, v_tel, v_nasc, coalesce(p->>'endereco', ''), coalesce(p->>'comoConheceu', ''), now(), coalesce(p->>'observacao', ''));
  perform _auditar('Cliente cadastrado', v_nome, v_tel);
  return jsonb_build_object('ok', true, 'message', 'Cliente cadastrado.');
end $$;


--
-- Name: api_salvar_config_cardapio(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_config_cardapio(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  perform _cfg_gravar('CardapioKicker', to_jsonb(coalesce(p->>'kicker', '')));
  perform _cfg_gravar('CardapioFrase', to_jsonb(coalesce(p->>'frase', '')));
  if p ? 'tempoEntrega' then perform _cfg_gravar('CardapioTempoEntrega', to_jsonb(coalesce(p->>'tempoEntrega', ''))); end if;
  if p ? 'tempoRetirada' then perform _cfg_gravar('CardapioTempoRetirada', to_jsonb(coalesce(p->>'tempoRetirada', ''))); end if;
  if p ? 'tempoMesa' then perform _cfg_gravar('CardapioTempoMesa', to_jsonb(coalesce(p->>'tempoMesa', ''))); end if;
  perform _auditar('Configuração do Cardápio Digital atualizada');
  return jsonb_build_object('ok', true, 'message', 'Cardápio atualizado.');
end $$;


--
-- Name: api_salvar_config_entrega(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_config_entrega(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare t numeric := _num(p->>'taxaPadrao', -1); a numeric := _num(p->>'ajudaDiaria', -1); v_t0 numeric; v_a0 numeric;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if t < 0 or t > 500 then return _falha('Taxa de entrega inválida.'); end if;
  if a < 0 or a > 1000 then return _falha('Ajuda diária inválida.'); end if;
  select coalesce(_num(valor #>> '{}'), 0) into v_t0 from sistema where chave = 'TaxaEntregaPadrao';
  select coalesce(_num(valor #>> '{}'), 0) into v_a0 from sistema where chave = 'AjudaDiariaEntregador';
  perform _cfg_gravar('TaxaEntregaPadrao', to_jsonb(round(t, 2)));
  perform _cfg_gravar('AjudaDiariaEntregador', to_jsonb(round(a, 2)));
  perform _auditar('Configuração de entrega alterada', 'Taxa: R$ ' || to_char(coalesce(v_t0, 0), 'FM999990.00') || ' → R$ ' || to_char(t, 'FM999990.00')
    || ' | Ajuda diária: R$ ' || to_char(coalesce(v_a0, 0), 'FM999990.00') || ' → R$ ' || to_char(a, 'FM999990.00') || ' (vale só para pedidos e fechamentos futuros)');
  return jsonb_build_object('ok', true, 'message', 'Configuração de entrega salva.');
end $_$;


--
-- Name: api_salvar_config_estoque(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_config_estoque(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_b boolean := coalesce(p->>'bloquear', '') in ('true', 't');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  perform _cfg_gravar('BLOQUEAR_ESTOQUE_NEGATIVO', to_jsonb(v_b));
  perform _auditar('Regra de estoque alterada', 'Bloquear venda sem estoque: ' || case when v_b then 'Sim' else 'Não' end);
