--
-- Name: api_salvar_config_notificacoes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_config_notificacoes(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_antes jsonb; v_novo jsonb; k text; e jsonb; v_perfis jsonb;
        v_ids text[] := array['pedido','entrega','estoque','financeiro','ocorrencia','sistema','fidelidade','indicacao','aniversario','inativos'];
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if jsonb_typeof(p->'eventos') <> 'object' then return _falha('Configuração inválida.'); end if;
  select coalesce(valor, '{}'::jsonb) into v_antes from sistema where chave = 'NotificacoesConfig';
  if v_antes is null or jsonb_typeof(v_antes) <> 'object' then v_antes := '{}'::jsonb; end if;
  v_novo := v_antes;
  foreach k in array v_ids loop
    e := p->'eventos'->k;
    if e is null or jsonb_typeof(e) <> 'object' then continue; end if;
    select coalesce(jsonb_agg(distinct x), '[]'::jsonb) into v_perfis
      from jsonb_array_elements_text(case when jsonb_typeof(e->'perfis') = 'array' then e->'perfis' else '[]'::jsonb end) x
      where x in ('Admin','Operador','Cozinha');
    v_novo := v_novo || jsonb_build_object(k, jsonb_build_object('ativo', (coalesce(e->>'ativo','') <> 'false'), 'perfis', v_perfis));
  end loop;
  if length(v_novo::text) > 4000 then return _falha('Configuração grande demais.'); end if;
  perform _cfg_gravar('NotificacoesConfig', v_novo);
  if v_novo <> v_antes then perform _auditar('Configuração de notificações alterada', 'Eventos atualizados'); end if;
  return jsonb_build_object('ok', true, 'message', case when v_novo <> v_antes then 'Notificações atualizadas.' else 'Nada mudou.' end);
end $$;


--
-- Name: api_salvar_conta(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_conta(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare v_id uuid := _uuid(p->>'id'); c contas_acessos%rowtype; v_serv text := left(btrim(coalesce(p->>'servico', '')), 80);
  v_email text := left(btrim(coalesce(p->>'email', '')), 120); v_link text := left(btrim(coalesce(p->>'link', '')), 500);
  v_obs text := left(btrim(coalesce(p->>'observacao', '')), 500); v_senha text := coalesce(p->>'senha', ''); v_sid uuid;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_serv = '' then return _falha('Informe o nome do serviço (ex.: Supabase, GitHub).'); end if;
  if v_link <> '' and v_link !~* '^https?://' then v_link := 'https://' || v_link; end if;
  if length(v_senha) > 200 then return _falha('Senha longa demais.'); end if;
  if v_id is null then
    insert into contas_acessos (servico, email, link, observacao, ordem) values (v_serv, v_email, v_link, v_obs, coalesce((select max(ordem) + 1 from contas_acessos), 1)) returning * into c;
  else
    update contas_acessos set servico = v_serv, email = v_email, link = v_link, observacao = v_obs, atualizado_em = now() where id = v_id returning * into c;
    if not found then return _falha('Conta não encontrada.'); end if;
  end if;
  if coalesce((p->>'removerSenha')::boolean, false) and c.senha_id is not null then
    delete from vault.secrets where id = c.senha_id; update contas_acessos set senha_id = null where id = c.id;
  elsif v_senha <> '' then
    if c.senha_id is null then
      v_sid := vault.create_secret(v_senha, 'conta_acesso_' || c.id::text, 'Senha da conta ' || v_serv);
      update contas_acessos set senha_id = v_sid where id = c.id;
    else
      perform vault.update_secret(c.senha_id, v_senha);
    end if;
  end if;
  perform _auditar(case when v_id is null then 'Conta cadastrada' else 'Conta editada' end, v_serv || case when v_senha <> '' then ' (senha alterada)' else '' end);
  return jsonb_build_object('ok', true, 'message', 'Conta salva.') || api_listar_contas('{}');
end $$;


--
-- Name: api_salvar_cupom(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_cupom(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v record;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select * into v from _cupom_validar(p, null);
  if v.erro is not null then return _falha(v.erro); end if;
  insert into cupons (codigo, nome, tipo, valor, frete_gratis, data_inicio, data_fim, hora_inicio, hora_fim, limite_total, limite_por_cliente, valor_minimo, ativa, acumula, faixas, criado_por,
                      somente_conta, cliente_id, mensagem, visivel_conta, automatico, validade_dias)
  values ((v.c).codigo, (v.c).nome, (v.c).tipo, (v.c).valor, (v.c).frete_gratis, (v.c).data_inicio, (v.c).data_fim, (v.c).hora_inicio, (v.c).hora_fim, (v.c).limite_total, (v.c).limite_por_cliente, (v.c).valor_minimo, (v.c).ativa, (v.c).acumula, (v.c).faixas, auth.uid(),
          (v.c).somente_conta, (v.c).cliente_id, (v.c).mensagem, (v.c).visivel_conta, (v.c).automatico, (v.c).validade_dias);
  perform _auditar('Cupom criado', (v.c).codigo, (v.c).nome || ' | benefício ' || (v.c).tipo || ' ' || (v.c).valor);
  return jsonb_build_object('ok', true, 'message', 'Cupom criado.');
end $$;


--
-- Name: api_salvar_dados_restaurante(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_dados_restaurante(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare k text; chaves text[] := array['nome','endereco','telefone','horario','redes']; lim int[] := array[60,200,30,300,300]; i int; v text;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  for i in 1..5 loop
    k := chaves[i];
    v := btrim(coalesce(p->>k, ''));
    if length(v) > lim[i] then return _falha('O campo "' || k || '" passou de ' || lim[i] || ' caracteres.'); end if;
    perform _cfg_gravar('Restaurante' || initcap(k), to_jsonb(v));
  end loop;
  perform _auditar('Dados do restaurante atualizados');
  return jsonb_build_object('ok', true, 'message', 'Dados do restaurante salvos.');
end $$;


--
-- Name: api_salvar_evento(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_evento(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id'); v_nome text := left(btrim(coalesce(p->>'nome', '')), 120); v_data date := _data_iso(btrim(coalesce(p->>'data', '')));
        v_st text := coalesce(nullif(btrim(p->>'status'), ''), 'Orçamento'); v_vc numeric; v_novo uuid;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_nome = '' or v_data is null then return _falha('Informe nome e data do evento.'); end if;
  if v_st <> all (array['Orçamento','Confirmado','Em andamento','Concluído','Cancelado']) then v_st := 'Orçamento'; end if;
  v_vc := case when btrim(coalesce(p->>'valorContratado', '')) = '' then 0 else _num(p->>'valorContratado', -1) end;
  if v_vc < 0 then return _falha('Valor contratado inválido.'); end if;
  v_vc := round(v_vc, 2);
  if v_id is not null and exists (select 1 from eventos where id = v_id) then
  if _versao_conflita(p, 'eventos', v_id) then return _conflito('Este registro foi alterado por outra pessoa enquanto você editava. A tela foi atualizada — confira e edite de novo.'); end if;
    update eventos set nome = v_nome, tipo = left(coalesce(p->>'tipo', ''), 60), data = v_data, hora_inicio = _hora_valida(p->>'horaInicio'), hora_fim = _hora_valida(p->>'horaFim'),
           local = left(coalesce(p->>'local', ''), 160), contratante = left(coalesce(p->>'contratante', ''), 120), telefone = left(coalesce(p->>'telefone', ''), 30),
           status = v_st, valor_contratado = v_vc, observacoes = left(coalesce(p->>'observacoes', ''), 1000)
     where id = v_id;
    perform _recalcular_evento(v_id);
    perform _auditar('Evento alterado', v_id::text, v_nome);
    return jsonb_build_object('ok', true, 'message', 'Evento atualizado.', 'evento', _evento_json(v_id));
  end if;
  insert into eventos (nome, tipo, data, hora_inicio, hora_fim, local, contratante, telefone, status, valor_contratado, valor_recebido, valor_a_receber, custo_total, resultado, observacoes, criado_por)
  values (v_nome, left(coalesce(p->>'tipo', ''), 60), v_data, _hora_valida(p->>'horaInicio'), _hora_valida(p->>'horaFim'), left(coalesce(p->>'local', ''), 160),
          left(coalesce(p->>'contratante', ''), 120), left(coalesce(p->>'telefone', ''), 30), v_st, v_vc, 0, v_vc, 0, v_vc, left(coalesce(p->>'observacoes', ''), 1000), auth.uid())
  returning id into v_novo;
  perform _auditar('Evento criado', v_novo::text, v_nome);
  return jsonb_build_object('ok', true, 'message', 'Evento criado.', 'evento', _evento_json(v_novo));
end $$;


--
-- Name: api_salvar_fornecedor(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_fornecedor(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'id'); v_nome text := btrim(coalesce(p->>'nome', '')); f fornecedores%rowtype;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if char_length(v_nome) < 2 or char_length(v_nome) > 80 then return _falha('Informe o nome do fornecedor (2 a 80 letras).'); end if;
  if exists (select 1 from fornecedores where lower(btrim(nome)) = lower(v_nome) and id is distinct from v_id) then return _falha('Já existe um fornecedor com esse nome.'); end if;
  if v_id is null then
    insert into fornecedores (nome, telefone, observacao, criado_por) values (v_nome, left(btrim(coalesce(p->>'telefone', '')), 30), left(btrim(coalesce(p->>'observacao', '')), 300), auth.uid()) returning * into f;
    perform _auditar('Fornecedor cadastrado', v_nome);
  else
    update fornecedores set nome = v_nome, telefone = left(btrim(coalesce(p->>'telefone', '')), 30), observacao = left(btrim(coalesce(p->>'observacao', '')), 300),
           ativo = case when p ? 'ativo' then coalesce(p->>'ativo', 'true') not in ('false', 'f') else ativo end
     where id = v_id returning * into f;
    if not found then return _falha('Fornecedor não encontrado.'); end if;
    perform _auditar('Fornecedor alterado', v_nome);
  end if;
  return jsonb_build_object('ok', true, 'message', 'Fornecedor salvo.', 'fornecedor', to_jsonb(f));
end $$;


--
-- Name: api_salvar_ia_extras(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_ia_extras(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if coalesce(p->>'senhaAdmin', '') = '' then return _falha('Informe a sua senha de administrador.'); end if;
  if _exige_admin(p->>'senhaAdmin') is null then return _falha('Senha de administrador incorreta.'); end if;
  update ai_config set extras_publico = coalesce((p->>'publico')::boolean, false), atualizado_em = now() where id;
  perform _auditar('IAs extras no atendimento público', case when coalesce((p->>'publico')::boolean, false) then 'ligado' else 'desligado' end);
  return jsonb_build_object('ok', true, 'message', case when coalesce((p->>'publico')::boolean, false) then 'As IAs extras também atendem os clientes do cardápio.' else 'As IAs extras ficam só no uso interno.' end) || api_listar_chaves_ia('{}');
end $$;


--
-- Name: api_salvar_meta(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_meta(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_tipo text := p->>'tipo'; v_val numeric := _num(p->>'valor');
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if v_tipo is null or v_tipo not in ('MetaMensal','MetaDiaria') then return _falha('Tipo de meta inválido.'); end if;
