  perform _auditar('Meta atualizada', v_tipo || ': R$ ' || to_char(v_val, 'FM999990.00'));
  return jsonb_build_object('ok', true);
end $_$;


--
-- Name: api_salvar_precos_lote(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_salvar_precos_lote(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare x jsonb; e estoque%rowtype; v_un text; v_c numeric; f numeric; n int := 0;
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  if jsonb_typeof(p->'itens') <> 'array' or jsonb_array_length(p->'itens') = 0 then return _falha('Nada para salvar.'); end if;
  if jsonb_array_length(p->'itens') > 400 then return _falha('Muitos itens de uma vez.'); end if;
  for x in select value from jsonb_array_elements(p->'itens') loop
    select * into e from estoque where id = _uuid(x->>'id') for update;
    if not found then continue; end if;
    v_un := lower(coalesce(nullif(btrim(x->>'unidade'), ''), e.unidade::text));
    if v_un not in ('un','g','kg','ml','l') then raise exception 'Unidade inválida em "%".', e.ingrediente; end if;
    f := case when v_un <> e.unidade::text then _converter_unidade(1, e.unidade::text, v_un) end;
    v_c := case when x ? 'custo' and nullif(btrim(x->>'custo'), '') is not null then _num(x->>'custo', -1)
                when f is not null then e.custo_unitario / f else e.custo_unitario end;
    if v_c < 0 or v_c > 999999 then raise exception 'Preço inválido em "%".', e.ingrediente; end if;
    if v_un is distinct from e.unidade::text or round(v_c, 4) is distinct from e.custo_unitario then
      update estoque set unidade = v_un::unidade_estoque, custo_unitario = round(v_c, 4),
             quantidade = case when f is not null then quantidade * f else quantidade end,
             quantidade_minima = case when f is not null then quantidade_minima * f else quantidade_minima end
       where id = e.id;
      n := n + 1;
    end if;
  end loop;
  if n > 0 then perform _auditar('Preços de ingredientes em lote', n || ' ingrediente(s) atualizado(s)'); end if;
  return jsonb_build_object('ok', true, 'message', case when n = 0 then 'Nada mudou.' else n || ' ingrediente(s) atualizado(s). Custos dos produtos recalculados.' end, 'alterados', n);
exception when others then
  if sqlstate = 'P0001' then return _falha(sqlerrm); end if;
  raise;
end $$;


--
-- Name: api_saude_sistema(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_saude_sistema(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
declare itens jsonb := '[]'::jsonb; v_n int; v_min numeric; v_b record; v_i record; v_c int; v_ia int; v_ult timestamptz; v_pior text := 'ok';
begin
  if not tem_nivel('Admin') then return _negado(); end if;
  select count(*), coalesce(extract(epoch from (now() - min(criado_em))) / 60, 0) into v_n, v_min from fila_sync where principal_ok_em is null;
  itens := itens || jsonb_build_object('id', 'fila', 'titulo', 'Cópia para a planilha de reserva',
    'nivel', case when v_n = 0 then 'ok' when v_min < 30 then 'atencao' else 'problema' end,
    'texto', case when v_n = 0 then 'Tudo copiado.' else v_n || ' item(ns) esperando; o mais antigo há ' || round(v_min) || ' min.' end);
  select * into v_b from backups order by data_hora desc limit 1;
  itens := itens || jsonb_build_object('id', 'backup', 'titulo', 'Backup automático',
    'nivel', case when v_b.id is null then 'problema' when v_b.status <> 'Sucesso' then 'problema' when v_b.data_hora < now() - interval '48 hours' then 'problema' when v_b.data_hora < now() - interval '26 hours' then 'atencao' else 'ok' end,
    'texto', case when v_b.id is null then 'Nenhum backup encontrado.' when v_b.status <> 'Sucesso' then 'O último backup falhou: ' || coalesce(left(v_b.erro, 120), 'sem detalhe') else 'Último backup há ' || round(extract(epoch from (now() - v_b.data_hora)) / 3600, 1) || ' h.' end);
  itens := itens || jsonb_build_object('id', 'drive', 'titulo', 'Cópia do backup no Drive',
    'nivel', case when v_b.id is null then 'atencao' when v_b.copia_drive_erro is not null then 'atencao' when v_b.copia_drive_em is null then 'atencao' else 'ok' end,
    'texto', case when v_b.copia_drive_erro is not null then 'Falhou: ' || left(v_b.copia_drive_erro, 120) when v_b.copia_drive_em is null then 'Ainda não copiado.' else 'Copiado no Drive.' end);
  select * into v_i from integridade_checks order by criado_em desc limit 1;
  itens := itens || jsonb_build_object('id', 'integridade', 'titulo', 'Conferência de vendas (diária)',
    'nivel', case when v_i.id is null then 'atencao' when v_i.status <> 'ok' then 'problema' when v_i.criado_em < now() - interval '3 days' then 'atencao' else 'ok' end,
    'texto', case when v_i.id is null then 'Ainda não rodou.' when v_i.status <> 'ok' then 'Conferência do dia ' || to_char((v_i.detalhe->>'data')::date, 'DD/MM') || ' achou diferença: ' || v_i.supabase_vendas || ' vendas no Supabase x ' || v_i.planilha_vendas || ' na planilha.' else 'Conferido o dia ' || to_char((v_i.detalhe->>'data')::date, 'DD/MM') || ': ' || v_i.supabase_vendas || ' vendas no Supabase e ' || v_i.planilha_vendas || ' na planilha.' end);
  select count(*) into v_c from cron.job j where (select d.status from cron.job_run_details d where d.jobid = j.jobid order by d.start_time desc limit 1) = 'failed';
  itens := itens || jsonb_build_object('id', 'tarefas', 'titulo', 'Tarefas automáticas', 'nivel', case when v_c = 0 then 'ok' else 'problema' end,
    'texto', case when v_c = 0 then 'Todas rodaram bem na última vez.' else v_c || ' tarefa(s) falharam na última execução.' end);
  select count(*) into v_ia from ai_log where criado_em > now() - interval '1 hour' and status = 'erro';
  itens := itens || jsonb_build_object('id', 'ia', 'titulo', 'Assistente (IA)', 'nivel', case when v_ia >= 5 then 'atencao' else 'ok' end,
    'texto', case when v_ia >= 5 then v_ia || ' erro(s) na última hora; o sistema segue normal.' else 'Funcionando.' end);
  itens := itens || _saude_integracoes();
  itens := itens || _saude_uso_plano();
  select case when bool_or(x->>'nivel' = 'problema') then 'problema' when bool_or(x->>'nivel' = 'atencao') then 'atencao' else 'ok' end into v_pior from jsonb_array_elements(itens) x;
  return jsonb_build_object('ok', true, 'geral', v_pior, 'itens', itens, 'em', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI'));
end $$;


--
-- Name: api_segredo(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_segredo(p_nome text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
