--
-- Name: auth_nivel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_nivel() RETURNS public.nivel_acesso
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when u.nivel::text = 'Desenvolvedor' then 'Admin'::nivel_acesso else u.nivel end
  from usuarios u
  where u.id = auth.uid() and u.ativo
    and (coalesce(auth.jwt() ->> 'session_id', '') = ''
         or exists (select 1 from auth.sessions s where s.id = (auth.jwt() ->> 'session_id')::uuid))
$$;


--
-- Name: backup_tabelas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backup_tabelas() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'tabela', c.relname::text,
           'chaves', to_jsonb(coalesce(public._pk_cols(c.relname::text),
              array[(select a.attname::text from pg_attribute a
                      where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
                      order by a.attnum limit 1)]))
         ) order by c.relname), '[]'::jsonb)
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r','p') and not c.relispartition
    and c.relname <> all (public._backup_excluidas())
$$;


--
-- Name: chamar_edge(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chamar_edge(p_funcao text, p_body jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT net.http_post(
    url := coalesce((SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='project_url'), 'https://SEU-PROJETO.supabase.co')||'/functions/v1/'||p_funcao,
    headers := jsonb_build_object('Content-Type','application/json',
      'Authorization','Bearer '||(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='service_key')),
    body := p_body, timeout_milliseconds := 30000) $$;


--
-- Name: chat_abrir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_abrir(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  cfg chat_config%rowtype; v_ip text := _ip_cliente();
  v_cod text := lower(btrim(coalesce(p->>'codigo', '')));
  v_num text := btrim(coalesce(p->>'numero', ''));
  v_tel4 text := regexp_replace(coalesce(p->>'telefone4', ''), '\D', '', 'g');
  -- Acompanhamento do pedido: quem já está dentro do pedido (código completo, sem telefone) não precisa informar os 4 dígitos.
  v_sem_tel boolean := coalesce(p->>'acompanhamento', '') = 'true' and length(lower(btrim(coalesce(p->>'codigo', '')))) >= 32;
  v vendas%rowtype; c chat_conversas%rowtype; v_tok text;
begin
  select * into cfg from chat_config where id;
  if not coalesce(cfg.chat_publico_ligado, false) then
    return jsonb_build_object('ok', false, 'desligado', true, 'message', 'O atendimento por chat está indisponível no momento.');
  end if;
  if not v_sem_tel and v_tel4 !~ '^[0-9]{4}$' then return _falha('Informe os 4 últimos dígitos do telefone do pedido.'); end if;
  if _excedeu('chat_ip_' || v_ip, 10) or _excedeu('chat_falhas', 200) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas tentativas seguidas. Aguarde alguns minutos.');
  end if;
  if v_cod ~ '^[0-9a-f-]{8,36}$' then
    select * into v from vendas
     where right(id::text, 8) = right(v_cod, 8) and right(id::text, length(v_cod)) = v_cod
       and (v_sem_tel or right(regexp_replace(coalesce(telefone_cliente, ''), '\D', '', 'g'), 4) = v_tel4)
     order by data_hora desc limit 1;
  elsif v_num ~ '^[0-9]{1,9}$' and not v_sem_tel then
    select * into v from vendas
     where numero_pedido = v_num::int
       and right(regexp_replace(coalesce(telefone_cliente, ''), '\D', '', 'g'), 4) = v_tel4
     order by data_hora desc limit 1;
  end if;
  if v.id is null then
    perform _registrar_falha('chat_ip_' || v_ip, 600); perform _registrar_falha('chat_falhas', 600);
    return _falha('Não encontrei um pedido com esses dados. Confira o número e os 4 últimos dígitos do telefone.');
  end if;
  if v.data_hora < now() - make_interval(hours => cfg.janela_horas) then
    return _falha('Este pedido passou do prazo de atendimento pelo chat. Fale diretamente com o restaurante.');
  end if;
  v_tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  select * into c from chat_conversas where venda_id = v.id and estado <> 'encerrada' for update;
  if c.id is null then
    begin
      insert into chat_conversas (venda_id) values (v.id) returning * into c;
    exception when unique_violation then
      select * into c from chat_conversas where venda_id = v.id and estado <> 'encerrada';
    end;
  end if;
  insert into chat_tokens (conversa_id, token_hash) values (c.id, _chat_hash(v_tok))
  on conflict (conversa_id) do update set token_hash = excluded.token_hash, criado_em = now();
  return jsonb_build_object('ok', true, 'token', v_tok, 'conversaId', c.id, 'estado', c.estado, 'caixaAberto', _chat_caixa_aberto(),
    'pedido', jsonb_build_object('numero', v.numero_pedido, 'status', v.status::text, 'statusPedido', v.status_pedido::text,
      'tipoEntrega', v.tipo::text, 'data', to_char(v.data_hora at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')));
end $_$;


--
-- Name: chat_assumir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_assumir(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'conversaId'); c chat_conversas%rowtype; v_login text := _login_de(auth.uid());
        v_forcar boolean := coalesce(p->>'forcar', '') = 'true' and auth_nivel()::text = 'Admin';
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  select * into c from chat_conversas where id = v_id for update;
  if c.id is null then return _falha('Conversa não encontrada.'); end if;
  if c.estado = 'encerrada' then return _falha('Este atendimento já foi encerrado.'); end if;
  if c.estado = 'recepcao' then return _falha('O cliente ainda não terminou de pedir ajuda.'); end if;
  if c.estado = 'em_atendimento' and c.atendente_id is distinct from auth.uid() and not v_forcar then
    return _falha('Este atendimento já foi assumido por ' || coalesce(_login_de(c.atendente_id), 'outra pessoa') || '.');
  end if;
  if c.estado = 'em_atendimento' and c.atendente_id = auth.uid() then
    return jsonb_build_object('ok', true, 'message', 'Você já está neste atendimento.');
  end if;
  update chat_conversas set estado = 'em_atendimento', atendente_id = auth.uid(), atualizado_em = now() where id = v_id;
  insert into chat_mensagens (conversa_id, autor, autor_id, texto) values (v_id, 'sistema', auth.uid(), coalesce(v_login, 'A equipe') || ' assumiu o atendimento.');
  if c.ocorrencia_id is not null then
    update ocorrencias set status = 'Em andamento', responsavel = v_login, atualizada_em = now(),
      historico = historico || jsonb_build_array(_agora_br() || ' — ' || coalesce(v_login, '') || ': assumiu o atendimento pelo chat')
    where id = c.ocorrencia_id and status <> 'Resolvida';
  end if;
  perform _auditar('Chat: atendimento assumido', 'conversa ' || left(v_id::text, 8));
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: chat_encerrar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_encerrar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'conversaId'); v_sol text := _chat_limpar(p->>'solucao'); c chat_conversas%rowtype; v_login text := _login_de(auth.uid());
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  if char_length(v_sol) < 3 then return _falha('Registre a solução antes de encerrar.'); end if;
  if char_length(v_sol) > 600 then return _falha('Solução muito longa (máximo 600 caracteres).'); end if;
  select * into c from chat_conversas where id = v_id for update;
  if c.id is null then return _falha('Conversa não encontrada.'); end if;
  if c.estado = 'encerrada' then return jsonb_build_object('ok', true, 'message', 'Este atendimento já estava encerrado.'); end if;
  if c.estado = 'recepcao' then return _falha('O cliente ainda não pediu atendimento da equipe.'); end if;
  if c.estado = 'em_atendimento' and c.atendente_id is distinct from auth.uid() and auth_nivel()::text <> 'Admin' then
    return _falha('Este atendimento está com ' || coalesce(_login_de(c.atendente_id), 'outra pessoa') || '.');
  end if;
  update chat_conversas set estado = 'encerrada', solucao = v_sol, encerrada_em = now(), atualizado_em = now(),
    atendente_id = coalesce(atendente_id, auth.uid()), nao_lidas_equipe = 0, nao_lidas_cliente = nao_lidas_cliente + 1
  where id = v_id;
  insert into chat_mensagens (conversa_id, autor, autor_id, texto) values (v_id, 'sistema', auth.uid(), 'Atendimento encerrado pela equipe.');
  if c.ocorrencia_id is not null then
    update ocorrencias set status = 'Resolvida', solucao = v_sol, atualizada_em = now(),
      responsavel = coalesce(nullif(responsavel, ''), v_login),
      historico = historico || jsonb_build_array(_agora_br() || ' — ' || coalesce(v_login, '') || ': atendimento encerrado pelo chat — ' || left(v_sol, 120))
    where id = c.ocorrencia_id;
  end if;
  perform _auditar('Chat: atendimento encerrado', 'conversa ' || left(v_id::text, 8));
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: chat_enviar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_enviar(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := _uuid(p->>'conversaId'); v_tok text := coalesce(p->>'token', ''); v_ip text := _ip_cliente();
  v_txt text := _chat_limpar(p->>'texto'); c chat_conversas%rowtype; v_mid bigint;
begin
  if not _chat_ligado() then return jsonb_build_object('ok', false, 'desligado', true, 'message', 'O atendimento por chat está indisponível no momento.'); end if;
  if v_id is null or length(v_tok) < 32 or length(v_tok) > 128 then return _falha('Conversa não encontrada.'); end if;
  if _excedeu('chat_tok_' || v_ip, 20) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas tentativas seguidas. Aguarde alguns minutos.');
  end if;
  if not _chat_validar(v_id, v_tok) then
    perform _registrar_falha('chat_tok_' || v_ip, 600);
    return _falha('Conversa não encontrada.');
  end if;
  if char_length(v_txt) < 1 then return _falha('Escreva a mensagem.'); end if;
  if char_length(v_txt) > 300 then return _falha('Mensagem muito longa (máximo 300 caracteres).'); end if;
  perform _registrar_falha('chatenv_' || v_id::text, 300);
  if _excedeu('chatenv_' || v_id::text, 15) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas mensagens seguidas. Aguarde alguns minutos.');
  end if;
  select * into c from chat_conversas where id = v_id for update;
  if c.id is null then return _falha('Conversa não encontrada.'); end if;
  if c.estado = 'encerrada' then return _falha('Este atendimento foi encerrado.'); end if;
  if (select count(*) from chat_mensagens where conversa_id = v_id and autor = 'cliente') >= 60 then
    return _falha('Limite de mensagens desta conversa atingido.');
  end if;
  insert into chat_mensagens (conversa_id, autor, texto) values (v_id, 'cliente', v_txt) returning id into v_mid;
  update chat_conversas set atualizado_em = now(),
    nao_lidas_equipe = nao_lidas_equipe + case when estado in ('aguardando', 'em_atendimento') then 1 else 0 end
  where id = v_id;
  return jsonb_build_object('ok', true, 'id', v_mid);
end $$;


--
-- Name: chat_ia_consumir_cota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_ia_consumir_cota() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limite integer;
  v_usado integer;
  v_dia date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  select ia_publica_cota_dia into v_limite
  from chat_config where id = true for update;

  if v_limite is null then v_limite := 30; end if;

  insert into chat_ia_cotas (dia, chamadas) values (v_dia, 0)
  on conflict (dia) do nothing;

  update chat_ia_cotas
     set chamadas = chamadas + 1, atualizado_em = now()
   where dia = v_dia and chamadas < v_limite
  returning chamadas into v_usado;

  if v_usado is null then
    select chamadas into v_usado from chat_ia_cotas where dia = v_dia;
    return jsonb_build_object('ok', false, 'limite', true, 'usado', v_usado, 'cota', v_limite);
  end if;

  return jsonb_build_object('ok', true, 'limite', false, 'usado', v_usado,
    'cota', v_limite, 'restante', greatest(v_limite - v_usado, 0));
end;
$$;


--
-- Name: chat_ia_reservar_chamada(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_ia_reservar_chamada(p_conversa_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_novo smallint;
begin
  update chat_conversas
     set ia_chamadas = ia_chamadas + 1, atualizado_em = now()
   where id = p_conversa_id and estado = 'recepcao' and ia_chamadas < 6
  returning ia_chamadas into v_novo;
  if v_novo is null then return jsonb_build_object('ok', false, 'codigo', 'limite_ia_conversa'); end if;
  return jsonb_build_object('ok', true, 'ia_chamadas', v_novo);
end;
$$;


--
-- Name: chat_ia_validar(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_ia_validar(p_conversa uuid, p_token text, p_ip text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_chave text := 'iapub_ip_' || left(coalesce(nullif(p_ip, ''), 'sem_ip'), 64);
begin
  -- limite por IP: no máximo 12 tentativas/chamadas em 10 min
  if _excedeu(v_chave, 12) then
    return jsonb_build_object('ok', false, 'motivo', 'limite_ip');
  end if;
  -- token da conversa (o mesmo que o chat_abrir entrega ao cliente)
  if p_conversa is null or length(coalesce(p_token, '')) < 32 or length(p_token) > 128
     or not _chat_validar(p_conversa, p_token) then
    perform _registrar_falha(v_chave, 600);
    return jsonb_build_object('ok', false, 'motivo', 'conversa');
  end if;
  perform _registrar_falha(v_chave, 600); -- conta a chamada válida no mesmo limite
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: chat_ler(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_ler(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_id uuid := _uuid(p->>'conversaId'); v_tok text := coalesce(p->>'token', ''); v_ip text := _ip_cliente();
  v_dep bigint := case when (p->>'depois') ~ '^[0-9]{1,18}$' then (p->>'depois')::bigint else 0 end;
  c chat_conversas%rowtype; v_msgs jsonb;
begin
  if not _chat_ligado() then return jsonb_build_object('ok', false, 'desligado', true, 'message', 'O atendimento por chat está indisponível no momento.'); end if;
  if v_id is null or length(v_tok) < 32 or length(v_tok) > 128 then return _falha('Conversa não encontrada.'); end if;
  if _excedeu('chat_tok_' || v_ip, 20) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas tentativas seguidas. Aguarde alguns minutos.');
  end if;
  if not _chat_validar(v_id, v_tok) then
    perform _registrar_falha('chat_tok_' || v_ip, 600);
    return _falha('Conversa não encontrada.');
  end if;
  perform _registrar_falha('chatler_' || v_id::text, 60);
  if _excedeu('chatler_' || v_id::text, 40) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Aguarde alguns segundos.');
  end if;
  select * into c from chat_conversas where id = v_id;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'autor', m.autor, 'texto', m.texto, 'em', m.criado_em) order by m.id), '[]'::jsonb)
    into v_msgs from (select * from chat_mensagens where conversa_id = v_id and id > v_dep order by id limit 100) m;
  if c.nao_lidas_cliente > 0 then update chat_conversas set nao_lidas_cliente = 0 where id = v_id; end if;
  return jsonb_build_object('ok', true, 'estado', c.estado, 'mensagens', v_msgs, 'caixaAberto', _chat_caixa_aberto());
end $_$;


--
-- Name: chat_ler_fila(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_ler_fila() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_lista jsonb;
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;   -- Desenvolvedor já vale como Admin em auth_nivel()
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'vendaId', c.venda_id, 'estado', c.estado, 'tipo', c.tipo_problema, 'resumo', c.resumo,
      'naoLidas', c.nao_lidas_equipe, 'atendenteId', c.atendente_id, 'ocorrenciaId', c.ocorrencia_id,
      'nome', c.nome_cliente, 'telefone', c.telefone_cliente, 'pedidoNaoLocalizado', c.pedido_nao_localizado,
      'outrosPedidos', c.outros_pedidos, 'antesDePedir', (c.intencao = 'antes_de_pedir'),
      'criadoEm', c.criado_em, 'atualizadoEm', c.atualizado_em)
    order by case when c.estado = 'aguardando' then 0 else 1 end, c.atualizado_em asc), '[]'::jsonb)
  into v_lista from chat_conversas c where c.estado in ('aguardando', 'em_atendimento');
  return jsonb_build_object('ok', true, 'conversas', v_lista);
end $$;


--
-- Name: chat_marcar_lida(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_marcar_lida(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  update chat_conversas set nao_lidas_equipe = 0 where id = _uuid(p->>'conversaId') and nao_lidas_equipe > 0;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: chat_responder(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_responder(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid := _uuid(p->>'conversaId'); v_txt text := _chat_limpar(p->>'texto'); c chat_conversas%rowtype; v_mid bigint;
begin
  if not tem_nivel('Admin', 'Operador') then return _negado(); end if;
  if char_length(v_txt) < 1 then return _falha('Escreva a mensagem.'); end if;
  if char_length(v_txt) > 1000 then return _falha('Mensagem muito longa (máximo 1000 caracteres).'); end if;
  select * into c from chat_conversas where id = v_id for update;
  if c.id is null then return _falha('Conversa não encontrada.'); end if;
  if c.estado <> 'em_atendimento' then return _falha('Assuma o atendimento antes de responder.'); end if;
  if c.atendente_id is distinct from auth.uid() and auth_nivel()::text <> 'Admin' then
    return _falha('Este atendimento está com ' || coalesce(_login_de(c.atendente_id), 'outra pessoa') || '.');
  end if;
  insert into chat_mensagens (conversa_id, autor, autor_id, texto) values (v_id, 'atendente', auth.uid(), v_txt) returning id into v_mid;
  update chat_conversas set atualizado_em = now(), nao_lidas_equipe = 0, nao_lidas_cliente = nao_lidas_cliente + 1 where id = v_id;
  return jsonb_build_object('ok', true, 'id', v_mid);
end $$;


--
-- Name: chat_status(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_status(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('ok', true, 'ligado', public._chat_ligado(), 'caixaAberto', public._chat_caixa_aberto());
$$;


--
-- Name: chat_transferir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_transferir(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := _uuid(p->>'conversaId'); v_tok text := coalesce(p->>'token', ''); v_ip text := _ip_cliente();
  v_tipo text := btrim(coalesce(p->>'tipo', '')); v_txt text := _chat_limpar(p->>'texto');
  v_res text := nullif(left(_chat_limpar(p->>'resumo'), 600), '');
  c chat_conversas%rowtype; ve vendas%rowtype; v_oc uuid; v_rot text; v_otipo text; v_aberto boolean;
begin
  if not _chat_ligado() then return jsonb_build_object('ok', false, 'desligado', true, 'message', 'O atendimento por chat está indisponível no momento.'); end if;
  if v_id is null or length(v_tok) < 32 or length(v_tok) > 128 then return _falha('Conversa não encontrada.'); end if;
  if _excedeu('chat_tok_' || v_ip, 20) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas tentativas seguidas. Aguarde alguns minutos.');
  end if;
  if not _chat_validar(v_id, v_tok) then
    perform _registrar_falha('chat_tok_' || v_ip, 600);
    return _falha('Conversa não encontrada.');
  end if;
  if v_tipo <> all (array['atraso','item_errado','item_faltando','cobranca','qualidade','outro','antes_de_pedir']) then v_tipo := 'outro'; end if;
  if char_length(v_txt) < 3 then return _falha('Descreva o que você precisa.'); end if;
  if char_length(v_txt) > 300 then return _falha('Descrição muito longa (máximo 300 caracteres).'); end if;
  select * into c from chat_conversas where id = v_id for update;
  if c.id is null then return _falha('Conversa não encontrada.'); end if;
  if c.estado = 'encerrada' then return _falha('Este atendimento foi encerrado.'); end if;
  v_aberto := _chat_caixa_aberto();
  if c.estado <> 'recepcao' then
    return jsonb_build_object('ok', true, 'jaTransferida', true, 'estado', c.estado, 'caixaAberto', v_aberto);
  end if;
  -- consistência entre intenção e tipo
  if c.intencao = 'antes_de_pedir' then v_tipo := 'antes_de_pedir';
  elsif v_tipo = 'antes_de_pedir' then v_tipo := 'outro'; end if;
  if c.intencao is null and c.venda_id is not null then c.intencao := 'pedido_feito'; end if;
  if c.intencao is null then c.intencao := case when v_tipo = 'antes_de_pedir' then 'antes_de_pedir' else 'pedido_feito' end; end if;

  if c.venda_id is not null and c.intencao = 'pedido_feito' then
    select * into ve from vendas where id = c.venda_id;
    v_rot := case v_tipo when 'atraso' then 'Atraso' when 'item_errado' then 'Item errado' when 'item_faltando' then 'Item faltando'
                         when 'cobranca' then 'Cobrança' when 'qualidade' then 'Qualidade' else 'Outro' end;
    v_otipo := case v_tipo when 'atraso' then 'Entrega' when 'cobranca' then 'Pagamento' when 'outro' then 'Atendimento' else 'Produção' end;
    insert into ocorrencias (tipo, setor, venda_id, cliente, telefone, registrado_por, descricao, status, historico)
    values (v_otipo, 'Outro', ve.id, ve.cliente_nome, ve.telefone_cliente, null,
            left('Chat do cliente — ' || v_rot || ': ' || coalesce(v_res, v_txt), 600), 'Aberta',
            jsonb_build_array(_agora_br() || ' — Cliente (chat): pediu atendimento da equipe'))
    returning id into v_oc;
  end if;

  insert into chat_mensagens (conversa_id, autor, texto) values (v_id, 'cliente', v_txt);
  insert into chat_mensagens (conversa_id, autor, texto) values (v_id, 'sistema',
    case when v_aberto then 'Pedido de ajuda enviado. Uma pessoa da equipe vai responder aqui.'
         else 'O restaurante está fechado agora. Sua mensagem ficou registrada e a resposta vem quando ele abrir.' end);
  update chat_conversas set estado = 'aguardando', tipo_problema = v_tipo, intencao = c.intencao, resumo = coalesce(v_res, v_txt), texto_original = v_txt,
    ocorrencia_id = v_oc, transferida_em = now(), atualizado_em = now(), nao_lidas_equipe = nao_lidas_equipe + 1
  where id = v_id;
  return jsonb_build_object('ok', true, 'estado', 'aguardando', 'caixaAberto', v_aberto);
end $$;


--
-- Name: chat_triagem_abrir(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_triagem_abrir(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ip text := _ip_cliente(); c chat_conversas%rowtype; v_tok text;
begin
  if not _chat_ligado() then
    return jsonb_build_object('ok', false, 'desligado', true, 'message', 'O atendimento por chat está indisponível no momento.');
  end if;
  if not _chat_caixa_aberto() then
    return jsonb_build_object('ok', false, 'fechado', true, 'message', 'O restaurante está fechado agora. Volte no horário de atendimento.');
  end if;
  if _excedeu('triagem_ip_' || v_ip, 3) or _excedeu('triagem_global', 200) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas tentativas seguidas. Aguarde alguns minutos.');
  end if;
  perform _registrar_falha('triagem_ip_' || v_ip, 3600);
  perform _registrar_falha('triagem_global', 86400);
  insert into chat_conversas (venda_id) values (null) returning * into c;
  v_tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  insert into chat_tokens (conversa_id, token_hash) values (c.id, _chat_hash(v_tok));
  return jsonb_build_object('ok', true, 'conversaId', c.id, 'token', v_tok, 'estado', c.estado);
end $$;


--
-- Name: chat_vincular_pedido(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_vincular_pedido(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := _uuid(p->>'conversaId'); v_tok text := coalesce(p->>'token', ''); v_ip text := _ip_cliente();
  v_nome text := left(_chat_limpar(p->>'nome'), 80);
  v_tel text := right(regexp_replace(coalesce(p->>'telefone', ''), '\D', '', 'g'), 11);
  cfg chat_config%rowtype; c chat_conversas%rowtype; v_venda uuid; v_outros int := 0;
  v_ok constant jsonb := jsonb_build_object('ok', true, 'message', 'Certo, vamos chamar a equipe.');
begin
  select * into cfg from chat_config where id;
  if not coalesce(cfg.chat_publico_ligado, false) then
    return jsonb_build_object('ok', false, 'desligado', true, 'message', 'O atendimento por chat está indisponível no momento.');
  end if;
  if v_id is null or length(v_tok) < 32 or length(v_tok) > 128 then return _falha('Conversa não encontrada.'); end if;
  if length(v_tel) < 10 or char_length(v_nome) < 2 then return _falha('Informe seu nome e o telefone com DDD.'); end if;
  if _excedeu('chat_ip_' || v_ip, 10) or _excedeu('chat_vinc_' || v_tel, 5) then
    return jsonb_build_object('ok', false, 'limite', true, 'message', 'Muitas tentativas seguidas. Aguarde alguns minutos.');
  end if;
  perform _registrar_falha('chat_vinc_' || v_tel, 3600);
  if not _chat_validar(v_id, v_tok) then
    perform _registrar_falha('chat_ip_' || v_ip, 600);
    return _falha('Conversa não encontrada.');
  end if;
  select * into c from chat_conversas where id = v_id for update;
  if c.id is null or c.estado <> 'recepcao' then return _falha('Conversa não encontrada.'); end if;

  select count(*) into v_outros from vendas
   where right(regexp_replace(coalesce(telefone_cliente, ''), '\D', '', 'g'), 11) = v_tel
     and data_hora >= now() - make_interval(hours => cfg.janela_horas);
  select v.id into v_venda from vendas v
   where right(regexp_replace(coalesce(v.telefone_cliente, ''), '\D', '', 'g'), 11) = v_tel
     and v.data_hora >= now() - make_interval(hours => cfg.janela_horas)
     and not exists (select 1 from chat_conversas x where x.venda_id = v.id and x.estado <> 'encerrada' and x.id <> v_id)
   order by v.data_hora desc limit 1;

  begin
    update chat_conversas set intencao = 'pedido_feito', nome_cliente = v_nome, telefone_cliente = v_tel,
      venda_id = v_venda, pedido_nao_localizado = (v_venda is null),
      outros_pedidos = greatest(v_outros - (case when v_venda is null then 0 else 1 end), 0), atualizado_em = now()
    where id = v_id;
  exception when unique_violation then
    update chat_conversas set intencao = 'pedido_feito', nome_cliente = v_nome, telefone_cliente = v_tel,
      venda_id = null, pedido_nao_localizado = true, atualizado_em = now() where id = v_id;
  end;
  return v_ok;   -- nunca revela se existe pedido
end $$;


--
-- Name: enfileirar_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enfileirar_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare reg jsonb; rid text;
begin
  if current_setting('rst.sem_fila', true) = 'on' then return null; end if;
  if tg_table_name not in ('categorias','produtos','produto_precos','combos','combo_precos','combo_itens','adicionais','produto_adicionais',
                           'formas_pagamento','sistema','clientes','vendas','itens_venda','pagamentos_venda') then return null; end if;
  if tg_op = 'DELETE' then reg := to_jsonb(old); else reg := to_jsonb(new); end if;
  rid := coalesce(reg->>'id', reg->>'chave');
  insert into fila_sync (tabela, registro_id, operacao, payload)
  values (tg_table_name, rid, tg_op::op_sync, case when tg_op = 'DELETE' then null else reg end);
  return null;
end $$;


--
-- Name: entrega_atualizar_posicao(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entrega_atualizar_posicao(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid(); v_venda uuid; v_lat double precision; v_lng double precision; v_prec real;
  v_ent uuid; v_st text;
begin
  if v_user is null then return jsonb_build_object('ok', false, 'codigo', 'sem_login'); end if;
  begin
    v_venda := (p->>'vendaId')::uuid; v_lat := (p->>'lat')::double precision; v_lng := (p->>'lng')::double precision;
    v_prec := nullif(p->>'precisaoM', '')::real;
  exception when others then return jsonb_build_object('ok', false, 'codigo', 'dados_invalidos'); end;
  if v_lat is null or v_lng is null or v_lat not between -90 and 90 or v_lng not between -180 and 180 then
    return jsonb_build_object('ok', false, 'codigo', 'dados_invalidos'); end if;
  if v_prec is not null then v_prec := least(greatest(v_prec, 0), 5000); end if;
  select entregador_id, status_pedido::text into v_ent, v_st from vendas where id = v_venda;
  if v_ent is null or v_ent <> v_user then return jsonb_build_object('ok', false, 'codigo', 'sem_permissao'); end if;
  if v_st <> 'Saiu para entrega' then return jsonb_build_object('ok', false, 'codigo', 'fora_da_entrega'); end if;
  insert into entregador_posicoes (venda_id, entregador_id, lat, lng, precisao_m, atualizado_em)
  values (v_venda, v_user, v_lat, v_lng, v_prec, now())
  on conflict (venda_id) do update set lat = excluded.lat, lng = excluded.lng, precisao_m = excluded.precisao_m, atualizado_em = now(), entregador_id = excluded.entregador_id;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: entrega_ver_posicao(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entrega_ver_posicao(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_nivel text := auth_nivel()::text; v_venda uuid; pos entregador_posicoes%rowtype; d entrega_destinos%rowtype; v_st text; v_seg int;
begin
  if v_nivel is null or v_nivel not in ('Admin', 'Operador') then return jsonb_build_object('ok', false, 'codigo', 'sem_permissao'); end if;
  begin v_venda := (p->>'vendaId')::uuid; exception when others then return jsonb_build_object('ok', false, 'codigo', 'dados_invalidos'); end;
  select status_pedido::text into v_st from vendas where id = v_venda;
  if v_st is null then return jsonb_build_object('ok', false, 'codigo', 'nao_encontrado'); end if;
  if v_st <> 'Saiu para entrega' then return jsonb_build_object('ok', true, 'estado', 'aguardando'); end if;
  select * into pos from entregador_posicoes where venda_id = v_venda;
  if not found then return jsonb_build_object('ok', true, 'estado', 'sem_posicao'); end if;
  v_seg := greatest(0, extract(epoch from (now() - pos.atualizado_em))::int);
  select * into d from entrega_destinos where venda_id = v_venda;
  return jsonb_build_object('ok', true, 'estado', case when v_seg > 300 then 'sem_sinal' else 'ok' end,
    'lat', pos.lat, 'lng', pos.lng, 'precisaoM', pos.precisao_m, 'atualizadoHaSeg', v_seg,
    'km', case when d.venda_id is not null then round(_dist_km(pos.lat, pos.lng, d.lat, d.lng)::numeric, 1) end,
    'destinoCompartilhado', d.venda_id is not null);
end $$;


--
-- Name: erro_limpa_(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erro_limpa_(t text, n integer DEFAULT 300) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select left(regexp_replace(regexp_replace(regexp_replace(regexp_replace(ia_limpa_(t, 2000),
         'eyJ[[:alnum:]_.-]{20,}', '[token]', 'g'),
         '(apikey|token|senha|password|authorization|bearer)[=: ]+[^ ]+', '\1=[oculto]', 'gi'),
         '\?[^ )]*', '', 'g'),
         '[<>]', ' ', 'g'), n)
$$;


--
-- Name: fiscal_obter_cnpj_empresa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_obter_cnpj_empresa() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select regexp_replace(coalesce((select cnpj from public.fiscal_empresa where id),''),'\D','','g')
$$;


--
-- Name: ia_agregar(text, text, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_agregar(p_tabela text, p_coluna text, p_ini date DEFAULT NULL::date, p_fim date DEFAULT NULL::date, p_busca text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  adm boolean := tem_nivel('Admin');
  tz constant text := 'America/Sao_Paulo';
  t text := lower(btrim(coalesce(p_tabela, '')));
  c text := lower(btrim(coalesce(p_coluna, '')));
  b text := nullif(replace(replace(btrim(coalesce(p_busca, '')), '%', ''), '_', ''), '');
  dcol text; dtipo text; ctipo text; dexpr text := 'true'; dd text := 'null::date'; kx text; sql text; r jsonb;
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  if not (t = any(public._ia_tabelas(adm))) then return jsonb_build_object('ok', false, 'message', 'Tabela não disponível para o seu perfil.'); end if;
  select c2.column_name::text, c2.data_type::text into dcol, dtipo
    from information_schema.columns c2
   where c2.table_schema = 'public' and c2.table_name::text = t
     and c2.column_name::text in ('data_hora','data','criado_em','abertura','atualizada_em','recebido_em')
   order by array_position(array['data_hora','data','criado_em','abertura','atualizada_em','recebido_em'], c2.column_name::text) limit 1;
  if dcol is not null then
    dd := case when dtipo = 'date' then format('t.%I', dcol) else format('(t.%I at time zone %L)::date', dcol, tz) end;
  end if;
  if c in ('dia','mes') then
    if dcol is null then return jsonb_build_object('ok', false, 'message', 'Esta tabela não tem coluna de data para agrupar por dia/mês.'); end if;
    kx := format('to_char(d, %L)', case when c = 'dia' then 'YYYY-MM-DD' else 'YYYY-MM' end);
  else
    select c3.data_type::text into ctipo from information_schema.columns c3
     where c3.table_schema = 'public' and c3.table_name::text = t and c3.column_name::text = c;
    if ctipo is null or public._ia_oculta(c, adm) then return jsonb_build_object('ok', false, 'message', 'Coluna não disponível para agrupar (use o nome exato do catálogo, ou "dia"/"mes").'); end if;
    kx := format('coalesce(nullif(m->>%L, %L), %L)', c, '', '(vazio)');
  end if;
  if p_ini is not null or p_fim is not null then
    if p_ini is null or p_fim is null or p_fim < p_ini or (p_fim - p_ini) > 732 then
      return jsonb_build_object('ok', false, 'message', 'Período inválido (máx. 2 anos).');
    end if;
    if dcol is not null then dexpr := format('%s between %L::date and %L::date', dd, p_ini, p_fim); end if;
  end if;
  sql := format($q$
    with f as (select public._ia_mascara(to_jsonb(t), $1) m, %s d from public.%I t where %s),
    g as (select m, d from f where $2::text is null or m::text ilike '%%' || $2 || '%%'),
    k as (select %s as chave, m from g),
    cnt as (select chave, count(*) qtd from k group by 1 order by 2 desc limit 60),
    sm as (select k.chave, e.key kk, sum((e.value #>> '{}')::numeric) vv
             from k join cnt on cnt.chave = k.chave, jsonb_each(k.m) e
            where $1 and jsonb_typeof(e.value) = 'number' and e.key <> %L
              and e.key not in ('id','ordem','numero','numero_pedido','prazo_dias','capacidade','ordem_cardapio')
            group by 1, 2)
    select jsonb_build_object(
      'total', (select count(*) from g),
      'grupos', coalesce((select jsonb_agg(jsonb_build_object('chave', cnt.chave, 'qtd', cnt.qtd)
            || case when $1 then jsonb_build_object('somas', coalesce((select jsonb_object_agg(sm.kk, sm.vv) from sm where sm.chave = cnt.chave), '{}'::jsonb)) else '{}'::jsonb end
            order by cnt.qtd desc) from cnt), '[]'::jsonb))
  $q$, dd, t, dexpr, kx, c);
  execute sql into r using adm, b;
  return jsonb_build_object('ok', true, 'tabela', t, 'agrupado_por', c, 'periodo', case when p_ini is null then null else p_ini::text || ' a ' || p_fim::text end,
                            'aviso', 'Mostra até 60 grupos, os maiores primeiro.') || r;
end $_$;


--
-- Name: ia_ajuda_buscar(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_ajuda_buscar(p_pergunta text, p_perfil text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare q text; r jsonb; v_real text := (select nivel::text from usuarios where id = auth.uid() and ativo);
        v_nivel text := auth_nivel()::text; v_alvo text; v_todos boolean;
begin
  if v_real is null or v_nivel is null then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  v_todos := (v_real = 'Desenvolvedor' and p_perfil is null);
  v_alvo := case when v_real = 'Desenvolvedor' and p_perfil in ('Admin','Operador','Garçom','Cozinha','Entregador') then p_perfil else v_nivel end;
  -- palavras da pergunta (sem acento) + sinônimos de uso comum, para "funcionário" achar "usuário", "apagar" achar "excluir" etc.
  select string_agg(distinct w, ' | ') into q from (
    with base as (
      select distinct regexp_replace(translate(lower(x), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc'), '[^a-z0-9]', '', 'g') w
        from regexp_split_to_table(left(coalesce(p_pergunta, ''), 500), '\s+') x)
    select w from base
     where length(w) >= 3 and w not in ('como','que','uma','uns','para','por','com','eu','posso','fazer','faco','onde','qual','quais','meu','minha','nao','sistema','tem','dos','das','nos','nas','mais','esse','essa','isso','quero','preciso','ver')
    union
    select s from base b, lateral unnest(case
        when b.w in ('funcionario','funcionaria','funcionarios','colaborador','colaboradora','colaboradores','empregado','empregada','atendente','atendentes') then array['usuario','acesso','login','perfil']
        when b.w in ('cadastrar','cadastro','cadastrei','registrar','incluir','criar','adicionar','inserir','novo','nova') then array['cadastrar','criar']
        when b.w in ('apagar','deletar','remover','tirar','excluir') then array['excluir','remover']
        when b.w in ('menu','cardapios') then array['cardapio','produto']
        when b.w in ('comanda','comandas') then array['pedido','venda']
        when b.w in ('motoboy','motoqueiro','entregadores') then array['entregador','entrega']
        else array[]::text[] end) s
     where length(b.w) >= 3
  ) z where w is not null and w <> '';
  if q is null then return jsonb_build_object('ok', true, 'topicos', '[]'::jsonb); end if;
  select coalesce(jsonb_agg(jsonb_build_object('titulo', titulo, 'passos', passos, 'perfis', perfis) order by rk desc), '[]'::jsonb) into r from (
   select * from (
    select titulo, passos, perfis, ts_rank(
             setweight(to_tsvector('portuguese', translate(lower(titulo), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc')), 'A') ||
             setweight(to_tsvector('portuguese', translate(lower(palavras_chave), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc')), 'B') ||
             setweight(to_tsvector('portuguese', translate(lower(passos), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc')), 'C'),
             to_tsquery('portuguese', q)) rk
      from ai_ajuda where ativo and (v_todos or v_alvo = any(perfis))) m
   where rk > 0 order by rk desc limit 3) z;
  return jsonb_build_object('ok', true, 'topicos', coalesce(r, '[]'::jsonb));
end $$;


--
-- Name: ia_alerta_(text, text, text, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_alerta_(cod text, sev text, titulo text, valor numeric, ref numeric DEFAULT NULL::numeric, det jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object('codigo', cod, 'severidade', sev, 'titulo', titulo, 'valor', valor, 'referencia', ref, 'detalhe', det))
$$;


--
-- Name: ia_anomalias(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_anomalias(p_data date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  d date; res jsonb := '[]'::jsonb; a jsonb; t jsonb; i int; n int := 0; sf numeric := 0; media numeric;
  fat numeric; ped int; canc int; m_dia numeric; m_base numeric; b28 jsonb; x record; qtd int; val numeric;
begin
  if not tem_nivel('Admin','Operador') then
    return jsonb_build_object('ok', false, 'message', 'Sem permissão.');
  end if;
  d := coalesce(p_data, hoje);
  a := ia_totais_(d, d);
  fat := (a->>'faturamento')::numeric; ped := (a->>'pedidos')::int; canc := (a->>'cancelados')::int;

  for i in 1..4 loop
    t := ia_totais_(d - 7 * i, d - 7 * i);
    if (t->>'pedidos')::int > 0 then n := n + 1; sf := sf + (t->>'faturamento')::numeric; end if;
  end loop;
  if n >= 2 then media := sf / n; end if;

  if d < hoje and media > 0 then
    if fat < media * 0.6 then
      res := res || ia_alerta_('FATURAMENTO_BAIXO','media','Faturamento do dia bem abaixo da média do mesmo dia da semana', fat, round(media,2));
    elsif fat > media * 1.5 then
      res := res || ia_alerta_('FATURAMENTO_ALTO','info','Faturamento do dia bem acima da média do mesmo dia da semana', fat, round(media,2));
    end if;
  end if;

  if canc >= 3 and canc::numeric / (ped + canc) >= 0.15 then
    res := res || ia_alerta_('CANCELAMENTOS_ALTOS','alta','Muitos cancelamentos no dia', canc, ped + canc);
  end if;

  if fat > 0 and ped >= 5 then
    m_dia := (fat - (a->>'custo')::numeric - (a->>'taxas')::numeric) / fat * 100;
    b28 := ia_totais_(d - 28, d - 1);
    if (b28->>'faturamento')::numeric > 0 then
      m_base := ((b28->>'faturamento')::numeric - (b28->>'custo')::numeric - (b28->>'taxas')::numeric) / (b28->>'faturamento')::numeric * 100;
      if m_dia < m_base - 5 then
        res := res || ia_alerta_('MARGEM_EM_QUEDA','media','Margem do dia mais de 5 pontos abaixo dos últimos 28 dias', round(m_dia,1), round(m_base,1));
      end if;
    end if;
  end if;

  if d = hoje then
    select count(*) into qtd from vendas
     where status = 'Confirmada' and status_pedido in ('Recebido','Em preparo','Pronta')
       and data_hora < now() - interval '60 minutes' and data_hora >= now() - interval '12 hours';
    if qtd > 0 then res := res || ia_alerta_('PEDIDOS_PARADOS','alta','Pedidos há mais de 60 min sem andamento', qtd); end if;
  end if;

  select count(*) into qtd from vendas
   where status = 'Confirmada' and status_pedido = 'Suspenso' and data_hora >= now() - interval '24 hours';
  if qtd > 0 then res := res || ia_alerta_('PEDIDOS_SUSPENSOS','media','Pedidos suspensos nas últimas 24 h', qtd); end if;

  select count(*) filter (where quantidade <= 0) as zerados,
         count(*) filter (where quantidade <= quantidade_minima and quantidade_minima > 0) as baixos,
         coalesce(jsonb_agg(ingrediente) filter (where quantidade <= quantidade_minima and quantidade_minima > 0), '[]'::jsonb) as nomes
    into x from (select ingrediente, quantidade, quantidade_minima from estoque where status = 'Ativo'
                 order by case when quantidade_minima > 0 then quantidade / quantidade_minima else 9999 end limit 200) e;
  if x.zerados > 0 then res := res || ia_alerta_('ESTOQUE_ZERADO','alta','Ingredientes com estoque zerado', x.zerados); end if;
  if x.baixos > 0 then
    res := res || ia_alerta_('ESTOQUE_BAIXO','media','Ingredientes no mínimo ou abaixo', x.baixos, null, (select jsonb_agg(v) from (select jsonb_array_elements(x.nomes) v limit 5) q));
  end if;

  select diferenca into val from caixa_sessoes
   where status = 'Fechado' and fechamento >= now() - interval '7 days' and diferenca is not null and diferenca <> 0
   order by fechamento desc limit 1;
  if val is not null then
    res := res || ia_alerta_('CAIXA_DIFERENCA', case when abs(val) >= 20 then 'alta' else 'baixa' end, 'Diferença no último fechamento de caixa', val);
  end if;

  select count(*), coalesce(sum(valor),0) into qtd, val from despesas where status = 'A pagar' and vencimento < hoje;
  if qtd > 0 then res := res || ia_alerta_('CONTAS_VENCIDAS','media','Contas a pagar vencidas', val, qtd); end if;

  select count(*), coalesce(sum(valor_total),0) into qtd, val from vendas
   where status = 'Confirmada' and status_pagamento = 'A Receber'
     and status_pedido in ('Entregue','Retirada','Servida') and data_hora < now() - interval '24 hours';
  if qtd > 0 then res := res || ia_alerta_('A_RECEBER_ANTIGO','media','Vendas concluídas há mais de 24 h ainda a receber', val, qtd); end if;

  return jsonb_build_object('ok', true, 'data', d, 'parcial', d = hoje, 'alertas', res);
end $$;


--
-- Name: ia_catalogo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_catalogo() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare adm boolean := tem_nivel('Admin'); r text;
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  select string_agg(t || '(' || cols || ')', '; ' order by t) into r
  from (select c.table_name::text t, string_agg(c.column_name::text, ',' order by c.ordinal_position) cols
        from information_schema.columns c
        where c.table_schema = 'public' and c.table_name::text = any(public._ia_tabelas(adm))
          and not public._ia_oculta(c.column_name::text, adm)
        group by c.table_name) x;
  return jsonb_build_object('ok', true, 'tabelas', coalesce(r,'') || '. PRIVACIDADE: telefone, endereço, localização, e-mail, CPF, nascimento, login e senhas dos clientes e usuários são ocultos de propósito e nunca devem ser informados nem inventados.');
end $$;


--
-- Name: ia_comparativo(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_comparativo(p_ini date, p_fim date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  len int; a jsonb; b jsonb; t jsonb; i int; n int := 0; sf numeric := 0; sp numeric := 0;
  fa numeric; fb numeric; pa int; pb int; sem jsonb := null;
begin
  if not tem_nivel('Admin','Operador') then
    return jsonb_build_object('ok', false, 'message', 'Sem permissão.');
  end if;
  if p_ini is null or p_fim is null or p_fim < p_ini or (p_fim - p_ini) > 92 then
    return jsonb_build_object('ok', false, 'message', 'Período inválido.');
  end if;
  len := p_fim - p_ini + 1;
  a := ia_totais_(p_ini, p_fim);
  b := ia_totais_(p_ini - len, p_ini - 1);
  fa := (a->>'faturamento')::numeric; fb := (b->>'faturamento')::numeric;
  pa := (a->>'pedidos')::int;         pb := (b->>'pedidos')::int;
  if p_ini = p_fim then
    for i in 1..4 loop
      t := ia_totais_(p_ini - 7 * i, p_ini - 7 * i);
      if (t->>'pedidos')::int > 0 then n := n + 1; sf := sf + (t->>'faturamento')::numeric; sp := sp + (t->>'pedidos')::int; end if;
    end loop;
    if n > 0 then
      sem := jsonb_build_object('dias_base', n, 'media_faturamento', round(sf / n, 2), 'media_pedidos', round(sp / n, 1),
               'var_faturamento_pct', case when sf > 0 then round((fa - sf / n) / (sf / n) * 100, 1) end);
    end if;
  end if;
  return jsonb_build_object('ok', true,
    'atual',    jsonb_build_object('faturamento', fa, 'pedidos', pa),
    'anterior', jsonb_build_object('ini', p_ini - len, 'fim', p_ini - 1, 'faturamento', fb, 'pedidos', pb),
    'var_faturamento_pct', case when fb > 0 then round((fa - fb) / fb * 100, 1) end,
    'var_pedidos_pct',     case when pb > 0 then round((pa - pb)::numeric / pb * 100, 1) end,
    'mesmo_dia_da_semana', sem);
end $$;


--
-- Name: ia_consulta(text, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_consulta(p_tipo text, p_ini date, p_fim date, p_busca text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  tz constant text := 'America/Sao_Paulo';
  adm boolean := tem_nivel('Admin');
  t_ini timestamptz; t_fim timestamptz; b text := nullif(btrim(coalesce(p_busca,'')), '');
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  if p_ini is null or p_fim is null or p_fim < p_ini or (p_fim - p_ini) > 92 then return jsonb_build_object('ok', false, 'message', 'Período inválido (máx. 93 dias).'); end if;
  t_ini := (p_ini::timestamp at time zone tz); t_fim := ((p_fim + 1)::timestamp at time zone tz);
  if p_tipo = 'resumo' then
    return jsonb_build_object('ok', true, 'tipo', p_tipo, 'resumo', ia_periodo_(p_ini, p_fim, adm),
      'top_produtos', ia_top_produtos_(p_ini, p_fim, adm, 10, 'mais'));
  elsif p_tipo = 'serie_diaria' then
    return jsonb_build_object('ok', true, 'tipo', p_tipo, 'dias', coalesce((select jsonb_agg(
        jsonb_build_object('dia', dia, 'pedidos', n) || case when adm then jsonb_build_object('faturamento', v) else '{}'::jsonb end order by dia)
      from (select (data_hora at time zone tz)::date dia, count(*) n, sum(valor_total) v from vendas where status::text='Confirmada' and data_hora>=t_ini and data_hora<t_fim group by 1) x), '[]'::jsonb));
  elsif p_tipo = 'produto' then
    if b is null then return jsonb_build_object('ok', false, 'message', 'Informe o nome do produto.'); end if;
    return jsonb_build_object('ok', true, 'tipo', p_tipo, 'busca', b, 'produtos', coalesce((select jsonb_agg(
        jsonb_build_object('produto', d, 'qtd', q) || case when adm then jsonb_build_object('valor', v) else '{}'::jsonb end order by q desc)
      from (select iv.descricao d, sum(iv.quantidade) q, sum(iv.valor_total_item) v from itens_venda iv join vendas ve on ve.id=iv.venda_id
            where ve.status::text='Confirmada' and ve.data_hora>=t_ini and ve.data_hora<t_fim and iv.descricao ilike '%' || replace(replace(b,'%',''),'_','') || '%' group by 1 order by 2 desc limit 10) x), '[]'::jsonb));
  elsif p_tipo = 'cliente' then
    if not adm then return jsonb_build_object('ok', false, 'message', 'Só o Administrador consulta clientes.'); end if;
    if b is null then return jsonb_build_object('ok', false, 'message', 'Informe o nome do cliente.'); end if;
    return jsonb_build_object('ok', true, 'tipo', p_tipo, 'busca', b, 'clientes', coalesce((select jsonb_agg(jsonb_build_object('nome', n, 'pedidos', p, 'gasto', g, 'ultimo_pedido', u))
      from (select ve.cliente_nome n, count(*) p, sum(ve.valor_total) g, to_char(max(ve.data_hora) at time zone tz, 'DD/MM/YYYY') u from vendas ve
            where ve.status::text='Confirmada' and ve.data_hora>=t_ini and ve.data_hora<t_fim and ve.cliente_nome ilike '%' || replace(replace(b,'%',''),'_','') || '%' group by 1 order by 3 desc limit 5) x), '[]'::jsonb));
  elsif p_tipo = 'despesas' then
    if not adm then return jsonb_build_object('ok', false, 'message', 'Só o Administrador consulta despesas.'); end if;
    return jsonb_build_object('ok', true, 'tipo', p_tipo, 'por_categoria', coalesce((select jsonb_agg(jsonb_build_object('categoria', coalesce(cat,'Sem categoria'), 'status', st, 'total', v, 'qtd', n) order by v desc)
      from (select categoria::text cat, status::text st, sum(valor) v, count(*) n from despesas where data_hora>=t_ini and data_hora<t_fim and status::text <> 'Cancelada' group by 1,2) x), '[]'::jsonb));
  end if;
  return jsonb_build_object('ok', false, 'message', 'Tipo de consulta desconhecido.');
end $$;


--
-- Name: ia_contexto_geral(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_contexto_geral() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  tz constant text := 'America/Sao_Paulo';
  adm boolean := tem_nivel('Admin');
  h date := (now() at time zone tz)::date;
  d0 timestamptz := ((now() at time zone tz)::date::timestamp at time zone tz);
  r jsonb; cx record;
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;

  r := jsonb_build_object(
    'ok', true,
    'agora', to_char(now() at time zone tz, 'DD/MM/YYYY HH24:MI'),
    'dia_semana', trim(to_char(now() at time zone tz, 'TMDay')),
    'perfil', case when adm then 'Admin' else 'Operador' end,
    'periodos', jsonb_build_object(
      'hoje', ia_periodo_(h, h, adm),
      'ontem', ia_periodo_(h-1, h-1, adm),
      'ultimos_7_dias', ia_periodo_(h-6, h, adm),
      'ultimos_30_dias', ia_periodo_(h-29, h, adm),
      'mes_atual', ia_periodo_(date_trunc('month', h)::date, h, adm)),
    'top_produtos_hoje', ia_top_produtos_(h, h, adm, 8, 'mais'),
    'top_produtos_30d', ia_top_produtos_(h-29, h, adm, 10, 'mais'),
    'menos_vendidos_30d', ia_top_produtos_(h-29, h, adm, 5, 'menos'),
    'pedidos_por_hora_30d', coalesce((select jsonb_object_agg(hh, n) from (select extract(hour from data_hora at time zone tz)::int hh, count(*) n from vendas where status::text='Confirmada' and data_hora >= now() - interval '30 days' group by 1) x), '{}'::jsonb),
    'pedidos_por_dia_semana_30d', coalesce((select jsonb_object_agg(dw, n) from (select trim(to_char(data_hora at time zone tz, 'TMDay')) dw, count(*) n from vendas where status::text='Confirmada' and data_hora >= now() - interval '30 days' group by 1) x), '{}'::jsonb),
    'producao', (ia_producao_operacional() - 'ok'),
    'entregas', (ia_entregas_operacional() - 'ok'),
    'estoque', (ia_estoque_operacional() - 'ok'),
    'pedidos_em_andamento', coalesce((select jsonb_agg(jsonb_build_object('pedido', v.numero_pedido, 'tipo', v.tipo::text, 'status', v.status_pedido::text, 'minutos_desde_recebido', floor(extract(epoch from now() - coalesce(v.recebido_em, v.data_hora))/60), 'origem', v.origem::text, 'mesa', m.numero) || case when adm then jsonb_build_object('valor', v.valor_total) else '{}'::jsonb end order by coalesce(v.recebido_em, v.data_hora))
        from (select * from vendas where status::text='Confirmada' and status_pedido::text in ('Recebido','Em preparo','Pronta','Saiu para entrega','Suspenso') order by coalesce(recebido_em, data_hora) limit 25) v left join mesas m on m.id = v.mesa_id), '[]'::jsonb),
    'mesas', jsonb_build_object(
      'por_status', coalesce((select jsonb_object_agg(s, n) from (select status::text s, count(*) n from mesas group by 1) x), '{}'::jsonb),
      'chamados', coalesce((select jsonb_agg(jsonb_build_object('mesa', numero, 'chamado', chamado_tipo::text)) from mesas where chamado_tipo is not null and chamado_tipo::text <> ''), '[]'::jsonb)),
    'cupons_ativos', coalesce((select jsonb_agg(jsonb_build_object('codigo', codigo, 'nome', nome, 'tipo', tipo::text, 'valor', valor, 'frete_gratis', frete_gratis, 'valor_minimo', valor_minimo, 'ate', data_fim)) from (select * from cupons where ativa and (data_fim is null or data_fim >= h) order by criado_em desc limit 10) c), '[]'::jsonb),
    'formas_pagamento', coalesce((select jsonb_agg(jsonb_build_object('nome', nome, 'permite_troco', permite_troco) || case when adm then jsonb_build_object('taxa_percentual', taxa_percentual, 'taxa_fixa', taxa_fixa, 'prazo_dias', prazo_dias) else '{}'::jsonb end order by ordem) from formas_pagamento where ativa), '[]'::jsonb),
    'feedbacks_30d', jsonb_build_object(
      'quantidade', (select count(*) from feedbacks where data >= now() - interval '30 days'),
      'nota_media', (select round(avg(nota)::numeric, 2) from feedbacks where data >= now() - interval '30 days'),
      'recentes', coalesce((select jsonb_agg(jsonb_build_object('nota', nota, 'comentario', public._ia_scrub(left(coalesce(comentario,''), 140)))) from (select * from feedbacks order by data desc limit 5) f), '[]'::jsonb)),
    'ocorrencias_abertas', jsonb_build_object(
      'quantidade', (select count(*) from ocorrencias where status::text <> 'Resolvida'),
      'recentes', coalesce((select jsonb_agg(jsonb_build_object('numero', numero, 'tipo', tipo::text, 'setor', setor::text, 'status', status::text, 'descricao', public._ia_scrub(left(coalesce(descricao,''), 140)))) from (select * from ocorrencias where status::text <> 'Resolvida' order by data_hora desc limit 5) o), '[]'::jsonb)),
    'cardapio', jsonb_build_object(
      'produtos', coalesce((select jsonb_agg(jsonb_build_object('nome', p.nome, 'categoria', c.nome, 'preco_de', pr.pmin, 'preco_ate', pr.pmax, 'esgotado', exists(select 1 from v_cardapio_esgotados e where e.id = p.id)) order by c.ordem, p.ordem_cardapio)
          from v_cardapio_produtos p left join v_cardapio_categorias c on c.id = p.categoria_id
          left join lateral (select min(preco) pmin, max(preco) pmax from v_cardapio_precos x where x.item_id = p.id and x.tipo = 'produto') pr on true), '[]'::jsonb),
      'combos', coalesce((select jsonb_agg(jsonb_build_object('nome', b.nome, 'preco_de', pr.pmin, 'preco_ate', pr.pmax, 'esgotado', exists(select 1 from v_cardapio_esgotados e where e.id = b.id)))
          from v_cardapio_combos b left join lateral (select min(preco) pmin, max(preco) pmax from v_cardapio_precos x where x.item_id = b.id and x.tipo <> 'produto') pr on true), '[]'::jsonb))
  );

  select * into cx from caixa_sessoes where status::text = 'Aberto' order by abertura desc limit 1;
  if found then
    r := r || jsonb_build_object('caixa', jsonb_build_object('aberto', true, 'desde', to_char(cx.abertura at time zone tz, 'DD/MM HH24:MI'), 'fundo_caixa', cx.fundo_caixa,
      'sangrias', coalesce((select sum(valor) from sangrias where caixa_id = cx.id), 0),
      'pedidos_na_sessao', (select count(*) from vendas where caixa_id = cx.id and status::text='Confirmada')));
    if adm then
      r := jsonb_set(r, '{caixa,vendas_na_sessao}', to_jsonb(coalesce((select sum(valor_total) from vendas where caixa_id = cx.id and status::text='Confirmada'), 0)));
    end if;
  else
    r := r || jsonb_build_object('caixa', jsonb_build_object('aberto', false));
  end if;

  if adm then
    r := r || jsonb_build_object(
      'despesas', jsonb_build_object(
        'a_pagar_vencidas', jsonb_build_object('qtd', (select count(*) from despesas where status::text='A pagar' and vencimento < h), 'total', coalesce((select sum(valor) from despesas where status::text='A pagar' and vencimento < h),0)),
        'a_pagar_proximos_7_dias', jsonb_build_object('qtd', (select count(*) from despesas where status::text='A pagar' and vencimento >= h and vencimento <= h+7), 'total', coalesce((select sum(valor) from despesas where status::text='A pagar' and vencimento >= h and vencimento <= h+7),0)),
        'pagas_30d_por_categoria', coalesce((select jsonb_object_agg(coalesce(cat,'Sem categoria'), v) from (select categoria::text cat, sum(valor) v from despesas where status::text='Paga' and data_hora >= now() - interval '30 days' group by 1 order by 2 desc limit 10) x), '{}'::jsonb)),
      'clientes', jsonb_build_object(
        'total', (select count(*) from clientes),
        'novos_30d', (select count(*) from clientes where criado_em >= now() - interval '30 days'),
        'melhores_30d', coalesce((select jsonb_agg(jsonb_build_object('nome', n, 'pedidos', p, 'gasto', g)) from (select ve.cliente_nome n, count(*) p, sum(ve.valor_total) g from vendas ve where ve.status::text='Confirmada' and ve.data_hora >= now() - interval '30 days' and coalesce(ve.cliente_nome,'') <> '' group by 1 order by 3 desc limit 5) x), '[]'::jsonb)),
      'eventos_proximos', coalesce((select jsonb_agg(jsonb_build_object('nome', nome, 'data', data, 'status', status::text, 'a_receber', valor_a_receber)) from (select * from eventos where data >= h order by data limit 5) e), '[]'::jsonb),
      'estoque_valor_total', (select coalesce(sum(quantidade * coalesce(custo_unitario,0)),0) from estoque where quantidade > 0)
    );
  end if;
  return r;
end $$;


--
-- Name: ia_cota_tentar(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_cota_tentar(p_user uuid, p_nivel text DEFAULT 'Admin'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c ai_config; g int; u int; lim int; hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  select * into c from ai_config where id;
  select coalesce(sum(chamadas),0) into g from ai_uso where dia = hoje;
  select coalesce(sum(chamadas),0) into u from ai_uso where dia = hoje and usuario_id = p_user;
  lim := case when p_nivel = 'Operador' then c.cota_diaria_operador
              when p_nivel in ('Garçom','Cozinha','Entregador') then least(c.cota_diaria_operador, 15)
              else c.cota_diaria_usuario end;
  if g >= c.cota_diaria_global then return jsonb_build_object('ok', false, 'motivo', 'cota_global'); end if;
  if u >= lim then return jsonb_build_object('ok', false, 'motivo', 'cota_usuario'); end if;
  return jsonb_build_object('ok', true, 'restante_usuario', lim - u, 'restante_global', c.cota_diaria_global - g);
end $$;


--
-- Name: ia_cron_status_(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_cron_status_() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
begin
  if coalesce(ia_nivel_real(), '') <> 'Desenvolvedor' then return jsonb_build_object('ok', false); end if;
  return jsonb_build_object('ok', true,
    'jobs_ativos', (select count(*) from cron.job where active),
    'falhas_7d', coalesce((select jsonb_agg(jsonb_build_object('job', j.jobname, 'falhas', f.n, 'ultima_msg', ia_limpa_(f.msg, 150)) order by f.n desc)
        from (select jobid, count(*) n, max(return_message) msg from cron.job_run_details where status = 'failed' and start_time >= now() - interval '7 days' group by jobid) f
        join cron.job j on j.jobid = f.jobid), '[]'::jsonb),
    'ultima_execucao', coalesce((select jsonb_agg(jsonb_build_object('job', j.jobname, 'status', d.status, 'em', d.start_time) order by j.jobname)
        from cron.job j left join lateral (select status, start_time from cron.job_run_details where jobid = j.jobid order by start_time desc limit 1) d on true where j.active), '[]'::jsonb));
end $$;


--
-- Name: ia_diag_banco(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_diag_banco() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare ns oid := 'public'::regnamespace;
begin
  if coalesce(ia_nivel_real(), '') <> 'Desenvolvedor' then
    return jsonb_build_object('ok', false, 'message', 'Disponível só para o Desenvolvedor.');
  end if;
  return jsonb_build_object('ok', true,
    'tabelas_total', (select count(*) from pg_class where relnamespace = ns and relkind = 'r'),
    'tabelas_sem_rls', coalesce((select jsonb_agg(relname order by relname) from pg_class where relnamespace = ns and relkind = 'r' and not relrowsecurity), '[]'::jsonb),
    'tabelas_rls_sem_politica', coalesce((select jsonb_agg(c.relname order by c.relname) from pg_class c where c.relnamespace = ns and c.relkind = 'r' and c.relrowsecurity
        and not exists (select 1 from pg_policies p where p.schemaname = 'public' and p.tablename = c.relname)), '[]'::jsonb),
    'tabelas_anon_pode_escrever', coalesce((select jsonb_agg(c.relname order by c.relname) from pg_class c where c.relnamespace = ns and c.relkind = 'r'
        and (has_table_privilege('anon', c.oid, 'INSERT') or has_table_privilege('anon', c.oid, 'UPDATE') or has_table_privilege('anon', c.oid, 'DELETE'))), '[]'::jsonb),
    'politicas_escrita_sem_filtro', coalesce((select jsonb_agg(tablename || '.' || policyname || ' (' || cmd || ')' order by tablename)
        from pg_policies where schemaname = 'public' and cmd <> 'SELECT' and (coalesce(qual, 'true') = 'true' and coalesce(with_check, 'true') = 'true')), '[]'::jsonb),
    'funcoes_definer_total', (select count(*) from pg_proc where pronamespace = ns and prosecdef),
    'funcoes_definer_sem_search_path', coalesce((select jsonb_agg(proname order by proname) from pg_proc where pronamespace = ns and prosecdef
        and (proconfig is null or not (proconfig::text ilike '%search_path%'))), '[]'::jsonb),
    'funcoes_anon_executa', coalesce((select jsonb_agg(proname order by proname) from pg_proc where pronamespace = ns and prokind = 'f'
        and prorettype <> 'trigger'::regtype and has_function_privilege('anon', oid, 'execute') and proname not like 'ia\_%' and proname not in ('registrar_erro_cliente')), '[]'::jsonb),
    'views_definer', coalesce((select jsonb_agg(c.relname order by c.relname) from pg_class c where c.relnamespace = ns and c.relkind = 'v'
        and not coalesce(c.reloptions::text, '') ilike '%security_invoker=true%'), '[]'::jsonb),
    'fks_sem_indice', coalesce((select jsonb_agg(x.tabela || '.' || x.conname order by x.tabela) from (
        select c.conrelid::regclass::text tabela, c.conname from pg_constraint c where c.contype = 'f' and c.connamespace = ns
          and not exists (select 1 from pg_index i where i.indrelid = c.conrelid
                and array(select unnest(c.conkey) order by 1) = array(select unnest((i.indkey::int2[])[0:array_length(c.conkey, 1) - 1]) order by 1)) limit 15) x), '[]'::jsonb),
    'indices_nunca_usados', coalesce((select jsonb_agg(jsonb_build_object('indice', s.indexrelname, 'tabela', s.relname, 'kb', pg_relation_size(s.indexrelid) / 1024) order by pg_relation_size(s.indexrelid) desc)
        from (select * from pg_stat_user_indexes si where si.schemaname = 'public' and si.idx_scan = 0
                and not exists (select 1 from pg_index i where i.indexrelid = si.indexrelid and (i.indisunique or i.indisprimary)) order by pg_relation_size(si.indexrelid) desc limit 8) s), '[]'::jsonb),
    'tabelas_leitura_sequencial', coalesce((select jsonb_agg(jsonb_build_object('tabela', relname, 'linhas', n_live_tup, 'seq_scans', seq_scan, 'idx_scans', coalesce(idx_scan, 0)) order by seq_scan desc)
        from (select * from pg_stat_user_tables where schemaname = 'public' and n_live_tup > 500 and seq_scan > 100 and seq_scan > 5 * coalesce(idx_scan, 0) order by seq_scan desc limit 6) t), '[]'::jsonb),
    'tabelas_com_lixo', coalesce((select jsonb_agg(jsonb_build_object('tabela', relname, 'mortas', n_dead_tup, 'vivas', n_live_tup) order by n_dead_tup desc)
        from (select * from pg_stat_user_tables where schemaname = 'public' and n_dead_tup > 100 and n_dead_tup > 0.2 * greatest(n_live_tup, 1) order by n_dead_tup desc limit 6) t), '[]'::jsonb),
    'gatilhos_desativados', coalesce((select jsonb_agg(c.relname || '.' || t.tgname order by c.relname) from pg_trigger t join pg_class c on c.oid = t.tgrelid
        where c.relnamespace = ns and not t.tgisinternal and t.tgenabled = 'D'), '[]'::jsonb),
    'agendador', ia_cron_status_());
end $$;


