--
-- Name: ia_diag_sistema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_diag_sistema() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(ia_nivel_real(), '') <> 'Desenvolvedor' then
    return jsonb_build_object('ok', false, 'message', 'Disponível só para o Desenvolvedor.');
  end if;
  return jsonb_build_object('ok', true, 'gerado_em', now(),
    'sync', (select jsonb_build_object(
        'principal_ultimo_ok', principal_ultimo_ok, 'principal_ultimo_erro', principal_ultimo_erro, 'principal_erro_msg', ia_limpa_(principal_ultimo_erro_msg),
        'contingencia_ultimo_ok', contingencia_ultimo_ok, 'contingencia_ultimo_erro', contingencia_ultimo_erro, 'contingencia_erro_msg', ia_limpa_(contingencia_ultimo_erro_msg),
        'contingencia_atraso_min', contingencia_atraso_minutos, 'limite_itens', alerta_itens_limite, 'limite_horas', alerta_horas_limite)
      from sync_estado limit 1),
    'fila', (select jsonb_build_object(
        'pendentes_principal', count(*) filter (where principal_ok_em is null),
        'pendentes_contingencia', count(*) filter (where contingencia_ok_em is null),
        'com_erro_principal', count(*) filter (where principal_ok_em is null and principal_erro is not null),
        'com_erro_contingencia', count(*) filter (where contingencia_ok_em is null and contingencia_erro is not null),
        'mais_antigo_min', round(extract(epoch from now() - min(criado_em) filter (where principal_ok_em is null or contingencia_ok_em is null)) / 60))
      from fila_sync),
    'fila_erros', coalesce((select jsonb_agg(jsonb_build_object('tabela', tabela, 'operacao', operacao, 'destino', destino, 'erro', erro, 'qtd', qtd) order by qtd desc)
      from (select * from (
              select tabela, operacao::text operacao, 'principal' destino, ia_limpa_(principal_erro) erro, count(*) qtd
                from fila_sync where principal_ok_em is null and principal_erro is not null group by 1, 2, 4
              union all
              select tabela, operacao::text, 'contingencia', ia_limpa_(contingencia_erro), count(*)
                from fila_sync where contingencia_ok_em is null and contingencia_erro is not null group by 1, 2, 4) u
            order by qtd desc limit 6) x), '[]'::jsonb),
    'backups', coalesce((select jsonb_agg(jsonb_build_object('data', data_hora, 'tipo', tipo::text, 'status', status, 'tamanho_mb', round(coalesce(tamanho_bytes, 0) / 1048576.0, 1), 'tentativas', tentativas, 'erro', ia_limpa_(erro)) order by data_hora desc)
      from (select * from backups order by data_hora desc limit 5) b), '[]'::jsonb),
    'integridade', coalesce((select jsonb_agg(jsonb_build_object('data', criado_em, 'vendas_supabase', supabase_vendas, 'vendas_planilha', planilha_vendas, 'diferenca', diferenca_vendas, 'status', status) order by criado_em desc)
      from (select * from integridade_checks order by criado_em desc limit 3) i), '[]'::jsonb),
    'auditoria_24h', coalesce((select jsonb_agg(jsonb_build_object('acao', ia_limpa_(acao, 60), 'qtd', qtd) order by qtd desc)
      from (select acao, count(*) qtd from auditoria where data_hora >= now() - interval '24 hours' group by 1 order by 2 desc limit 10) a), '[]'::jsonb),
    'banco', jsonb_build_object('tamanho_mb', round(pg_database_size(current_database()) / 1048576.0),
      'maiores_tabelas', coalesce((select jsonb_agg(jsonb_build_object('tabela', relname, 'mb', mb) order by mb desc)
        from (select c.relname, round(pg_total_relation_size(c.oid) / 1048576.0, 1) mb from pg_class c join pg_namespace n on n.oid = c.relnamespace
               where n.nspname = 'public' and c.relkind = 'r' order by pg_total_relation_size(c.oid) desc limit 5) t), '[]'::jsonb)),
    'erros_js_total_48h', (select coalesce(sum(ocorrencias), 0) from erros_cliente where ultima_em >= now() - interval '48 hours'),
    'erros_js_48h', coalesce((select jsonb_agg(jsonb_build_object('mensagem', mensagem, 'origem', origem, 'tela', tela, 'ocorrencias', oc, 'usuarios', us, 'ultima', ult, 'pilha', pilha) order by oc desc)
      from (select mensagem, origem, max(tela) tela, sum(ocorrencias) oc, count(distinct usuario_id) us, max(ultima_em) ult, max(left(pilha, 300)) pilha
              from erros_cliente where ultima_em >= now() - interval '48 hours' group by mensagem, origem order by sum(ocorrencias) desc limit 8) e), '[]'::jsonb),
    'ia_erros_24h', coalesce((select jsonb_agg(jsonb_build_object('codigo', cod, 'provedor', provedor, 'qtd', qtd) order by qtd desc)
      from (select coalesce(detalhe, '?') cod, provedor, count(*) qtd from ai_log where status = 'erro' and criado_em >= now() - interval '24 hours' group by 1, 2 order by 3 desc limit 6) e), '[]'::jsonb));
end $$;


--
-- Name: ia_entregas_operacional(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_entregas_operacional() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb;
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  select jsonb_build_object('ok', true,
    'em_rota', (select count(*) from vendas where status_pedido::text = 'Saiu para entrega'),
    'prontas_aguardando', (select count(*) from vendas where status_pedido::text = 'Pronta' and tipo::text ilike '%entrega%'),
    'mais_antiga_em_rota_min', (select floor(extract(epoch from now() - min(saiu_em)) / 60) from vendas where status_pedido::text = 'Saiu para entrega'),
    'tempo_medio_7d_min', (select round(avg(extract(epoch from concluida_em - saiu_em) / 60)::numeric, 0) from vendas where saiu_em is not null and concluida_em is not null and concluida_em >= now() - interval '7 days'),
    'por_entregador', coalesce((select jsonb_agg(jsonb_build_object('entregador', u.login, 'em_rota', c.n)) from (select entregador_id, count(*) n from vendas where status_pedido::text = 'Saiu para entrega' and entregador_id is not null group by 1) c join usuarios u on u.id = c.entregador_id), '[]'::jsonb)
  ) into r;
  return r;
end $$;


--
-- Name: ia_estoque_operacional(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_estoque_operacional() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb;
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  select jsonb_build_object('ok', true,
    'total_itens', (select count(*) from estoque where status::text = 'Ativo' or status::text ilike 'ativ%'),
    'zerados', coalesce((select jsonb_agg(jsonb_build_object('ingrediente', ingrediente, 'unidade', unidade)) from (select * from estoque where quantidade <= 0 order by ingrediente limit 15) z), '[]'::jsonb),
    'abaixo_do_minimo', coalesce((select jsonb_agg(jsonb_build_object('ingrediente', ingrediente, 'quantidade', quantidade, 'minimo', quantidade_minima, 'unidade', unidade)) from (select * from estoque where quantidade > 0 and quantidade_minima > 0 and quantidade <= quantidade_minima order by (quantidade / nullif(quantidade_minima,0)) limit 15) z), '[]'::jsonb)
  ) into r;
  return r;
end $$;


--
-- Name: ia_explorar(text, date, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_explorar(p_tabela text, p_ini date DEFAULT NULL::date, p_fim date DEFAULT NULL::date, p_busca text DEFAULT NULL::text, p_limite integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  adm boolean := tem_nivel('Admin');
  tz constant text := 'America/Sao_Paulo';
  t text := lower(btrim(coalesce(p_tabela, '')));
  b text := nullif(replace(replace(btrim(coalesce(p_busca, '')), '%', ''), '_', ''), '');
  lim int := least(greatest(coalesce(p_limite, 30), 1), 100);
  dcol text; dtipo text; dexpr text := 'true'; dsel text; sql text; r jsonb;
begin
  if not tem_nivel('Admin','Operador') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  if not (t = any(public._ia_tabelas(adm))) then return jsonb_build_object('ok', false, 'message', 'Tabela não disponível para o seu perfil.'); end if;
  select c.column_name::text, c.data_type::text into dcol, dtipo
    from information_schema.columns c
   where c.table_schema = 'public' and c.table_name::text = t
     and c.column_name::text in ('data_hora','data','criado_em','abertura','atualizada_em','recebido_em')
   order by array_position(array['data_hora','data','criado_em','abertura','atualizada_em','recebido_em'], c.column_name::text) limit 1;
  dsel := case when dcol is null then 'null::timestamptz' else format('t.%I', dcol) end;
  if p_ini is not null or p_fim is not null then
    if p_ini is null or p_fim is null or p_fim < p_ini or (p_fim - p_ini) > 366 then
      return jsonb_build_object('ok', false, 'message', 'Período inválido (máx. 366 dias).');
    end if;
    if dcol is not null then
      if dtipo = 'date' then dexpr := format('t.%I between %L::date and %L::date', dcol, p_ini, p_fim);
      else dexpr := format('(t.%I at time zone %L)::date between %L::date and %L::date', dcol, tz, p_ini, p_fim); end if;
    end if;
  end if;
  sql := format($q$
    with f as (select public._ia_mascara(to_jsonb(t), $1) m, %s d from public.%I t where %s),
    g as (select m, d from f where $2::text is null or m::text ilike '%%' || $2 || '%%')
    select jsonb_build_object(
      'total', (select count(*) from g),
      'linhas', coalesce((select jsonb_agg(m) from (select m from g order by d desc nulls last limit %s) z), '[]'::jsonb),
      'somas', case when $1 and (select count(*) from g) <= 5000 then coalesce((
          select jsonb_object_agg(s.k, s.v) from (
            select e.k, sum((e.v #>> '{}')::numeric) v from g, jsonb_each(g.m) e(k, v)
             where jsonb_typeof(e.v) = 'number' and e.k not in ('id','ordem','numero','numero_pedido','prazo_dias','capacidade','ordem_cardapio')
             group by e.k) s), '{}'::jsonb) else null end)
  $q$, dsel, t, dexpr, lim);
  execute sql into r using adm, b;
  return jsonb_build_object('ok', true, 'tabela', t, 'periodo', case when p_ini is null then null else p_ini::text || ' a ' || p_fim::text end) || r;
end $_$;


--
-- Name: ia_limpa_(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_limpa_(t text, n integer DEFAULT 160) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select left(regexp_replace(regexp_replace(regexp_replace(coalesce(t, ''),
         '[[:alnum:]._%+-]+@[[:alnum:].-]+', '[email]', 'g'), '[0-9]{6,}', '#', 'g'), '[\r\n\t]+', ' ', 'g'), n)
$$;


