--
-- Name: ia_painel_uso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_painel_uso() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
begin
  if not tem_nivel('Admin') then return jsonb_build_object('ok', false, 'message', 'Sem permissão.'); end if;
  return jsonb_build_object('ok', true,
    'hoje', coalesce((select jsonb_agg(jsonb_build_object('provedor', provedor, 'chamadas', c, 'erros', e)) from
        (select provedor, sum(chamadas) c, sum(erros) e from ai_uso where dia = (now() at time zone 'America/Sao_Paulo')::date group by 1) x), '[]'::jsonb),
    'ultimos_7_dias', coalesce((select sum(chamadas) from ai_uso where dia >= current_date - 7), 0),
    'erros_24h', (select count(*) from ai_log where status = 'erro' and criado_em >= now() - interval '24 hours'),
    'cache_24h', (select count(*) from ai_log where status = 'cache' and criado_em >= now() - interval '24 hours'));
end $$;


--
-- Name: ia_periodo_(date, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_periodo_(p_a date, p_b date, p_adm boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  tz constant text := 'America/Sao_Paulo';
  t_ini timestamptz := (p_a::timestamp at time zone tz);
  t_fim timestamptz := ((p_b + 1)::timestamp at time zone tz);
  r jsonb; tot jsonb; fat numeric; cus numeric; tx numeric; ped int;
begin
  r := jsonb_build_object(
    'de', p_a, 'ate', p_b,
    'pedidos', (select count(*) from vendas where status::text='Confirmada' and data_hora>=t_ini and data_hora<t_fim),
    'cancelados', (select count(*) from vendas where status::text='Cancelada' and data_hora>=t_ini and data_hora<t_fim),
    'por_tipo', coalesce((select jsonb_object_agg(k, n) from (select tipo::text k, count(*) n from vendas where status::text='Confirmada' and data_hora>=t_ini and data_hora<t_fim group by 1) x), '{}'::jsonb),
    'por_origem', coalesce((select jsonb_object_agg(k, n) from (select origem::text k, count(*) n from vendas where status::text='Confirmada' and data_hora>=t_ini and data_hora<t_fim group by 1) x), '{}'::jsonb)
  );
  if p_adm then
    tot := ia_totais_(p_a, p_b);
    fat := coalesce((tot->>'faturamento')::numeric,0); cus := coalesce((tot->>'custo')::numeric,0); tx := coalesce((tot->>'taxas')::numeric,0); ped := coalesce((tot->>'pedidos')::int,0);
    r := r || jsonb_build_object(
      'faturamento', fat, 'custo_vendas', cus, 'taxas_pagamento', tx, 'lucro_bruto', fat - tx - cus,
      'margem_pct', case when fat > 0 and cus > 0 then round((fat - tx - cus) / fat * 100, 1) end,
      'ticket_medio', case when ped > 0 then round(fat / ped, 2) end,
      'descontos', coalesce((select sum(valor_desconto) from vendas where status::text='Confirmada' and data_hora>=t_ini and data_hora<t_fim),0),
      'taxas_entrega', coalesce((select sum(taxa_entrega) from vendas where status::text='Confirmada' and data_hora>=t_ini and data_hora<t_fim),0),
      'a_receber', coalesce((select sum(valor_total) from vendas where status::text='Confirmada' and status_pagamento::text='A Receber' and data_hora>=t_ini and data_hora<t_fim),0),
      'despesas_pagas', coalesce((select sum(valor) from despesas where status::text='Paga' and data_hora>=t_ini and data_hora<t_fim),0),
      'por_pagamento', coalesce((select jsonb_object_agg(f, v) from (select pv.forma_pagamento f, sum(pv.valor) v from pagamentos_venda pv join vendas ve on ve.id=pv.venda_id where ve.status::text='Confirmada' and ve.data_hora>=t_ini and ve.data_hora<t_fim group by 1) x), '{}'::jsonb)
    );
  end if;
  return r;
end $$;


--
-- Name: ia_producao_operacional(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_producao_operacional() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r jsonb;
  ini_hoje timestamptz := date_trunc('day', now() at time zone 'America/Sao_Paulo') at time zone 'America/Sao_Paulo';
begin
  if not tem_nivel('Admin','Operador') then
    return jsonb_build_object('ok', false, 'message', 'Sem permissão.');
  end if;
  select jsonb_build_object('ok', true,
    'recebidos_agora', (select count(*) from vendas where status_pedido::text = 'Recebido' and status::text <> 'Cancelada'),
    'em_preparo_agora', (select count(*) from vendas where status_pedido::text = 'Em preparo' and status::text <> 'Cancelada'),
    'prontos_agora', (select count(*) from vendas where status_pedido::text = 'Pronta' and status::text <> 'Cancelada'),
    'pedidos_hoje', (select count(*) from vendas where data_hora >= ini_hoje and status::text <> 'Cancelada'),
    'pedido_aberto_mais_antigo_min', (select floor(extract(epoch from now() - min(recebido_em)) / 60) from vendas where status_pedido::text in ('Recebido','Em preparo','Pronta') and status::text <> 'Cancelada' and recebido_em is not null),
    'preparo_medio_hoje_min', (select round(avg(extract(epoch from pronta_em - inicio_preparo_em) / 60)::numeric, 0) from vendas where inicio_preparo_em is not null and pronta_em is not null and pronta_em >= inicio_preparo_em and pronta_em >= ini_hoje and status::text <> 'Cancelada'),
    'preparo_medio_7d_min', (select round(avg(extract(epoch from pronta_em - inicio_preparo_em) / 60)::numeric, 0) from vendas where inicio_preparo_em is not null and pronta_em is not null and pronta_em >= inicio_preparo_em and pronta_em >= now() - interval '7 days' and status::text <> 'Cancelada'),
    'espera_antes_do_preparo_7d_min', (select round(avg(extract(epoch from inicio_preparo_em - recebido_em) / 60)::numeric, 0) from vendas where recebido_em is not null and inicio_preparo_em is not null and inicio_preparo_em >= recebido_em and inicio_preparo_em >= now() - interval '7 days' and status::text <> 'Cancelada'),
    'tempo_total_medio_7d_min', (select round(avg(extract(epoch from concluida_em - recebido_em) / 60)::numeric, 0) from vendas where recebido_em is not null and concluida_em is not null and concluida_em >= recebido_em and concluida_em >= now() - interval '7 days' and status::text <> 'Cancelada'),
    'pedidos_concluidos_7d', (select count(*) from vendas where concluida_em is not null and concluida_em >= now() - interval '7 days' and status::text <> 'Cancelada')
  ) into r;
  return r;
end
$$;


--
-- Name: ia_publico_contexto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_publico_contexto() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_set(b, '{adicionais_disponiveis_em_todos_os_lanches}',
           coalesce((select jsonb_agg(jsonb_build_object('nome', e->>'nome', 'preco', nullif((e->>'preco')::numeric, 0)))
                       from jsonb_array_elements(b->'adicionais_disponiveis_em_todos_os_lanches') e), '[]'::jsonb))
         || jsonb_build_object('aviso_adicionais', 'Adicional com preco nulo: o valor aparece na tela ao montar o pedido. Nunca diga que e gratis nem invente valor.')
  from (select public.ia_publico_contexto_base() b) x;
$$;


--
-- Name: ia_publico_contexto_base(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_publico_contexto_base() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with esg as (select tipo::text tipo, id from public.v_cardapio_esgotados),
  pr as (
    select p.tipo::text tipo, p.item_id,
           case when count(distinct p.preco) = 1 then to_jsonb(min(p.preco))
                else jsonb_object_agg(coalesce(f.nome, '?'), p.preco) end preco
      from public.v_cardapio_precos p left join public.v_cardapio_formas f on f.id = p.forma_pagamento_id
     group by p.tipo, p.item_id)
  select jsonb_build_object(
    'caixa_aberto', coalesce((select bool_or(caixa_aberto) from public.v_cardapio_status), false),
    'config', (select coalesce(jsonb_object_agg(chave, valor), '{}'::jsonb) from public.v_cardapio_config
                where chave in ('CardapioTempoRetirada','CardapioTempoMesa','CardapioTempoEntrega','TaxaEntregaPadrao') and valor::text not in ('""','null')),
    'formas_pagamento', (select coalesce(jsonb_agg(jsonb_build_object('nome', nome, 'aceita_troco', permite_troco) order by ordem), '[]'::jsonb) from public.v_cardapio_formas),
    'adicionais_disponiveis_em_todos_os_lanches', (select coalesce(jsonb_agg(jsonb_build_object('nome', nome, 'preco', preco) order by nome), '[]'::jsonb)
                                                  from (select distinct nome, preco from public.v_cardapio_adicionais) a),
    'produtos', (select coalesce(jsonb_agg(jsonb_build_object(
        'nome', p.nome, 'descricao', left(coalesce(p.descricao,''), 220), 'categoria', c.nome, 'destaque', coalesce(p.destaque,false),
        'esgotado', exists(select 1 from esg e where e.tipo = 'produto' and e.id = p.id),
        'preco', (select pr.preco from pr where pr.tipo = 'produto' and pr.item_id = p.id)
      ) order by c.ordem, p.ordem_cardapio, p.nome), '[]'::jsonb)
      from public.v_cardapio_produtos p left join public.v_cardapio_categorias c on c.id = p.categoria_id),
    'combos', (select coalesce(jsonb_agg(jsonb_build_object(
        'nome', b.nome, 'categoria', c.nome, 'destaque', coalesce(b.destaque,false),
        'esgotado', exists(select 1 from esg e where e.tipo = 'combo' and e.id = b.id),
        'preco', (select pr.preco from pr where pr.tipo = 'combo' and pr.item_id = b.id),
        'itens', coalesce((select jsonb_agg(ci.quantidade || 'x ' || pp.nome) from public.v_cardapio_combo_itens ci join public.v_cardapio_produtos pp on pp.id = ci.produto_id where ci.combo_id = b.id), '[]'::jsonb)
      ) order by c.ordem, b.ordem_cardapio, b.nome), '[]'::jsonb)
      from public.v_cardapio_combos b left join public.v_cardapio_categorias c on c.id = b.categoria_id),
    'mais_pedidos', (select coalesce(jsonb_agg(n order by pos), '[]'::jsonb) from (
        select coalesce(p.nome, b.nome) n, m.posicao pos from public.v_cardapio_mais_pedidos m
          left join public.v_cardapio_produtos p on m.tipo::text = 'produto' and p.id = m.id
          left join public.v_cardapio_combos b on m.tipo::text = 'combo' and b.id = m.id
         order by m.posicao limit 8) z where n is not null),
    'promocoes', (select coalesce(jsonb_agg(jsonb_build_object('nome', nome, 'beneficio', beneficio)), '[]'::jsonb)
                    from (select distinct nome, beneficio from public.promocoes where ativa) q)
  );
$$;


--
-- Name: ia_publico_limite(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_publico_limite(p_ip text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_k text := 'iaqa_ip_' || left(coalesce(nullif(p_ip,''), 'sem_ip'), 64);
begin
  if public._excedeu(v_k, 20) then return jsonb_build_object('ok', false, 'motivo', 'limite_ip'); end if;
  perform public._registrar_falha(v_k, 600);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: ia_publico_status_pedido(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_publico_status_pedido(p_telefone text, p_ip text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tel text := right(public._so_digitos(p_telefone), 11);
  v_ipk text := 'iastat_ip_' || left(coalesce(nullif(p_ip,''), 'sem_ip'), 64);
  v_telk text; cfg public.chat_config%rowtype; r jsonb;
begin
  if length(v_tel) < 10 then return jsonb_build_object('ok', false, 'motivo', 'telefone_invalido'); end if;
  v_telk := 'iastat_tel_' || v_tel;
  if public._excedeu(v_ipk, 10) or public._excedeu(v_telk, 6) then return jsonb_build_object('ok', false, 'motivo', 'limite'); end if;
  perform public._registrar_falha(v_ipk, 600); perform public._registrar_falha(v_telk, 600);
  select * into cfg from public.chat_config where id;
  select coalesce(jsonb_agg(jsonb_build_object(
      'numero', x.numero_pedido, 'situacao', x.status::text, 'andamento', x.status_pedido::text, 'tipo', x.tipo::text,
      'quando', to_char(x.data_hora at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI'), 'valor_total', x.valor_total,
      'pagamento', x.status_pagamento::text, 'motivo_cancelamento', nullif(x.motivo_cancelamento, ''),
      'itens', coalesce((select jsonb_agg(i.quantidade || 'x ' || coalesce(i.descricao,'') order by i.ctid) from public.itens_venda i where i.venda_id = x.id), '[]'::jsonb)
    ) order by x.data_hora desc), '[]'::jsonb) into r
  from (select * from public.vendas v
         where right(public._so_digitos(v.telefone_cliente), 11) = v_tel
           and v.data_hora >= now() - make_interval(hours => coalesce(cfg.janela_horas, 48))
         order by v.data_hora desc limit 3) x;
  return jsonb_build_object('ok', true, 'pedidos', r);
end $$;


--
-- Name: ia_resumo_periodo(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_resumo_periodo(p_ini date, p_fim date) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  tz constant text := 'America/Sao_Paulo';
  t_ini timestamptz; t_fim timestamptz; tot jsonb; fat numeric; cus numeric; tx numeric; ped int;
begin
  if not tem_nivel('Admin','Operador') then
    return jsonb_build_object('ok', false, 'message', 'Sem permissão.');
  end if;
  if p_ini is null or p_fim is null or p_fim < p_ini or (p_fim - p_ini) > 92 then
    return jsonb_build_object('ok', false, 'message', 'Período inválido (máx. 93 dias).');
  end if;
  t_ini := (p_ini::timestamp at time zone tz);
  t_fim := ((p_fim + 1)::timestamp at time zone tz);
  tot := ia_totais_(p_ini, p_fim);
  fat := (tot->>'faturamento')::numeric; cus := (tot->>'custo')::numeric; tx := (tot->>'taxas')::numeric; ped := (tot->>'pedidos')::int;
  return jsonb_build_object(
    'ok', true, 'ini', p_ini, 'fim', p_fim,
    'faturamento', fat, 'custo', cus, 'taxas_pagamento', tx, 'lucro_bruto', fat - tx - cus,
    'margem_pct', case when fat > 0 then round((fat - tx - cus) / fat * 100, 1) end,
    'pedidos', ped, 'cancelados', (tot->>'cancelados')::int,
    'ticket_medio', case when ped > 0 then round(fat / ped, 2) end,
    'descontos', coalesce((select sum(valor_desconto) from vendas where status = 'Confirmada' and data_hora >= t_ini and data_hora < t_fim), 0),
    'taxas_entrega', coalesce((select sum(taxa_entrega) from vendas where status = 'Confirmada' and data_hora >= t_ini and data_hora < t_fim), 0),
    'a_receber', coalesce((select sum(valor_total) from vendas where status = 'Confirmada' and status_pagamento = 'A Receber' and data_hora >= t_ini and data_hora < t_fim), 0),
    'despesas_pagas', coalesce((select sum(valor) from despesas where status = 'Paga' and data_hora >= t_ini and data_hora < t_fim), 0),
    'por_tipo', coalesce((select jsonb_agg(jsonb_build_object('tipo', tipo, 'pedidos', n, 'valor', v) order by v desc)
        from (select tipo::text tipo, count(*) n, sum(valor_total) v from vendas
              where status = 'Confirmada' and data_hora >= t_ini and data_hora < t_fim group by 1) x), '[]'::jsonb),
    'por_origem', coalesce((select jsonb_agg(jsonb_build_object('origem', origem, 'pedidos', n, 'valor', v) order by v desc)
        from (select origem::text origem, count(*) n, sum(valor_total) v from vendas
              where status = 'Confirmada' and data_hora >= t_ini and data_hora < t_fim group by 1) x), '[]'::jsonb),
    'por_pagamento', coalesce((select jsonb_agg(jsonb_build_object('forma', f, 'valor', v) order by v desc)
        from (select pv.forma_pagamento f, sum(pv.valor) v from pagamentos_venda pv join vendas ve on ve.id = pv.venda_id
              where ve.status = 'Confirmada' and ve.data_hora >= t_ini and ve.data_hora < t_fim group by 1) x), '[]'::jsonb),
    'top_produtos', coalesce((select jsonb_agg(jsonb_build_object('nome', d, 'qtd', q, 'valor', v, 'margem_pct', m) order by v desc)
        from (select iv.descricao d, sum(iv.quantidade) q, sum(iv.valor_total_item) v,
                     case when sum(iv.valor_total_item) > 0
                          then round((sum(iv.valor_total_item) - sum(iv.custo_unitario * iv.quantidade)) / sum(iv.valor_total_item) * 100, 1) end m
              from itens_venda iv join vendas ve on ve.id = iv.venda_id
              where ve.status = 'Confirmada' and ve.data_hora >= t_ini and ve.data_hora < t_fim
              group by iv.descricao order by sum(iv.valor_total_item) desc limit 5) x), '[]'::jsonb),
    'por_hora', coalesce((select jsonb_agg(jsonb_build_object('hora', h, 'pedidos', n, 'valor', v) order by h)
        from (select extract(hour from data_hora at time zone tz)::int h, count(*) n, sum(valor_total) v from vendas
              where status = 'Confirmada' and data_hora >= t_ini and data_hora < t_fim group by 1) x), '[]'::jsonb)
  );
end $$;


--
-- Name: ia_sugestao_compras(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_sugestao_compras(p_dias integer DEFAULT 14, p_cobertura integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare itens jsonb; total numeric;
begin
  if not tem_nivel('Admin','Operador') then
    return jsonb_build_object('ok', false, 'message', 'Sem permissão.');
  end if;
  p_dias := least(greatest(coalesce(p_dias,14),3),60); p_cobertura := least(greatest(coalesce(p_cobertura,7),1),30);
  with cons as (
    select ingrediente_id, sum(abs(quantidade)) q from movimentacoes_estoque
     where tipo in ('Venda','Perda','Saída') and data >= now() - make_interval(days => p_dias) group by 1
  ), base as (
    select e.id, e.ingrediente, e.unidade::text un, e.quantidade, e.quantidade_minima, e.custo_unitario,
           coalesce(c.q,0) / p_dias cdia
      from estoque e left join cons c on c.ingrediente_id = e.id where e.status = 'Ativo'
  ), calc as (
    select *, case when cdia > 0 then round(quantidade / cdia, 1) end dias_restantes,
           greatest(0, ceil(cdia * p_cobertura + quantidade_minima - quantidade)) sugerido
      from base
  ), sel as (
    select * from calc
     where sugerido > 0 or (quantidade_minima > 0 and quantidade <= quantidade_minima)
     order by (case when dias_restantes is null then 9999 else dias_restantes end), ingrediente limit 30
  )
  select coalesce(jsonb_agg(jsonb_build_object('ingrediente', ingrediente, 'unidade', un, 'em_estoque', quantidade,
           'minimo', quantidade_minima, 'consumo_dia', round(cdia,2), 'dias_restantes', dias_restantes,
           'sugerido', sugerido, 'custo_estimado', round(sugerido * coalesce(custo_unitario,0), 2))), '[]'::jsonb),
         coalesce(sum(sugerido * coalesce(custo_unitario,0)),0)
    into itens, total from sel;
  return jsonb_build_object('ok', true, 'janela_dias', p_dias, 'cobertura_dias', p_cobertura,
                            'custo_total_estimado', round(total,2), 'itens', itens);
end $$;


--
-- Name: ia_top_produtos_(date, date, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_top_produtos_(p_a date, p_b date, p_adm boolean, p_limite integer, p_ordem text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare tz constant text := 'America/Sao_Paulo'; t_ini timestamptz := (p_a::timestamp at time zone tz); t_fim timestamptz := ((p_b + 1)::timestamp at time zone tz);
begin
  return coalesce((select jsonb_agg(
      jsonb_build_object('produto', d, 'qtd', q) ||
      case when p_adm then jsonb_build_object('valor', v, 'margem_pct', m) else '{}'::jsonb end)
    from (select iv.descricao d, sum(iv.quantidade) q, sum(iv.valor_total_item) v,
                 case when sum(iv.valor_total_item) > 0 and sum(iv.custo_unitario*iv.quantidade) > 0 then round((sum(iv.valor_total_item) - sum(iv.custo_unitario*iv.quantidade)) / sum(iv.valor_total_item) * 100, 1) end m
          from itens_venda iv join vendas ve on ve.id=iv.venda_id
          where ve.status::text='Confirmada' and ve.data_hora>=t_ini and ve.data_hora<t_fim
          group by iv.descricao
          order by case when p_ordem='menos' then sum(iv.quantidade) end asc, case when p_ordem<>'menos' then sum(iv.quantidade) end desc
          limit greatest(1, least(coalesce(p_limite,10), 25))) x), '[]'::jsonb);
end $$;


--
-- Name: ia_totais_(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_totais_(p_ini date, p_fim date) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'faturamento', coalesce(sum(valor_total) filter (where status = 'Confirmada'), 0),
    'custo',       coalesce(sum(custo_total) filter (where status = 'Confirmada'), 0),
    'pedidos',     count(*) filter (where status = 'Confirmada'),
    'cancelados',  count(*) filter (where status = 'Cancelada'),
    'taxas', coalesce((select sum(pv.taxa_aplicada) from pagamentos_venda pv join vendas ve on ve.id = pv.venda_id
                        where ve.status = 'Confirmada'
                          and ve.data_hora >= (p_ini::timestamp at time zone 'America/Sao_Paulo')
                          and ve.data_hora <  ((p_fim + 1)::timestamp at time zone 'America/Sao_Paulo')), 0))
  from vendas
  where data_hora >= (p_ini::timestamp at time zone 'America/Sao_Paulo')
    and data_hora <  ((p_fim + 1)::timestamp at time zone 'America/Sao_Paulo')
$$;


--
-- Name: ia_uso_somar(uuid, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ia_uso_somar(p_user uuid, p_provedor text, p_erro boolean, p_tin integer DEFAULT 0, p_tout integer DEFAULT 0) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into ai_uso (dia, provedor, usuario_id, chamadas, erros, tokens_in, tokens_out)
  values ((now() at time zone 'America/Sao_Paulo')::date, p_provedor, p_user, 1, case when p_erro then 1 else 0 end, coalesce(p_tin,0), coalesce(p_tout,0))
  on conflict (dia, provedor, usuario_id) do update
    set chamadas = ai_uso.chamadas + 1, erros = ai_uso.erros + excluded.erros,
        tokens_in = ai_uso.tokens_in + excluded.tokens_in, tokens_out = ai_uso.tokens_out + excluded.tokens_out
$$;


--
-- Name: ifood_acao_resultado(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_acao_resultado(p_id bigint, p_estado text, p_erro text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a ifood_acoes%rowtype;
begin
  update ifood_acoes set estado = p_estado, tentativas = tentativas + 1, erro = left(p_erro, 300), executado_em = now() where id = p_id returning * into a;
  if a.id is null then return; end if;
  if p_estado = 'ok' then
    if a.acao = 'confirmar' then update ifood_pedidos set estado = 'confirmado', confirmado_em = coalesce(confirmado_em, now()), atualizado_em = now() where pedido_ifood = a.pedido_ifood and estado = 'novo'; end if;
    perform public._integ_log('ifood', 'info', 'Ação enviada ao iFood: ' || a.acao || ' (pedido ' || a.pedido_ifood || ')');
  elsif p_estado in ('erro', 'duvida') then
    perform public._integ_log('ifood', 'erro', 'Ação NÃO confirmada no iFood: ' || a.acao || ' — ' || coalesce(p_erro, ''));
  end if;
end $$;


--
-- Name: ifood_acoes_pendentes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_acoes_pendentes() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'pedido', a.pedido_ifood, 'acao', a.acao, 'dados', a.dados, 'tentativas', a.tentativas) order by a.id), '[]'::jsonb)
  from (select * from ifood_acoes where estado = 'pendente' order by id limit 20) a
$$;


--
-- Name: ifood_aplicar_evento(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_aplicar_evento(p_codigo text, p_pedido text, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r ifood_pedidos%rowtype; v vendas%rowtype; v_st text;
begin
  select * into r from ifood_pedidos where pedido_ifood = p_pedido for update;
  if not found then return jsonb_build_object('ok', false, 'desconhecido', true); end if;
  if p_codigo in ('CFM', 'CONFIRMED') and r.estado = 'novo' then update ifood_pedidos set estado = 'confirmado', confirmado_em = now(), atualizado_em = now() where pedido_ifood = p_pedido;
  elsif p_codigo in ('RTP', 'READY_TO_PICKUP') and r.estado in ('novo', 'confirmado', 'em_preparo') then update ifood_pedidos set estado = 'pronto', atualizado_em = now() where pedido_ifood = p_pedido;
  elsif p_codigo in ('DSP', 'DISPATCHED') and r.estado <> 'cancelado' then update ifood_pedidos set estado = 'despachado', atualizado_em = now() where pedido_ifood = p_pedido;
  elsif p_codigo in ('CON', 'CONCLUDED') and r.estado <> 'cancelado' then
    update ifood_pedidos set estado = 'concluido', atualizado_em = now() where pedido_ifood = p_pedido;
    update vendas set status_pedido = case when tipo = 'Entrega' then 'Entregue' else 'Retirada' end::status_pedido, concluida_em = coalesce(concluida_em, now())
      where id = r.venda_id and status = 'Confirmada' and status_pedido::text not in ('Entregue', 'Retirada', 'Servida');
  elsif p_codigo in ('CAN', 'CANCELLED') and r.estado = 'concluido' then
    -- o pedido já foi entregue: um cancelamento tardio não pode cancelar a venda sozinho
    perform _integ_log('ifood', 'aviso', 'Pedido #' || r.numero_ifood || ': cancelamento recebido depois de concluído (ignorado)');
    perform _auditar('Cancelamento do iFood ignorado', 'iFood #' || r.numero_ifood || ' · cancelamento recebido depois de concluído' || coalesce(' · ' || nullif(p_motivo, ''), ''));
    return jsonb_build_object('ok', true, 'ignorado', true);
  elsif p_codigo in ('CAN', 'CANCELLED') and r.estado <> 'cancelado' then
    update ifood_pedidos set estado = 'cancelado', atualizado_em = now() where pedido_ifood = p_pedido;
    select * into v from vendas where id = r.venda_id for update;
    if found and v.status = 'Confirmada' then
      v_st := v.status_pedido::text;
      update vendas set status = 'Cancelada', motivo_cancelamento = left('Cancelado pelo iFood' || coalesce(' · ' || nullif(p_motivo, ''), ''), 200) where id = v.id;
      if v_st in ('Recebido', 'Em preparo', 'Suspenso') then perform _ajustar_estoque(_itens_da_venda(v.id), -1, v.id); end if;
      update ifood_acoes set estado = 'pulada', erro = 'pedido cancelado' where pedido_ifood = p_pedido and estado in ('pendente', 'duvida');
      perform _auditar('Pedido do iFood cancelado pelo iFood', 'iFood #' || r.numero_ifood || coalesce(' · ' || nullif(p_motivo, ''), '') || case when v_st not in ('Recebido', 'Em preparo', 'Suspenso') then ' · já estava pronto: estoque NÃO devolvido' else '' end);
      perform _integ_log('ifood', 'aviso', 'Pedido #' || r.numero_ifood || ' cancelado pelo iFood');
      begin perform _push_enviar('pedido', '❌ iFood cancelou o pedido #' || r.numero_ifood, coalesce(nullif(p_motivo, ''), 'Veja o painel'), 'ifood-can-' || r.pedido_ifood); exception when others then null; end;
    end if;
  end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: ifood_atualizar_pedido(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_atualizar_pedido(p_order jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r ifood_pedidos%rowtype; v_sem int; v_val jsonb; v_total numeric; v_forma text;
begin
  select * into r from ifood_pedidos where pedido_ifood = p_order->>'id' for update;
  if not found then return public.ifood_criar_pedido(p_order, false); end if;
  if r.venda_id is null or r.estado = 'cancelado' then return jsonb_build_object('ok', true, 'ignorado', true); end if;
  v_sem := public._ifood_gravar_itens(r.venda_id, p_order, true);
  v_val := public._ifood_valores(p_order);
  v_total := (v_val->>'total')::numeric;
  v_forma := public._ifood_gravar_pagamentos(r.venda_id, p_order, v_total, (v_val->>'entregaIfood')::boolean);
  if r.comissao is not null and r.comissao > 0 then perform public._ifood_aplicar_comissao(r.venda_id, r.comissao); end if;
  update vendas set valor_total = v_total, valor_original = (v_val->>'original')::numeric, valor_desconto = (v_val->>'descontoLoja')::numeric,
         desconto_detalhe = case when (v_val->>'descontoLoja')::numeric > 0 then 'Desconto/cupom iFood pago pela loja' else '' end,
         taxa_entrega = (v_val->>'taxaEntrega')::numeric, forma_pagamento = v_forma,
         custo_total = coalesce((select sum(custo_unitario * quantidade) from itens_venda where venda_id = r.venda_id), 0)
   where id = r.venda_id;
  update ifood_pedidos set bruto = p_order, itens_sem_ligacao = v_sem, atualizado_em = now() where pedido_ifood = r.pedido_ifood;
  perform _auditar('Pedido do iFood alterado pelo cliente', 'iFood #' || r.numero_ifood, null);
  perform _integ_log('ifood', 'aviso', 'Pedido #' || r.numero_ifood || ' foi alterado pelo cliente');
  return jsonb_build_object('ok', true, 'semLigacao', v_sem);
end $$;


--
-- Name: ifood_avaliacoes_gravar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_avaliacoes_gravar(p_lista jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e jsonb; v_n int := 0; v_fb uuid; v_venda uuid; v_nota int; v_ja boolean; v_num text;
begin
  for e in select value from jsonb_array_elements(coalesce(p_lista, '[]'::jsonb)) loop
    if nullif(e->>'id', '') is null then continue; end if;
    v_ja := exists (select 1 from ifood_avaliacoes where id = e->>'id');
    v_nota := round(public._ifood_n(coalesce(e->'score', e->'rating', e->'nota')))::int;
    select venda_id, numero_ifood into v_venda, v_num from ifood_pedidos where pedido_ifood = e->>'orderId';
    insert into ifood_avaliacoes (id, pedido_ifood, nota, comentario, criada_em, resposta, bruto)
    values (e->>'id', e->>'orderId', v_nota, left(coalesce(e->>'comment', e->>'text', ''), 1000), nullif(e->>'createdAt', '')::timestamptz,
            nullif(coalesce(e->'replies'->0->>'text', e->>'reply'), ''), e)
    on conflict (id) do update set resposta = coalesce(excluded.resposta, ifood_avaliacoes.resposta), nota = excluded.nota;
    if not v_ja then
      begin
        insert into feedbacks (venda_id, nota, comentario, data, status, origem) values (v_venda, greatest(least(v_nota, 5), 1), left(coalesce(e->>'comment', e->>'text', ''), 1000), coalesce(nullif(e->>'createdAt', '')::timestamptz, now()), 'Novo', 'iFood') returning id into v_fb;
        update ifood_avaliacoes set feedback_id = v_fb where id = e->>'id';
      exception when others then null; end;
      if v_nota <= 2 then perform _push_enviar('feedback', '⭐ Avaliação baixa no iFood (' || v_nota || ')', coalesce(left(e->>'comment', 100), 'Veja no painel'), 'ifood-aval-' || (e->>'id')); end if;
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end $$;


--
-- Name: ifood_catalogo_gravar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_catalogo_gravar(p_itens jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e jsonb; v_n int := 0; r ifood_itens%rowtype; v_chave text;
begin
  for e in select value from jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) loop
    v_chave := coalesce(nullif(e->>'externalCode', ''), nullif(e->>'id', ''));
    if v_chave is null then continue; end if;
    r := public._ifood_item_visto(v_chave, e->>'name', 'produto');
    update ifood_itens set ifood_item_id = coalesce(nullif(e->>'id', ''), ifood_item_id), preco_ifood = case when e ? 'price' then public._ifood_n(e->'price') else preco_ifood end,
      preco_visto_em = now(), categoria = left(coalesce(nullif(e->>'category', ''), categoria), 120) where chave = v_chave;
    v_n := v_n + 1;
  end loop;
  perform public._integ_log('ifood', 'info', 'Catálogo do iFood importado: ' || v_n || ' item(ns)');
  return v_n;
end $$;


--
-- Name: ifood_credenciais(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_credenciais() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('ligado', public._integracao_ligada('ifood'),
    'clientId', (select valor from integracoes_segredos where chave = 'ifood_client_id'),
    'clientSecret', (select valor from integracoes_segredos where chave = 'ifood_client_secret'),
    'merchantId', (select valor from integracoes_segredos where chave = 'ifood_merchant_id'),
    'config', (select config from integracoes_config where provedor = 'ifood'))
$$;


--
-- Name: ifood_criar_pedido(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_criar_pedido(p_order jsonb, p_simulado boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_id text := p_order->>'id'; v_disp text := coalesce(nullif(p_order->>'displayId', ''), right(coalesce(p_order->>'id', ''), 4));
  v_venda uuid := gen_random_uuid(); v_tipo venda_tipo; v_nome text; v_tel text; v_end text; v_comp text; v_ref text; v_obs text;
  v_val jsonb; v_total numeric; v_sem int; v_caixa uuid; v_numero int; v_troco numeric; v_agend text; v_forma text; v_pend numeric; v_cash numeric; v_stpag status_pagamento; ad jsonb; v_cpf text; v_okdata timestamptz;
begin
  if v_id is null then return jsonb_build_object('ok', false, 'message', 'Pedido sem id.'); end if;
  if exists (select 1 from ifood_pedidos where pedido_ifood = v_id) then return jsonb_build_object('ok', true, 'duplicado', true); end if;
  if jsonb_typeof(p_order->'items') is distinct from 'array' or jsonb_array_length(p_order->'items') = 0 then return jsonb_build_object('ok', false, 'message', 'Pedido sem itens.'); end if;
  v_tipo := case when upper(coalesce(p_order->>'orderType', '')) in ('TAKEOUT', 'PICKUP', 'INDOOR') then 'Retirada' else 'Entrega' end::venda_tipo;
  v_nome := left(btrim(coalesce(p_order->'customer'->>'name', 'Cliente iFood')), 80) || ' (iFood)';
  v_tel := left(regexp_replace(coalesce(p_order->'customer'->'phone'->>'number', ''), '[^0-9]', '', 'g'), 20);
  ad := coalesce(p_order->'delivery'->'deliveryAddress', '{}'::jsonb);
  v_end := coalesce(nullif(ad->>'formattedAddress', ''), btrim(concat_ws(', ', ad->>'streetName', ad->>'streetNumber', ad->>'neighborhood', ad->>'city')));
  v_comp := coalesce(ad->>'complement', ''); v_ref := coalesce(ad->>'reference', '');
  v_cpf := regexp_replace(coalesce(p_order->'customer'->>'documentNumber', ''), '[^0-9]', '', 'g');
  if not public._cpf_valido(v_cpf) then v_cpf := null; end if;
  v_val := public._ifood_valores(p_order);
  v_total := (v_val->>'total')::numeric;
  v_pend := public._ifood_n(p_order->'payments'->'pending');
  v_cash := case when (v_val->>'entregaIfood')::boolean then 0 else round(least(greatest(v_pend, 0), v_total), 2) end;
  v_stpag := case when v_cash > 0.009 then 'A Receber' else 'Pago' end;
  v_forma := case when v_cash > 0.009 and v_total - v_cash > 0.009 then 'iFood (pago no app) + iFood (pagar na entrega)' when v_cash > 0.009 then 'iFood (pagar na entrega)' else 'iFood (pago no app)' end;
  v_obs := 'iFood #' || v_disp;
  if v_tipo = 'Entrega' and (v_val->>'entregaIfood')::boolean then v_obs := v_obs || ' · ENTREGA PELO iFOOD'; end if;
  select (m->'cash'->>'changeFor') into v_troco from jsonb_array_elements(coalesce(p_order->'payments'->'methods', '[]'::jsonb)) m where m->'cash'->>'changeFor' is not null limit 1;
  if v_troco is not null and public._ifood_n(to_jsonb(v_troco)) > 0 and upper(coalesce(p_order->'delivery'->>'deliveredBy', '')) = 'MERCHANT' then v_obs := v_obs || ' · levar troco para R$ ' || replace(to_char(public._ifood_n(to_jsonb(v_troco)), 'FM9999990.00'), '.', ','); end if;
  if upper(coalesce(p_order->>'orderTiming', '')) = 'SCHEDULED' then
    v_agend := coalesce(p_order->'schedule'->>'deliveryDateTimeStart', p_order->'delivery'->>'deliveryDateTime', p_order->>'preparationStartDateTime', '');
    begin v_okdata := nullif(v_agend, '')::timestamptz; exception when others then v_okdata := null; end;
    v_obs := v_obs || ' · AGENDADO' || case when v_okdata is not null then ' para ' || to_char(v_okdata at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI') else '' end;
  end if;
  if nullif(btrim(coalesce(p_order->'delivery'->>'observations', '')), '') is not null then v_obs := v_obs || ' · ' || btrim(p_order->'delivery'->>'observations'); end if;
  if p_simulado then v_obs := v_obs || ' · TESTE (simulação)'; end if;
  select id into v_caixa from caixa_sessoes where status = 'Aberto' limit 1;

  insert into vendas (id, cliente_nome, telefone_cliente, forma_pagamento, valor_total, custo_total, status, tipo, status_pedido, endereco, complemento, referencia, observacoes_entrega,
                      status_pagamento, cpf_nota, recebido_em, valor_original, valor_desconto, desconto_detalhe, origem, taxa_entrega, caixa_id, requisicao_id, canal)
  values (v_venda, v_nome, nullif(v_tel, ''), v_forma, v_total, 0, 'Confirmada', v_tipo, 'Recebido',
          case when v_tipo = 'Entrega' then coalesce(v_end, '') else '' end, case when v_tipo = 'Entrega' then v_comp else '' end, case when v_tipo = 'Entrega' then v_ref else '' end, v_obs,
          v_stpag, v_cpf, case when v_stpag = 'Pago' then now() end, (v_val->>'original')::numeric, (v_val->>'descontoLoja')::numeric,
          case when (v_val->>'descontoLoja')::numeric > 0 then 'Desconto/cupom iFood pago pela loja' else '' end, 'Balcão', (v_val->>'taxaEntrega')::numeric, v_caixa, 'ifood:' || v_id, 'iFood')
  returning numero_pedido into v_numero;

  v_sem := public._ifood_gravar_itens(v_venda, p_order, false);
  update vendas set custo_total = coalesce((select sum(custo_unitario * quantidade) from itens_venda where venda_id = v_venda), 0) where id = v_venda;

  perform public._ifood_gravar_pagamentos(v_venda, p_order, v_total, (v_val->>'entregaIfood')::boolean);

  insert into ifood_pedidos (pedido_ifood, venda_id, numero_ifood, estado, expira_em, itens_sem_ligacao, simulado, bruto)
  values (v_id, v_venda, v_disp, 'novo', now() + interval '8 minutes', v_sem, p_simulado, p_order);
  update ifood_estado set ultimo_pedido_em = now(), atualizado_em = now() where id;
  perform _auditar('Pedido do iFood recebido', 'iFood #' || v_disp || ' → venda #' || v_numero || ' · R$ ' || replace(to_char(v_total, 'FM9999990.00'), '.', ',') || case when v_sem > 0 then ' · ' || v_sem || ' item(ns) sem ligação' else '' end || case when p_simulado then ' · SIMULAÇÃO' else '' end, null);
  perform _integ_log('ifood', case when v_sem > 0 then 'aviso' else 'info' end, 'Pedido #' || v_disp || ' recebido' || case when v_sem > 0 then ' (' || v_sem || ' item sem ligação)' else '' end);
  return jsonb_build_object('ok', true, 'vendaId', v_venda, 'numero', v_numero, 'semLigacao', v_sem);
end $_$;


--
-- Name: ifood_enfileirar(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_enfileirar(p_pedido text, p_acao text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public._ifood_enfileirar(p_pedido, p_acao, '{}'::jsonb)
$$;


--
-- Name: ifood_escalar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_escalar() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v_n int := 0;
begin
  for r in select pedido_ifood, numero_ifood, avisos, extract(epoch from (now() - criado_em)) / 60 as min from ifood_pedidos where estado = 'novo' and not simulado and criado_em > now() - interval '9 minutes' loop
    if (r.min >= 6 and r.avisos < 2) or (r.min >= 4 and r.avisos < 1) then
      update ifood_pedidos set avisos = case when r.min >= 6 then 2 else 1 end where pedido_ifood = r.pedido_ifood;
      perform _push_enviar('pedido', '⏰ iFood #' || coalesce(r.numero_ifood, '') || ' esperando confirmação', 'Confirme agora: o iFood cancela sozinho em poucos minutos.', 'ifood-conf-' || r.pedido_ifood || '-' || r.avisos);
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end $$;


--
-- Name: ifood_evento_guardar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_evento_guardar(p jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v int;
begin
  insert into ifood_eventos (id, codigo, codigo_completo, pedido_ifood, criado_ifood, bruto)
  values (p->>'id', p->>'code', p->>'fullCode', p->>'orderId', nullif(p->>'createdAt', '')::timestamptz, p) on conflict (id) do nothing;
  get diagnostics v = row_count;
  return v > 0;
end $$;


--
-- Name: ifood_evento_resultado(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_evento_resultado(p_id text, p_final boolean, p_erro text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update ifood_eventos set tentativas = tentativas + 1, erro = left(p_erro, 300), processado_em = case when p_final then now() else null end where id = p_id
$$;


--
-- Name: ifood_eventos_pendentes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_eventos_pendentes() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'codigo', coalesce(codigo_completo, codigo), 'pedido', pedido_ifood, 'tentativas', tentativas, 'bruto', bruto) order by recebido_em), '[]'::jsonb)
  from (select * from ifood_eventos where processado_em is null and recebido_em > now() - interval '1 day' order by recebido_em limit 50) x
$$;


--
-- Name: ifood_eventos_vencidos_fechar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_eventos_vencidos_fechar() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  update ifood_eventos set processado_em = now(), erro = 'Ficou mais de 1 dia sem processar: encerrado com erro'
   where processado_em is null and recebido_em <= now() - interval '1 day';
  get diagnostics n = row_count;
  if n > 0 then perform _integ_log('ifood', 'aviso', n || ' evento(s) do iFood ficaram mais de 1 dia sem processar e foram encerrados com erro'); end if;
  return n;
end $$;


--
-- Name: ifood_limpar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_limpar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dias int := coalesce((select (config->>'retencaoClientesDias')::int from integracoes_config where provedor = 'ifood'), 90);
begin
  delete from ifood_eventos where recebido_em < now() - interval '30 days';
  delete from ifood_acoes where criado_em < now() - interval '60 days' and estado in ('ok', 'pulada');
  update ifood_pedidos set bruto = jsonb_set(coalesce(bruto, '{}'::jsonb) - 'customer' - 'delivery', '{apagado}', 'true'::jsonb) where criado_em < now() - make_interval(days => v_dias) and coalesce((bruto->>'apagado'), '') <> 'true';
  update vendas set telefone_cliente = null, endereco = '', complemento = '', referencia = '', cliente_nome = 'Cliente iFood', cpf_nota = null
   where canal = 'iFood' and data_hora < now() - make_interval(days => v_dias) and (telefone_cliente is not null or endereco <> '' or cliente_nome <> 'Cliente iFood' or cpf_nota is not null);
end $$;


--
-- Name: ifood_log(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_log(p_nivel text, p_msg text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public._integ_log('ifood', case when p_nivel in ('info','aviso','erro') then p_nivel else 'info' end, p_msg)
$$;


--
-- Name: ifood_loja_estado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_loja_estado() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_jsonb(l) from ifood_loja l where id
$$;


--
-- Name: ifood_loja_gravar(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_loja_gravar(p_status jsonb, p_interrupcao text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_disp boolean; v_sit text;
begin
  v_sit := coalesce(p_status->0->>'state', p_status->>'state', p_status->>'status', '');
  v_disp := coalesce((p_status->0->>'available')::boolean, (p_status->>'available')::boolean, upper(v_sit) in ('OK', 'AVAILABLE', 'OPEN'));
  update ifood_loja set situacao = left(v_sit, 60), disponivel = v_disp,
    motivo = left(coalesce(p_status->0->'validations'->0->>'message', p_status->0->>'message', p_status->>'message', ''), 200),
    interrupcao_id = coalesce(p_interrupcao, interrupcao_id), verificado_em = now(), bruto = p_status, atualizado_em = now() where id;
end $$;


--
-- Name: ifood_loja_verificar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_loja_verificar() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l ifood_loja%rowtype;
begin
  select * into l from ifood_loja where id;
  if l.pausada_ate is not null and l.pausada_ate < now() and not l.fechada_por_nos then
    update ifood_loja set pausada_ate = null where id;
    perform public._ifood_enfileirar('LOJA', 'loja_retomar', '{}'::jsonb);
  end if;
  update ifood_negociacoes set estado = 'expirada' where estado = 'aberta' and expira_em < now() - interval '2 minutes';
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: ifood_marcar_consulta(boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_marcar_consulta(p_ok boolean, p_erro text DEFAULT NULL::text, p_token_ok boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update ifood_estado set ultima_consulta = now(),
    ultima_consulta_ok = case when p_ok then now() else ultima_consulta_ok end,
    token_ok = coalesce(p_token_ok, token_ok),
    ultimo_erro = case when p_ok then null else left(p_erro, 300) end,
    ultimo_erro_em = case when p_ok then ultimo_erro_em else now() end, atualizado_em = now() where id;
  if not p_ok and p_erro is not null then perform public._integ_log('ifood', 'erro', p_erro); end if;
end $$;


--
-- Name: ifood_negociacao_fim(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_negociacao_fim(p_evento jsonb, p_pedido text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m jsonb := coalesce(p_evento->'metadata', '{}'::jsonb); v_id text := coalesce(nullif(m->>'disputeId', ''), nullif(m->>'handshakeId', ''));
begin
  update ifood_negociacoes set estado = case when estado = 'aberta' then 'encerrada' else estado end, respondido_em = coalesce(respondido_em, now())
   where (v_id is not null and id = v_id) or (v_id is null and pedido_ifood = p_pedido and estado = 'aberta');
end $$;


--
-- Name: ifood_negociacao_registrar(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_negociacao_registrar(p_evento jsonb, p_pedido text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m jsonb := coalesce(p_evento->'metadata', '{}'::jsonb); v_id text := coalesce(nullif(m->>'disputeId', ''), nullif(m->>'handshakeId', ''), nullif(p_evento->>'id', ''));
        v_exp timestamptz; v_num text;
begin
  begin v_exp := nullif(coalesce(m->>'expiresAt', m->>'expirationDate'), '')::timestamptz; exception when others then v_exp := null; end;
  insert into ifood_negociacoes (id, pedido_ifood, tipo, motivo, expira_em, alternativas, bruto)
  values (v_id, p_pedido, coalesce(m->>'handshakeType', m->>'type'), left(coalesce(m->>'message', m->>'reason', m->>'handshakeGroup', ''), 300), coalesce(v_exp, now() + interval '5 minutes'),
          case when jsonb_typeof(m->'alternatives') = 'array' then m->'alternatives' else '[]'::jsonb end, p_evento)
  on conflict (id) do nothing;
  if found then
    select numero_ifood into v_num from ifood_pedidos where pedido_ifood = p_pedido;
    perform _push_enviar('pedido', '⚠️ iFood: cliente pediu cancelamento/reembolso #' || coalesce(v_num, ''), 'Responda no painel (Integrações → iFood) antes do prazo.', 'ifood-neg-' || v_id);
    perform _integ_log('ifood', 'aviso', 'Negociação de cancelamento no pedido #' || coalesce(v_num, p_pedido));
    perform _auditar('Negociação do iFood recebida', 'Pedido iFood #' || coalesce(v_num, p_pedido) || ' · ' || coalesce(m->>'handshakeType', ''));
  end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: ifood_novos_sem_confirmar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_novos_sem_confirmar() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('pedido', pedido_ifood, 'numero', numero_ifood, 'minutos', round(extract(epoch from (now() - criado_em)) / 60, 1))), '[]'::jsonb)
  from ifood_pedidos where estado = 'novo' and not simulado and criado_em > now() - interval '15 minutes'
$$;


--
-- Name: ifood_pedido_dados(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_pedido_dados(p_pedido text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('estado', estado, 'simulado', simulado, 'expiraEm', expira_em, 'numero', numero_ifood) from ifood_pedidos where pedido_ifood = p_pedido
$$;


--
-- Name: ifood_precisa(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_precisa(p_tarefa text, p_minutos integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v timestamptz;
begin
  select case p_tarefa when 'financeiro' then financeiro_em when 'avaliacoes' then avaliacoes_em end into v from ifood_estado where id;
  if v is not null and v > now() - make_interval(mins => p_minutos) then return false; end if;
  if p_tarefa = 'financeiro' then update ifood_estado set financeiro_em = now() where id; else update ifood_estado set avaliacoes_em = now() where id; end if;
  return true;
end $$;


--
-- Name: ifood_preco_confirmar(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_preco_confirmar(p_id bigint, p_ok boolean, p_erro text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare h ifood_precos_hist%rowtype;
begin
  update ifood_precos_hist set estado = case when p_ok then 'ok' else 'erro' end, erro = left(p_erro, 300) where id = p_id returning * into h;
  if p_ok and h.id is not null then update ifood_itens set preco_ifood = h.preco_depois, preco_visto_em = now() where chave = h.chave; end if;
end $$;


--
-- Name: ifood_repasses_gravar(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_repasses_gravar(p_lista jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e jsonb; o jsonb; v_n int := 0; v_ped int; v_venda uuid; v_com numeric;
begin
  for e in select value from jsonb_array_elements(coalesce(p_lista, '[]'::jsonb)) loop
    if nullif(e->>'id', '') is null then continue; end if;
    v_ped := 0;
    for o in select value from jsonb_array_elements(case when jsonb_typeof(e->'orders') = 'array' then e->'orders' else '[]'::jsonb end) loop
      v_venda := null; v_com := null;
      update ifood_pedidos set repassado_em = coalesce(repassado_em, now()), repasse_id = e->>'id', comissao = coalesce(nullif(public._ifood_n(o->'commission'), 0), nullif(public._ifood_n(o->'fees'), 0), comissao)
       where pedido_ifood = coalesce(o->>'orderId', o->>'id')
       returning venda_id, comissao into v_venda, v_com;
      if found then
        v_ped := v_ped + 1;
        if v_com is not null and v_com > 0 then perform public._ifood_aplicar_comissao(v_venda, v_com); end if;
      end if;
    end loop;
    insert into ifood_repasses (id, pago_em, periodo_ini, periodo_fim, valor, pedidos, bruto)
    values (e->>'id', nullif(e->>'paymentDate', '')::date, nullif(e->>'periodStart', '')::date, nullif(e->>'periodEnd', '')::date, public._ifood_n(coalesce(e->'amount', e->'value')), v_ped, e)
    on conflict (id) do update set valor = excluded.valor, pedidos = excluded.pedidos, pago_em = excluded.pago_em, bruto = excluded.bruto;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


--
-- Name: ifood_token_gravar(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_token_gravar(p_token text, p_seg integer) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update ifood_token set token = p_token, expira_em = now() + make_interval(secs => greatest(p_seg, 60)) where id;
  update ifood_estado set token_ok = true, atualizado_em = now() where id;
$$;


--
-- Name: ifood_token_ler(); Type: FUNCTION; Schema: public; Owner: -
