$$;


--
-- Name: ifood_trava_pegar(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ifood_trava_pegar(p_dono text, p_seg integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v int;
begin
  update ifood_estado set trava_dono = p_dono, trava_ate = now() + make_interval(secs => p_seg) where id and (trava_ate is null or trava_ate < now() or trava_dono = p_dono);
