$$;


--
-- Name: mp_aplicar_status(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_aplicar_status(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare g pagamentos_online%rowtype; v_chave text := nullif(btrim(coalesce(p->>'chaveEvento', '')), ''); v_ass boolean := coalesce((p->>'assinaturaOk')::boolean, false);
        v_st text := lower(btrim(coalesce(p->>'status', ''))); v_ev bigint; v_vr numeric; v_res jsonb; v_reserva uuid; v_oid text := nullif(btrim(coalesce(p->>'mpOrderId', '')), ''); v_vst text; v_n int; v_antes numeric;
begin
  if v_chave is not null and not v_ass then
    insert into pagamentos_online_eventos (chave, tipo, status_mp, assinatura_ok, detalhe)
    values ('invalida:' || gen_random_uuid()::text, left(coalesce(p->>'tipoEvento', ''), 60), left(coalesce(p->>'statusMp', ''), 60), false, p->'detalhe');
    return jsonb_build_object('ok', false, 'ignorado', 'assinatura');
  end if;
  if v_st not in ('aguardando', 'aprovado', 'recusado', 'expirado', 'cancelado', 'reembolso_parcial', 'reembolsado', 'erro') then return _falha('Status inválido.'); end if;

  select reserva_id into v_reserva from pagamentos_online where id = _uuid(p->>'pagamentoId');
  if v_reserva is null and v_oid is not null then select reserva_id into v_reserva from pagamentos_online where mp_order_id = v_oid; end if;
  if v_reserva is null then
    if v_chave is not null then
      insert into pagamentos_online_eventos (chave, tipo, status_mp, assinatura_ok, detalhe) values (v_chave, left(coalesce(p->>'tipoEvento', ''), 60), left(coalesce(p->>'statusMp', ''), 60), true, p->'detalhe')
      on conflict (chave) do nothing;
    end if;
    return jsonb_build_object('ok', false, 'ignorado', 'pagamento_desconhecido');
  end if;
  perform 1 from pedidos_reserva where id = v_reserva for update;                 -- trava: reserva primeiro, depois o pagamento
  select * into g from pagamentos_online where id = coalesce(_uuid(p->>'pagamentoId'), (select id from pagamentos_online where mp_order_id = v_oid)) for update;

  if v_chave is not null then
    insert into pagamentos_online_eventos (chave, pagamento_id, tipo, status_mp, assinatura_ok, detalhe)
    values (v_chave, g.id, left(coalesce(p->>'tipoEvento', ''), 60), left(coalesce(p->>'statusMp', ''), 60), true, p->'detalhe')
    on conflict (chave) do nothing returning id into v_ev;
    if v_ev is null then return jsonb_build_object('ok', true, 'duplicado', true); end if;
  end if;

  update pagamentos_online set
    mp_order_id = coalesce(v_oid, mp_order_id), mp_payment_id = coalesce(nullif(p->>'mpPaymentId', ''), mp_payment_id),
    pix_copia_cola = coalesce(nullif(p->>'pixCopiaCola', ''), pix_copia_cola), pix_qr_base64 = coalesce(nullif(p->>'pixQrBase64', ''), pix_qr_base64),
    pix_expira_em = coalesce(nullif(p->>'pixExpiraEm', '')::timestamptz, pix_expira_em),
    cartao_final = case when p->>'cartaoFinal' ~ '^[0-9]{4}$' then p->>'cartaoFinal' else cartao_final end,
    cartao_bandeira = coalesce(left(nullif(p->>'cartaoBandeira', ''), 30), cartao_bandeira),
    status_detalhe = case when p ? 'statusDetalhe' then left(coalesce(p->>'statusDetalhe', ''), 200) else status_detalhe end, atualizado_em = now()
   where id = g.id;
  select * into g from pagamentos_online where id = g.id;

  if v_st = 'aprovado' then
    if g.status not in ('reembolso_parcial', 'reembolsado') then v_res := _mp_confirmar_pagamento(g.id); end if;
  elsif v_st in ('recusado', 'expirado', 'cancelado') then
    if g.status = 'aguardando' then update pagamentos_online set status = v_st, atualizado_em = now() where id = g.id; end if;
  elsif v_st = 'erro' then
    if g.status = 'aguardando' then
      update pagamentos_online set status = 'erro', erro = left(coalesce(p->>'erro', ''), 300), atualizado_em = now() where id = g.id;
      -- não deu nem para criar o pagamento: solta a reserva na hora (a página oferece pagar na entrega)
      if exists (select 1 from pedidos_reserva where id = g.reserva_id and estado = 'ativa')
         and not exists (select 1 from pagamentos_online where reserva_id = g.reserva_id and status = 'aprovado') then
        perform _mp_soltar(g.reserva_id, 'cancelada', 'Erro ao criar o pagamento');
      end if;
    end if;
  elsif v_st in ('reembolso_parcial', 'reembolsado') then
    if g.status in ('aprovado', 'reembolso_parcial', 'reembolsado') then
      v_antes := coalesce(g.valor_reembolsado, 0);
      v_vr := round(least(g.valor, greatest(g.valor_reembolsado, case when v_st = 'reembolsado' then g.valor else coalesce(_num(p->>'valorReembolsado'), 0) end)), 2);
      update pagamentos_online set valor_reembolsado = v_vr, status = case when v_vr >= g.valor then 'reembolsado' else 'reembolso_parcial' end, atualizado_em = now() where id = g.id;
      if v_vr >= g.valor and g.venda_id is not null then
        update reembolsos set status = 'Devolvido', devolvido_em = now(), observacao = 'Reembolsado pelo Mercado Pago' where venda_id = g.venda_id and status = 'Pendente';
      end if;
      -- devolução feita fora do sistema (painel do Mercado Pago) numa venda que NÃO foi cancelada: o dinheiro já saiu
      if g.venda_id is not null and coalesce(g.decisao, '') <> 'reembolsar' then
        select status::text into v_vst from vendas where id = g.venda_id;
        if v_vst is not null and v_vst <> 'Cancelada' then
          if v_vr >= g.valor then
            insert into reembolsos (venda_id, valor, forma_pagamento, motivo, status, devolvido_em, observacao)
            values (g.venda_id, v_vr, 'Mercado Pago', 'Reembolso feito no painel do Mercado Pago', 'Devolvido', now(), 'Devolvido direto no painel do Mercado Pago; a venda continua ativa: decida se cancela.')
            on conflict (venda_id) do nothing;
            get diagnostics v_n = row_count;
            if v_n > 0 then perform _push_enviar('reembolso', 'Reembolso feito no Mercado Pago', 'R$ ' || _dinheiro(v_vr) || ' devolvido direto no painel do Mercado Pago. A venda continua ativa: veja se cancela.', 'mp-reembolso-' || g.venda_id::text); end if;
          elsif v_vr > v_antes + 0.009 then
            perform _push_enviar('reembolso', 'Reembolso parcial no Mercado Pago', 'R$ ' || _dinheiro(v_vr) || ' de R$ ' || _dinheiro(g.valor) || ' devolvido direto no painel do Mercado Pago.', 'mp-reembolso-' || g.venda_id::text);
          end if;
        end if;
      end if;
      perform _auditar('Reembolso Mercado Pago', 'Pagamento ' || g.id || ' | R$ ' || _dinheiro(v_vr) || ' de R$ ' || _dinheiro(g.valor), '');
    end if;
  end if;

  return jsonb_build_object('ok', true, 'pagamentoId', g.id, 'status', (select status from pagamentos_online where id = g.id), 'resultado', v_res);
end $_$;


--
-- Name: mp_cancelar_resultado(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_cancelar_resultado(p_id uuid, p_ok boolean, p_erro text DEFAULT ''::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update pagamentos_online
     set mp_cancelado_em = case when p_ok then now() else mp_cancelado_em end,
         mp_cancelar_tentativas = case when p_ok then mp_cancelar_tentativas else mp_cancelar_tentativas + 1 end,
         erro = case when p_ok then erro else left(coalesce(nullif(p_erro, ''), erro), 300) end
   where id = p_id
$$;


--
-- Name: mp_credenciais(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_credenciais(p_modo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('ligado', c.ligado, 'modoAtual', case when c.modo = 'producao' then 'producao' else 'homologacao' end,
    'modo', m.modo, 'config', c.config,
    'publicKey', (select valor from integracoes_segredos where chave = case when m.modo = 'producao' then 'mp_public_key_producao' else 'mp_public_key_teste' end),
    'accessToken', (select valor from integracoes_segredos where chave = case when m.modo = 'producao' then 'mp_access_token_producao' else 'mp_access_token_teste' end),
    'webhookSecret', (select valor from integracoes_segredos where chave = 'mp_webhook_secret'))
  from integracoes_config c,
       lateral (select case when coalesce(p_modo, c.modo) = 'producao' then 'producao' else 'homologacao' end as modo) m
  where c.provedor = 'mercadopago'
$$;


--
-- Name: mp_expirar_reservas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_expirar_reservas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0;
begin
  for r in select id from pedidos_reserva where estado = 'ativa' and expira_em < now() order by expira_em limit 100 for update skip locked loop
    if exists (select 1 from pagamentos_online g where g.reserva_id = r.id and (g.status = 'aprovado' or (g.decisao_pendente and g.decisao is null))) then continue; end if;
    update pagamentos_online set status = 'expirado', status_detalhe = 'reserva vencida', atualizado_em = now() where reserva_id = r.id and status = 'aguardando';
    perform _mp_soltar(r.id, 'expirada', 'Tempo esgotado sem pagamento');
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: mp_pendentes_cancelar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_pendentes_cancelar() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'modo', t.mp_modo, 'orderId', t.mp_order_id) order by t.atualizado_em), '[]'::jsonb)
  from (select id, mp_modo, mp_order_id, atualizado_em from pagamentos_online
         where metodo = 'pix' and status in ('expirado', 'cancelado') and mp_order_id is not null
           and mp_cancelado_em is null and mp_cancelar_tentativas < 5 and atualizado_em > now() - interval '3 hours'
         order by atualizado_em limit 20) t
$$;


--
-- Name: mp_preparar_pagamento(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mp_preparar_pagamento(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r pedidos_reserva%rowtype; f formas_pagamento%rowtype; g pagamentos_online%rowtype; v_modo text; v_novo uuid; v_email text; v_achou boolean; v_teste_email text;
begin
  select * into r from pedidos_reserva where id = _uuid(p->>'reservaId') for update;
  if not found or r.user_id is distinct from _uuid(p->>'userId') then return _falha('Pedido não encontrado.'); end if;
  if r.estado = 'confirmada' then return _falha('Este pedido já foi pago.'); end if;
  if r.estado <> 'ativa' or r.expira_em < now() then return _falha('O tempo deste pedido acabou. Faça o pedido de novo.'); end if;
  if coalesce((public._mp_publico(r.user_id)->>'ligado')::boolean, false) is not true then return _falha('O pagamento pelo site não está disponível agora.'); end if;
  select * into f from formas_pagamento where id = r.forma_pagamento_id;
  if f.id is null or not f.aceita_online or f.tipo_online is null then return _falha('Forma de pagamento inválida.'); end if;
  if exists (select 1 from pagamentos_online where reserva_id = r.id and status = 'aprovado') then return _falha('Este pedido já foi pago.'); end if;
  if (select count(*) from pagamentos_online where reserva_id = r.id) >= 5 then return _falha('Muitas tentativas de pagamento. Faça o pedido de novo.'); end if;

  select * into g from pagamentos_online
   where reserva_id = r.id and metodo = 'pix' and status = 'aguardando' and pix_copia_cola is not null and (pix_expira_em is null or pix_expira_em > now())
   order by criado_em desc limit 1;
  v_achou := found;
  if v_achou and f.tipo_online = 'pix' then
    return jsonb_build_object('ok', true, 'reaproveitar', true, 'pagamentoId', g.id, 'metodo', 'pix', 'valor', g.valor,
      'pixCopiaCola', g.pix_copia_cola, 'pixQrBase64', g.pix_qr_base64, 'pixExpiraEm', g.pix_expira_em);
  end if;
  if f.tipo_online in ('credito', 'debito') and exists (select 1 from pagamentos_online where reserva_id = r.id and metodo in ('credito', 'debito') and status = 'aguardando' and criado_em > now() - interval '2 minutes') then
    return _falha('Seu pagamento está em andamento. Aguarde alguns segundos.');
  end if;

  update pagamentos_online set status = 'cancelado', status_detalhe = 'substituído por nova tentativa', atualizado_em = now() where reserva_id = r.id and status = 'aguardando';
  select case when modo = 'producao' then 'producao' else 'homologacao' end, nullif(btrim(coalesce(config->>'emailPagadorTeste', '')), '')
    into v_modo, v_teste_email from integracoes_config where provedor = 'mercadopago';
  insert into pagamentos_online (reserva_id, user_id, metodo, mp_modo, valor) values (r.id, r.user_id, f.tipo_online, v_modo, r.valor_total) returning id into v_novo;
  select email into v_email from auth.users where id = r.user_id;
  if v_modo = 'homologacao' and v_teste_email is not null then v_email := v_teste_email; end if;
  return jsonb_build_object('ok', true, 'pagamentoId', v_novo, 'metodo', f.tipo_online, 'modo', v_modo, 'valor', r.valor_total, 'expiraEm', r.expira_em,
    'email', v_email, 'nome', r.cliente_nome,
    'itens', (select coalesce(jsonb_agg(jsonb_build_object('titulo', left(coalesce(e->>'descricao', 'Item'), 100), 'quantidade', _num(e->>'quantidade', 1), 'valorUnitario', _num(e->>'valorUnitario'))), '[]'::jsonb)
                from jsonb_array_elements(r.itens) e));
end $$;


--
-- Name: nfce_credenciais(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_credenciais(p_ambiente text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('ligado', public._integracao_ligada('nfce'), 'modo', (select modo from integracoes_config where provedor = 'nfce'),
    'token', (select valor from integracoes_segredos where chave = 'nfce_token_' || case when p_ambiente = 'producao' then 'producao' else 'homologacao' end),
    'cnpj', (select cnpj from fiscal_empresa where id))
$$;


--
-- Name: nfce_inutilizacao_resultado(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_inutilizacao_resultado(p_id bigint, p_estado text, p_msg text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update nfce_inutilizacoes set estado = case when p_estado in ('feita', 'recusada') then p_estado else case when tentativas + 1 >= 6 then 'recusada' else 'duvida' end end,
    resposta = left(coalesce(p_msg, ''), 400), feito_em = case when p_estado = 'feita' then now() else feito_em end, tentativas = tentativas + 1, trava_ate = null where id = p_id;
  perform public._integ_log('nfce', case when p_estado = 'feita' then 'info' else 'aviso' end, 'Inutilização ' || p_estado || ': ' || left(coalesce(p_msg, ''), 150));
end $$;


--
-- Name: nfce_inutilizacoes_pendentes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_inutilizacoes_pendentes() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb;
begin
  with c as (select id from nfce_inutilizacoes where estado in ('pendente', 'duvida') and (trava_ate is null or trava_ate < now()) order by id limit 3 for update skip locked),
  u as (update nfce_inutilizacoes i set trava_ate = now() + interval '2 minutes' from c where i.id = c.id returning i.id, i.serie, i.numero_ini, i.numero_fim, i.justificativa, i.ambiente)
  select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb) into r from u;
  return r;
end $$;


--
-- Name: nfce_log(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_log(p_nivel text, p_msg text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public._integ_log('nfce', case when p_nivel in ('info','aviso','erro') then p_nivel else 'info' end, p_msg)
$$;


--
-- Name: nfce_montar(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_montar(p_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare n nfce_notas%rowtype; v vendas%rowtype; e fiscal_empresa%rowtype; r record; v_itens jsonb := '[]'::jsonb; v_pags jsonb := '[]'::jsonb;
  v_sem text; v_semlig text; v_bruto numeric := 0; v_desc numeric; v_outras numeric; v_total numeric; v_dsum numeric := 0; v_osum numeric := 0; v_di numeric; v_oi numeric;
  v_cnt int; v_i int := 0; v_psum numeric := 0; v_pf fiscal_perfis%rowtype; v_cpf text; v_item jsonb;
begin
  select * into n from nfce_notas where id = p_id; if not found then return jsonb_build_object('ok', false, 'motivo', 'Nota não encontrada.'); end if;
  select * into v from vendas where id = n.venda_id; if not found then return jsonb_build_object('ok', false, 'motivo', 'Venda não encontrada.'); end if;
  select * into e from fiscal_empresa where id;
  if not public._fiscal_empresa_ok() then return jsonb_build_object('ok', false, 'motivo', 'Dados fiscais da empresa incompletos (Integrações → Nota fiscal → Dados fiscais).'); end if;
  select string_agg(distinct coalesce(iv.descricao, '(item)'), ', ') into v_sem from itens_venda iv where iv.venda_id = v.id and iv.valor_total_item > 0 and public._perfil_fiscal_efetivo(iv.produto_id, iv.combo_id) is null;
  if v_sem is not null then return jsonb_build_object('ok', false, 'motivo', 'Item sem perfil fiscal: ' || left(v_sem, 150) || '. Defina o perfil e reemita.'); end if;
  select string_agg(distinct btrim(regexp_replace(regexp_replace(iv.descricao, '\s*\(obs:.*$', ''), '\s*\[SEM LIGAÇÃO\]', '')), ', ') into v_semlig
    from itens_venda iv where iv.venda_id = v.id and iv.valor_total_item > 0 and iv.descricao like '%[SEM LIGAÇÃO]%';
  if v_semlig is not null then return jsonb_build_object('ok', false, 'motivo', 'Item do iFood sem ligação com um produto: ' || left(v_semlig, 150) || '. Ligue o item (Integrações e contas → iFood) e reemita.'); end if;
  select coalesce(sum(valor_total_item), 0), count(*) into v_bruto, v_cnt from itens_venda where venda_id = v.id and valor_total_item > 0;
  if v_cnt = 0 or v_bruto <= 0 then return jsonb_build_object('ok', false, 'dispensar', true, 'motivo', 'Venda sem valor: não há nota a emitir.'); end if;
  v_desc := coalesce(v.valor_desconto, 0); v_outras := coalesce(v.taxa_entrega, 0) + coalesce(v.acrescimo_forma, 0);
  v_total := round(v_bruto - v_desc + v_outras, 2);
  for r in select iv.id, iv.produto_id, iv.combo_id, iv.descricao, iv.quantidade, iv.valor_total_item vt from itens_venda iv where iv.venda_id = v.id and iv.valor_total_item > 0 order by iv.id loop
    v_i := v_i + 1;
    if v_i = v_cnt then v_di := round(v_desc - v_dsum, 2); v_oi := round(v_outras - v_osum, 2);
    else v_di := round(v_desc * r.vt / v_bruto, 2); v_oi := round(v_outras * r.vt / v_bruto, 2); end if;
    v_dsum := v_dsum + v_di; v_osum := v_osum + v_oi;
    select * into v_pf from fiscal_perfis where id = public._perfil_fiscal_efetivo(r.produto_id, r.combo_id);
    v_item := jsonb_build_object('numero_item', v_i, 'codigo_produto', coalesce(r.produto_id, r.combo_id)::text,
      'descricao', left(coalesce(nullif(btrim(regexp_replace(regexp_replace(coalesce(r.descricao, ''), '\s*\(obs:.*$', ''), '\s*\[SEM LIGAÇÃO\]', '')), ''), 'Item'), 120),
      'codigo_ncm', v_pf.ncm, 'cfop', v_pf.cfop, 'unidade_comercial', v_pf.unidade, 'quantidade_comercial', r.quantidade, 'valor_unitario_comercial', round(r.vt / nullif(r.quantidade, 0), 6),
      'unidade_tributavel', v_pf.unidade, 'quantidade_tributavel', r.quantidade, 'valor_unitario_tributavel', round(r.vt / nullif(r.quantidade, 0), 6), 'valor_bruto', round(r.vt, 2),
      'icms_origem', v_pf.origem::int, 'icms_situacao_tributaria', coalesce(v_pf.csosn, v_pf.cst_icms), 'pis_situacao_tributaria', v_pf.pis_cst, 'cofins_situacao_tributaria', v_pf.cofins_cst, 'inclui_no_total', 1);
    if v_pf.cest is not null then v_item := v_item || jsonb_build_object('cest', v_pf.cest); end if;
    if v_di > 0 then v_item := v_item || jsonb_build_object('valor_desconto', v_di); end if;
    if v_oi > 0 then v_item := v_item || jsonb_build_object('valor_outras_despesas', v_oi); end if;
    v_itens := v_itens || v_item;
  end loop;
  for r in select forma_pagamento, valor from pagamentos_venda where venda_id = v.id and valor > 0 order by valor desc loop
    v_pags := v_pags || jsonb_build_object('forma_pagamento', public._nfce_forma_codigo(r.forma_pagamento), 'valor_pagamento', round(r.valor, 2), 'descricao_pagamento', public._nfce_forma_desc(r.forma_pagamento));
    v_psum := v_psum + round(r.valor, 2);
  end loop;
  if jsonb_array_length(v_pags) = 0 then
    v_pags := jsonb_build_array(jsonb_build_object('forma_pagamento', public._nfce_forma_codigo(v.forma_pagamento), 'valor_pagamento', v_total, 'descricao_pagamento', public._nfce_forma_desc(v.forma_pagamento)));
  elsif v_psum <> v_total then
    v_pags := jsonb_set(v_pags, '{0,valor_pagamento}', to_jsonb(round((v_pags->0->>'valor_pagamento')::numeric + (v_total - v_psum), 2)));
  end if;
  v_cpf := coalesce(n.cpf, v.cpf_nota);
  return jsonb_build_object('ok', true, 'valor', v_total, 'payload', jsonb_strip_nulls(jsonb_build_object(
    'natureza_operacao', 'VENDA AO CONSUMIDOR', 'cnpj_emitente', e.cnpj, 'presenca_comprador', case when v.tipo::text = 'Entrega' then 4 else 1 end,
    'modalidade_frete', 9, 'local_destino', 1, 'consumidor_final', 1, 'cpf_destinatario', v_cpf, 'itens', v_itens, 'formas_pagamento', v_pags)));
end $_$;


--
-- Name: nfce_pegar_pendentes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_pegar_pendentes(p_limite integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb;
begin
  with c as (select id from nfce_notas where estado in ('pendente', 'duvida', 'contingencia', 'cancelando') and emitir_apos <= now() and proxima_tentativa <= now() and (trava_ate is null or trava_ate < now())
               order by id limit greatest(1, least(coalesce(p_limite, 5), 20)) for update skip locked),
  u as (update nfce_notas n set trava_ate = now() + interval '2 minutes', atualizado_em = now() from c where n.id = c.id returning n.id, n.ref, n.venda_id, n.ambiente, n.estado, n.tentativas, n.cancelamento_motivo)
  select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb) into r from u;
  return r;
end $$;


--
-- Name: nfce_resultado(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfce_resultado(p_id bigint, p_res jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n nfce_notas%rowtype; v_r text := p_res->>'resultado'; v_msg text := left(coalesce(p_res->>'mensagem', ''), 600); v_tent int;
begin
  select * into n from nfce_notas where id = p_id for update;
  if not found then return jsonb_build_object('ok', false); end if;
  if n.estado in ('autorizada', 'cancelada') and v_r <> 'autorizada' then return jsonb_build_object('ok', true, 'ignorado', true); end if;
  if v_r = 'autorizada' then
    update nfce_notas set estado = 'autorizada', numero = nullif(p_res->>'numero', '')::int, serie = nullif(p_res->>'serie', '')::int, chave = p_res->>'chave', protocolo = p_res->>'protocolo',
      url_danfe = p_res->>'urlDanfe', url_xml = p_res->>'urlXml', url_consulta = p_res->>'urlConsulta', status_sefaz = p_res->>'statusSefaz', mensagem = v_msg, erro_pt = null,
      emitida_em = coalesce(emitida_em, now()), trava_ate = null, atualizado_em = now(), tentativas = tentativas + 1 where id = p_id;
    perform public._integ_log('nfce', 'info', 'Nota ' || coalesce(p_res->>'numero', '?') || ' autorizada (venda ' || n.ref || ')');
    if n.cancelar_pedido then perform public._nfce_iniciar_cancelamento(p_id, 'Venda cancelada no sistema'); end if;
  elsif v_r = 'rejeitada' then
    update nfce_notas set estado = 'rejeitada', status_sefaz = p_res->>'statusSefaz', mensagem = v_msg, erro_pt = public._nfce_traduzir(v_msg), trava_ate = null, atualizado_em = now(), tentativas = tentativas + 1 where id = p_id;
    perform public._integ_log('nfce', 'erro', 'Nota rejeitada (venda ' || n.ref || '): ' || left(v_msg, 200));
  elsif v_r = 'pendencia' then
    update nfce_notas set estado = 'pendencia', erro_pt = left(coalesce(p_res->>'motivo', 'Pendência'), 300), trava_ate = null, atualizado_em = now() where id = p_id;
    perform public._integ_log('nfce', 'aviso', 'Nota parada (venda ' || n.ref || '): ' || left(coalesce(p_res->>'motivo', ''), 200));
  elsif v_r = 'dispensada' then
    update nfce_notas set estado = 'dispensada', erro_pt = left(coalesce(p_res->>'motivo', ''), 300), trava_ate = null, atualizado_em = now() where id = p_id;
  elsif v_r = 'cancelada' then
    update nfce_notas set estado = 'cancelada', cancelada_em = coalesce(cancelada_em, now()), mensagem = v_msg, erro_pt = null, cancelar_manual = false, trava_ate = null, atualizado_em = now() where id = p_id;
    perform public._integ_log('nfce', 'info', 'Nota cancelada (venda ' || n.ref || ')');
  elsif v_r = 'cancelamento_recusado' then
    update nfce_notas set estado = 'autorizada', cancelar_manual = true, mensagem = v_msg, trava_ate = null, atualizado_em = now(),
      erro_pt = 'A Sefaz/Focus não aceitou o cancelamento da nota (' || left(v_msg, 160) || '). O contador precisa orientar o procedimento.' where id = p_id;
    perform public._integ_log('nfce', 'erro', 'Cancelamento recusado (venda ' || n.ref || '): ' || left(v_msg, 200));
  elsif v_r = 'contingencia' then
    update nfce_notas set estado = 'contingencia', numero = nullif(p_res->>'numero', '')::int, serie = nullif(p_res->>'serie', '')::int, chave = p_res->>'chave', mensagem = v_msg,
      proxima_tentativa = now() + interval '3 minutes', trava_ate = null, atualizado_em = now() where id = p_id;
  elsif n.estado = 'cancelando' then
    v_tent := n.tentativas + 1;
    update nfce_notas set tentativas = v_tent, mensagem = v_msg, proxima_tentativa = now() + make_interval(mins => least(power(2, least(v_tent, 4))::int, 15)), trava_ate = null, atualizado_em = now(),
      estado = case when v_tent >= 6 then 'autorizada' else 'cancelando' end,
      cancelar_manual = (v_tent >= 6), erro_pt = case when v_tent >= 6 then 'Não consegui cancelar a nota automaticamente. O contador precisa orientar.' else erro_pt end where id = p_id;
  else
    v_tent := n.tentativas + 1;
    update nfce_notas set estado = case when v_tent >= 8 then 'erro' else 'duvida' end, tentativas = v_tent, mensagem = v_msg,
      erro_pt = case when v_tent >= 8 then 'Não consegui falar com a Focus/Sefaz depois de várias tentativas. Veja o registro e use "Reemitir".' else null end,
      proxima_tentativa = now() + make_interval(mins => least(power(2, least(v_tent, 5))::int, 30)), trava_ate = null, atualizado_em = now() where id = p_id;
    if v_tent >= 8 then perform public._integ_log('nfce', 'erro', 'Nota parada por erro de comunicação (venda ' || n.ref || ')'); end if;
  end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: registrar_erro_cliente(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_erro_cliente(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  uid uuid := auth.uid(); hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  tp text; msg text; ori text; pil text; h text; vezes int; novos int; total int;
begin
  if uid is null or auth_nivel() is null or p is null or jsonb_typeof(p) <> 'object' then return jsonb_build_object('ok', false); end if;
  tp := case when p->>'tipo' = 'promise' then 'promise' else 'error' end;
  msg := erro_limpa_(p->>'mensagem', 300); ori := erro_limpa_(p->>'origem', 120); pil := erro_limpa_(p->>'pilha', 600);
  if msg = '' then return jsonb_build_object('ok', false); end if;
  h := md5(tp || '|' || msg || '|' || ori);
  vezes := case when (p->>'vezes') ~ '^[0-9]{1,2}$' then greatest((p->>'vezes')::int, 1) else 1 end;
  update erros_cliente set ocorrencias = least(ocorrencias + vezes, 9999), ultima_em = now() where hash = h and dia = hoje;
  if found then return jsonb_build_object('ok', true, 'novo', false); end if;
  select count(*) into novos from erros_cliente where usuario_id = uid and criado_em > now() - interval '1 hour';
  select count(*) into total from erros_cliente where dia = hoje;
  if novos >= 20 or total >= 300 then return jsonb_build_object('ok', false, 'motivo', 'limite'); end if;
  insert into erros_cliente (usuario_id, nivel, tipo, mensagem, origem, pilha, tela, versao, aparelho, hash, ocorrencias)
  values (uid, coalesce(ia_nivel_real(), '?'), tp, msg, ori, pil,
          left(regexp_replace(coalesce(p->>'tela', ''), '[^a-zA-Z0-9_-]', '', 'g'), 40),
          left(regexp_replace(coalesce(p->>'versao', ''), '[^a-zA-Z0-9._-]', '', 'g'), 30),
          erro_limpa_(p->>'aparelho', 80), h, vezes)
  on conflict (hash, dia) do update set ocorrencias = least(erros_cliente.ocorrencias + vezes, 9999), ultima_em = now();
  return jsonb_build_object('ok', true, 'novo', true);
end $_$;


--
-- Name: restaurar_backup_dados(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurar_backup_dados(p_dados jsonb, p_preservar text[] DEFAULT ARRAY['usuarios'::text, 'auditoria'::text]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_todas text[]; v_ordem text[] := '{}'; v_pend text[]; v_pronta text[];
  t text; v_cols text; v_pks text[]; v_pkl text; v_set text; v_xs text; v_bs text;
  v_src text; v_n bigint; v_esp bigint; v_cont jsonb := '{}'::jsonb; i int;
begin
  if p_dados is null or jsonb_typeof(p_dados) <> 'object' then
    raise exception 'Arquivo de backup inválido.';
  end if;
  perform set_config('statement_timeout', '900000', true);
  perform set_config('lock_timeout', '30000', true);

  select coalesce(array_agg(c.relname::text order by c.relname), '{}') into v_todas
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r','p') and not c.relispartition
    and jsonb_typeof(p_dados -> c.relname::text) = 'array'
    and c.relname <> all (p_preservar) and c.relname <> all (public._backup_excluidas());

  v_pend := v_todas;
  while coalesce(array_length(v_pend, 1), 0) > 0 loop
    select coalesce(array_agg(u.nome order by u.nome), '{}') into v_pronta
    from unnest(v_pend) as u(nome)
    where not exists (
      select 1 from pg_constraint k
      join pg_class cf on cf.oid = k.conrelid
      join pg_class cp on cp.oid = k.confrelid
      where k.contype = 'f' and cf.relname = u.nome and cf.relnamespace = 'public'::regnamespace
        and cp.relnamespace = 'public'::regnamespace and cp.relname = any (v_pend) and cp.relname <> u.nome);
    if coalesce(array_length(v_pronta, 1), 0) = 0 then v_pronta := v_pend; end if;
    v_ordem := v_ordem || v_pronta;
    select coalesce(array_agg(x), '{}') into v_pend from unnest(v_pend) as x where x <> all (v_pronta);
  end loop;

  foreach t in array v_ordem loop
    select string_agg(format('%I', a.attname), ', ' order by a.attnum) into v_cols
    from pg_attribute a
    where a.attrelid = format('public.%I', t)::regclass and a.attnum > 0 and not a.attisdropped and a.attgenerated = '';
    v_pks := public._pk_cols(t);
    v_src := format('(select * from jsonb_populate_recordset(null::public.%I, $1 -> %L)%s) b', t, t,
                    case when t = 'sistema' then ' where chave <> ''MANUTENCAO''' else '' end);
    if v_pks is null then
      execute format('delete from public.%I', t);
      execute format('insert into public.%I (%s) overriding system value select %s from %s', t, v_cols, v_cols, v_src) using p_dados;
    else
      select string_agg(format('%I', x), ', ') into v_pkl from unnest(v_pks) as x;
      select string_agg(format('%I = excluded.%I', a.attname, a.attname), ', ') into v_set
      from pg_attribute a
      where a.attrelid = format('public.%I', t)::regclass and a.attnum > 0 and not a.attisdropped
        and a.attgenerated = '' and a.attname::text <> all (v_pks);
      execute format('insert into public.%I (%s) overriding system value select %s from %s on conflict (%s) %s',
                     t, v_cols, v_cols, v_src, v_pkl,
                     case when v_set is null then 'do nothing' else 'do update set ' || v_set end) using p_dados;
    end if;
  end loop;

  for i in reverse coalesce(array_length(v_ordem, 1), 0) .. 1 loop
    t := v_ordem[i];
    v_pks := public._pk_cols(t);
    if t = 'sistema' or v_pks is null then continue; end if;
    select string_agg('x.' || format('%I', k), ', '), string_agg(format('%I', k), ', ') into v_xs, v_bs from unnest(v_pks) as k;
    execute format('delete from public.%I x where (%s) not in (select %s from jsonb_populate_recordset(null::public.%I, $1 -> %L))',
                   t, v_xs, v_bs, t, t) using p_dados;
  end loop;

  foreach t in array v_ordem loop
    if t = 'sistema' then continue; end if;
    execute format('select count(*) from public.%I', t) into v_n;
    v_esp := jsonb_array_length(p_dados -> t);
    v_cont := v_cont || jsonb_build_object(t, v_n);
    if v_n <> v_esp then
      raise exception 'Conferência falhou em %: o backup tem % linhas e o banco ficou com %. Nada foi alterado.', t, v_esp, v_n;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'tabelas', coalesce(array_length(v_ordem, 1), 0), 'linhas', v_cont);
end;
$_$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


