    estado text DEFAULT 'recepcao'::text NOT NULL,
    tipo_problema text,
    resumo text,
    texto_original text,
    ia_chamadas smallint DEFAULT 0 NOT NULL,
    atendente_id uuid,
    ocorrencia_id uuid,
    nao_lidas_equipe integer DEFAULT 0 NOT NULL,
    nao_lidas_cliente integer DEFAULT 0 NOT NULL,
    solucao text,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    transferida_em timestamp with time zone,
    encerrada_em timestamp with time zone,
    intencao text,
    nome_cliente text,
    telefone_cliente text,
    pedido_nao_localizado boolean DEFAULT false NOT NULL,
    outros_pedidos smallint DEFAULT 0 NOT NULL,
    CONSTRAINT chat_conversas_estado_check CHECK ((estado = ANY (ARRAY['recepcao'::text, 'aguardando'::text, 'em_atendimento'::text, 'encerrada'::text]))),
    CONSTRAINT chat_conversas_ia_chamadas_check CHECK (((ia_chamadas >= 0) AND (ia_chamadas <= 3))),
    CONSTRAINT chat_conversas_intencao_check CHECK (((intencao IS NULL) OR (intencao = ANY (ARRAY['pedido_feito'::text, 'antes_de_pedir'::text])))),
    CONSTRAINT chat_conversas_pedido_ao_transferir CHECK (((estado = 'recepcao'::text) OR (intencao IS DISTINCT FROM 'pedido_feito'::text) OR (venda_id IS NOT NULL) OR pedido_nao_localizado)),
    CONSTRAINT chat_conversas_resumo_check CHECK ((char_length(resumo) <= 600)),
