    CONSTRAINT chat_conversas_texto_original_check CHECK ((char_length(texto_original) <= 300)),
    CONSTRAINT chat_conversas_tipo_problema_check CHECK (((tipo_problema IS NULL) OR (tipo_problema = ANY (ARRAY['atraso'::text, 'item_errado'::text, 'item_faltando'::text, 'cobranca'::text, 'qualidade'::text, 'outro'::text, 'antes_de_pedir'::text]))))
