--
-- Name: v_cardapio_esgotados; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cardapio_esgotados AS
 WITH ligado AS (
         SELECT COALESCE(( SELECT ((sistema.valor #>> '{}'::text[]) = ANY (ARRAY['true'::text, 'Sim'::text]))
                   FROM public.sistema
                  WHERE (sistema.chave = 'BLOQUEAR_ESTOQUE_NEGATIVO'::text)), false) AS on_
        ), falta AS (
         SELECT pi.produto_id,
            bool_or(((pi.quantidade_por_unidade > (0)::numeric) AND ((e.quantidade + 0.000000001) < pi.quantidade_por_unidade))) AS f1,
            min(
                CASE
                    WHEN (pi.quantidade_por_unidade > (0)::numeric) THEN (e.quantidade / pi.quantidade_por_unidade)
                    ELSE NULL::numeric
                END) AS razao
           FROM (public.produto_ingredientes pi
             JOIN public.estoque e ON ((e.id = pi.ingrediente_id)))
          GROUP BY pi.produto_id
        )
 SELECT 'produto'::text AS tipo,
    p.id
   FROM (public.v_cardapio_produtos p
     JOIN falta f ON ((f.produto_id = p.id))),
    ligado
  WHERE (ligado.on_ AND f.f1)
UNION ALL
 SELECT 'combo'::text AS tipo,
    b.id
   FROM public.v_cardapio_combos b,
    ligado
  WHERE (ligado.on_ AND (EXISTS ( SELECT 1
           FROM ((public.combo_itens ci
             JOIN public.produto_ingredientes pi ON ((pi.produto_id = ci.produto_id)))
             JOIN public.estoque e ON ((e.id = pi.ingrediente_id)))
          WHERE ((ci.combo_id = b.id) AND (pi.quantidade_por_unidade > (0)::numeric) AND ((e.quantidade + 0.000000001) < (pi.quantidade_por_unidade * (GREATEST(COALESCE(ci.quantidade, 1), 1))::numeric))))));


--
-- Name: v_cardapio_formas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cardapio_formas AS
 SELECT id,
    nome,
    ordem,
    permite_troco,
    acrescimo_percentual,
    acrescimo_fixo
   FROM public.formas_pagamento
  WHERE (ativa AND visivel_cardapio);


--
-- Name: v_cardapio_mais_pedidos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cardapio_mais_pedidos AS
 WITH cont AS (
         SELECT COALESCE(('p_'::text || (iv.produto_id)::text), ('c_'::text || (iv.combo_id)::text)) AS chave,
                CASE
                    WHEN (iv.produto_id IS NOT NULL) THEN 'produto'::text
                    ELSE 'combo'::text
                END AS tipo,
            COALESCE(iv.produto_id, iv.combo_id) AS item_id,
            sum(COALESCE(iv.quantidade, 1)) AS qtd
           FROM (public.itens_venda iv
             JOIN public.vendas v ON ((v.id = iv.venda_id)))
          WHERE ((v.status = 'Confirmada'::public.venda_status) AND (v.data_hora >= (now() - '30 days'::interval)) AND ((iv.produto_id IS NOT NULL) OR (iv.combo_id IS NOT NULL)))
          GROUP BY COALESCE(('p_'::text || (iv.produto_id)::text), ('c_'::text || (iv.combo_id)::text)),
                CASE
                    WHEN (iv.produto_id IS NOT NULL) THEN 'produto'::text
                    ELSE 'combo'::text
                END, COALESCE(iv.produto_id, iv.combo_id)
        ), vis AS (
         SELECT c.tipo,
            c.item_id,
            c.qtd
           FROM cont c
          WHERE (((c.tipo = 'produto'::text) AND (EXISTS ( SELECT 1
                   FROM public.v_cardapio_produtos p
                  WHERE (p.id = c.item_id)))) OR ((c.tipo = 'combo'::text) AND (EXISTS ( SELECT 1
                   FROM public.v_cardapio_combos b
                  WHERE (b.id = c.item_id)))))
        )
 SELECT tipo,
    item_id AS id,
    (row_number() OVER (ORDER BY qtd DESC, item_id))::integer AS posicao
   FROM vis
  ORDER BY qtd DESC, item_id
 LIMIT 8;


--
-- Name: v_cardapio_precos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cardapio_precos AS
 SELECT 'produto'::text AS tipo,
    pp.produto_id AS item_id,
    pp.forma_pagamento_id,
    pp.preco
   FROM ((public.produto_precos pp
     JOIN public.produtos p ON (((p.id = pp.produto_id) AND p.ativo)))
     JOIN public.formas_pagamento f ON (((f.id = pp.forma_pagamento_id) AND f.ativa AND f.visivel_cardapio)))
UNION ALL
 SELECT 'combo'::text AS tipo,
    cp.combo_id AS item_id,
    cp.forma_pagamento_id,
    cp.preco
   FROM ((public.combo_precos cp
     JOIN public.combos c ON (((c.id = cp.combo_id) AND c.ativo)))
     JOIN public.formas_pagamento f ON (((f.id = cp.forma_pagamento_id) AND f.ativa AND f.visivel_cardapio)));


