    quantidade,
    valor_unitario,
        CASE
            WHEN (public.auth_nivel() = ANY (ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso])) THEN custo_unitario
            ELSE NULL::numeric
        END AS custo_unitario,
    valor_total_item,
    adicionais_ids
   FROM public.itens_venda i;


