    m.chamado_em,
    u.login AS garcom_responsavel
   FROM (public.mesas m
     LEFT JOIN public.usuarios u ON ((u.id = m.garcom_responsavel_id)))
  WHERE public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso, 'Garçom'::public.nivel_acesso]);


