CREATE VIEW public.v_ocorrencias WITH (security_invoker='true') AS
 SELECT id,
    numero,
    data_hora,
    tipo,
    setor,
    venda_id,
    cliente,
    telefone,
    public._login_de(registrado_por) AS registrado_por,
    responsavel,
    descricao,
    solucao,
    status,
    atualizada_em,
    historico
   FROM public.ocorrencias o;


--
-- Name: v_sessao_aberta; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_sessao_aberta AS
 SELECT id,
    abertura,
    (
        CASE
            WHEN ((public.auth_nivel())::text = ANY (ARRAY['Admin'::text, 'Operador'::text, 'Desenvolvedor'::text])) THEN fundo_caixa
            ELSE NULL::numeric
        END)::numeric(10,2) AS fundo_caixa,
    public._login_de(usuario_abertura) AS usuario_abertura,
    public._caixa_vence_em(abertura) AS vence_em,
    (now() >= public._caixa_vence_em(abertura)) AS passou_vencimento,
    public._caixa_vencido(id) AS vencido,
    ( SELECT cfg.aviso_horas
           FROM public.caixa_config cfg
         LIMIT 1) AS aviso_horas,
    ( SELECT l.ate
           FROM public.caixa_liberacoes l
          WHERE ((l.caixa_id = s.id) AND (l.ate > now()))
          ORDER BY l.ate DESC
         LIMIT 1) AS liberado_ate,
    ( SELECT public._login_de(l.liberado_por) AS _login_de
           FROM public.caixa_liberacoes l
          WHERE ((l.caixa_id = s.id) AND (l.ate > now()))
          ORDER BY l.ate DESC
         LIMIT 1) AS liberado_por,
    ( SELECT l.motivo
           FROM public.caixa_liberacoes l
          WHERE ((l.caixa_id = s.id) AND (l.ate > now()))
          ORDER BY l.ate DESC
         LIMIT 1) AS liberado_motivo
   FROM public.caixa_sessoes s
  WHERE ((status = 'Aberto'::public.status_caixa) AND (public.auth_nivel() IS NOT NULL));


--
-- Name: v_vendas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_vendas AS
 SELECT id,
    numero_pedido AS numero,
    data_hora,
    cliente_nome,
    telefone_cliente AS cliente_telefone,
    forma_pagamento,
    valor_total,
        CASE
            WHEN (public.auth_nivel() = ANY (ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso])) THEN custo_total
            ELSE NULL::numeric
        END AS custo_total,
    status,
    motivo_cancelamento,
    tipo AS tipo_entrega,
    status_pedido,
    endereco,
    complemento,
    referencia,
    observacoes_entrega,
    pronta_em,
    concluida_em,
    status_pagamento,
    recebido_em,
    valor_original,
    valor_desconto,
    desconto_detalhe,
    public._login_de(entregador_id) AS entregador,
    saiu_em,
    origem,
    mesa_id,
    taxa_entrega,
    fechamento_entrega_id,
    public._login_de(registrado_por) AS registrado_por,
    inicio_preparo_em,
    public._mesa_numero_de(mesa_id) AS mesa_numero,
    acrescimo_forma,
    preferencias_cliente
   FROM public.vendas v;


