--
-- Name: adicionais adicionais_admin; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY adicionais_admin ON public.adicionais TO authenticated USING (public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso])) WITH CHECK (public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso]));


--
-- Name: adicionais adicionais_ler; Type: POLICY; Schema: public; Owner: -
--

