--

CREATE POLICY vendas_alterar ON public.vendas FOR UPDATE TO authenticated USING (public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso])) WITH CHECK (public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso]));


--
-- Name: vendas vendas_criar; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY vendas_criar ON public.vendas FOR INSERT TO authenticated WITH CHECK ((( SELECT public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso]) AS tem_nivel) OR (( SELECT public.tem_nivel(VARIADIC ARRAY['Garçom'::public.nivel_acesso]) AS tem_nivel) AND (registrado_por = ( SELECT auth.uid() AS uid)))));


--
-- Name: vendas vendas_ler; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY vendas_ler ON public.vendas FOR SELECT TO authenticated USING ((public.tem_nivel(VARIADIC ARRAY['Admin'::public.nivel_acesso, 'Operador'::public.nivel_acesso]) OR (public.tem_nivel(VARIADIC ARRAY['Garçom'::public.nivel_acesso]) AND (((tipo = 'Mesa'::public.venda_tipo) AND (mesa_id IN ( SELECT m.id
   FROM public.mesas m
  WHERE (m.garcom_responsavel_id = ( SELECT auth.uid() AS uid))))) OR (registrado_por = ( SELECT auth.uid() AS uid)))) OR (public.tem_nivel(VARIADIC ARRAY['Cozinha'::public.nivel_acesso]) AND (status = 'Confirmada'::public.venda_status) AND (status_pedido = ANY (ARRAY['Recebido'::public.status_pedido, 'Em preparo'::public.status_pedido, 'Pronta'::public.status_pedido, 'Suspenso'::public.status_pedido]))) OR (public.tem_nivel(VARIADIC ARRAY['Cozinha'::public.nivel_acesso]) AND (status = 'Confirmada'::public.venda_status) AND (status_pedido = ANY (ARRAY['Retirada'::public.status_pedido, 'Entregue'::public.status_pedido, 'Servida'::public.status_pedido])) AND (caixa_id = ( SELECT public._caixa_aberto_id() AS _caixa_aberto_id))) OR (public.tem_nivel(VARIADIC ARRAY['Entregador'::public.nivel_acesso]) AND (tipo = 'Entrega'::public.venda_tipo) AND (entregador_id = ( SELECT auth.uid() AS uid)))));


