-- ---------------------------------------------------------------------
-- Extras fora do schema public
-- ---------------------------------------------------------------------
-- RLS ligado automaticamente em toda tabela nova do public
drop event trigger if exists ensure_rls;
create event trigger ensure_rls on ddl_command_end
  when tag in ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  execute function public.rls_auto_enable();

-- Tempo real (Realtime) nestas tabelas
alter publication supabase_realtime add table public.chat_conversas, public.chat_mensagens, public.mesas, public.vendas;

-- Bucket privado dos backups (Storage)
insert into storage.buckets (id, name, public) values ('backups', 'backups', false) on conflict (id) do nothing;
